/// The brand header at the top of the home panel, shown before and after
/// activation. `assets/icon/app_icon.webp` is 1400x695 with about 129
/// transparent rows above and below the artwork, so at the displayed 250x124
/// it carried roughly 23 logical pixels of empty space on each side. This
/// shows only the band that holds the artwork and puts the
/// "Part of Winthos AI" line in the empty area under the baked-in "Win's VPN"
/// wordmark, so the header is shorter and gains no height for the subtitle.
class WinsHomeBrandHeader extends StatelessWidget {
  const WinsHomeBrandHeader({super.key});

  /// Fixed English in every locale, by owner ruling 2026-09-29: the logo
  /// sentences are not translated. Deliberately not passed through `_t()`.
  static const String subtitle = 'Part of Winthos AI';

  /// Logical size the whole asset is drawn at (unchanged from before).
  static const double logoWidth = 250;
  static const double logoHeight = 124;

  /// The band of the drawn asset that is shown: the artwork spans y = 23 to
  /// 101, so this keeps 1 pixel of margin above it and 3 below.
  static const double bandTop = 22;
  static const double bandHeight = 82;

  /// The "Win's VPN" wordmark spans x = 91 to 234 and ends at y = 72 in the
  /// drawn asset. The subtitle box sits directly under it.
  static const double _wordmarkLeft = 91;
  static const double _wordmarkWidth = 143;
  static const double _subtitleTop = 75;
  static const double _subtitleHeight = 15;

  /// The floating buttons that sit over the top corners of the home, in the
  /// coordinate space of the SafeArea that holds both them and the home panel.
  /// `_buildMapModeButton` and `_buildShareShortcut` place themselves with
  /// these same numbers. The map button is an IconButton (48 dp on a phone)
  /// inside a TvFocusDecoration border.
  static const double mapButtonLeft = 10;
  static const double mapButtonTop = 8;
  static const double mapButtonSize = 48;
  static const double mapButtonBorder = 1;
  static const double shareButtonRight = 10;
  static const double shareButtonTop = 8;
  static const double shareButtonSize = 56;

  /// Space kept between the header box and a floating button. Zero: the box
  /// has about 10 dp of empty margin left and right of the artwork already,
  /// and at 384 dp the header sits 1 dp clear of the share button, which must
  /// not be pushed.
  static const double buttonGap = 0;

  /// How far to move the header so its box stays clear of the floating
  /// [obstacles] (already positioned in the same space as [header], the
  /// header's box as laid out today). Returns zero when nothing overlaps, so a
  /// wide enough window keeps the header exactly where it is. It prefers a
  /// sideways shift to the right (which needs [spareRight] dp of room in the
  /// slot); otherwise it moves the header down past the obstacles.
  static ({double dx, double dy}) clearance({
    required Rect header,
    required Iterable<Rect> obstacles,
    required double spareRight,
  }) {
    final padded = [for (final o in obstacles) o.inflate(buttonGap)];
    final hits = padded.where((o) => o.overlaps(header)).toList();
    if (hits.isEmpty) return (dx: 0, dy: 0);
    var dx = 0.0;
    for (final o in hits) {
      if (o.center.dx < header.center.dx) {
        dx = dx > o.right - header.left ? dx : o.right - header.left;
      }
    }
    if (dx > 0 && dx <= spareRight) {
      final moved = header.shift(Offset(dx, 0));
      if (!padded.any((o) => o.overlaps(moved))) return (dx: dx, dy: 0);
    }
    var dy = 0.0;
    for (final o in hits) {
      dy = dy > o.bottom - header.top ? dy : o.bottom - header.top;
    }
    return (dx: 0, dy: dy);
  }

  @override
  Widget build(BuildContext context) {
    // FittedBox(scaleDown): at 250 dp or wider this is exactly the fixed
    // 250 x 84 header below. Narrower than that (a 270 dp window leaves about
    // 220 dp), the logo, wordmark and subtitle scale down together with the
    // aspect ratio kept, instead of the subtitle and wordmark being clipped.
    return FittedBox(
      fit: BoxFit.scaleDown,
      child: SizedBox(
        width: logoWidth,
        height: bandHeight,
        child: Stack(
          clipBehavior: Clip.hardEdge,
          children: [
            Positioned(
              left: 0,
              top: -bandTop,
              width: logoWidth,
              height: logoHeight,
              child: Image.asset(
                'assets/icon/app_icon.webp',
                width: logoWidth,
                height: logoHeight,
                fit: BoxFit.contain,
              ),
            ),
            Positioned(
              left: _wordmarkLeft,
              top: _subtitleTop - bandTop,
              width: _wordmarkWidth,
              height: _subtitleHeight,
              child: FittedBox(
                fit: BoxFit.scaleDown,
                child: Text(
                  subtitle,
                  key: const Key('home_brand_subtitle'),
                  maxLines: 1,
                  textAlign: TextAlign.center,
                  style: const TextStyle(
                    color: Color(0xFF4B5563),
                    fontSize: 11,
                    fontWeight: FontWeight.w500,
                    letterSpacing: 0.3,
                    height: 1.2,
                  ),
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }
}

