class _VpnDashboardBodyState extends State<VpnDashboardBody>
    with WidgetsBindingObserver {
  static const _methodChannel = MethodChannel('wins_vpn/tunnel');
  // v3 nests key pairs by account scope (see _clientKeyScopeToken) instead of
  // storing one unscoped pair for the whole install. Without this, switching
  // the logged-in account on one install (shared device, or free access ->
  // paid) silently reused the previous account's WireGuard key, which can
  // collide with another account's key on a shared Double VPN core peer.
  static const String _clientKeyPairFormat = 'wireguard-x25519-v3';
  static const Set<String> _sensitiveStateFileNames = <String>{
    'client_keypair.json',
    'calc_session.json',
    'calc_state.json',
    'install_id.txt',
    'node_cache.json',
    'pending_logout.json',
    'user_pin.txt',
    'vpn_config.txt',
    'vpn_settings.txt',
    'wins_vpn_restart_config.conf',
    // The winn/3 static identity of this device (winn3_device_key.dart).
    'winn3_keypair.json',
    'direct_udp_transport_memory.json',
  };
  // The Android service's copy of the Double VPN choice: "1" wanted, "0" not
  // wanted, anything else unknown. Deliberately NOT in the set above, which is
  // pinned byte for byte against the Apple allowlist and walked by loops that
  // run on every platform: only the Android native store knows this name.
  static const String _doubleVpnIntentRecord = 'route_intent.txt';
  Future<void> _doubleVpnIntentRecordQueue = Future<void>.value();
  bool _doubleVpnIntentWritesSealed = false;
  int _doubleVpnPreferenceRevision = 0;
  static const Set<String> _accountCleanupArtifacts = <String>{
    'vpn_config',
    'user_pin',
    'pending_logout',
    'vpn_settings',
    'restart_config',
    'activation_marker',
    'client_keys',
  };
  static const String _defaultProtocolLabel = 'Winn Protocol®';
  static const bool _forceXrayDiagnosticRequested =
      bool.fromEnvironment('WINS_FORCE_XRAY', defaultValue: false);
  static final bool _forceXrayForDiagnostics = diagnosticForceXrayEnabled(
    requested: _forceXrayDiagnosticRequested,
    releaseMode: kReleaseMode,
  );
  // MTU (2026-09-20 owner decision): 1280 everywhere for cellular-path
  // compatibility. The earlier 1440 setting was the IPv4-optimal size (inner +
  // 16 WG transport + 16 Poly1305 + 8 UDP + 20 IPv4 = exactly 1500, and 90*16
  // so WireGuard's padding multiple added nothing), but it depends on a clean
  // 1500 path with working PMTUD. Cellular carriers frequently violate both,
  // and a 1440 inner on those paths blackholes large packets. 1280 is the IPv6
  // minimum MTU and survives every access network; the throughput cost is 160
  // bytes per packet on the paths that did support 1440. This is the
  // CONFIGURED value: VpnTunnelService still caps it further for IPv6 outer
  // endpoints when the peer address requires it. See awgInterfaceMtuForEndpoint
  // there.
  static const int _directAwgMtu = 1280;
  static const int _stealthTransportMtu = 1280;
  static const int _defaultAwgJc = 2;
  static const int _defaultAwgJmin = 10;
  static const int _defaultAwgJmax = 30;
  static const String _compiledAppVersion = String.fromEnvironment(
    'WINS_APP_VERSION',
    defaultValue: '1.0.17',
  );
  // A-04 (Sol audit, 2026-08-28): the public-website define feeds
  // user-tap browser launches (update fallback, payment/social links). In a
  // release build it is constrained to the compiled first-party origins --
  // a build command must not be able to aim a shipped artifact's taps at an
  // arbitrary HTTPS origin. Debug/profile keep the override for staging.
  static const String _publicWebsiteUrlDefine = String.fromEnvironment(
    'WINS_PUBLIC_WEBSITE_URL',
    defaultValue: '',
  );
  static String _resolvePublicWebsiteUrl() {
    const fallback = 'https://winsvpn.org';
    final value = _publicWebsiteUrlDefine.trim();
    if (value.isEmpty) return fallback;
    if (!kReleaseMode) return value;
    final uri = Uri.tryParse(value);
    final allowed = {
      'winsvpn.org',
      'www.winsvpn.org',
      'winsvpn.com',
      'www.winsvpn.com',
    };
    if (uri != null &&
        uri.scheme == 'https' &&
        uri.port == 443 &&
        uri.userInfo.isEmpty &&
        allowed.contains(uri.host.toLowerCase())) {
      return value;
    }
    assert(
      false,
      'WINS_PUBLIC_WEBSITE_URL is constrained to first-party origins in '
      'release builds (A-04); the define was ignored.',
    );
    return fallback;
  }

  static final String _publicWebsiteUrl = _resolvePublicWebsiteUrl();
  static const String _defaultAnnouncement =
      "Welcome to Win's VPN! Thank you for helping yourself by using our services!!";

  // ---------------------------------------------------------------------
  // Announcement signing: trusted public keys.
  //
  // The compiled defaults are the reviewed ceremony public keys in
  // lib/announcement_signature.dart (kReviewedAnnouncementPubkeyA1..A3),
  // where A1 is the key the hub signs with and A2/A3 are the pre-generated
  // offline successors; see that file for provenance and the
  // WINS_ANNOUNCE_PUBKEY_A* dart-define override mechanism. The matching
  // private keys never leave the hub.
  //
  // ENFORCEMENT IS THE DEFAULT. The verifier is enforcing whenever any
  // real key is compiled in, and the reviewed keys ARE compiled in by
  // default -- a build that clears every slot via defines is the only
  // non-enforcing build, which is what keeps the dev/test paths on their
  // old behaviour without weakening the shipped app. There is no build
  // that both enforces and carries fake keys, and no build that carries
  // real keys but forgets to enforce.
  //
  // ROLLOUT ORDER IS LOAD-BEARING: the hub must be serving signed envelopes
  // BEFORE any enforcing build reaches users. Under the Fable 5.1 ruling
  // (IA-CP-06, 2026-09-29) announcements are signed OFFLINE like descriptors:
  // the operator signs with the a1 private key on an offline machine, the hub
  // verifies the uploaded envelope against the a1..a3 PUBLIC keys, refuses a
  // non-increasing `seq`, and serves it verbatim. No announcement private key
  // is ever installed on the hub.
  static const bool _externalPaymentLinksEnabled = bool.fromEnvironment(
    'WINS_ENABLE_EXTERNAL_PAYMENT_LINKS',
    defaultValue: false,
  );
  static const bool _googlePlayBuild = bool.fromEnvironment(
    'WINS_GOOGLE_PLAY_BUILD',
    defaultValue: false,
  );
  // A-03 (audits 2026-08-28): live smoke and leak-audit behavior is a TEST
  // harness, never a distribution capability. These defines could
  // automatically accept legal state, log into free access, connect, probe,
  // or start high-volume speed traffic with zero user action -- a stale or
  // hostile build define must not be able to arm that in a RELEASE artifact.
  // Release builds resolve every one of them to disabled regardless of the
  // build command; debug/profile keep them for the live-test lanes.
  static const bool _appleLiveTunnelSmokeEnabled = !kReleaseMode &&
      bool.fromEnvironment('WINS_APPLE_LIVE_TUNNEL_SMOKE', defaultValue: false);
  static const int _appleLiveTunnelSmokeTimeoutSeconds = int.fromEnvironment(
    'WINS_APPLE_LIVE_TUNNEL_SMOKE_TIMEOUT_SECONDS',
    defaultValue: 120,
  );
  static const String _appleLiveTunnelSmokePin = String.fromEnvironment(
    'WINS_APPLE_LIVE_TUNNEL_SMOKE_PIN',
    defaultValue: '',
  );
  static const bool _appleLiveTunnelSmokeDoubleVpnEnabled = !kReleaseMode &&
      bool.fromEnvironment(
        'WINS_APPLE_LIVE_TUNNEL_SMOKE_DOUBLE_VPN',
        defaultValue: false,
      );
  static const bool _appleExternalLeakAuditEnabled = !kReleaseMode &&
      bool.fromEnvironment(
        'WINS_APPLE_EXTERNAL_LEAK_AUDIT',
        defaultValue: false,
      );
  static const String _appleExternalLeakAuditUrls = String.fromEnvironment(
    'WINS_APPLE_EXTERNAL_LEAK_AUDIT_URLS',
    defaultValue: '',
  );
  static const int _appleExternalLeakAuditMinimumEndpoints =
      int.fromEnvironment(
    'WINS_APPLE_EXTERNAL_LEAK_AUDIT_MINIMUM_ENDPOINTS',
    defaultValue: 2,
  );
  static const bool _speedTestSmokeEnabled = !kReleaseMode &&
      bool.fromEnvironment('WINS_SPEED_TEST_SMOKE', defaultValue: false);

  // -------------------------------------------------------------------
  // Network-observable identity. See
  // docs/handoff/CONTROL_PLANE_NEUTRAL_DOMAIN_MIGRATION_20260806.md.
  //
  // A neutral control-plane domain is defeated by anything else on the wire
  // that still says "Win's VPN", so the brand-bearing strings the client emits
  // are build-time values rather than literals. Both defaults below preserve
  // today's behaviour exactly, except where noted on the route probe.
  // -------------------------------------------------------------------

  /// User-Agent on every control-plane request. Travels inside TLS, so this is
  /// not a network-observable leak -- it is a leak to whatever terminates that
  /// TLS (the CDN, and anyone who compels it) and a plaintext brand string in
  /// the binary. Default unchanged; no server-side code reads it.
  static const String _clientUserAgent = String.fromEnvironment(
    'WINS_CLIENT_USER_AGENT',
    defaultValue: 'WinsVPN-App/1.0',
  );

  /// User-Agent on the Xray WebSocket preflight, and the one genuinely
  /// **cleartext** brand string the client emits.
  ///
  /// The preflight runs pre-tunnel against the data-plane node, and when the
  /// hub specifies `security: none` (the port-80 transport) there is no TLS
  /// around it -- so `User-Agent: WinsVPN-Route-Probe/1.0` went out in the
  /// clear, on a connection whose hostname is otherwise neutral. That single
  /// header undid the neutral data-plane domain for every port-80 user.
  ///
  /// **The empty default is the fix, and it is deliberately a behaviour
  /// change.** Empty omits the header entirely, which is also what the real
  /// Xray transport that follows sends -- so the preflight stops being
  /// distinguishable from the tunnel it is preflighting. HTTP/1.1 does not
  /// require User-Agent and no node-side rule matches on it; if one ever does,
  /// this define restores the old string without a code change.
  ///
  /// A-03 (audits 2026-08-28): the define is DEBUG/PROFILE ONLY. In a release
  /// build the value is forced empty no matter what the build command set --
  /// a release configuration mistake must never re-arm a product-identifying
  /// cleartext header.
  static const String _routeProbeUserAgent = kReleaseMode
      ? ''
      : String.fromEnvironment('WINS_ROUTE_PROBE_USER_AGENT', defaultValue: '');

  /// Canonical URL of the published privacy policy. Transmitted to the hub in
  /// legal-acceptance payloads and shown in the consent UI, so a neutral build
  /// must be able to name a neutral copy. Default unchanged.
  static const String _privacyPolicyUrl = String.fromEnvironment(
    'WINS_PRIVACY_POLICY_URL',
    defaultValue: 'https://www.winsvpn.org/privacy/',
  );
