  final String _secSalt = "W1NS_V12_SALT_2024";

  String _reveal(String scrambled) {
    try {
      List<int> s = base64.decode(scrambled);
      List<int> k = utf8.encode(_secSalt);
      return utf8.decode(List.generate(s.length, (i) => s[i] ^ k[i % k.length]),
          allowMalformed: true);
    } catch (e) {
      return defaultGatewayBase;
    }
  }

  String _sha256Hex(String value) =>
      crypto.sha256.convert(utf8.encode(value)).toString();

  String get _bundledLegalDocumentHash => _sha256Hex(_legalFallbackBody);

  String? _stringValue(Map<String, dynamic> data, List<String> keys) {
    for (final key in keys) {
      final value = data[key];
      if (value != null && value.toString().trim().isNotEmpty)
        return value.toString();
    }
    return null;
  }

  /// Verifier built from the compiled-in public key set (see
  /// [AnnouncementVerifier.fromCompiledDefines]). In a release build an
  /// empty or malformed keyring throws at construction, so a release
  /// artifact can never construct a non-enforcing verifier; the non-enforcing
  /// state exists only for debug/profile builds whose defines explicitly
  /// emptied every slot. Constructed eagerly (not late) so a misprovisioned
  /// release fails hard at State construction instead of lazily inside the
  /// first announcement poll.
  final AnnouncementVerifier _announcementVerifier =
      AnnouncementVerifier.fromCompiledDefines();

  /// The single HTTP client for gateway/nodes/announcement control-plane
  /// requests, with the compiled CA anchor set enforced (see
  /// lib/control_plane_pinning.dart). Requests to hosts that are not part of
  /// the pinned control plane (the GitHub recovery record, api.ipify.org,
  /// the Cloudflare geo-scene fallback, speed-test streams) deliberately
  /// keep using the stock clients: the pinned client fail-closes on any
  /// host it does not carry pins for.
  // The connect-and-verify ceiling matches the hub window's per-attempt
  // timeout: a permit held past the point the window abandoned the attempt
  // only blocks other walks (hub_request_window.dart:353-355).
  late final http.Client _controlPlaneClient = createPinnedControlPlaneClient(
    connectionVerificationTimeout:
        const HubRequestWindowPolicy().perRequestTimeout,
  );

  /// The announcement text to display for a hub response, or null to leave the
  /// current one alone.
  ///
  /// This is the single choke point for all four polled routes. Every
  /// ingestion path goes through it, so a route that returns a signed
  /// announcement and a route that returns bare text can never leave the app
  /// flipping between valid and invalid depending on which call happened last.
  Future<String?> _resolveAnnouncement(Map<String, dynamic> data) async {
    final accountEpoch = _accountSessionEpoch.current;
    final String? plaintext = _stringValue(data, ['announcement']);
    if (!_announcementVerifier.enforcing) {
      // No public key compiled in. Only reachable in debug/profile builds
      // whose defines explicitly emptied every slot (release builds throw at
      // verifier construction); keep the pre-signing behaviour for them.
      // Defense in depth: a release build that somehow reached this branch
      // must never display unverified text.
      if (kReleaseMode) {
        throw StateError(
          'non-enforcing announcement verifier in a release build: '
          'refusing to display unverified announcement text',
        );
      }
      return plaintext;
    }
    final result = await _announcementVerifier.verify(
      data,
      minimumSequence: _announcementSeqFloor,
    );
    if (!_accountEpochIsCurrent(accountEpoch)) return null;
    final envelope = result.envelope;
    if (envelope == null) {
      _debugLog('Announcement not displayed: ${result.rejection}');
      // Fail closed onto the bundled default. That string is compiled into the
      // signed app, so it is trusted by construction and needs no signature.
      // The cost is a denial-of-announcements if someone can strip the field;
      // the alternative is accepting forged text, which is strictly worse.
      return _defaultAnnouncement;
    }
    if (envelope.sequence < _announcementSeqFloor) {
      // Verified against a floor that a newer verification has since raised.
      // Never display or persist the older text; keep the newest.
      return _latestVerifiedAnnouncementText ?? _defaultAnnouncement;
    }
    if (envelope.sequence > _announcementSeqFloor) {
      _announcementSeqFloor = envelope.sequence;
      unawaited(
          _writeVpnRuntimeSetting('announcement_seq_floor', envelope.sequence));
    }
    // WVP-005: persist whatever the restore-side verification needs -- the
    // signed envelope exactly as the hub emitted it -- so a relaunch can
    // re-verify the last announcement instead of trusting a plaintext copy
    // that any process with write access to vpn_settings.txt could replace.
    final Object? signedEnvelope = data['announcement_signed'];
    if (signedEnvelope is Map && signedEnvelope.isNotEmpty) {
      unawaited(_writeVpnRuntimeSetting('server_announcement_signed',
          Map<String, dynamic>.from(signedEnvelope)));
    }
    _latestVerifiedAnnouncementText = envelope.text;
    return envelope.text;
  }

  /// WVP-005: restores the last announcement through the SAME verification
  /// path hub-fetched announcements take ([_resolveAnnouncement], i.e.
  /// Ed25519 over the signed envelope plus the persisted replay floor).
  ///
  /// The persisted record must carry the `announcement_signed` envelope the
  /// hub emits. A missing, unsigned, malformed or tampered record is
  /// DISCARDED (logged once per launch) and the compiled
  /// [_defaultAnnouncement] replaces it: its bytes come from the signed
  /// build, never from the disk, so an attacker who can write
  /// vpn_settings.txt cannot make a single text byte render.
  Future<String> _restoreAnnouncementForDisplay(
      Map<String, dynamic> settingsData) async {
    final Object? rawRecord = settingsData['server_announcement_signed'];
    if (rawRecord is! Map || rawRecord.isEmpty) {
      if (!_announcementRestoreDiscardLogged) {
        _debugLog(
            'Persisted announcement record is unsigned or missing; discarded '
            'and falling back to the compiled default announcement.');
        _announcementRestoreDiscardLogged = true;
      }
      return _defaultAnnouncement;
    }
    final String? resolved = await _resolveAnnouncement(
        <String, dynamic>{'announcement_signed': rawRecord});
    if (resolved == null) {
      if (!_announcementRestoreDiscardLogged) {
        _debugLog(
            'Persisted announcement record failed verification; discarded '
            'and falling back to the compiled default announcement.');
        _announcementRestoreDiscardLogged = true;
      }
      return _defaultAnnouncement;
    }
    return resolved;
  }

  bool _accountEpochIsCurrent(int expectedEpoch) =>
      _accountSessionEpoch.isCurrent(expectedEpoch);

  Future<int?> _beginAccountActivation() async {
    final activationAllowed =
        await _accountCleanupStartupBarrier.activationAllowed();
    if (!activationAllowed) {
      _forcePendingAccountCleanupUi();
      return null;
    }
    if (_settingsWritesSealed) {
      _showFeedback('Account cleanup is still in progress. Try again shortly.');
      return null;
    }
    _settingsWritesSealed = false;
    _doubleVpnIntentWritesSealed = false;
    final epoch = _accountSessionEpoch.bump();
    _hubCancellations.notifyGenerationChanged();
    return epoch;
  }

  int _beginAccountTeardown() {
    _cancelSpeedTest();
    _settingsWritesSealed = true;
    _doubleVpnIntentWritesSealed = true;
    final epoch = _accountSessionEpoch.bump();
    _hubCancellations.notifyGenerationChanged();
    return epoch;
  }

  Future<void> _applyAccountSyncData(
      Map<String, dynamic> data, int expectedEpoch) async {
    if (!_accountEpochIsCurrent(expectedEpoch)) return;
    // Pre-positioned discovery record, if this response carried one. Rides the
    // poll the client already makes -- no extra request, no new cadence, no
    // new shape -- and is silent to the user whatever it decides.
    await _ingestPrePositionedDiscoveryRecord(data, expectedEpoch);
    if (!_accountEpochIsCurrent(expectedEpoch)) return;
    final String? announcement = await _resolveAnnouncement(data);
    if (!_accountEpochIsCurrent(expectedEpoch)) return;
    final String? localizedAnnouncement =
        announcement != null ? _localizedAnnouncement(announcement) : null;
    final String? expiration =
        _stringValue(data, ['expiration_date', 'expirationdate']);
    final String? referralCode =
        _stringValue(data, ['referral_code', 'referralcode']);
    final String? referralLink =
        _stringValue(data, ['referral_link', 'referrallink']);
    final String? referralBackupLink =
        _stringValue(data, ['referral_backup_link', 'referralbackuplink']);

    void applyValues() {
      if (localizedAnnouncement != null) {
        _serverAnnouncement = localizedAnnouncement;
      }
      if (expiration != null) _expirationDate = expiration;
      if (referralCode != null) _referralCode = referralCode;
      if (referralLink != null) _referralLink = referralLink;
      if (referralBackupLink != null) _referralBackupLink = referralBackupLink;
    }

    if (mounted) {
      setState(applyValues);
    } else {
      applyValues();
    }
    if (localizedAnnouncement != null) {
      unawaited(_maybeNotifyServerAnnouncement(localizedAnnouncement));
    }
  }

  Map<String, dynamic> _mapValue(Map<String, dynamic> data, List<String> keys) {
    for (final key in keys) {
      final value = data[key];
      if (value is Map) return Map<String, dynamic>.from(value);
    }
    return <String, dynamic>{};
  }

  bool _boolValue(dynamic value) {
    if (value is bool) return value;
    return value.toString().toLowerCase() == 'true';
  }

  bool _boolDefaultTrue(dynamic value) {
    if (value == null) return true;
    if (value is bool) return value;
    final lower = value.toString().trim().toLowerCase();
    return !(lower == 'false' ||
        lower == '0' ||
        lower == 'no' ||
        lower == 'off' ||
        lower == 'disabled');
  }

  List<String> _stringListValue(dynamic value) {
    if (value is List) {
      return value
          .map((item) => _hostnameOnly(item.toString()))
          .where((item) => item.isNotEmpty)
          .toSet()
          .toList();
    }
    if (value is String && value.trim().isNotEmpty) {
      return value
          .split(',')
          .map(_hostnameOnly)
          .where((item) => item.isNotEmpty)
          .toSet()
          .toList();
    }
    return <String>[];
  }

  String _normalizeProtocolLabel(dynamic value) {
    final label = (value ?? '').toString().trim();
    if (label.isEmpty) return _defaultProtocolLabel;
    final lower = label.toLowerCase();
    if (lower == 'smart protocol' ||
        lower == 'direct awg' ||
        lower == 'tcp stealth') {
      return _defaultProtocolLabel;
    }
    return label.replaceAll('Smart Protocol', _defaultProtocolLabel);
  }

  /// The session-detail line: negotiated Winn Protocol version + live
  /// transport, already translated. Empty when there is no live session, so
  /// the widget renders nothing rather than a claim. All decisions live in
  /// lib/winn_session_descriptor.dart so they are testable without a widget.
  /// A wanted Double VPN that is running on one hop, for as long as the tunnel
  /// is up. Bound to the session, not to the cached config: the latch is set
  /// at commit (_routeIsSingleHopAtCommit) and replaced by the Android
  /// service's own answer (_adoptNativeDoubleVpnMarker), so the dashboard and
  /// the notification read one fact. Until either has spoken (a restored
  /// session on a platform with no service reading) it falls back to the
  /// restored config. Every path that can start a single-hop tunnel
  /// (the cached lead, the TCP leg, any later one) commits through
  /// _startTunnelCandidate, so none of them is silent.
  bool get _doubleVpnSingleHopSession =>
      _isConnected &&
      (_committedDoubleVpnSingleHop ??
          doubleVpnRequestedButSingleHop(
            doubleVpnRequested: _isDoubleVpnRequested,
            config: _cachedVpnConfig,
          ));

  /// Whether the session that just committed is one hop under a Double VPN
  /// request. On Android the service decides this (the route its saved config
  /// says it has, plus the user's current choice) and posts the notification
  /// from the same answer, so the dashboard asks it instead of recomputing and
  /// the two cannot disagree. Elsewhere, or when the service does not answer,
  /// the same rule is applied here to the config that committed.
  Future<bool> _routeIsSingleHopAtCommit(
      Map<String, dynamic> committedConfig) async {
    Object? reported;
    if (Platform.isAndroid) {
      reported = (await _latestTunnelReadiness())?['double_vpn_single_hop'];
    }
    return doubleVpnCommittedSingleHop(
      doubleVpnRequested: _isDoubleVpnRequested,
      config: committedConfig,
      nativeReported: reported,
    );
  }

  /// Takes the service's own marker from a readiness reading, for a service
  /// this process did not start (adopted after a restart of the app) or that
  /// the system restarted from its saved config. A reading that is obsolete,
  /// or that arrives while a switch is preparing, is dropped.
  void _adoptNativeDoubleVpnMarker(
    Map<dynamic, dynamic> readiness, {
    required int displayGeneration,
    required int accountEpoch,
  }) {
    final reported = readiness['double_vpn_single_hop'];
    if (reported is! bool ||
        !mounted ||
        _isTunnelTransitioning ||
        !_nativeReadingIsCurrent(displayGeneration, accountEpoch) ||
        _committedDoubleVpnSingleHop == reported) {
      return;
    }
    setState(() => _committedDoubleVpnSingleHop = reported);
  }

  String get _winnSessionDetailLine => winnSessionDetail(
        version: winnSessionVersion(
          isConnected: _isConnected,
          rawProtocolVersion: _activeProtocolVersion,
        ),
        transport: winnSessionTransport(
          isConnected: _isConnected,
          stealthActive: _isCensorshipModeActive,
        ),
        translate: _t,
      );

  String _hostnameOnly(String value) {
    var cleaned = value.trim();
    if (cleaned.isEmpty) return '';
    try {
      final parsed = Uri.parse(cleaned);
      if (parsed.hasScheme && parsed.host.isNotEmpty) return parsed.host;
    } catch (_) {}
    cleaned = cleaned.split('/').first.trim();
    if (cleaned.startsWith('[') && cleaned.contains(']')) {
      return cleaned.substring(1, cleaned.indexOf(']'));
    }
    final parts = cleaned.split(':');
    if (parts.length == 2 && int.tryParse(parts.last) != null) {
      return parts.first.trim();
    }
    return cleaned;
  }

  ({String host, int port})? _hostPortValue(dynamic value,
      {int defaultPort = 443}) {
    var cleaned = (value ?? '').toString().trim();
    if (cleaned.isEmpty) return null;
    try {
      final parsed = Uri.parse(cleaned);
      if (parsed.hasScheme && parsed.host.isNotEmpty) {
        final port = parsed.hasPort ? parsed.port : defaultPort;
        return port > 0 && port <= 65535
            ? (host: parsed.host, port: port)
            : null;
      }
    } catch (_) {}
    cleaned = cleaned.split('/').first.trim();
    if (cleaned.startsWith('[') && cleaned.contains(']')) {
      final end = cleaned.indexOf(']');
      final host = cleaned.substring(1, end);
      final suffix = cleaned.substring(end + 1);
      final port = suffix.startsWith(':')
          ? int.tryParse(suffix.substring(1)) ?? defaultPort
          : defaultPort;
      return host.isNotEmpty && port > 0 && port <= 65535
          ? (host: host, port: port)
          : null;
    }
    final lastColon = cleaned.lastIndexOf(':');
    if (lastColon > 0) {
      final maybePort = int.tryParse(cleaned.substring(lastColon + 1));
      if (maybePort != null && maybePort > 0 && maybePort <= 65535) {
        return (host: cleaned.substring(0, lastColon), port: maybePort);
      }
    }
    return cleaned.isNotEmpty ? (host: cleaned, port: defaultPort) : null;
  }

  /// Headers for control-plane JSON requests.
  ///
  /// This deliberately does NOT set a `Host` header. It once took an
  /// `includeHost` flag that overrode `Host` with `defaultHubHost` while TLS
  /// negotiated a different SNI name -- domain fronting. No call site ever
  /// passed it, and it was removed on 2026-08-03 rather than left dormant.
  ///
  /// Domain fronting has not worked since 2018: Google and Amazon CloudFront
  /// both disabled it, and Cloudflare enforces agreement between the SNI name
  /// and the Host header. Reviving it would not evade anything and would get
  /// requests rejected by any modern CDN, so the risk was a future maintainer
  /// finding the flag and assuming it was a working circumvention tool.
  /// Rationale in docs/CONTROL_PLANE_BOOTSTRAP_RESILIENCE.md section 6.
  Map<String, String> _jsonHeaders() {
    final userAgent = _clientUserAgent.trim();
    return <String, String>{
      'Content-Type': 'application/json',
      'Accept': 'application/json',
      // Omitted entirely when the define is blanked, rather than sent empty:
      // an empty User-Agent is itself an unusual, matchable value.
      if (userAgent.isNotEmpty) 'User-Agent': userAgent,
    };
  }

  // Redaction choke point for every debug log line. This line is the reason a
  // tunnel/session fact written by a developer (server hostname, endpoint IP,
  // public key, user identifier, connection timestamp) never reaches the device
  // log: it is stripped at the sink regardless of which caller emitted it, so a
  // future log line that forgets its own redaction still ships clean. The log
  // is assert-gated (debug-only) already, but a debug build is still a searchable
  // artifact on a seized device, so the value is scrubbed even there.
  void _debugLog(String message) {
    if (kReleaseMode || !_diagnosticsEnabled) return;

    final clean = redactLogSecrets(message);
    assert(() {
      debugPrint(clean);
      return true;
    }());
  }

  String _redactedTunnelFailureText(Object error) {
    return redactTunnelFailureText(error);
  }

  Future<void> _persistTunnelFailureDiagnostic(
      String protocolLabel, Object error) async {
    // BUILD-SETTINGS LANE (2026-08-10). The diagnostics toggle owns this gate:
    // when the user has turned diagnostics off, a failure must not be written
    // to disk at all, and an existing copy is already cleared by the setter.
    if (!_diagnosticsEnabled) return;
    try {
      final directory = await _appDocumentsDirectory();
      final file = File('${directory.path}/last_tunnel_failure.json');
      await file.writeAsString(jsonEncode({
        'schema_version': 1,
        'recorded_at_utc': DateTime.now().toUtc().toIso8601String(),
        'platform': Platform.operatingSystem,
        'protocol': _normalizeProtocolLabel(protocolLabel),
        'secret_material_redacted': true,
        'failure': _redactedTunnelFailureText(error),
      }));
    } catch (_) {}
  }

  Future<void> _clearTunnelFailureDiagnostic() async {
    try {
      final directory = await _appDocumentsDirectory();
      final file = File('${directory.path}/last_tunnel_failure.json');
      if (await file.exists()) await file.delete();
    } catch (_) {}
  }

  // --- Direct UDP transport memory ---------------------------------------
  //
  // The direct AmneziaWG leg is the only transport that reaches a gateway on
  // its real address: Cloudflare cannot proxy arbitrary UDP, so that port
  // carries no source restriction, while TCP 80/443 are filtered to the
  // Cloudflare ranges and are invisible to a raw-IP probe. Leading with it on
  // every connect therefore emits a self-identifying datagram from the user's
  // real address to the node's real address, over and over, including on
  // networks that have already been shown to swallow it.
  //
  // These four helpers remember where that leg did and did not work so the
  // connect order can be flipped on the networks where it is only cost. They
  // never remove a transport -- see the safety contract in
  // direct_udp_transport_memory.dart. Every one of them swallows its own
  // errors: this is an optimisation, and a broken optimisation must degrade to
  // the shipping order, never to a connect that cannot start.
  static const String _directUdpTransportMemoryFileName =
      'direct_udp_transport_memory.json';

  /// A permission-free fingerprint of the network this device is attached to.
  /// Interface name plus IPv4 /24, hashed by [directUdpNetworkScope] so nothing
  /// address-shaped is ever written to disk. No plugin, no location permission,
  /// no new dependency.
  Future<String> _directUdpNetworkScope() async {
    try {
      final interfaces = await NetworkInterface.list(
        includeLoopback: false,
        includeLinkLocal: false,
        type: InternetAddressType.IPv4,
      );
      final tokens = <String>[];
      for (final interface in interfaces) {
        for (final address in interface.addresses) {
          final octets = address.address.split('.');
          if (octets.length != 4) continue;
          tokens
              .add('${interface.name}/${octets[0]}.${octets[1]}.${octets[2]}');
        }
      }
      return directUdpNetworkScope(tokens);
    } catch (_) {
      return kDirectUdpUnknownScope;
    }
  }

  Future<DirectUdpTransportMemory> _readDirectUdpTransportMemory() async {
    try {
      final encoded =
          await _readSensitiveText(_directUdpTransportMemoryFileName);
      if (encoded == null) return DirectUdpTransportMemory.empty;
      return DirectUdpTransportMemory.fromJson(
        jsonDecode(encoded),
        now: DateTime.now().toUtc(),
      );
    } catch (_) {
      return DirectUdpTransportMemory.empty;
    }
  }

  /// Whether the direct UDP leg should run after the CDN-fronted TCP legs on
  /// this network instead of before them. False -- the shipping order -- is the
  /// answer for every uncertain case.
  Future<bool> _directUdpIsDemotedForNetwork(String scope) async {
    try {
      final memory = await _readDirectUdpTransportMemory();
      return memory.shouldDemoteDirectUdp(
        scope: scope,
        now: DateTime.now().toUtc(),
      );
    } catch (_) {
      return false;
    }
  }

  Future<void> _recordDirectUdpOutcome({
    required String scope,
    required bool reachable,
  }) async {
    try {
      final now = DateTime.now().toUtc();
      final memory = await _readDirectUdpTransportMemory();
      final updated = reachable
          ? memory.recordDirectUdpReachable(scope: scope, now: now)
          : memory.recordDirectUdpUnreachable(scope: scope, now: now);
      if (updated.isEmpty) {
        await _deleteSensitiveText(_directUdpTransportMemoryFileName);
        return;
      }
      final encoded = jsonEncode(updated.toJson());
      await _writeSensitiveText(_directUdpTransportMemoryFileName, encoded);
      if (await _readSensitiveText(_directUdpTransportMemoryFileName) != encoded) {
        throw StateError('Transport memory failed durable read-back');
      }
    } catch (_) {}
  }

  void _emitAppleLiveTunnelSmokeHarnessLine(String message) {
    debugPrint(message);
    try {
      stdout.writeln(message);
    } catch (_) {}
  }

  /// Posts [verifyRequest] across [urls] through the staggered hub window and
  /// returns the first authenticated response, by arrival, that [rejectionOf]
  /// accepts; otherwise the free-verify terminal marker, or null.
  ///
  /// [rejectionOf] runs inside each attempt, BEFORE the window may declare a
  /// winner, so an invalid reply loses and a later valid one can still win. It
  /// must not persist anything.
  ///
  /// [alreadyAttempted] lets a second pass skip fronts the first pass already
  /// tried: the recovery record can only reorder the compiled list, so the old
  /// second pass repeated the same 29 fronts. [budget] is one absolute budget
  /// shared by every pass of one operation. Result-derived flags are committed
  /// after the walk, and only while [shouldCancel] still says the operation is
  /// current.
  Future<Map<String, dynamic>?> _postAuthenticatedBatchedFallback(
    List<String> urls,
    VerifyRequestContext verifyRequest, {
    required HubOperationBudget budget,
    required Future<String?> Function(Map<String, dynamic> data) rejectionOf,
    Duration timeout = const Duration(seconds: 4),
    Set<String>? alreadyAttempted,
    bool Function()? shouldCancel,
  }) async {
    final candidates = urls
        .map((url) => url.trim())
        .where((url) =>
            url.isNotEmpty && !(alreadyAttempted?.contains(url) ?? false))
        .toList();
    if (candidates.isEmpty || budget.spent) return null;
    if (shouldCancel?.call() == true) return null;
    final cancellation = _hubCancellations.track(shouldCancel ?? () => false);

    String previewBody(String value) {
      final compact = value.replaceAll(RegExp(r'\s+'), ' ').trim();
      if (compact.length <= 180) return compact;
      return '${compact.substring(0, 180)}...';
    }

    final outcome = await runHubRequestWindow<Map<String, dynamic>>(
      urls: candidates,
      shouldCancel: shouldCancel,
      cancellation: cancellation,
      preference: _hubOriginPreference,
      policy: HubRequestWindowPolicy(
        perRequestTimeout: timeout,
        totalDeadline: budget.remaining,
      ),
      attempt: (url, abort) async {
        try {
          final response = await sendHubRequest(
            _controlPlaneClient,
            'POST',
            Uri.parse(url),
            abort: abort,
            headers: verifyRequest.headers,
            body: verifyRequest.body,
          );
          _noteWinn3KeyCollision(response, verifyRequest.body);
          final result =
              classifyFreeVerifyAttempt(response.statusCode, response.body);
          final candidate = result.value;
          if (result.verdict == HubAttemptVerdict.accepted &&
              candidate != null) {
            final rejection = await rejectionOf(candidate);
            if (rejection == null) return result;
            _debugLog('Gateway race rejected the reply through $url: '
                '$rejection');
            return const HubAttemptResult<Map<String, dynamic>>.rejected();
          }
          _debugLog(response.statusCode == 200
              ? 'Gateway race unauthenticated through $url'
              : 'Gateway race HTTP ${response.statusCode} through $url: '
                  '${previewBody(response.body)}');
          return result;
        } catch (e) {
          _debugLog('Gateway race failed through $url: $e');
          return const HubAttemptResult<Map<String, dynamic>>.rejected();
        }
      },
    );
    _hubCancellations.release(cancellation);
    alreadyAttempted?.addAll(outcome.started);
    if (outcome.deadlineReached) {
      _debugLog('Gateway walk reached its deadline after '
          '${outcome.started.length} of ${candidates.length} fronts');
    }
    if (outcome.cancelled || shouldCancel?.call() == true) return null;
    if (outcome.terminalKinds.contains('rate_limited')) {
      _lastGatewayRateLimited = true;
    }
    final accepted = outcome.value;
    if (accepted != null) return accepted;
    final terminal = freeVerifyTerminalByPriority(outcome.terminalKinds);
    return terminal == null
        ? null
        : <String, dynamic>{'_wins_free_verify_terminal': terminal};
  }

  /// The pre-winner checks for one authenticated /verify or /free/verify
  /// reply (hub_verify_candidate.dart). Normalization and key attachment are
  /// pure; nothing is persisted.
  Future<String?> _hubVerifyRejection(
    Map<String, dynamic> responseData, {
    required Map<String, String> clientKeys,
    required HubVerifyRequirements requirements,
  }) {
    final served = _mapValue(responseData, ['vpn_config', 'vpnconfig']);
    final normalized =
        _attachLocalClientKeys(_normalizeVpnConfig(served), clientKeys);
    return hubVerifyCandidateRejection(
      responseData: responseData,
      servedConfig: served,
      normalizedConfig: normalized,
      localClientPublicKey: clientKeys['public_key'] ?? '',
      localWinn3StaticPublic: clientKeys[kWinn3ClientKeysPublicEntry] ?? '',
      requirements: requirements,
    );
  }

  /// The raw key binding of one authenticated reply (AWG echo and winn/3
  /// echo/served private), checked on the served map before local keys are
  /// attached. Every path that accepts a reply runs this before it commits a
  /// staged identity or persists anything (Sol, N-1).
  String? _hubKeyBindingRejection(
    Map<String, dynamic> responseData,
    Map<String, String> clientKeys,
  ) =>
      hubVerifyKeyBindingRejection(
        servedConfig: _mapValue(responseData, ['vpn_config', 'vpnconfig']),
        localClientPublicKey: clientKeys['public_key'] ?? '',
        localWinn3StaticPublic: clientKeys[kWinn3ClientKeysPublicEntry] ?? '',
      );

  /// [_resolveDynamicEndpoints] inside what is left of one operation's budget.
  /// With nothing left it is not started and the compiled primary is used;
  /// if it outlasts the budget its answer is not waited for (the fetch itself
  /// is not cancelled).
  Future<Map<String, String>> _resolveDynamicEndpointsWithin(Duration budget) {
    Map<String, String> compiledPrimary() {
      final gateways = primaryStealthGateways;
      return <String, String>{
        'gateway': gateways.isNotEmpty
            ? gateways.first
            : gatewayBase(defaultGatewayBase),
      };
    }

    return runWithinBudget<Map<String, String>>(
      _resolveDynamicEndpoints,
      budget: budget,
      onExhausted: compiledPrimary,
    );
  }

  Future<DoubleVpnAssignmentAttempt<Map<String, dynamic>?>>
      _postDoubleVpnAssignmentRace(
    List<String> urls,
    VerifyRequestContext verifyRequest,
    Duration timeout, {
    int frontOffset = 0,
    HubCancellation? cancellation,
    void Function(int started)? onFrontsStarted,
  }) async {
    final candidates = urls.where((url) => url.trim().isNotEmpty).toList();
    if (candidates.isEmpty) {
      return const DoubleVpnAssignmentAttempt<Map<String, dynamic>?>(
        statusCode: 599,
        body: '',
        headers: {},
        value: null,
      );
    }
    // One attempt walks the fronts through the staggered hub window: the first
    // front at once, the next only after silence or an outright failure, and at
    // most three open. It used to post to every front (29) at the same instant.
    // All of them reach the same hub, and each Double request upserts the
    // assignment, syncs the exit peer and holds a hub worker for up to five
    // seconds waiting for the Core, so the burst queued behind itself past this
    // attempt's seven seconds (and put 29 SNI names on the wire at once).
    //
    // The walk starts where the previous attempt stopped ([frontOffset] is the
    // number of fronts already started in this poll), so a front that keeps
    // answering "preparing" (a stale or hostile edge) costs one attempt and not
    // every attempt, and fronts that never answer are all reached in turn.
    final first = frontOffset % candidates.length;
    final ordered = <String>[
      ...candidates.skip(first),
      ...candidates.take(first),
    ];
    DoubleVpnAssignmentAttempt<Map<String, dynamic>?>? authenticated;
    DoubleVpnAssignmentAttempt<Map<String, dynamic>?>? pending;
    DoubleVpnAssignmentAttempt<Map<String, dynamic>?>? terminal;
    final outcome = await runHubRequestWindow<http.Response>(
      urls: ordered,
      cancellation: cancellation,
      policy: HubRequestWindowPolicy(
        perRequestTimeout: timeout,
        // Ends before pollDoubleVpnAssignment's own timer for this attempt, so
        // a preparing reply collected here still reaches the retry loop.
        totalDeadline: timeout - const Duration(milliseconds: 250),
      ),
      attempt: (url, abort) async {
        try {
          final response = await sendHubRequest(
            _controlPlaneClient,
            'POST',
            Uri.parse(url),
            abort: abort,
            headers: verifyRequest.headers,
            body: verifyRequest.body,
          );
          _noteWinn3KeyCollision(response, verifyRequest.body);
          Map<String, dynamic>? decoded;
          if (!response.body.contains('<!DOCTYPE')) {
            try {
              final raw = jsonDecode(response.body);
              if (raw is Map) decoded = Map<String, dynamic>.from(raw);
            } catch (_) {}
          }
          final attempt = DoubleVpnAssignmentAttempt<Map<String, dynamic>?>(
            statusCode: response.statusCode,
            body: response.body,
            headers: response.headers,
            value: decoded,
          );
          if (response.statusCode == 200 &&
              decoded?['status'] == 'authenticated') {
            authenticated ??= attempt;
            return HubAttemptResult<http.Response>.accepted(response);
          }
          if (isDoubleVpnAssignmentPreparing(
            statusCode: response.statusCode,
            body: response.body,
            headers: response.headers,
          )) {
            pending ??= attempt;
            return const HubAttemptResult<http.Response>.terminal(
                'double_vpn_preparing');
          }
          // Authentication, maintenance, capacity, and generic Core
          // unavailability are authoritative failures, not polling signals. An
          // edge's own error page (not a JSON object) is this front failing,
          // not the hub's answer, so it moves on to the next front instead of
          // outranking a preparing reply.
          if (decoded != null &&
              const <int>{400, 401, 403, 409, 422, 429, 503}
                  .contains(response.statusCode)) {
            terminal ??= attempt;
            return const HubAttemptResult<http.Response>.terminal(
                'double_vpn_refused');
          }
        } catch (e) {
          _debugLog('Double VPN assignment request failed through $url: $e');
        }
        return const HubAttemptResult<http.Response>.rejected();
      },
    );
    onFrontsStarted?.call(outcome.started.length);
    final answered = authenticated ?? terminal ?? pending;
    if (answered != null) {
      if (identical(answered, pending) && candidates.length > 1 &&
          (frontOffset % candidates.length) + outcome.started.length <
              candidates.length) {
        // A preparing front can be stale or hostile. Keep walking other
        // fronts at the one-second floor while this sweep is incomplete.
        return DoubleVpnAssignmentAttempt<Map<String, dynamic>?>(
          statusCode: answered.statusCode,
          body: answered.body,
          headers: <String, String>{
            for (final entry in answered.headers.entries)
              if (entry.key.trim().toLowerCase() != 'retry-after')
                entry.key: entry.value,
            'retry-after': '1',
          },
          value: answered.value,
        );
      }
      return answered;
    }
    // No front reached the hub in this attempt. If every front has had its
    // turn since the poll began, that is final. Otherwise the next attempt
    // continues from where this one stopped, under the same one-second floor
    // and 90-second budget as any other retry.
    if (outcome.cancelled ||
        frontOffset + outcome.started.length >= candidates.length) {
      return const DoubleVpnAssignmentAttempt<Map<String, dynamic>?>(
        statusCode: 599,
        body: '',
        headers: {},
        value: null,
      );
    }
    return const DoubleVpnAssignmentAttempt<Map<String, dynamic>?>(
      statusCode: 503,
      body: '',
      headers: {'x-wins-error-code': doubleVpnAssignmentPreparingCode},
      value: null,
    );
  }

  Future<Map<String, dynamic>?> _postDoubleVpnAssignmentWithRetry(
    List<String> urls,
    VerifyRequestContext verifyRequest, {
    required bool doubleVpnRequested,
    bool Function()? shouldCancel,
  }) async {
    // The poll stops WAITING on cancellation or on its own timer; the window
    // inside an attempt must stop launching and abort what is in flight too,
    // or an account switch, disconnect or superseding connect leaves requests
    // with the old body and bearer going out and holds the shared transport
    // permits. So the same cancellation reaches the window, and is signalled
    // whichever way the poll ends.
    final cancellation = HubCancellation(shouldCancel);
    var frontsStarted = 0;
    late final DoubleVpnAssignmentRetryOutcome<Map<String, dynamic>?> outcome;
    try {
      outcome = await pollDoubleVpnAssignment<Map<String, dynamic>?, String>(
        doubleVpnRequested: doubleVpnRequested,
        requestIdentity: verifyRequest.body,
        shouldCancel: shouldCancel,
        requestTimeout: const Duration(seconds: 7),
        maximumElapsed: const Duration(seconds: 90),
        request: (identicalRequestBody, timeout) =>
            _postDoubleVpnAssignmentRace(
          urls,
          verifyRequest,
          timeout,
          frontOffset: frontsStarted,
          cancellation: cancellation,
          onFrontsStarted: (started) => frontsStarted += started,
        ),
      );
    } finally {
      cancellation.cancel();
    }
    if (outcome.cancelled || outcome.deadlineReached) return null;
    final attempt = outcome.attempt;
    if (attempt?.statusCode != 200 ||
        attempt?.value?['status'] != 'authenticated') {
      return null;
    }
    return attempt?.value;
  }

  String? _freeVerifyTerminalKind(Map<String, dynamic>? data) {
    final value = data?['_wins_free_verify_terminal'];
    return value is String && value.trim().isNotEmpty ? value.trim() : null;
  }

  bool _showFreeVerifyTerminalFeedback(Map<String, dynamic>? data) {
    final terminal = _freeVerifyTerminalKind(data);
    if (terminal == null) return false;
    switch (terminal) {
      case 'identity_collision':
        _showFeedback(
            'Free-device identity conflict. Please reinstall or contact support.');
        break;
      case 'maintenance':
        _showFeedback(
            'The free service is undergoing maintenance. Please try again soon.');
        break;
      case 'disabled':
        _showFeedback('Free access is currently disabled.');
        break;
      case 'offline':
        _showFeedback(
            'No free server is online right now. Please try again soon.');
        break;
      case 'rate_limited':
        _showFeedback(
            'Too many free activation attempts. Please wait a minute and try again.');
        break;
      case 'rejected':
        _showFeedback(
            'The free activation request was rejected. Please reinstall or contact support.');
        break;
      default:
        _showFeedback(
            'Free access is temporarily unavailable. Check your connection, or contact support if this keeps happening.');
        break;
    }
    return true;
  }

  /// Returns a terminal free-access state ("disabled" / "offline") when the
  /// control plane reports one, or null to let activation proceed.
  ///
  /// This runs on the new-user activation path, which is the most censorship-
  /// exposed path in the app: someone who cannot get past it has no working
  /// tunnel yet and no other way in. It used to query only
  /// `defaultGatewayBase`, so a censored `sync.winsvpn.org` made it return null
  /// while every other control-plane call in the app failed over. Null is
  /// "proceed", so the failure was quiet rather than loud -- the user was not
  /// blocked, they were denied the early, accurate message and went on to fail
  /// later at node fetch with something less useful. It now walks the same
  /// gateway list as the rest of the control plane.
  ///
  /// It deliberately does NOT call `_resolveDynamicEndpoints()`, which the
  /// `_refreshAccountStatus` failover pattern does. That helper performs a
  /// GitHub fetch for the recovery record, and by its own contract the record
  /// "may only ever select among gateways already compiled into this signed app
  /// build" -- it reorders the compiled set, it cannot add to it. Since every
  /// compiled gateway is tried here anyway, the round trip would buy no
  /// reachability and would put a network call in front of a preflight on the
  /// latency-sensitive activation path.
  Future<String?> _freeAccessPreflightTerminalKind({
    bool Function()? shouldCancel,
  }) async {
    final base = gatewayBase(defaultGatewayBase);
    final gateways = freeStatusGateways(GatewayEndpoints(gateway: base));
    if (gateways.isEmpty) return null;

    // The same staggered window as /free/verify. The walk used to be serial
    // at 3 s per front, 87 s before activation could even start when every
    // front was silent. The first control-plane answer by arrival decides; an
    // empty string is that answer saying "nothing terminal".
    final cancellation = _hubCancellations.track(shouldCancel ?? () => false);
    final outcome = await runHubRequestWindow<String>(
      urls: _hubOriginPreference.order(gateways),
      timeoutPreference: _hubOriginPreference,
      shouldCancel: shouldCancel,
      cancellation: cancellation,
      policy: const HubRequestWindowPolicy(
        perRequestTimeout: Duration(seconds: 3),
        totalDeadline: kFreeStatusPreflightDeadline,
      ),
      attempt: (url, abort) async {
        final uri = Uri.parse(url).replace(
          queryParameters: {'platform': Platform.operatingSystem},
        );
        try {
          final response = await sendHubRequest(
            _controlPlaneClient,
            'GET',
            uri,
            abort: abort,
          );
          // An HTML body is a captive portal or a block page, not the control
          // plane. Treat it as this gateway being unusable and try the next one
          // rather than concluding anything about free access.
          if (response.body.contains('<!DOCTYPE')) {
            return const HubAttemptResult<String>.rejected();
          }
          // This walk accepts any non-HTML reply, so only a 200 may teach the
          // shared preference; it still reads the preference, so a known-good
          // front is tried first.
          if (response.statusCode == 200) {
            _hubOriginPreference.recordAccepted(url);
          }
          return HubAttemptResult<String>.accepted(
            classifyFreeStatusTerminalState(
                  response.statusCode,
                  response.body,
                ) ??
                '',
          );
        } catch (e) {
          _debugLog('Free status preflight unavailable through $url: $e');
          return const HubAttemptResult<String>.rejected();
        }
      },
    );
    _hubCancellations.release(cancellation);
    final terminal = outcome.value;
    // Every gateway was unreachable, or the walk ran out of time. Preserve the
    // original meaning of null: nothing terminal was established, so
    // activation proceeds and reports a real error at the next step rather
    // than inventing one here.
    return terminal == null || terminal.isEmpty ? null : terminal;
  }

  bool _isBase64WireGuardKey(String value) {
    try {
      return base64Decode(value).length == 32;
    } catch (_) {
      return false;
    }
  }

  List<int> _generateWireGuardPrivateKeyBytes() {
    final random = Random.secure();
    final privateBytes = List<int>.generate(32, (_) => random.nextInt(256));
    privateBytes[0] &= 248;
    privateBytes[31] &= 127;
    privateBytes[31] |= 64;
    return privateBytes;
  }

  Future<String> _deriveWireGuardPublicKey(List<int> privateBytes) async {
    if (privateBytes.length != 32) {
      throw const FormatException('WireGuard private key must be 32 bytes');
    }
    final keyPair = await X25519().newKeyPairFromSeed(privateBytes);
    return base64Encode((await keyPair.extractPublicKey()).bytes);
  }

  bool get _usesNativeSecureStateStore =>
      Platform.isAndroid ||
      Platform.isWindows ||
      Platform.isLinux ||
      _isApplePlatform;

  // Names that historically lived as ordinary files on iOS/macOS before the
  // Keychain-backed secure state store covered Apple platforms (H-2). Used
  // only to drive the one-time migration and its fail-closed fallback read
  // below - never to decide storage routing for any other sensitive name.
  static const Set<String> _legacyAppleMigrationNames = <String>{
    'user_pin.txt',
    'vpn_settings.txt',
    'pending_logout.json',
    'direct_udp_transport_memory.json',
  };

  String get _secureStateReadMethod =>
      _isApplePlatform ? 'secureStateRead' : 'readSecureText';
  String get _secureStateWriteMethod =>
      _isApplePlatform ? 'secureStateWrite' : 'writeSecureText';
  String get _secureStateDeleteMethod =>
      _isApplePlatform ? 'secureStateDelete' : 'deleteSecureText';

  void _validateSensitiveStateName(String name) {
    if (!_sensitiveStateFileNames.contains(name) &&
        !(Platform.isAndroid && name == _doubleVpnIntentRecord)) {
      throw ArgumentError.value(
          name, 'name', 'Unsupported sensitive state file');
    }
  }

  Future<String?> _readSensitiveText(String name) async {
    _validateSensitiveStateName(name);
    if (_usesNativeSecureStateStore) {
      try {
        final value = await _methodChannel.invokeMethod<String>(
          _secureStateReadMethod,
          <String, dynamic>{'name': name},
        ).timeout(const Duration(seconds: 4));
        if (value != null) return value;
      } catch (e) {
        if (!_isApplePlatform || !_legacyAppleMigrationNames.contains(name)) {
          rethrow;
        }
        _debugLog('Secure state read failed for $name; checking for an '
            'un-migrated legacy file this session.');
      }
      if (_isApplePlatform && _legacyAppleMigrationNames.contains(name)) {
        return _readLegacyAppleFileIfPresent(name);
      }
      return null;
    }
    final directory = await _appDocumentsDirectory();
    final file = File('${directory.path}/$name');
    return await file.exists() ? file.readAsString() : null;
  }

  Future<void> _writeSensitiveText(String name, String value) async {
    if (_accountResetRequiresRestart) {
      // A started local reset seals every Dart write until restart, so no
      // cached state can repopulate erased storage.
      throw StateError('Local account reset requires restart');
    }
    _validateSensitiveStateName(name);
    if (_usesNativeSecureStateStore) {
      final write = _methodChannel.invokeMethod<bool>(
        _secureStateWriteMethod,
        <String, dynamic>{'name': name, 'value': value},
      );
      // The Android service uses this document as the authoritative Double
      // VPN choice. A timed-out native write can still complete later; do not
      // report failure and let another choice or start overtake it.
      final stored = Platform.isAndroid && name == 'vpn_settings.txt'
          ? await write
          : await write.timeout(const Duration(seconds: 4));
      if (stored != true) {
        throw StateError('Native secure state write was not acknowledged');
      }
      return;
    }
    final directory = await _appDocumentsDirectory();
    final file = File('${directory.path}/$name');
    final temporary = File(
      '${file.path}.tmp.$pid.${DateTime.now().microsecondsSinceEpoch}',
    );
    try {
      await temporary.writeAsString(value, flush: true);
      await temporary.rename(file.path);
    } finally {
      if (await temporary.exists()) await temporary.delete();
    }
  }

  Future<void> _deleteSensitiveText(String name) async {
    _validateSensitiveStateName(name);
    if (_usesNativeSecureStateStore) {
      final deleted = await _methodChannel.invokeMethod<bool>(
        _secureStateDeleteMethod,
        <String, dynamic>{'name': name},
      ).timeout(const Duration(seconds: 4));
      if (_isApplePlatform && _legacyAppleMigrationNames.contains(name)) {
        await _deleteLegacyAppleFileIfPresent(name);
      }
      if (deleted != true) {
        throw StateError('Native secure state deletion was not acknowledged');
      }
      return;
    }
    final directory = await _appDocumentsDirectory();
    final file = File('${directory.path}/$name');
    if (await file.exists()) await file.delete();
  }

  Future<String?> _readLegacyAppleFileIfPresent(String name) async {
    try {
      final directory = await _appDocumentsDirectory();
      final legacyFile = File('${directory.path}/$name');
      return await legacyFile.exists() ? await legacyFile.readAsString() : null;
    } catch (_) {
      return null;
    }
  }

  Future<void> _deleteLegacyAppleFileIfPresent(String name) async {
    try {
      final directory = await _appDocumentsDirectory();
      final legacyFile = File('${directory.path}/$name');
      if (await legacyFile.exists()) await legacyFile.delete();
    } catch (e) {
      _debugLog('Legacy plaintext cleanup deferred for $name: $e');
    }
  }

  // One-time (retried every launch until it succeeds) migration of sensitive
  // state that iOS/macOS used to store as ordinary files before the
  // Keychain-backed secure store covered Apple platforms (H-2). Never logs
  // file content. If the native write or the read-back verification fails,
  // the legacy file is left in place so this session (via the fallback read
  // in _readSensitiveText) and the next launch's retry can still use it.
  Future<void> _migrateLegacyAppleSensitiveState() async {
    if (!_isApplePlatform) return;
    for (final name in _legacyAppleMigrationNames) {
      try {
        final directory = await _appDocumentsDirectory();
        final legacyFile = File('${directory.path}/$name');
        if (!await legacyFile.exists()) continue;
        final legacyContent = await legacyFile.readAsString();
        await _writeSensitiveText(name, legacyContent);
        final readBack = await _methodChannel.invokeMethod<String>(
          _secureStateReadMethod,
          <String, dynamic>{'name': name},
        ).timeout(const Duration(seconds: 4));
        if (readBack != legacyContent) {
          throw StateError('Secure state migration read-back mismatch');
        }
        final wipeLength = await legacyFile.length();
        await legacyFile.writeAsBytes(List<int>.filled(wipeLength, 0),
            flush: true);
        await legacyFile.delete();
      } catch (_) {
        _debugLog('Legacy sensitive state migration deferred for $name; will '
            'retry next launch.');
      }
    }
  }

  Future<Map<String, dynamic>> _readSensitiveJsonMap(String name) async {
    final raw = (await _readSensitiveText(name))?.trim() ?? '';
    if (raw.isEmpty) return <String, dynamic>{};
    final decoded = jsonDecode(raw);
    if (decoded is Map) return Map<String, dynamic>.from(decoded);
    throw const FormatException('Sensitive state payload is not a JSON object');
  }

  // Derives a stable, non-reversible per-account scope token instead of
  // using the account number directly, so the on-disk/Keychain store never
  // holds a raw account number next to key material.
  String _clientKeyScopeToken(String accountScope) =>
      _sha256Hex('wins-client-keypair-scope-v1\n$accountScope');

  String _clientKeyOperationKeyForScopeToken(String scopeToken) =>
      'client-keypair-container';

  Future<T> _serializeClientKeyOperation<T>(
    String accountScope,
    Future<T> Function() operation,
  ) =>
      _serializeClientKeyOperationForScopeToken(
        _clientKeyScopeToken(accountScope),
        operation,
      );

  Future<T> _serializeClientKeyOperationForScopeToken<T>(
    String scopeToken,
    Future<T> Function() operation,
  ) =>
      _clientKeyOperationQueue.run(
        _clientKeyOperationKeyForScopeToken(scopeToken),
        operation,
      );

  /// The account-scoped identity container. A store that cannot be read at
  /// all THROWS: a transient keystore failure or the 4 s channel timeout must
  /// never read as an empty store, or a create overwrites every other
  /// account's identity and a delete reports success while the key is still
  /// stored. A present container that is corrupt or of an unsupported format
  /// holds nothing usable and comes back as `unusable`, so a create replaces
  /// it (as before) and a delete removes it whole instead of failing forever.
  Future<({Map<String, dynamic> accounts, bool unusable})>
      _readClientKeyPairContainer() async {
    final encoded = await _readSensitiveText('client_keypair.json');
    if (encoded == null) {
      return (accounts: <String, dynamic>{}, unusable: false);
    }
    try {
      final decoded = jsonDecode(encoded);
      if (decoded is Map &&
          (decoded['format'] ?? '') == _clientKeyPairFormat &&
          decoded['accounts'] is Map) {
        return (
          accounts: Map<String, dynamic>.from(decoded['accounts'] as Map),
          unusable: false,
        );
      }
    } catch (_) {
      // Corrupt or pre-account-scoping payload: nothing in it is trusted.
    }
    return (accounts: <String, dynamic>{}, unusable: true);
  }

  Future<Map<String, dynamic>> _readClientKeyPairAccounts() async =>
      (await _readClientKeyPairContainer()).accounts;

  Future<void> _writeClientKeyPairAccounts(
      Map<String, dynamic> accounts) async {
    final encoded = jsonEncode({
      'format': _clientKeyPairFormat,
      'accounts': accounts,
    });
    await _writeSensitiveText('client_keypair.json', encoded);
    if (await _readSensitiveText('client_keypair.json') != encoded) {
      throw StateError('Secure VPN identity failed read-back verification');
    }
  }

  Future<Map<String, String>> _saveNewClientKeyPair(String accountScope) async {
    final privateBytes = _generateWireGuardPrivateKeyBytes();
    final privateKey = base64Encode(privateBytes);
    final publicKey = await _deriveWireGuardPublicKey(privateBytes);
    final accounts = await _readClientKeyPairAccounts();
    accounts[_clientKeyScopeToken(accountScope)] = {
      'private_key': privateKey,
      'public_key': publicKey,
    };
    await _writeClientKeyPairAccounts(accounts);
    return {'private_key': privateKey, 'public_key': publicKey};
  }

  // L-5: returns whether the native Apple Keychain cleanup (client key pair
  // AND the WinsTunnelSecretStore preshared key / Xray UUID - see
  // deleteClientKeyPairForAccount in AppDelegate.swift /
  // MainFlutterWindow.swift) genuinely completed, so the caller can surface
  // a failure instead of silently treating "no exception" as success. Only
  // an explicit `true` result counts; anything else (a non-true result, a
  // thrown PlatformException, or a missing/broken channel) is a failure.
  // Never logs the caught exception itself - only a fixed, secret-free
  // message - even though the native side already redacts it, so this path
  // can never become a place a future edit accidentally reintroduces a
  // secret-bearing log line.
  Future<bool> _deleteClientKeyPairForAccountUnlocked(String accountScope) =>
      _deleteClientKeyPairForScopeTokenUnlocked(
          _clientKeyScopeToken(accountScope));

  Future<bool> _deleteClientKeyPairForScopeTokenUnlocked(
      String scopeToken) async {
    final container = await _readClientKeyPairContainer();
    final accounts = container.accounts;
    if (container.unusable) {
      // Unusable, but it may still hold key bytes: remove it whole.
      if (!await _deleteSensitiveArtifactVerified('client_keypair.json')) {
        return false;
      }
    } else if (accounts.remove(scopeToken) != null) {
      await _writeClientKeyPairAccounts(accounts);
    }
    if (Platform.isIOS || Platform.isMacOS) {
      try {
        final deleted = await _methodChannel.invokeMethod<bool>(
          'deleteClientKeyPairForAccount',
          <String, dynamic>{'accountScope': scopeToken},
        );
        if (deleted != true) {
          _debugLog(
              'Native Apple tunnel secret cleanup did not confirm success.');
          return false;
        }
      } catch (e) {
        _debugLog('Native Apple tunnel secret cleanup failed.');
        return false;
      }
    }
    final remainingAccounts = await _readClientKeyPairAccounts();
    if (remainingAccounts.containsKey(scopeToken)) return false;
    if (Platform.isIOS || Platform.isMacOS) {
      final remaining =
          await _loadExistingNativeClientKeyPairByScopeToken(scopeToken);
      if (remaining != null) return false;
    }
    return true;
  }

  Future<bool> _deleteClientKeyPairForAccount(String accountScope) =>
      _serializeClientKeyOperation(
        accountScope,
        () => _deleteClientKeyPairForAccountUnlocked(accountScope),
      );

  Future<Map<String, String>?> _loadOrCreateNativeClientKeyPair(
      String accountScope) async {
    if (!Platform.isIOS && !Platform.isMacOS) return null;
    try {
      final keys = await _methodChannel.invokeMapMethod<String, dynamic>(
        'loadOrCreateClientKeyPair',
        <String, dynamic>{'accountScope': _clientKeyScopeToken(accountScope)},
      );
      final privateKey = (keys?['private_key'] ?? '').toString();
      final publicKey = (keys?['public_key'] ?? '').toString();
      if (_isBase64WireGuardKey(privateKey) &&
          _isBase64WireGuardKey(publicKey) &&
          await _deriveWireGuardPublicKey(base64Decode(privateKey)) ==
              publicKey) {
        return {'private_key': privateKey, 'public_key': publicKey};
      }
      _debugLog('Native Apple client key pair failed validation.');
    } catch (e) {
      _debugLog('Native Apple client key pair unavailable: $e');
    }
    return null;
  }

  Future<Map<String, String>?> _loadExistingNativeClientKeyPair(
          String accountScope) =>
      _loadExistingNativeClientKeyPairByScopeToken(
          _clientKeyScopeToken(accountScope));

  Future<Map<String, String>?> _loadExistingNativeClientKeyPairByScopeToken(
      String scopeToken) async {
    if (!Platform.isIOS && !Platform.isMacOS) return null;
    try {
      final keys = await _methodChannel.invokeMapMethod<String, dynamic>(
        'loadExistingClientKeyPair',
        <String, dynamic>{'accountScope': scopeToken},
      );
      if (keys == null) return null;
      final privateKey = (keys['private_key'] ?? '').toString();
      final publicKey = (keys['public_key'] ?? '').toString();
      if (_isBase64WireGuardKey(privateKey) &&
          _isBase64WireGuardKey(publicKey) &&
          await _deriveWireGuardPublicKey(base64Decode(privateKey)) ==
              publicKey) {
        return {'private_key': privateKey, 'public_key': publicKey};
      }
      throw StateError('Stored Apple VPN identity failed validation');
    } catch (e) {
      _debugLog('Existing Apple client key pair unavailable: $e');
      rethrow;
    }
  }

  // accountScope identifies which logged-in account (or the free-access
  // account) this key pair belongs to. Passing the wrong/empty scope would
  // recreate the original cross-account key-reuse bug, so every call site
  // must pass the same effective account identifier it sends to /verify.
  //
  // Refresh and reconnect use _loadExistingClientKeyPair, which never creates
  // or replaces identity. This create-capable path is reserved for free-access
  // enrollment; paid setup-key activation stages a candidate separately and
  // commits it only after the hub authenticates the setup key.
  Future<Map<String, String>> _loadOrCreateClientKeyPairUnlocked(
      String accountScope) async {
    final nativeKeyPair = await _loadOrCreateNativeClientKeyPair(
      accountScope,
    );
    if (nativeKeyPair != null) return nativeKeyPair;
    if (Platform.isIOS || Platform.isMacOS) {
      throw StateError(
          'Apple native Keychain client key pair is required for Packet Tunnel.');
    }

    final accounts = await _readClientKeyPairAccounts();
    final scopeToken = _clientKeyScopeToken(accountScope);
    final entry = accounts[scopeToken];
    if (accounts.containsKey(scopeToken) && entry is! Map) {
      throw StateError('Stored VPN identity is corrupted or unavailable');
    }
    if (entry is Map) {
      try {
        final privateKey = (entry['private_key'] ?? '').toString();
        final publicKey = (entry['public_key'] ?? '').toString();
        if (_isBase64WireGuardKey(privateKey) &&
            _isBase64WireGuardKey(publicKey) &&
            await _deriveWireGuardPublicKey(base64Decode(privateKey)) ==
                publicKey) {
          return {'private_key': privateKey, 'public_key': publicKey};
        }
      } catch (error) {
        throw StateError('Stored VPN identity is corrupted or unavailable');
      }
      throw StateError('Stored VPN identity failed cryptographic validation');
    }

    return _saveNewClientKeyPair(accountScope);
  }

  Future<Map<String, String>> _loadOrCreateClientKeyPair(String accountScope) =>
      _serializeClientKeyOperation(
        accountScope,
        () => _loadOrCreateClientKeyPairUnlocked(accountScope),
      );

  Future<Map<String, String>?> _loadExistingClientKeyPairUnlocked(
      String accountScope) async {
    if (Platform.isIOS || Platform.isMacOS) {
      return _loadExistingNativeClientKeyPair(accountScope);
    }
    final accounts = await _readClientKeyPairAccounts();
    final entry = accounts[_clientKeyScopeToken(accountScope)];
    if (entry == null) return null;
    if (entry is! Map) {
      throw StateError('Stored VPN identity is corrupted or unavailable');
    }
    final privateKey = (entry['private_key'] ?? '').toString();
    final publicKey = (entry['public_key'] ?? '').toString();
    if (!_isBase64WireGuardKey(privateKey) ||
        !_isBase64WireGuardKey(publicKey) ||
        await _deriveWireGuardPublicKey(base64Decode(privateKey)) !=
            publicKey) {
      throw StateError('Stored VPN identity failed cryptographic validation');
    }
    return {'private_key': privateKey, 'public_key': publicKey};
  }

  Future<Map<String, String>?> _loadExistingClientKeyPair(
          String accountScope) =>
      _serializeClientKeyOperation(
        accountScope,
        () => _loadExistingClientKeyPairUnlocked(accountScope),
      );

  Future<Map<String, String>> _stageClientKeyPairCandidate(
      String accountScope) async {
    if (accountScope.trim().isEmpty) {
      throw StateError('Account scope is required for VPN identity rotation');
    }
    final privateBytes = _generateWireGuardPrivateKeyBytes();
    return <String, String>{
      'private_key': base64Encode(privateBytes),
      'public_key': await _deriveWireGuardPublicKey(privateBytes),
    };
  }

  Future<void> _commitClientKeyPairCandidateUnlocked(
    String accountScope,
    Map<String, String> candidate,
  ) async {
    final privateKey = candidate['private_key'] ?? '';
    final publicKey = candidate['public_key'] ?? '';
    if (!_isBase64WireGuardKey(privateKey) ||
        !_isBase64WireGuardKey(publicKey) ||
        await _deriveWireGuardPublicKey(base64Decode(privateKey)) !=
            publicKey) {
      throw StateError('Candidate VPN identity failed validation');
    }
    if (Platform.isIOS || Platform.isMacOS) {
      final committed = await _methodChannel.invokeMethod<bool>(
        'replaceClientKeyPairForAccount',
        <String, dynamic>{
          'accountScope': _clientKeyScopeToken(accountScope),
          'privateKey': privateKey,
          'publicKey': publicKey,
        },
      );
      if (committed != true) {
        throw StateError('Apple VPN identity replacement was not confirmed');
      }
    } else {
      final accounts = await _readClientKeyPairAccounts();
      accounts[_clientKeyScopeToken(accountScope)] = <String, String>{
        'private_key': privateKey,
        'public_key': publicKey,
      };
      await _writeClientKeyPairAccounts(accounts);
    }
    final readBack = await _loadExistingClientKeyPairUnlocked(accountScope);
    if (readBack == null ||
        readBack['private_key'] != privateKey ||
        readBack['public_key'] != publicKey) {
      throw StateError('Candidate VPN identity failed durable read-back');
    }
  }

  Future<void> _commitClientKeyPairCandidate(
    String accountScope,
    Map<String, String> candidate,
  ) =>
      _serializeClientKeyOperation(
        accountScope,
        () => _commitClientKeyPairCandidateUnlocked(accountScope, candidate),
      );

  Map<String, dynamic> _attachLocalClientKeys(
      Map<String, dynamic> config, Map<String, String> clientKeys) {
    final withKeys = Map<String, dynamic>.from(config);
    withKeys['client_private_key'] = clientKeys['private_key'] ?? '';
    withKeys['client_public_key'] = clientKeys['public_key'] ?? '';
    // The winn/3 static private key is this device's own, attached here and
    // only once the hub echoes its public half. A served one is discarded.
    return attachLocalWinn3StaticKey(
        withKeys, Winn3DeviceKeyPair.fromClientKeys(clientKeys));
  }

  bool _configMatchesLocalClientKeys(
      Map<String, dynamic> config, Map<String, String> clientKeys) {
    return (config['client_private_key'] ?? '').toString() ==
            (clientKeys['private_key'] ?? '') &&
        (config['client_public_key'] ?? '').toString() ==
            (clientKeys['public_key'] ?? '');
  }

  // IA-CP-05 (Fable 5.1 ruling 2026-09-29): this device's own winn/3 X25519
  // static identity, per account scope, beside the AWG one and never reusing
  // it. Stored only in the secure state store; only the public half is sent.
  late final Winn3DeviceKeyStore _winn3KeyStore = Winn3DeviceKeyStore(
    read: () => _readSensitiveText(kWinn3KeyPairFileName),
    write: (value) => _writeSensitiveText(kWinn3KeyPairFileName, value),
    delete: () => _deleteSensitiveText(kWinn3KeyPairFileName),
  );

  /// The hub's "this v3 key belongs to another device" refusals, keyed by
  /// the public key the refused request carried, so a late refusal can only
  /// rotate the identity it named (never another account's).
  final Winn3KeyCollisionLedger _winn3KeyCollisions = Winn3KeyCollisionLedger();

  void _noteWinn3KeyCollision(http.Response response, String? requestBody) {
    if (_winn3KeyCollisions.note(
        response.statusCode, response.headers, requestBody)) {
      _debugLog('Hub reports this winn/3 key belongs to another device; '
          'the next request for that identity carries a fresh one.');
    }
  }

  /// A v3 identity is generated and sent only by a host that advertises it
  /// can carry winn/3 on this request.
  bool get _winn3ClientKeyHost => _winnCapabilityFlags['supports_winn3'] == true;

  /// This scope's v3 pair for one /verify request, generated and committed on
  /// first need. That first need is the migration trigger: a device upgraded
  /// from a build that ran on a hub-minted key has no local pair, sends a new
  /// public key, and the hub's adoption retires the hub-minted identity. Null
  /// when this host carries no winn/3 or the secure store failed; the request
  /// then carries no v3 key and no identity is rotated.
  Future<Winn3DeviceKeyPair?> _winn3KeyPairForRequest(
      String accountScope) async {
    if (!_winn3ClientKeyHost) return null;
    try {
      // A hub refusal (HTTP 409 winn3_static_public_in_use) for THIS scope's
      // stored public key is answered with a fresh pair once; a refusal for
      // any other key leaves this one alone.
      return _rememberLocalWinn3Key(await winn3KeyPairResolvingCollision(
        _winn3KeyStore,
        _clientKeyScopeToken(accountScope),
        _winn3KeyCollisions,
      ));
    } catch (_) {
      _debugLog('winn/3 device identity unavailable; no v3 key sent.');
      return null;
    }
  }

  /// A fresh, unstored v3 pair for setup-key enrollment, where the AWG
  /// identity is rotated too. Committed only after the hub authenticates.
  Future<Winn3DeviceKeyPair?> _stageWinn3KeyPairCandidate() async {
    if (!_winn3ClientKeyHost) return null;
    try {
      return await _winn3KeyStore.stageCandidate();
    } catch (_) {
      _debugLog('winn/3 device identity could not be staged.');
      return null;
    }
  }

  Future<bool> _commitWinn3KeyPairCandidate(
      String accountScope, Winn3DeviceKeyPair candidate) async {
    try {
      await _winn3KeyStore.commit(
          _clientKeyScopeToken(accountScope), candidate);
      _rememberLocalWinn3Key(candidate);
      return true;
    } catch (_) {
      _debugLog('winn/3 device identity could not be committed.');
      return false;
    }
  }

  /// This scope's stored v3 pair without creating one; null when absent or
  /// when the store cannot be read.
  Future<Winn3DeviceKeyPair?> _loadExistingWinn3KeyPair(
      String accountScope) async {
    try {
      return _rememberLocalWinn3Key(await _winn3KeyStore
          .loadExisting(_clientKeyScopeToken(accountScope)));
    } catch (_) {
      return null;
    }
  }

  /// The private halves of this device's own v3 keys seen this run. A v3
  /// private key in a config that is not in here (or in the store) is a
  /// hub-served session key and is never persisted or kept past its session.
  final Set<String> _winn3KnownLocalPrivateKeys = <String>{};

  Winn3DeviceKeyPair? _rememberLocalWinn3Key(Winn3DeviceKeyPair? pair) {
    if (pair != null) _winn3KnownLocalPrivateKeys.add(pair.privateKey);
    return pair;
  }

  /// Every local v3 private key, read from the store; on a store failure,
  /// the ones already seen this run (a missing entry only means one extra
  /// /verify later, never a leaked key).
  Future<Set<String>> _winn3LocalPrivateKeys() async {
    try {
      _winn3KnownLocalPrivateKeys.addAll(await _winn3KeyStore.allPrivateKeys());
    } catch (_) {
      _debugLog('winn/3 device identities unreadable; persisting none.');
    }
    return Set<String>.of(_winn3KnownLocalPrivateKeys);
  }

  /// What any config write may contain: no v3 private key except this
  /// device's own. Decided by value (Seat C, A-1), so it holds whatever
  /// rebuilt the config before it got here.
  Future<Map<String, dynamic>> _winn3PersistableConfig(
      Map<String, dynamic> config) async {
    if (servedWinn3StaticPrivate(config).isEmpty &&
        !config.containsKey(kWinn3StaticPrivateOriginField)) {
      return config;
    }
    return withoutForeignWinn3StaticPrivate(
        config, await _winn3LocalPrivateKeys());
  }

  /// Session end: a hub-served winn/3 private key (transition case) does not
  /// outlive the session that fetched it. Synchronous, by value, against the
  /// local keys seen this run; the disk copy never held it.
  void _dropHubSessionWinn3Key() {
    _cachedVpnConfig = withoutForeignWinn3StaticPrivate(
        _cachedVpnConfig, _winn3KnownLocalPrivateKeys);
  }

  /// Apple session end (Sol, OI-KEYSAPP-13): the Packet Tunnel extension
  /// restores `static_private` from the `org.winsvpn.tunnel-secrets` Keychain
  /// item, so a hub-served transition key saved there at start must go at
  /// stop too. Native `clearWinnSessionSecret` clears only that field and
  /// keeps it when it equals the device's own key for the scope; the AWG
  /// identity is never touched. Bounded by a timeout; a failure is logged and
  /// the next start replaces the item anyway.
  Future<void> _clearAppleWinnSessionSecret() async {
    if (!_isApplePlatform) return;
    try {
      final scope = await _effectiveAccountScopeForKeyPair();
      final local = await _loadExistingWinn3KeyPair(scope);
      await _methodChannel.invokeMethod<bool>(
        'clearWinnSessionSecret',
        <String, dynamic>{
          'accountScope': _clientKeyScopeToken(scope),
          'keepStaticPrivate': local?.privateKey ?? '',
        },
      ).timeout(const Duration(seconds: 2));
    } catch (_) {
      _debugLog('Apple winn/3 session secret could not be cleared.');
    }
  }

  Future<bool> _deleteWinn3KeyPairForScopeToken(String scopeToken) async {
    try {
      return await _winn3KeyStore.delete(scopeToken);
    } catch (_) {
      _debugLog('winn/3 device identity cleanup remains pending.');
      return false;
    }
  }

  Future<Directory> _appDocumentsDirectory() async {
    if (_hasNativeTunnelBridge) {
      try {
        final path = await _methodChannel
            .invokeMethod<String>('getAppDocumentsDirectory');
        if (path != null && path.trim().isNotEmpty) {
          final directory = Directory(path.trim());
          await directory.create(recursive: true);
          return directory;
        }
      } catch (e) {
        _debugLog('Native app documents directory unavailable: $e');
      }
    }
    final String basePath;
    if (Platform.isWindows) {
      final appData = Platform.environment['APPDATA']?.trim() ?? '';
      if (appData.isEmpty) {
        throw StateError('Windows application data directory is unavailable');
      }
      basePath = appData;
    } else if (Platform.isMacOS) {
      basePath =
          '${Platform.environment['HOME'] ?? Directory.systemTemp.path}/Library/Application Support';
    } else {
      basePath =
          '${Platform.environment['HOME'] ?? Directory.systemTemp.path}/.local/share';
    }
    final directory = Directory('$basePath/wins_vpn');
    await directory.create(recursive: true);
    return directory;
  }

  Future<void> _persistVpnConfigBestEffort(
    Map<String, dynamic> config,
    String reason,
  ) async {
    try {
      _debugLog('VPN config persistence starting: $reason');
      // A hub-served winn/3 key is for one session and is never persisted.
      final encoded = jsonEncode(await _winn3PersistableConfig(config));
      if (Platform.isIOS || Platform.isMacOS) {
        await _persistEncodedVpnConfigOnApple(encoded);
        _debugLog('VPN config persistence complete: $reason');
        return;
      }
      await _writeSensitiveText('vpn_config.txt', encoded)
          .timeout(const Duration(seconds: 4));
      _debugLog('VPN config persistence complete: $reason');
    } catch (e) {
      _debugLog('VPN config persistence skipped ($reason): $e');
    }
  }

  /// A terminal v3 failure ends the fast path for this cache: the next
  /// explicit-node tap asks the hub first. The document is kept, in memory and
  /// on disk, as the fallback for a hub the network cannot reach.
  Future<void> _markCachedVpnConfigStale() async {
    if (_cachedVpnConfig.isEmpty ||
        !_cachedVpnConfig.containsKey(kVpnConfigFetchedAtKey)) {
      return;
    }
    final stale = markVpnConfigStale(_cachedVpnConfig);
    _cachedVpnConfig = stale;
    await _persistVpnConfigBestEffort(stale, 'winn3_terminal_failure_stale');
  }

  Future<void> _persistVpnConfigRequired(Map<String, dynamic> config) async {
    // A hub-served winn/3 key is for one session and is never persisted.
    final encoded = jsonEncode(await _winn3PersistableConfig(config));
    if (_isApplePlatform) {
      await _persistEncodedVpnConfigOnApple(encoded);
      final readBack = await _readEncodedVpnConfigOnApple();
      if (readBack != encoded) {
        throw StateError('Apple VPN config failed durable read-back');
      }
      return;
    }
    await _writeSensitiveText('vpn_config.txt', encoded);
    if (await _readSensitiveText('vpn_config.txt') != encoded) {
      throw StateError('VPN config failed durable read-back');
    }
  }

  Future<void> _persistEncodedVpnConfigOnApple(String encoded) async {
    final persisted = await _methodChannel.invokeMethod<bool>(
      'persistVpnConfig',
      <String, dynamic>{'config': encoded},
    ).timeout(const Duration(seconds: 2));
    if (persisted != true) {
      throw StateError('Apple native private config persistence failed');
    }
  }

  Future<String?> _readEncodedVpnConfigOnApple() async {
    if (!_isApplePlatform) {
      throw StateError('Apple native private config read requested elsewhere');
    }
    return _methodChannel
        .invokeMethod<String>('readVpnConfig')
        .timeout(const Duration(seconds: 2));
  }

  Future<void> _deleteVpnConfigOnApple() async {
    if (!_isApplePlatform) {
      throw StateError(
          'Apple native private config deletion requested elsewhere');
    }
    final deleted = await _methodChannel
        .invokeMethod<bool>('deleteVpnConfig')
        .timeout(const Duration(seconds: 2));
    if (deleted != true) {
      throw StateError('Apple native private config deletion failed');
    }
    if (await _readEncodedVpnConfigOnApple() != null) {
      throw StateError('Apple native private config remains after deletion');
    }
  }

  Future<void> _saveActivationSettingsRequired({
    required String accountNumber,
    required String announcement,
    required String expiration,
    required String referralCode,
    required String referralLink,
    required String referralBackupLink,
    required bool freeAccessSession,
  }) async {
    await _mutateVpnRuntimeSettings((data) {
      data['account_number'] = accountNumber;
      data['server_announcement'] = announcement;
      data['expiration_date'] = expiration;
      data['referral_code'] = referralCode;
      data['referral_link'] = referralLink;
      data['referral_backup_link'] = referralBackupLink;
      data['free_access_session'] = freeAccessSession;
      data['lifecycle_schema'] = 2;
      data.remove('account_terminal_status');
      data.remove('launcher_unlocked');
    });
    await _settingsMutationQueue;
    final readBack = await _readSensitiveJsonMap('vpn_settings.txt');
    if (readBack['account_number'] != accountNumber ||
        readBack['free_access_session'] != freeAccessSession ||
        readBack['lifecycle_schema'] != 2) {
      throw StateError('Activation settings failed durable read-back');
    }
  }

  Future<void> _writeActivationCompleteMarker(
      String accountScope, int expectedEpoch) async {
    if (!_accountEpochIsCurrent(expectedEpoch)) {
      throw StateError('Activation was superseded');
    }
    final encoded = jsonEncode(<String, dynamic>{
      'v': 1,
      'scope': _clientKeyScopeToken(accountScope),
    });
    await _writeSensitiveText('calc_state.json', encoded);
    if (!_accountEpochIsCurrent(expectedEpoch) ||
        await _readSensitiveText('calc_state.json') != encoded) {
      throw StateError('Activation completion marker failed durable read-back');
    }
  }

  Future<bool> _activationCompleteForScope(String accountScope) async {
    try {
      final encoded = await _readSensitiveText('calc_state.json');
      if (encoded == null) return false;
      final decoded = jsonDecode(encoded);
      return decoded is Map &&
          decoded['v'] == 1 &&
          decoded['scope'] == _clientKeyScopeToken(accountScope);
    } catch (_) {
      return false;
    }
  }

  Future<bool> _activationCompleteOrMigrateLegacy(
    String? storedPinCredential,
    Map<String, dynamic> settings,
  ) async {
    if (storedPinCredential == null) return false;
    final freeAccess = settings['free_access_session'] == true;
    final accountScope = freeAccess
        ? _freeAccessAccountNumber
        : (settings['account_number'] ?? '').toString().trim();
    if (accountScope.isEmpty) return false;
    if (settings['lifecycle_schema'] == 2) {
      return _activationCompleteForScope(accountScope);
    }
    if (!_hasUsableVpnConfig(_cachedVpnConfig)) return false;
    final keys = await _loadExistingClientKeyPair(accountScope);
    if (keys == null ||
        !_configMatchesLocalClientKeys(_cachedVpnConfig, keys)) {
      return false;
    }
    if (await _readDeviceAuthToken() == null) return false;
    await _writeActivationCompleteMarker(
        accountScope, _accountSessionEpoch.current);
    return true;
  }

  Future<void> _deleteActivationCompleteMarker() async {
    await _deleteSensitiveText('calc_state.json');
    if (await _readSensitiveText('calc_state.json') != null) {
      throw StateError('Activation completion marker remains after deletion');
    }
  }

  Future<Map<String, dynamic>> _readVpnRuntimeSettings() async {
    try {
      await _settingsMutationQueue;
      return await _readSensitiveJsonMap('vpn_settings.txt');
    } catch (e) {
      _debugLog('Settings read failed: $e');
    }
    return <String, dynamic>{};
  }

  /// [skipWriteWhen], evaluated after [mutation] ran, lets a caller whose
  /// mutation declined to change anything ask for no write at all (L91: the
  /// duress enrollment after a relock). Every other caller passes nothing
  /// and keeps the unconditional write.
  Future<void> _mutateVpnRuntimeSettings(
    void Function(Map<String, dynamic> data) mutation, {
    bool Function()? skipWriteWhen,
  }) {
    final scheduledEpoch = _accountSessionEpoch.current;
    final operation = _settingsMutationQueue.then((_) async {
      if (_settingsWritesSealed ||
          !_accountSessionEpoch.isCurrent(scheduledEpoch)) {
        throw StateError(
            'Account settings write superseded by lifecycle change');
      }
      final data = await _readSensitiveJsonMap('vpn_settings.txt');
      if (_settingsWritesSealed ||
          !_accountSessionEpoch.isCurrent(scheduledEpoch)) {
        throw StateError(
            'Account settings write superseded by lifecycle change');
      }
      mutation(data);
      if (skipWriteWhen?.call() == true) return;
      await _writeSensitiveText('vpn_settings.txt', jsonEncode(data));
      if (_settingsWritesSealed ||
          !_accountSessionEpoch.isCurrent(scheduledEpoch)) {
        // Only a teardown SEAL erases the document: the write repopulated
        // storage the teardown is erasing, so erase it again. An activation
        // bumps the epoch without sealing or erasing anything; its own writes
        // are queued behind this one and replace its values, and deleting the
        // whole document here threw away the privacy consent, the legal
        // acceptance, the PIN lockout ledger, both replay floors and every
        // preference.
        if (_settingsWritesSealed) {
          await _deleteSensitiveText('vpn_settings.txt');
        }
        throw StateError(
            'Account settings write superseded by lifecycle change');
      }
    });
    _settingsMutationQueue = operation.then<void>(
      (_) {},
      onError: (_, __) {},
    );
    return operation;
  }

  Future<void> _writeVpnRuntimeSetting(String key, Object? value) async {
    try {
      await _mutateVpnRuntimeSettings((data) {
        if (value == null) {
          data.remove(key);
        } else {
          data[key] = value;
        }
      });
    } catch (e) {
      _debugLog('Single setting save failed: $e');
    }
  }

  // M-14: the legacy Apple file -> Keychain migration is a purely local
  // operation (no network access, no device identifier) so it must not sit
  // behind the privacy-consent gate - otherwise choosing "Not now" leaves
  // old plaintext files on disk indefinitely. Run it first, unconditionally
  // (it is a no-op on non-Apple platforms and idempotent on repeat launches
  // - see _migrateLegacyAppleSensitiveState), then proceed to the
  // (consent-gated) rest of startup exactly as before.
  Future<void> _initializeLocalSecurityThenPrivacyConsent() async {
    if (_isApplePlatform) {
      await _migrateLegacyAppleSensitiveState();
    }
    // Point the privacy-safe crash sink at app-private storage now that the
    // directory is known. No transport is registered, so this only governs
    // where a scrubbed, identifier-free local record is written. A failure to
    // resolve the directory is harmless: the sink then redacts and drops.
    try {
      globalCrashReportDirectory = await _appDocumentsDirectory();
    } on Object {
      globalCrashReportDirectory = null;
    }
    await _initializePrivacyConsentGate();
  }

  Future<void> _initializePrivacyConsentGate() async {
    final cleanupOutcome = await _resumePendingAccountCleanup();
    if (cleanupOutcome == AccountCleanupResumeOutcome.pending) {
      _accountCleanupStartupBlocked = true;
      return;
    }
    _accountCleanupStartupBlocked = false;
    final settings = await _readVpnRuntimeSettings();
    final acceptedVersion =
        (settings['privacy_policy_accepted_version'] ?? '').toString().trim();
    if (acceptedVersion == _privacyPolicyVersion) {
      _privacyConsentGranted = true;
      if (mounted) setState(() {});
      _startPostPrivacyConsentInitialization();
      return;
    }
    if (!mounted) return;
    // CAMOUFLAGE OUTRANKS THE CONSENT PROMPT. This dialog is by some distance
    // the loudest thing this app can put on a screen: it is titled "Privacy
    // Policy and Legal Consent" and names the service and its domain. It is
    // what a cold start showed after a duress wipe, over the real activation
    // screen, because the wipe clears the accepted-version key along with
    // everything else -- so the panic feature ended by announcing the app to
    // whoever was holding the phone. The same would happen to every existing
    // install the day _privacyPolicyVersion is bumped.
    //
    // Where camouflage is latched, come up as the calculator and defer the
    // prompt to the moment someone actually unlocks into the real app (see
    // _onCalculatorButtonPressed). Nothing behind the decoy needs consent:
    // _startPostPrivacyConsentInitialization has not run, so there is no
    // network activity to consent to.
    // A credential store that cannot be read says nothing about enrollment.
    // Where camouflage applies, come up as the calculator and leave the
    // prompt for an unlock, as for a latched install; elsewhere there is no
    // disguise to keep, and the prompt below is shown.
    String? storedPin;
    try {
      storedPin = await _readSensitiveText('user_pin.txt');
    } catch (_) {
      if (_supportsInAppCamouflage) return _armCamouflageBeforeConsent();
    }
    final freeAccess = settings['free_access_session'] == true;
    final accountScope = freeAccess
        ? _freeAccessAccountNumber
        : (settings['account_number'] ?? '').toString().trim();
    final lifecycleSchema = settings['lifecycle_schema'];
    final activatedLocally = lifecycleSchema == 2
        ? storedPin != null &&
            accountScope.isNotEmpty &&
            await _activationCompleteForScope(accountScope)
        : storedPin != null || freeAccess;
    if (_supportsInAppCamouflage &&
        (activatedLocally || await _camouflageLatched() != false)) {
      await _armCamouflageBeforeConsent();
      return;
    }
    // Neither activated nor latched: the first-frame calculator is only the
    // neutral surface, not a cover (onboarding shows a never-activated
    // install the real app). Drop it before the consent dialog, which the
    // route guard would otherwise remove as a push over the decoy.
    if (mounted && _showDecoyCalculator) {
      setState(() => _showDecoyCalculator = false);
    }
    await _showPrivacyPolicyDialog(requireConsent: true);
  }

  /// Brings the decoy calculator up without granting consent and without any
  /// network work: a strictly local read of the enrolled credential's length
  /// (so the keypad still expects the right number of digits on a legacy
  /// 4-digit install) and the two flags that put the calculator on screen.
  ///
  /// Deliberately NOT _determineSecurityOnboardingLayer, which is
  /// consent-gated and ends in live network calls.
  Future<void> _armCamouflageBeforeConsent() async {
    if (!_supportsInAppCamouflage) return;
    try {
      final storedPinCredential = await _readSensitiveText('user_pin.txt');
      if (storedPinCredential != null) {
        _calculatorPinEntry.pinLength =
            PinCredentialCodec.storedPinLength(storedPinCredential);
      }
      _calculatorPinEntry.recoveryLength = 0;
    } catch (e) {
      _debugLog('Pre-consent camouflage credential probe skipped: $e');
    }
    if (!mounted) return;
    _clearProductSurfacesForDecoy();
    setState(() {
      _showDecoyCalculator = true;
      _calcDisplayString = "0";
      _calculatorPinEntry.reset();
    });
    unawaited(_setLauncherCamouflage(enabled: true));
  }

  Future<void> _persistPrivacyConsent() async {
    await _mutateVpnRuntimeSettings((data) {
      data['privacy_policy_accepted_version'] = _privacyPolicyVersion;
      data['privacy_policy_accepted_at'] =
          DateTime.now().toUtc().toIso8601String();
      data['privacy_policy_url'] = _privacyPolicyUrl;
    });
  }

  Future<bool> _showPrivacyPolicyDialog({required bool requireConsent}) async {
    if (!mounted || _privacyConsentPromptOpen) return _privacyConsentGranted;
    // Never over the decoy, whichever flow asks. Nothing is kept for later,
    // because nothing needs to be: _privacyConsentGranted is still false, and
    // the PIN unlock asks again for exactly that (_onCalculatorButtonPressed).
    if (_showDecoyCalculator) return _privacyConsentGranted;
    _privacyConsentPromptOpen = true;
    bool checked = false;
    try {
      final result = await showDialog<bool>(
        context: context,
        barrierDismissible: !requireConsent,
        builder: (dialogContext) => StatefulBuilder(
          // showDialog inserts this dialog into the root Navigator's overlay,
          // which sits above (not inside) the dashboard's local
          // _lightSurfaceTheme wrap, so without this Theme the dialog falls
          // back to the app-wide dark theme's light default text color on
          // top of this light _surfacePanel background -- unreadable
          // near-white-on-near-white text, including the actual policy body.
          builder: (context, setDialogState) => Theme(
            data: _lightSurfaceTheme(context),
            child: AlertDialog(
              backgroundColor: _surfacePanel,
              title: const Text('Privacy Policy and Legal Consent'),
              content: ConstrainedBox(
                constraints: BoxConstraints(
                  maxHeight:
                      min(MediaQuery.of(context).size.height * 0.66, 680),
                ),
                child: SingleChildScrollView(
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      const Text(
                        'Bundled offline Privacy Policy',
                        style: TextStyle(fontWeight: FontWeight.w700),
                      ),
                      const SizedBox(height: 4),
                      // NOT SelectableText. Both of these were SelectableText,
                      // and inside a SingleChildScrollView that made the dialog
                      // unusable: SelectableText claims the drag gesture for
                      // text selection, so a finger-scroll over the policy body
                      // selects text instead of scrolling. The consent checkbox
                      // sits BELOW this body, so a user who cannot scroll can
                      // never tick it, "Accept Privacy Policy" stays disabled
                      // forever, and the app is unusable from first launch.
                      // Reproduced on the simulator: two separate drag attempts
                      // raised the Copy/Look Up/Share menu and moved the content
                      // barely at all.
                      // Reading the policy does not require selecting it -- the
                      // URL is shown above and reachable from the app -- but
                      // consenting does require scrolling, so scrolling wins.
                      const Text(
                        'Version $_privacyPolicyVersion\n$_privacyPolicyUrl',
                        style: TextStyle(
                          color: _surfaceMutedText,
                          fontSize: 12,
                        ),
                      ),
                      const SizedBox(height: 12),
                      const Text(
                        _privacyPolicyBody,
                        style: TextStyle(height: 1.35),
                      ),
                      if (requireConsent) ...[
                        const SizedBox(height: 12),
                        CheckboxListTile(
                          contentPadding: EdgeInsets.zero,
                          value: checked,
                          controlAffinity: ListTileControlAffinity.leading,
                          onChanged: (value) =>
                              setDialogState(() => checked = value == true),
                          title: const Text(
                            'I have read and agree to the Privacy Policy and understand the data handling described above.',
                            style: TextStyle(fontSize: 13),
                          ),
                        ),
                      ],
                    ],
                  ),
                ),
              ),
              actions: [
                if (requireConsent)
                  TextButton(
                    onPressed: () =>
                        _endOwnDialog<bool>(dialogContext, false),
                    child: const Text('Not now'),
                  ),
                ElevatedButton(
                  onPressed: requireConsent && !checked
                      ? null
                      : () => _endOwnDialog<bool>(dialogContext, true),
                  child:
                      Text(requireConsent ? 'Accept Privacy Policy' : 'Close'),
                ),
              ],
            ),
          ),
        ),
      );
      if (requireConsent && result == true) {
        try {
          await _persistPrivacyConsent();
        } catch (e) {
          // Do NOT set _privacyConsentGranted here: the whole point of this
          // gate is that acceptance survives a relaunch, and claiming
          // success in memory while the durable write failed would just
          // trade "re-prompts forever" for "silently unprotected until the
          // next relaunch, then re-prompts forever anyway." Tell the user
          // now, with the real reason, instead of letting this vanish into
          // _debugLog behind a dialog that quietly closes and comes back
          // next launch with no explanation.
          _debugLog('Failed to persist privacy consent: $e');
          if (mounted) {
            await _showSecureStateFailureDialog(
              title: 'Privacy Policy acceptance was not saved',
              error: e,
            );
          }
          return _privacyConsentGranted;
        }
        _privacyConsentGranted = true;
        if (mounted) setState(() {});
        _startPostPrivacyConsentInitialization();
        return true;
      }
      return !requireConsent || _privacyConsentGranted;
    } finally {
      _privacyConsentPromptOpen = false;
    }
  }

  Future<void> _showTermsAndLegalDialog() async {
    // Read-only, opened by a tap on the dashboard. Never over the decoy, and
    // nothing to remember: the tap is the only way in.
    if (!mounted || _showDecoyCalculator) return;
    final acceptedVersion = _legalAcceptedVersion.trim();
    final acceptedHash = _legalAcceptedHash.trim();
    final acceptanceRecord = acceptedVersion.isNotEmpty &&
            acceptedHash.isNotEmpty
        ? 'Acceptance record on this device\nVersion $acceptedVersion\nHash $acceptedHash'
        : 'No legal acceptance record is stored on this device.';
    await showDialog<void>(
      context: context,
      builder: (dialogContext) => Theme(
        data: _lightSurfaceTheme(context),
        child: AlertDialog(
          backgroundColor: _surfacePanel,
          title: const Text('Terms and Legal'),
          content: ConstrainedBox(
            constraints: BoxConstraints(
              maxHeight: min(MediaQuery.of(context).size.height * 0.66, 680),
            ),
            child: SingleChildScrollView(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    acceptanceRecord,
                    style: const TextStyle(
                      color: _surfaceMutedText,
                      fontSize: 12,
                    ),
                  ),
                  const SizedBox(height: 12),
                  const Text(
                    'Current bundled legal text',
                    style: TextStyle(fontWeight: FontWeight.w700),
                  ),
                  const SizedBox(height: 4),
                  const Text(
                    'The acceptance record above identifies the version and hash accepted on this device. The text below is the current bundled version.',
                    style: TextStyle(fontSize: 12),
                  ),
                  const SizedBox(height: 12),
                  Text(
                    _localizedLegalBody(_legalFallbackBody),
                    style: const TextStyle(height: 1.35),
                  ),
                ],
              ),
            ),
          ),
          actions: [
            ElevatedButton(
              onPressed: () => _endOwnDialog<void>(dialogContext),
              child: const Text('Close'),
            ),
          ],
        ),
      ),
    );
  }

  // Shown when a write to the native secure-state store (Keychain on Apple
  // platforms) fails. Without this, callers like _showPrivacyPolicyDialog
  // would fail silently -- the dialog closes, nothing is saved, and the
  // only symptom is the same prompt reappearing next launch with no
  // indication why. nativeTunnelErrorSummary() (apple_tunnel_diagnostics
  // .dart) is the same redaction-safe formatter already used for tunnel
  // errors elsewhere, so this surfaces the real native domain/code instead
  // of a generic message while still going through the existing
  // path-and-secret scrubbing.
  Future<void> _showSecureStateFailureDialog({
    required String title,
    required Object error,
  }) async {
    // Never over the decoy, and never kept for the unlock: the error belongs
    // to a write that has since been abandoned. The unlock asks for consent
    // again (the write did not commit, so _privacyConsentGranted is still
    // false), and a failure that persists is raised, fresh, by that attempt.
    if (!mounted || _showDecoyCalculator) return;
    final detail = nativeTunnelErrorSummary(error);
    await showDialog<void>(
      context: context,
      barrierDismissible: true,
      builder: (dialogContext) => Theme(
        data: _lightSurfaceTheme(dialogContext),
        child: AlertDialog(
          backgroundColor: _surfacePanel,
          titleTextStyle: const TextStyle(
            color: _surfaceText,
            fontSize: 20,
            fontWeight: FontWeight.w700,
          ),
          contentTextStyle: const TextStyle(color: _surfaceText),
          title: Text(title),
          content: Text(
            "Win's VPN could not securely save this on your Mac, so it "
            "will ask again next time. Nothing else was affected.\n\n"
            "Details: ${detail.isEmpty ? 'unknown error' : detail}",
          ),
          actions: [
            ElevatedButton(
              onPressed: () => _endOwnDialog<void>(dialogContext),
              child: const Text('OK'),
            ),
          ],
        ),
      ),
    );
  }

  Future<bool> _ensurePrivacyConsentForNetworkUse() async {
    if (_privacyConsentGranted) return true;
    return _showPrivacyPolicyDialog(requireConsent: true);
  }

  void _startPostPrivacyConsentInitialization() {
    if (!_privacyConsentGranted || _postPrivacyInitializationStarted) return;
    _postPrivacyInitializationStarted = true;
    unawaited(() async {
      // Device identity must resolve before any account or configuration call
      // can build a request payload. All remaining work is ordered after that
      // local/native read and may then run independently.
      await _loadDeviceHardwareDetails();
      await _determineSecurityOnboardingLayer();
      _startStatusHeartbeat();
      unawaited(_loadCachedNodesFromDisk());
      unawaited(_sharedNodeDiscovery());
      // A-01 (audits 2026-08-28, three reports; owner decision
      // "user-triggered only"): the pre-VPN geo lookup is NO LONGER
      // automatic. It left the device on every launch from the user's real
      // IP to branded hosts (SNI "winsvpn"), a cheap mass-detection signal.
      // It now runs only when the user explicitly taps "show my approximate
      // location" on the disconnected screen; until then the screen shows
      // the offline world map.
      unawaited(_retryPendingLogout());
      // RETIRED (owner decision 2026-08-18): duress dispatch is disabled; the
      // startup retry is no longer invoked so a legacy pending_emergency can
      // never fire an outbound SMS/email after upgrade.
      _maybeRunAppleLiveTunnelSmoke();
      _maybeRunSpeedTestSmoke();
    }());
  }

  Future<Directory> _appleLiveTunnelSmokeDirectory() async {
    final runtimeDirectory =
        (_appleLiveTunnelSmokeRuntimeResultDirectory ?? '').trim();
    if (runtimeDirectory.isNotEmpty) {
      final directory = Directory(runtimeDirectory);
      await directory.create(recursive: true);
      return directory;
    }
    if (_isApplePlatform) {
      final home = Platform.environment['HOME'];
      final basePath = home == null || home.trim().isEmpty
          ? Directory.systemTemp.path
          : Platform.isMacOS
              ? '${home.trim()}/Library/Application Support'
              : '${home.trim()}/Library/Application Support';
      final directory = Directory('$basePath/wins_vpn');
      await directory.create(recursive: true);
      return directory;
    }
    return _appDocumentsDirectory();
  }

  Future<File> _appleLiveTunnelSmokeResultFile() async {
    final directory = await _appleLiveTunnelSmokeDirectory();
    final fileName = _appleLiveTunnelSmokeRuntimeResultFileName ??
        'apple_live_tunnel_smoke.json';
    return File('${directory.path}/$fileName');
  }

  Future<File> _appleLiveTunnelSmokeRequestFile() async {
    final directory = await _appleLiveTunnelSmokeDirectory();
    return File('${directory.path}/apple_live_tunnel_smoke_request.json');
  }

  Future<File> _appleLiveTunnelSmokeRequestPointerFile() async {
    final directory = await _appleLiveTunnelSmokeDirectory();
    return File(
        '${directory.path}/apple_live_tunnel_smoke_request_pointer.json');
  }

  Future<Map<String, dynamic>?> _readAppleLiveTunnelSmokeJsonFile(
      File file) async {
    final decoded = jsonDecode(await file.readAsString());
    if (decoded is! Map) return null;
    return Map<String, dynamic>.from(decoded);
  }

  // Release builds without the live smoke compile the emitter and the PIN
  // reader out entirely (const-false branch), so App.framework carries none of
  // their markers; tools/apple_release_contamination_gate.py checks the bytes.
  Future<void> _writeAppleLiveTunnelSmokeResult(
    String status, {
    Map<String, dynamic> fields = const {},
  }) async {
    if (!kReleaseMode || _appleLiveTunnelSmokeEnabled) {
      await _writeAppleLiveTunnelSmokeResultCompiled(status, fields: fields);
    }
  }

  Future<void> _writeAppleLiveTunnelSmokeResultCompiled(
    String status, {
    Map<String, dynamic> fields = const {},
  }) async {
    _debugLog('Apple live tunnel smoke result write starting: status=$status');
    final safeFields = <String, dynamic>{};
    const reservedKeys = {
      'schema_version',
      'smoke',
      'status',
      'platform',
      'updated_at',
      'secret_material_redacted',
    };
    for (final entry in fields.entries) {
      final key =
          reservedKeys.contains(entry.key) ? 'field_${entry.key}' : entry.key;
      final value = entry.value;
      if (value is bool || value is num) {
        safeFields[key] = value;
      } else if (value is Iterable) {
        safeFields[key] = value
            .map((item) => appleSafeDiagnosticString(item, maxLength: 96))
            .where((item) => item.isNotEmpty)
            .take(16)
            .toList();
      } else {
        safeFields[key] = appleSafeDiagnosticString(value, maxLength: 256);
      }
    }
    final payload = <String, dynamic>{
      'schema_version': 1,
      'smoke': 'apple_live_tunnel',
      'status': status,
      'platform': Platform.operatingSystem,
      'updated_at': DateTime.now().toUtc().toIso8601String(),
      'secret_material_redacted': true,
      ...safeFields,
    };
    _emitAppleLiveTunnelSmokeHarnessLine(
      'WINS_APPLE_LIVE_TUNNEL_SMOKE_RESULT ${jsonEncode(payload)}',
    );
    try {
      final file = await _appleLiveTunnelSmokeResultFile()
          .timeout(const Duration(seconds: 2));
      _debugLog('Apple live tunnel smoke result path resolved: ${file.path}');
      final tempFile = File(
          '${file.path}.tmp.${DateTime.now().microsecondsSinceEpoch}.${status.hashCode.abs()}');
      _debugLog('Apple live tunnel smoke result temp write starting.');
      await tempFile
          .writeAsString(const JsonEncoder.withIndent('  ').convert(payload))
          .timeout(const Duration(seconds: 2));
      _debugLog('Apple live tunnel smoke result temp write complete.');
      await tempFile.rename(file.path).timeout(const Duration(seconds: 2));
      _debugLog('Apple live tunnel smoke result rename complete.');
    } catch (e) {
      _debugLog('Apple live tunnel smoke result file write skipped: $e');
    }
  }

  String _appleLiveTunnelSmokePinValue() {
    if (!kReleaseMode || _appleLiveTunnelSmokeEnabled) {
      return _appleLiveTunnelSmokePinValueCompiled();
    }
    throw StateError('apple_live_tunnel_smoke_disabled');
  }

  String _appleLiveTunnelSmokePinValueCompiled() {
    final pin =
        (_appleLiveTunnelSmokeRuntimePin ?? _appleLiveTunnelSmokePin).trim();
    if (pinPolicyRejectionReason(pin) != null) {
      throw StateError('apple_live_tunnel_smoke_pin_missing_or_invalid');
    }
    return pin;
  }

  Future<Map<String, dynamic>?> _readAppleLiveTunnelSmokeRequest() async {
    try {
      final environment = Platform.environment;
      final envResultFileName =
          (environment['WINS_APPLE_LIVE_TUNNEL_SMOKE_RESULT_FILENAME'] ?? '')
              .trim();
      final envResultDirectory =
          (environment['WINS_APPLE_LIVE_TUNNEL_SMOKE_RESULT_DIRECTORY'] ?? '')
              .trim();
      final envRequestEnabled =
          environment['WINS_APPLE_LIVE_TUNNEL_SMOKE_REQUEST'] == '1' ||
              envResultFileName.isNotEmpty ||
              envResultDirectory.isNotEmpty;
      if (envRequestEnabled) {
        return {
          'schema_version': 1,
          'smoke': 'apple_live_tunnel',
          'enabled': true,
          'created_at_epoch':
              environment['WINS_APPLE_LIVE_TUNNEL_SMOKE_CREATED_AT_EPOCH'] ??
                  '',
          'timeout_seconds':
              environment['WINS_APPLE_LIVE_TUNNEL_SMOKE_TIMEOUT_SECONDS'] ?? '',
          'pin': environment['WINS_APPLE_LIVE_TUNNEL_SMOKE_PIN'] ?? '',
          'double_vpn_requested':
              environment['WINS_APPLE_LIVE_TUNNEL_SMOKE_DOUBLE_VPN'] == '1',
          'result_filename': envResultFileName,
          'result_directory': envResultDirectory,
          'external_leak_audit_requested':
              environment['WINS_APPLE_EXTERNAL_LEAK_AUDIT'] == '1',
          'external_leak_audit_urls':
              environment['WINS_APPLE_EXTERNAL_LEAK_AUDIT_URLS'] ?? '',
          'external_leak_audit_minimum_endpoints':
              environment['WINS_APPLE_EXTERNAL_LEAK_AUDIT_MINIMUM_ENDPOINTS'] ??
                  '',
          'request_source': 'environment',
        };
      }
      if (Platform.isMacOS) return null;

      final pointerFile = await _appleLiveTunnelSmokeRequestPointerFile();
      if (await pointerFile.exists()) {
        final pointer = await _readAppleLiveTunnelSmokeJsonFile(pointerFile);
        if (pointer == null || pointer['enabled'] == false) return null;
        final requestFileName = (pointer['request_filename'] ?? '').toString();
        if (RegExp(r'^apple_live_tunnel_smoke_request_[A-Za-z0-9_.-]+\.json$')
            .hasMatch(requestFileName)) {
          final directory = await _appleLiveTunnelSmokeDirectory();
          final requestFile = File('${directory.path}/$requestFileName');
          if (!await requestFile.exists()) return null;
          return await _readAppleLiveTunnelSmokeJsonFile(requestFile);
        }
        return null;
      }

      final legacyFile = await _appleLiveTunnelSmokeRequestFile();
      if (!await legacyFile.exists()) return null;
      return await _readAppleLiveTunnelSmokeJsonFile(legacyFile);
    } catch (e) {
      _debugLog('Apple live tunnel smoke request read failed: $e');
      return null;
    }
  }

  List<String> _parseAppleExternalLeakAuditUrls(Object? rawValue) {
    final values = <String>[];
    if (rawValue is Iterable) {
      for (final item in rawValue) {
        final value = item.toString().trim();
        if (value.isNotEmpty) values.add(value);
      }
    } else {
      final raw = rawValue?.toString().trim() ?? '';
      if (raw.isNotEmpty) {
        values.addAll(raw
            .split(RegExp(r'[\s,;]+'))
            .map((value) => value.trim())
            .where((value) => value.isNotEmpty));
      }
    }
    return values.take(8).toList(growable: false);
  }

  Future<bool> _shouldRunAppleLiveTunnelSmoke() async {
    if (!_isApplePlatform || (kReleaseMode && !_appleLiveTunnelSmokeEnabled)) {
      return false;
    }
    _appleLiveTunnelSmokeRuntimeDoubleVpnRequested =
        _appleLiveTunnelSmokeDoubleVpnEnabled;
    _appleExternalLeakAuditRuntimeRequested = _appleExternalLeakAuditEnabled;
    _appleExternalLeakAuditRuntimeUrls =
        _parseAppleExternalLeakAuditUrls(_appleExternalLeakAuditUrls);
    _appleExternalLeakAuditRuntimeMinimumEndpoints =
        _appleExternalLeakAuditMinimumEndpoints >= 1 &&
                _appleExternalLeakAuditMinimumEndpoints <= 6
            ? _appleExternalLeakAuditMinimumEndpoints
            : 2;

    final request = await _readAppleLiveTunnelSmokeRequest();
    var requestEnabled = false;
    if (request != null) {
      final timeout =
          int.tryParse((request['timeout_seconds'] ?? '').toString());
      if (timeout != null && timeout >= 30 && timeout <= 600) {
        _appleLiveTunnelSmokeRuntimeTimeoutSeconds = timeout;
      }
      final pin = (request['pin'] ?? '').toString();
      if (pinPolicyRejectionReason(pin) == null) {
        _appleLiveTunnelSmokeRuntimePin = pin;
      }
      _appleLiveTunnelSmokeRuntimeDoubleVpnRequested =
          request['double_vpn_requested'] == true ||
              request['double_vpn_requested']?.toString() == '1';
      final resultFileName = (request['result_filename'] ?? '').toString();
      if (RegExp(r'^apple_live_tunnel_smoke_[A-Za-z0-9_.-]+\.json$')
          .hasMatch(resultFileName)) {
        _appleLiveTunnelSmokeRuntimeResultFileName = resultFileName;
      }
      final resultDirectory = (request['result_directory'] ?? '').toString();
      if (resultDirectory.trim().isNotEmpty &&
          !resultDirectory.contains('\u0000')) {
        _appleLiveTunnelSmokeRuntimeResultDirectory = resultDirectory.trim();
      }
      _appleExternalLeakAuditRuntimeRequested =
          request['external_leak_audit_requested'] == true ||
              request['external_leak_audit_requested']?.toString() == '1';
      final requestAuditUrls =
          _parseAppleExternalLeakAuditUrls(request['external_leak_audit_urls']);
      if (requestAuditUrls.isNotEmpty) {
        _appleExternalLeakAuditRuntimeUrls = requestAuditUrls;
      }
      final minimumEndpoints = int.tryParse(
          (request['external_leak_audit_minimum_endpoints'] ?? '').toString());
      if (minimumEndpoints != null &&
          minimumEndpoints >= 1 &&
          minimumEndpoints <= 6) {
        _appleExternalLeakAuditRuntimeMinimumEndpoints = minimumEndpoints;
      }

      final createdAtEpoch =
          int.tryParse((request['created_at_epoch'] ?? '').toString());
      final nowEpoch = DateTime.now().toUtc().millisecondsSinceEpoch ~/ 1000;
      final requestFresh = request['request_source'] == 'environment' ||
          (createdAtEpoch != null &&
              createdAtEpoch <= nowEpoch + 60 &&
              nowEpoch - createdAtEpoch <= 900);
      requestEnabled = requestFresh &&
          (request['enabled'] == true ||
              request['smoke'] == 'apple_live_tunnel');
      if (!requestFresh) return _appleLiveTunnelSmokeEnabled;
    }
    return requestEnabled || _appleLiveTunnelSmokeEnabled;
  }

  void _maybeRunAppleLiveTunnelSmoke() {
    if (!_privacyConsentGranted) return;
    if (_appleLiveTunnelSmokeStarted) return;
    _appleLiveTunnelSmokeStarted = true;
    _debugLog('Apple live tunnel smoke gate scheduled.');
    unawaited(() async {
      try {
        final shouldRun = await _shouldRunAppleLiveTunnelSmoke();
        _debugLog(
          'Apple live tunnel smoke gate evaluated: shouldRun=$shouldRun '
          'envRequest=${Platform.environment['WINS_APPLE_LIVE_TUNNEL_SMOKE_REQUEST'] == '1'} '
          'envLive=${Platform.environment['WINS_APPLE_LIVE_TUNNEL_SMOKE'] == '1'}',
        );
        if (shouldRun) {
          await _runAppleLiveTunnelSmoke();
        } else {
          _appleLiveTunnelSmokeStarted = false;
        }
      } catch (e) {
        _debugLog('Apple live tunnel smoke gate failed: $e');
        _appleLiveTunnelSmokeStarted = false;
      }
    }());
  }

  Future<Map<String, dynamic>> _runAppleLiveTunnelSmokeSteps() async {
    _debugLog('Apple live tunnel smoke steps starting.');
    await _writeAppleLiveTunnelSmokeResult('running', fields: {
      'phase': 'starting',
      'timeout_seconds': _appleLiveTunnelSmokeRuntimeTimeoutSeconds ??
          _appleLiveTunnelSmokeTimeoutSeconds,
    });

    final legalDoc = await _loadLegalDocumentForAcceptance();
    _legalAcceptedVersion = legalDoc['version'] ?? _legalDocumentVersion;
    _legalAcceptedHash = legalDoc['hash'] ?? _bundledLegalDocumentHash;
    _accountController.text = _freeAccessAccountNumber;
    _pinSetupController.text = _appleLiveTunnelSmokePinValue();
    _isDoubleVpnRequested = _appleLiveTunnelSmokeRuntimeDoubleVpnRequested;
    await _saveVpnRuntimeSettings(
      accountNumber: _freeAccessAccountNumber,
      legalAcceptedVersion: _legalAcceptedVersion,
      legalAcceptedHash: _legalAcceptedHash,
      freeAccessSession: true,
    );

    await _writeAppleLiveTunnelSmokeResult('running', fields: {
      'phase': 'fetching_free_access_config',
      'legal_payload_present': _legalAcceptedVersion.isNotEmpty,
    });
    await _loginWithFreeAccess();

    if (!_isFreeAccessSession || !_hasUsableVpnConfig(_cachedVpnConfig)) {
      throw StateError('free_access_config_unavailable');
    }
    final doubleVpnRequested = _appleLiveTunnelSmokeRuntimeDoubleVpnRequested;
    final doubleVpnActive = _boolValue(_cachedVpnConfig['double_vpn_active']);
    final doubleVpnCoreId = _stringValue(
          _cachedVpnConfig,
          ['double_vpn_core_id', 'doublevpncoreid'],
        ) ??
        '';
    final doubleVpnExitSlug = _stringValue(
          _cachedVpnConfig,
          ['double_vpn_exit_slug', 'doublevpnexitslug'],
        ) ??
        '';
    final doubleVpnVerified = !doubleVpnRequested ||
        (doubleVpnActive &&
            doubleVpnCoreId.isNotEmpty &&
            doubleVpnExitSlug.isNotEmpty);

    await _writeAppleLiveTunnelSmokeResult('running', fields: {
      'phase': 'connecting',
      'free_access_session': _isFreeAccessSession,
      'node_count': _locations.length,
      'free_node_count': _freeNodeSlugs.length,
    });
    await _connectWithSmartProtocol();

    final ready = await _waitForTunnelReady(
      attempts: 30,
      delay: const Duration(milliseconds: 500),
    );
    final readiness = await _latestTunnelReadiness();
    final diagnosticReadiness =
        _lastAppleConnectedReadinessSnapshot ?? readiness;
    final probeArguments = _appleExternalLeakAuditRuntimeRequested
        ? <String, dynamic>{
            'externalLeakAuditRequested': true,
            'externalLeakAuditUrls': _appleExternalLeakAuditRuntimeUrls,
            'externalLeakAuditMinimumEndpoints':
                _appleExternalLeakAuditRuntimeMinimumEndpoints,
          }
        : null;
    final probe = await _methodChannel
        .invokeMapMethod<String, dynamic>('probeVpnInternet', probeArguments)
        .timeout(const Duration(seconds: 8), onTimeout: () => null);
    final probeSnapshot =
        (probe?['ok'] == true || probe?['internet_probe_attempted'] == true)
            ? probe
            : (_lastAppleInternetProbeFailure ?? probe);
    // Current connected PROOF, never mere session existence: a held Winn v3
    // session (recovering or blocked) must not pass this smoke test, and it
    // is reported on its own below.
    final connected = await _readNativeTunnelConnectedProof();
    final heldSession = _winn3HostLifecycle.holdsSession;
    final probeOk = probe?['ok'] == true;
    final externalLeakAuditOk = !_appleExternalLeakAuditRuntimeRequested ||
        probe?['external_leak_audit_passed'] == true;
    final expectedTransportMode =
        appleExpectedLiveTransportMode(forceXray: _forceXrayForDiagnostics);
    final allowedTransportModes =
        appleAllowedLiveTransportModes(forceXray: _forceXrayForDiagnostics);
    final observedTransportMode = appleReadinessString(
        diagnosticReadiness, 'provider_message_probe_transport_mode');
    final transportModeVerified = appleLiveTransportModeVerified(
        forceXray: _forceXrayForDiagnostics,
        observedTransportMode: observedTransportMode,
        transportModeSupported: appleReadinessBool(
            readiness, 'provider_message_probe_transport_mode_supported'),
        transportModeConsistent: appleReadinessBool(
            readiness, 'provider_message_probe_transport_mode_consistent'),
        executableSha256MatchesExpected: appleReadinessBool(readiness,
            'provider_message_probe_executable_sha256_matches_expected'));
    final passed = ready &&
        connected &&
        probeOk &&
        externalLeakAuditOk &&
        doubleVpnVerified &&
        transportModeVerified;

    final result = <String, dynamic>{
      'phase': 'connected_probe_complete',
      'ready': ready,
      'connected': connected,
      'winn3_held_session': heldSession,
      'passed': passed,
      'expected_transport_mode': expectedTransportMode,
      'allowed_transport_modes': allowedTransportModes,
      'observed_transport_mode': observedTransportMode,
      'transport_mode_verified': transportModeVerified,
      'double_vpn_requested': doubleVpnRequested,
      'double_vpn_active': doubleVpnActive,
      'double_vpn_verified': doubleVpnVerified,
      'double_vpn_core_id': doubleVpnCoreId,
      'double_vpn_exit_slug': doubleVpnExitSlug,
      ...appleLiveTunnelSmokeReadinessSnapshot(diagnosticReadiness),
      ...appleLiveTunnelSmokeProbeSnapshot(probeSnapshot),
      if (_lastAppleTunnelNeedsPermissionApproval)
        'vpn_configuration_permission_pending': true,
    };
    if (passed) {
      result['readiness_summary'] =
          'Apple live VPN connect/probe/disconnect passed.';
    } else {
      final lastAppleFailure = appleSafeDiagnosticString(
        _lastAppleTunnelFailureStatus,
        maxLength: 160,
      );
      final probeSummary = appleSafeDiagnosticString(
          result['internet_probe_summary'],
          maxLength: 160);
      final diagnostic = appleTunnelDebugFailureSummary(probeSnapshot, null);
      final safeDiagnostic =
          appleSafeDiagnosticString(diagnostic, maxLength: 160);
      final readinessFailure = lastAppleFailure.isNotEmpty
          ? lastAppleFailure
          : appleTunnelUserFailureStatus(readiness, null);
      final probeFailure =
          probeSummary.isNotEmpty && probeSummary != 'internet_probe_ok'
              ? probeSummary
              : safeDiagnostic;
      result['error'] = appleLiveTunnelContractFailureSummary(
        doubleVpnRequested: doubleVpnRequested,
        doubleVpnVerified: doubleVpnVerified,
        ready: ready,
        connected: connected,
        transportModeVerified: transportModeVerified,
        probeOk: probeOk,
        externalLeakAuditOk: externalLeakAuditOk,
        readinessFailure: readinessFailure,
        probeFailure: probeFailure,
      );
      result['readiness_summary'] = result['error'];
    }
    return result;
  }

  Future<Map<String, List<int>?>> _captureAppleSmokeLocalState() async {
    final directory = await _appDocumentsDirectory();
    const mutableFileNames = [
      'user_pin.txt',
      'vpn_settings.txt',
      'calc_state.json',
      'vpn_config.txt',
      'client_keypair.json',
      'node_cache.json',
    ];
    // user_pin.txt and vpn_settings.txt are Keychain-backed on Apple after
    // H-2, so they must be captured/restored through the secure-state
    // helpers, not raw file I/O - otherwise this snapshot would silently
    // miss the real credential/settings and the smoke test's throwaway
    // values would never be restored.
    const secureStateFileNames = {
      'user_pin.txt',
      'vpn_settings.txt',
      'calc_state.json',
    };
    final snapshot = <String, List<int>?>{};
    for (final name in mutableFileNames) {
      if (Platform.isIOS && name == 'vpn_config.txt') {
        final encoded = await _readEncodedVpnConfigOnApple();
        snapshot[name] = encoded == null ? null : utf8.encode(encoded);
        continue;
      }
      if (secureStateFileNames.contains(name)) {
        final encoded = await _readSensitiveText(name);
        snapshot[name] = encoded == null ? null : utf8.encode(encoded);
        continue;
      }
      final file = File('${directory.path}/$name');
      snapshot[name] = await file.exists() ? await file.readAsBytes() : null;
    }
    return snapshot;
  }

  Future<void> _restoreAppleSmokeLocalState(
      Map<String, List<int>?> snapshot) async {
    final directory = await _appDocumentsDirectory();
    const secureStateFileNames = {
      'user_pin.txt',
      'vpn_settings.txt',
      'calc_state.json',
    };
    for (final entry in snapshot.entries) {
      final bytes = entry.value;
      if (bytes == null && Platform.isIOS && entry.key == 'vpn_config.txt') {
        await _deleteVpnConfigOnApple();
      } else if (secureStateFileNames.contains(entry.key)) {
        if (bytes == null) {
          await _deleteSensitiveText(entry.key);
        } else {
          await _writeSensitiveText(entry.key, utf8.decode(bytes));
        }
      } else if (bytes == null) {
        final file = File('${directory.path}/${entry.key}');
        if (await file.exists()) await file.delete();
      } else if ((Platform.isIOS || Platform.isMacOS) &&
          entry.key == 'vpn_config.txt') {
        await _persistEncodedVpnConfigOnApple(utf8.decode(bytes));
      } else {
        final file = File('${directory.path}/${entry.key}');
        await file.writeAsBytes(bytes, flush: true);
      }
    }
  }

  Future<void> _runAppleLiveTunnelSmoke() async {
    _debugLog('Apple live tunnel smoke run starting.');
    var status = 'failed';
    var fields = <String, dynamic>{};
    Map<String, List<int>?>? localStateSnapshot;
    try {
      localStateSnapshot = await _captureAppleSmokeLocalState();
      fields = await _runAppleLiveTunnelSmokeSteps().timeout(
        Duration(
          seconds: max(
            _appleLiveTunnelSmokeRuntimeTimeoutSeconds ??
                _appleLiveTunnelSmokeTimeoutSeconds,
            30,
          ),
        ),
      );
      status = fields['passed'] == true ? 'passed' : 'failed';
    } on TimeoutException {
      _debugLog('Apple live tunnel smoke timed out.');
      fields = {
        'phase': 'timeout',
        'passed': false,
        'error': 'apple_live_tunnel_smoke_timeout',
      };
    } catch (error) {
      Map<dynamic, dynamic>? readiness;
      try {
        readiness =
            await _latestTunnelReadiness().timeout(const Duration(seconds: 5));
      } catch (e) {
        _debugLog('Apple live tunnel smoke readiness snapshot timed out: $e');
      }
      fields = {
        'phase': 'failed',
        'passed': false,
        'error': appleSafeDiagnosticString(error, maxLength: 160),
        ...appleLiveTunnelSmokeReadinessSnapshot(readiness),
      };
    } finally {
      _debugLog('Apple live tunnel smoke stop starting.');
      var stopped = false;
      try {
        stopped = await _stopNativeTunnel(keepVpnLauncher: true)
            .timeout(const Duration(seconds: 8), onTimeout: () => false);
      } catch (e) {
        _debugLog('Apple live tunnel smoke stop failed: $e');
      }
      _debugLog('Apple live tunnel smoke stop complete: stopped=$stopped');
      fields = {
        ...fields,
        'disconnect_attempted': true,
        'disconnect_ok': stopped,
      };
      var localStateRestored = false;
      if (localStateSnapshot != null) {
        try {
          await _restoreAppleSmokeLocalState(localStateSnapshot);
          localStateRestored = true;
          await _determineSecurityOnboardingLayer();
        } catch (e) {
          _debugLog('Apple live tunnel smoke state restore failed: $e');
        }
      }
      fields['local_state_restored'] = localStateRestored;
      final passed =
          fields['passed'] == true && stopped && localStateRestored;
      fields['passed'] = passed;
      status = passed ? 'passed' : 'failed';
      if (!stopped) {
        fields.putIfAbsent(
          'error',
          () => 'apple_live_tunnel_smoke_disconnect_failed',
        );
      } else if (!localStateRestored) {
        fields.putIfAbsent(
          'error',
          () => 'apple_live_tunnel_smoke_restore_failed',
        );
      }
      await _writeAppleLiveTunnelSmokeResult(status, fields: fields);
    }
  }

  bool _isNotifiableAnnouncement(String message) {
    final normalized = message.trim();
    if (normalized.isEmpty) return false;
    if (normalized == _defaultAnnouncement) return false;
    if (normalized == 'Syncing latest security updates...') return false;
    if (normalized == 'Secure Connection Established.') return false;
    return true;
  }

  /// Freedesktop notification bodies are parsed as a small markup subset, and
  /// daemons advertising `body-hyperlinks` (GNOME Shell, Plasma) turn
  /// `<a href="...">` into a CLICKABLE link. The announcement string is
  /// whatever the control plane last returned, so on Linux it must be escaped
  /// before it reaches either the native notify-send path in
  /// linux_tunnel_backend.cc or the notify-send fallback below -- otherwise a
  /// seized control plane or a leaked admin token could push a tappable
  /// "update required, download here" phishing link straight into the user's
  /// desktop notifications. Escaping (rather than deleting) keeps the literal
  /// characters visible for legitimate text such as "<3" or "A & B".
  ///
  /// Only Linux interprets markup here: Android (setContentText/BigTextStyle),
  /// Apple (UNNotificationContent) and Windows (Shell_NotifyIconW balloon) all
  /// take plain strings, so escaping them would show users literal `&lt;`.
  static String _escapeNotificationBodyMarkup(String body) {
    return body
        .replaceAll('&', '&amp;')
        .replaceAll('<', '&lt;')
        .replaceAll('>', '&gt;');
  }

  Future<bool> _showSystemAnnouncementNotification(String message) async {
    final title = _t("Win's VPN Announcement");
    final bounded = _boundedAnnouncementText(message);
    final body =
        Platform.isLinux ? _escapeNotificationBodyMarkup(bounded) : bounded;
    try {
      final shown = await _methodChannel.invokeMethod<bool>(
        'showAnnouncementNotification',
        {'title': title, 'body': body},
      ).timeout(const Duration(seconds: 4));
      if (shown == true) return true;
    } catch (e) {
      _debugLog('Native announcement notification skipped: $e');
      // macOS has no safe shell-based fallback: announcement text can come
      // from a server response, and no quoting scheme for an interpolated
      // `osascript -e` string is proof against AppleScript injection (see
      // H-1). Fail closed instead of shelling out with untrusted content.
      if (!Platform.isLinux) return false;
    }

    try {
      if (Platform.isLinux) {
        // Safe: notify-send receives an argument vector, not a shell
        // string, so there is no shell quoting to get wrong. `body` has
        // already been markup-escaped above, which is the separate hazard
        // notify-send's own argv handling does not cover. Process is started
        // with Process.start and SIGKILLed in finally so the same unbounded
        // buffering that crashed a 128 GB MacBook via _probePingLatencyMs
        // cannot recur here (see MACOS_MEMORY_BLOWUP_20260808.md).
        Process? notifyProcess;
        StreamSubscription<List<int>>? notifyOutSub;
        StreamSubscription<List<int>>? notifyErrSub;
        try {
          final process = await Process.start(
            'notify-send',
            ['--app-name=Win\'s VPN', title, body],
          );
          notifyProcess = process;
          final buffer = StringBuffer();
          var captured = 0;
          void capture(List<int> chunk) {
            if (captured >= _pingOutputByteCap) return;
            final room = _pingOutputByteCap - captured;
            final slice = chunk.length <= room ? chunk : chunk.sublist(0, room);
            captured += slice.length;
            buffer.write(utf8.decode(slice, allowMalformed: true));
          }

          final outDone = Completer<void>();
          final errDone = Completer<void>();
          void settle(Completer<void> c) {
            if (!c.isCompleted) c.complete();
          }

          notifyOutSub = process.stdout.listen(
            capture,
            onDone: () => settle(outDone),
            onError: (_) => settle(outDone),
            cancelOnError: true,
          );
          notifyErrSub = process.stderr.listen(
            capture,
            onDone: () => settle(errDone),
            onError: (_) => settle(errDone),
            cancelOnError: true,
          );
          final settled = await Future.wait<Object?>([
            process.exitCode,
            outDone.future,
            errDone.future,
          ]).timeout(const Duration(seconds: 4));
          return settled.first == 0;
        } catch (e) {
          _debugLog('Fallback announcement notification skipped: $e');
          return false;
        } finally {
          notifyProcess?.kill(ProcessSignal.sigkill);
          unawaited(notifyOutSub?.cancel());
          unawaited(notifyErrSub?.cancel());
        }
      }
    } catch (e) {
      _debugLog('Fallback announcement notification skipped: $e');
    }
    return false;
  }

  Future<void> _maybeNotifyServerAnnouncement(String message,
      {bool force = false}) async {
    final normalized = message.trim();
    if (!_isNotifiableAnnouncement(normalized)) return;
    if (!_isLoggedIn && !_isConnected && !_isFreeAccessSession) return;

    final hash = _sha256Hex(normalized);
    final settings = await _readVpnRuntimeSettings();
    final lastHash =
        (settings['last_notified_announcement_hash'] ?? '').toString();
    if (!force && lastHash == hash) return;

    final shown = await _showSystemAnnouncementNotification(normalized);
    if (shown || force) {
      await _writeVpnRuntimeSetting('last_notified_announcement_hash', hash);
      await _writeVpnRuntimeSetting('last_notified_announcement_at',
          DateTime.now().toUtc().toIso8601String());
    }
  }

  // device_auth_token authorizes device-mutation calls (see M-5). It is
  // stored inside vpn_settings.txt (see _persistDeviceAuthTokenRequired)
  // rather than its own file for the same native-allowlist reason as the
  // PIN attempt ledger above.
  Future<String?> _readDeviceAuthToken() async {
    final settings = await _readVpnRuntimeSettings();
    final token = (settings['device_auth_token'] ?? '').toString().trim();
    return token.isEmpty ? null : token;
  }

  // M-7-style strict persistence for device_auth_token specifically (H-1).
  // _saveVpnRuntimeSettings wraps its entire body in one bare try/catch, so
  // a secure-storage write failure there was silently swallowed and the
  // caller proceeded as if the token had been saved. Without a durably
  // saved token, a device can never send an authenticated /logout
  // (_sendLogoutToHub skips the call outright when the token is empty),
  // and _queuePendingLogout/_retryPendingLogout are left permanently stuck
  // retrying with no token to retry.
  //
  // This deliberately does not go through _saveVpnRuntimeSettings: no
  // try/catch around the mutation (let a genuine failure propagate), then
  // an unconditional durable read-back that bypasses
  // _readVpnRuntimeSettings/_readDeviceAuthToken -- both swallow read
  // failures for the many unrelated, best-effort settings they back --
  // the same way _readPinAttemptState bypasses it for the PIN lockout
  // ledger above.
  Future<void> _persistDeviceAuthTokenRequired(String token) async {
    final trimmed = token.trim();
    if (trimmed.length < 16) {
      throw StateError(
          'Device auth token is empty or too short to persist durably');
    }
    await _mutateVpnRuntimeSettings((data) {
      data['device_auth_token'] = trimmed;
    });
    // A write that is acknowledged but does not durably stick must still be
    // treated as a failure rather than silently accepted (mirrors
    // _writePinAttemptState's own durable read-back).
    await _settingsMutationQueue;
    final settings = await _readSensitiveJsonMap('vpn_settings.txt');
    final persisted = (settings['device_auth_token'] ?? '').toString();
    if (persisted != trimmed) {
      throw StateError('Device auth token failed durable read-back');
    }
  }

  Future<bool> _sendLogoutToHub({
    required bool freeAccess,
    required String accountNumber,
    required String deviceId,
    required String? deviceAuthToken,
  }) async {
    final token = deviceAuthToken?.trim() ?? '';
    if (token.isEmpty) {
      // No device auth token means this device predates activation/verify
      // issuing one, or it was never captured. Per M-5, treat it as
      // needing re-activation rather than sending an unauthenticated
      // device-mutation request.
      _debugLog(
          'Logout skipped: device auth token unavailable; device needs re-activation.');
      return false;
    }
    final endpoints = await _resolveDynamicEndpoints();
    final gatewayEndpoints = GatewayEndpoints(
      gateway: endpoints['gateway']!,
    );
    final logoutBody = jsonEncode({
      'account_number': accountNumber,
      'device_id': deviceId,
    });
    final headers = _jsonHeaders();
    headers['Authorization'] = 'Bearer $token';
    final gateways = freeAccess
        ? freeLogoutGateways(gatewayEndpoints)
        : logoutGateways(gatewayEndpoints);
    // The staggered hub window, not a serial walk: 29 fronts at 4 s each was
    // up to 116 s of spinner on Deactivate, and of the startup cleanup
    // barrier on the next launch, before the logout could even be queued.
    // Only the hub's own acknowledgment wins; every other reply loses and the
    // next front is tried. A timed-out request is aborted, not left open.
    final outcome = await runHubRequestWindow<bool>(
      urls: gateways,
      preference: _hubOriginPreference,
      policy: const HubRequestWindowPolicy(
        perRequestTimeout: Duration(seconds: 4),
        totalDeadline: kHubVerifyTotalDeadline,
      ),
      attempt: (url, abort) async {
        try {
          final response = await sendHubRequest(
            _controlPlaneClient,
            'POST',
            Uri.parse(url),
            abort: abort,
            headers: headers,
            body: logoutBody,
          );
          if (hubLogoutAcknowledged(response.statusCode, response.body)) {
            return const HubAttemptResult<bool>.accepted(true);
          }
        } catch (_) {}
        return const HubAttemptResult<bool>.rejected();
      },
    );
    return outcome.value == true;
  }

  // L-1: returns whether the pending-logout record is actually durable
  // rather than swallowing a write failure. The deactivation caller must
  // not delete local credentials on the strength of an unverified write -
  // that would leave the server with a stale device and no durable client
  // token left to ever remove it - so this both writes and reads the value
  // back before reporting success.
  Future<bool> _queuePendingLogout({
    required bool freeAccess,
    required String accountNumber,
    required String deviceId,
    String? deviceAuthToken,
  }) async {
    final encoded = jsonEncode({
      'free_access': freeAccess,
      'account_number': accountNumber,
      'device_id': deviceId,
      'device_auth_token': deviceAuthToken,
      'created_at': DateTime.now().toUtc().toIso8601String(),
    });
    try {
      return await _pendingLogoutOperations.run('pending_logout', () async {
        final existing = _decodePendingLogout(
            await _readSensitiveText('pending_logout.json'));
        if (existing != null &&
            !_pendingLogoutSameDevice(existing, freeAccess, accountNumber,
                deviceId)) {
          // The one durable slot holds another device row's revocation (a
          // different account on this install). Overwriting it would erase
          // that revocation; refusing keeps this account's credentials too.
          _debugLog('Pending logout slot holds another account; not replaced.');
          return false;
        }
        // Empty, unreadable, or this same device row: a newer token for the
        // same row supersedes the queued one.
        await _writeSensitiveText('pending_logout.json', encoded);
        return await _readSensitiveText('pending_logout.json') == encoded;
      });
    } catch (e) {
      _debugLog('Pending logout queue write failed: $e');
      return false;
    }
  }

  Map? _decodePendingLogout(String? encoded) {
    if (encoded == null) return null;
    try {
      final decoded = jsonDecode(encoded);
      return decoded is Map ? decoded : null;
    } catch (_) {
      return null;
    }
  }

  bool _pendingLogoutSameDevice(
    Map record,
    bool freeAccess,
    String accountNumber,
    String deviceId,
  ) {
    String normalized(Object? value) => (value ?? '')
        .toString()
        .replaceAll(RegExp(r'[^0-9A-Za-z]'), '')
        .toUpperCase();
    return (record['free_access'] == true) == freeAccess &&
        normalized(record['account_number']) == normalized(accountNumber) &&
        (record['device_id'] ?? '').toString() == deviceId;
  }

  /// Retires the slot only if it still holds [expected]: a record queued
  /// while a retry was in flight belongs to a later logout and must survive.
  Future<bool> _removePendingLogoutIfUnchanged(String expected) =>
      _pendingLogoutOperations.run('pending_logout', () async {
        if (await _readSensitiveText('pending_logout.json') != expected) {
          return false;
        }
        return _deleteSensitiveArtifactVerified('pending_logout.json');
      });

  /// Ordinary account cleanup removes only the departing account's queued
  /// logout. Another account's pending revocation survives it.
  Future<bool> _deletePendingLogoutForScope(String scopeToken) =>
      _pendingLogoutOperations.run('pending_logout', () async {
        final encoded = await _readSensitiveText('pending_logout.json');
        if (encoded == null) return true;
        final record = _decodePendingLogout(encoded);
        if (record != null) {
          final accountNumber = (record['account_number'] ?? '').toString();
          final accountScope = accountNumber.trim().isEmpty
              ? _freeAccessAccountNumber
              : accountNumber;
          if (_clientKeyScopeToken(accountScope) != scopeToken) return true;
        }
        // This account's record, or one too damaged to ever be retried.
        return _deleteSensitiveArtifactVerified('pending_logout.json');
      });

  Future<void> _retryPendingLogout() async {
    if (!_privacyConsentGranted) return;
    try {
      final encoded = await _pendingLogoutOperations.run(
        'pending_logout',
        () => _readSensitiveText('pending_logout.json'),
      );
      if (encoded == null) return;
      final decoded = jsonDecode(encoded);
      if (decoded is! Map) return;
      final freeAccess = decoded['free_access'] == true;
      final accountNumber = (decoded['account_number'] ?? '').toString();
      final deviceId = (decoded['device_id'] ?? '').toString();
      final deviceAuthToken = (decoded['device_auth_token'] ?? '').toString();
      if (deviceId.trim().isEmpty) {
        await _removePendingLogoutIfUnchanged(encoded);
        return;
      }
      final ok = await _sendLogoutToHub(
        freeAccess: freeAccess,
        accountNumber: accountNumber.trim().isEmpty
            ? _freeAccessAccountNumber
            : accountNumber,
        deviceId: deviceId,
        deviceAuthToken:
            deviceAuthToken.trim().isEmpty ? null : deviceAuthToken,
      );
      if (ok) await _removePendingLogoutIfUnchanged(encoded);
    } catch (e) {
      _debugLog('Pending logout retry skipped: $e');
    }
  }

  // ====================================================================
  // Duress (panic) code + emergency dispatch.
  //
  // A duress code is a second 6-digit PIN, stored as a PBKDF2 envelope under
  // `duress_credential` inside vpn_settings.txt -- exactly where the recovery
  // credential rides, and for the same reason: the native secure-store
  // allowlists on Android/Windows/Linux cannot take a brand-new filename from
  // here. The code itself is never stored.
  //
  // WHAT AN OBSERVER SEES, and this paragraph is only allowed to say what has
  // been MEASURED on a device rather than what the code appears to do. The
  // first end-to-end device run (2026-08-06) found the previous version of
  // this comment simply false: it claimed nothing observable separated a
  // duress entry from a mistyped code, while the duress entry alone raised a
  // modal dialog 1047 ms later and alone skipped a ~60 ms ledger write. Both
  // are now closed by construction rather than by assertion:
  //   * every entry that fails to unlock raises the SAME dialog from the SAME
  //     call site (_showEntryFailurePopup, buildEntryFailureDialog);
  //   * the duress branch pays for the SAME attempt-ledger write and arms
  //     only after it (classifyCredentialEntry, _verifyUserPin).
  // The suite asserts the equality itself, not the wording of this comment.
  //
  // HONEST PER-PLATFORM REALITY (full write-up in the dated handoffs):
  //   * The covert, cross-platform action is a secure WIPE of every
  //     incriminating local record -- the named secure-state files through the
  //     native delete channel, then a sweep of the app's own storage that
  //     keeps only the camouflage latch and, while an alert is queued, the
  //     encrypted secure-state directory carrying it.
  //   * Android's ActivityManager.clearApplicationUserData() is deliberately
  //     NOT on this path. It leaves an empty shell that is indistinguishable
  //     from a fresh install -- which is the problem, not the goal: a fresh
  //     install shows the branded consent dialog over the real activation
  //     screen, so the strongest wipe was also the thing that took the
  //     disguise off a seized phone. The native handler still exists for
  //     non-duress use; the duress path uses the sweep above instead.
  //   * iOS CANNOT self-delete or clear its own container from code at all;
  //     the wipe there is Keychain + files only and the icon stays put.
  //   * OFFLINE -- the realistic inspection case -- the alert cannot be sent,
  //     so it is queued (encrypted at rest) for a later retry and the
  //     secure-state directory is spared so the retry can still fire. A wipe
  //     that destroyed the queue would also destroy the only copy of the
  //     undelivered alert, so "delete everything now" and "the alert
  //     eventually leaves" cannot both hold when offline; this code chooses
  //     delivery. Everything outside that one directory still goes.
  //   * The app remains a plain calculator afterwards, on every branch. That
  //     is what the camouflage latch below is for.
  // ====================================================================

  /// Reads/writes the durable camouflage latch: the small, deliberately
  /// ordinary record whose PRESENCE tells the next cold start to come up as
  /// the decoy calculator.
  ///
  /// This exists because the decoy used to be armed from `appIsActivated`,
  /// i.e. "a PIN credential exists" -- and the duress wipe deletes exactly
  /// that credential. Controlled A/B on a device, both cold starts: before
  /// duress the app showed the calculator; after duress it showed the branded
  /// "Privacy Policy and Legal Consent" dialog naming the service and its
  /// domain, over the real activation screen. The feature built to make a
  /// seized phone look innocent was what stripped the disguise off it.
  ///
  /// The latch is a file the wipe keeps on purpose ([duressWipeKeepsEntry]),
  /// named and filled as a calculator's own display preferences
  /// ([kCamouflageLatchFileName], [kCamouflageLatchContents]) so that the one
  /// thing surviving a thorough wipe is the least remarkable thing on the
  /// device. Nothing in it names this app, a VPN, a decoy, or a duress code;
  /// an inspector who opens it finds a calculator's settings, which is what an
  /// innocent phone has.
  ///
  /// Where camouflage applies (Android and iOS phones, both of which answer
  /// `getAppDocumentsDirectory`), the latch lives only where the platform
  /// says. A failed answer THROWS here rather than falling back to the
  /// guessed path [_appDocumentsDirectory] uses: the latch is never there, so
  /// a guess reads as "not latched", and a write or a clear there is a no-op
  /// that reports success. A platform that does not answer within the 4 s
  /// the secure-state reads allow ([_readSensitiveText]) counts as failed.
  Future<File> _camouflageLatchFile() async {
    final Directory directory;
    if (_supportsInAppCamouflage) {
      final path = (await _methodChannel
              .invokeMethod<String>('getAppDocumentsDirectory')
              .timeout(const Duration(seconds: 4)))
          ?.trim();
      if (path == null || path.isEmpty) {
        throw StateError('App documents directory unavailable');
      }
      directory = Directory(path);
      await directory.create(recursive: true);
    } else {
      directory = await _appDocumentsDirectory();
    }
    return File(
        '${directory.path}${Platform.pathSeparator}$kCamouflageLatchFileName');
  }

  /// `true` latched, `false` not latched, `null` when the check itself failed.
  /// A failed check is never "not latched": that answer is the one that takes
  /// the disguise off a wiped phone. Callers arm the decoy on `null`, and do
  /// not write a latch on its strength alone (see
  /// [_determineSecurityOnboardingLayer]), so a passing failure on an install
  /// that was never activated does not leave it a calculator for good.
  Future<bool?> _camouflageLatched() async {
    if (!_supportsInAppCamouflage) return false;
    try {
      return await (await _camouflageLatchFile()).exists();
    } catch (e) {
      _debugLog('Camouflage latch read unavailable: $e');
      return null;
    }
  }

  /// Idempotent. Called every time the decoy is armed and, unconditionally, at
  /// the end of the duress wipe, so no ordering or failure above can leave the
  /// app un-disguised.
  Future<void> _latchCamouflage() async {
    if (!_supportsInAppCamouflage) return;
    try {
      // An ordinary cleanup journal is proof that teardown, not duress, is in
      // progress. Do not recreate the latch while that transaction removes it.
      if (await _readAccountCleanupJournal() != null) return;
      final file = await _camouflageLatchFile();
      if (await file.exists()) return;
      await file.writeAsString(jsonEncode(kCamouflageLatchContents),
          flush: true);
    } catch (e) {
      _debugLog('Camouflage latch write deferred: $e');
    }
  }

  Future<String?> _readDuressCredential() async {
    await _settingsMutationQueue;
    final settings = await _readSensitiveJsonMap('vpn_settings.txt');
    final stored = settings['duress_credential'];
    if (stored is! String || stored.trim().isEmpty) return null;
    return stored;
  }

  Future<void> _writeDuressCredential(String? credential) async {
    await _mutateVpnRuntimeSettings((data) {
      if (credential == null) {
        data.remove('duress_credential');
      } else {
        data['duress_credential'] = credential;
      }
    });
    final persisted = await _readDuressCredential();
    if (persisted != credential) {
      throw StateError('Duress credential failed durable read-back');
    }
  }

  Future<String?> _readTrustedContact() async {
    await _settingsMutationQueue;
    final settings = await _readSensitiveJsonMap('vpn_settings.txt');
    return sanitizeTrustedContact('${settings['duress_contact'] ?? ''}');
  }

  Future<void> _writeTrustedContact(String? contact) async {
    final sanitized = contact == null ? null : sanitizeTrustedContact(contact);
    await _mutateVpnRuntimeSettings((data) {
      if (sanitized == null) {
        data.remove('duress_contact');
      } else {
        data['duress_contact'] = sanitized;
      }
    });
    final persisted = await _readTrustedContact();
    if (persisted != sanitized) {
      throw StateError('Trusted contact failed durable read-back');
    }
  }

  /// Optional secondary email for the trusted contact, stored beside the
  /// primary phone number in vpn_settings.txt (`duress_contact_email`). The
  /// device-native SMS path uses only the phone; the email exists for the
  /// pending iOS relay decision (see the dated handoff) and is never required.
  Future<String?> _readTrustedContactEmail() async {
    await _settingsMutationQueue;
    final settings = await _readSensitiveJsonMap('vpn_settings.txt');
    return sanitizeTrustedContact('${settings['duress_contact_email'] ?? ''}');
  }

  Future<void> _writeTrustedContactEmail(String? email) async {
    final sanitized = email == null ? null : sanitizeTrustedContact(email);
    await _mutateVpnRuntimeSettings((data) {
      if (sanitized == null) {
        data.remove('duress_contact_email');
      } else {
        data['duress_contact_email'] = sanitized;
      }
    });
  }

  /// Enrolls the duress code, and (only for the Android device-native SMS
  /// path) a trusted-contact phone number. Validation mirrors the real PIN's
  /// setup backstop: [duressPinPolicyRejectionReason] enforces a strong,
  /// six-digit code distinct from the real one, and [PinCredentialCodec.encode]
  /// re-checks strength as the last line of defence. Writes are verified on
  /// read-back, exactly like the recovery credential, so the user is never told
  /// a panic code is armed when it is not.
  ///
  /// [trustedPhone] is stored ONLY when a real SMS alert is being enrolled
  /// (Android, with the SMS permission granted). When it is null (iOS, or an
  /// Android user who declined SMS), NO contact is stored, so the duress code
  /// is a local-wipe-only action and nothing in storage implies an outbound
  /// alert. That is the whole point of passing it conditionally.
  /// Returns true when enrolled. Returns false, having written NOTHING,
  /// when [stillAway] reports a relock (the dialog that asked for this was
  /// removed): it is checked after the credential encoding and again inside
  /// the one settings write, at the moment of writing. The credential and
  /// both contact fields go in that single write, so a relock can never
  /// leave half an enrollment.
  Future<bool> _enrollDuress({
    required String realPin,
    required String duressPin,
    String? trustedPhone,
    String? trustedEmail,
    bool Function()? stillAway,
  }) async {
    final away = stillAway ?? () => true;
    final rejection = duressPinPolicyRejectionReason(realPin, duressPin);
    if (rejection != null) {
      throw StateError(
          'Refused to store a duress code that fails setup policy');
    }
    String? phone;
    if (trustedPhone != null) {
      phone = sanitizeTrustedContact(trustedPhone);
      if (phone == null || !_isPhoneShapedContact(phone)) {
        throw StateError('A valid phone number is required for the SMS alert');
      }
    }
    final email =
        phone == null ? null : sanitizeTrustedContact(trustedEmail ?? '');
    final credential = await _pinCredentialCodec.encode(duressPin);
    // A relock during the encoding: nothing is written, not even a no-op.
    if (!away()) return false;
    var written = false;
    // One write for all three fields, with the relock checked inside it; a
    // relock there skips the write itself, not just the changes.
    // Null phone/email clears any prior contact, so a re-enrolment that opts
    // out of SMS truly leaves no destination behind.
    await _mutateVpnRuntimeSettings(skipWriteWhen: () => !written, (data) {
      if (!away()) return;
      data['duress_credential'] = credential;
      if (phone == null) {
        data.remove('duress_contact');
      } else {
        data['duress_contact'] = phone;
      }
      if (email == null) {
        data.remove('duress_contact_email');
      } else {
        data['duress_contact_email'] = email;
      }
      written = true;
    });
    if (!written) return false;
    if (await _readDuressCredential() != credential) {
      throw StateError('Duress credential failed durable read-back');
    }
    if (await _readTrustedContact() != phone) {
      throw StateError('Trusted contact failed durable read-back');
    }
    final storedDuress = await _readDuressCredential();
    if (storedDuress == null ||
        !await _pinCredentialCodec.verifyStoredCredential(
            duressPin, storedDuress)) {
      throw StateError('Duress code failed read-back verification');
    }
    return true;
  }

  /// Mirrors the hub's `EMERGENCY_PHONE_RE`: a plausible international or local
  /// dialling number. Used to decide whether the device-native SMS path can
  /// carry an alert, and to refuse a non-numeric contact at enrollment.
  bool _isPhoneShapedContact(String contact) {
    return RegExp(r'^\+?[0-9][0-9 ().-]{5,31}$').hasMatch(contact.trim());
  }

  /// Persists the most recent COARSE (IP-derived) location so an offline duress
  /// entry still carries a last-known position after a restart. Best-effort:
  /// the app holds no GPS permission, so this is the only location it ever has.
  Future<void> _persistLastKnownCoarseLocation(
      double? latitude, double? longitude) async {
    if (latitude == null || longitude == null) return;
    try {
      await _mutateVpnRuntimeSettings((data) {
        data['last_coarse_lat'] = latitude;
        data['last_coarse_lng'] = longitude;
      });
    } catch (_) {
      // A dropped best-effort location write must never surface; the dispatch
      // simply goes out without coordinates if nothing was ever persisted.
    }
  }

  Future<List<double?>> _readLastKnownCoarseLocation() async {
    try {
      await _settingsMutationQueue;
      final settings = await _readSensitiveJsonMap('vpn_settings.txt');
      double? asDouble(dynamic value) => value is num
          ? value.toDouble()
          : (value is String ? double.tryParse(value.trim()) : null);
      return <double?>[
        asDouble(settings['last_coarse_lat']),
        asDouble(settings['last_coarse_lng']),
      ];
    } catch (_) {
      return const <double?>[null, null];
    }
  }

  /// Fires the emergency response for a matched duress code. Everything here is
  /// best-effort and fail-safe: any failure must still leave the user on the
  /// calculator, never surface a stack trace, and never look different from a
  /// wrong PIN. Guarded so it runs at most once per process.
  Future<void> _armDuress() async {
    if (_duressArmed) return;
    _duressArmed = true;
    DuressDispatch? dispatch;
    var delivered = false;
    var queued = false;
    try {
      final contact = await _readTrustedContact();
      double? latitude = _preVpnLatitude;
      double? longitude = _preVpnLongitude;
      if (latitude == null || longitude == null) {
        final persisted = await _readLastKnownCoarseLocation();
        latitude ??= persisted.isNotEmpty ? persisted[0] : null;
        longitude ??= persisted.length > 1 ? persisted[1] : null;
      }
      if (contact != null) {
        dispatch = DuressDispatch(
          trustedContact: contact,
          latitude: latitude,
          longitude: longitude,
          capturedAtUtc: DateTime.now().toUtc(),
        );
        // DEVICE-NATIVE delivery (owner decision): the alert leaves from the
        // handset's own SMS radio on Android, with no hub and no server
        // identity. See _deliverDuressDispatch and the dated handoff for the
        // hard iOS limit (no covert programmatic SMS on iOS).
        delivered = await _deliverDuressDispatch(dispatch);
        if (!delivered && _duressRetryTransportAvailable(contact)) {
          // Offline / transient: keep the alert for a later device-native
          // retry. Only queue when a transport could actually drain it later,
          // otherwise (e.g. iOS with the relay disabled) there is nothing to
          // retry and holding a record would be dead weight to wipe.
          queued = await _queueDuressDispatch(dispatch);
        }
      }
    } catch (_) {
      // Never log the contact or coordinates; a bare marker is all a duress
      // diagnostic may ever carry.
      _debugLog('Duress dispatch stage did not complete.');
    }
    // A live OS VPN indicator is one of the strongest tells; it must not
    // outlive a duress entry. Best-effort and non-blocking.
    try {
      await _methodChannel
          .invokeMethod('stopTunnel')
          .timeout(const Duration(seconds: 3));
    } catch (_) {}
    // Wipe. Preserve the queued dispatch only when an alert was actually
    // queued for a later retry; otherwise (delivered, or nowhere to retry)
    // wipe thoroughly.
    final preserveQueue = queued;
    try {
      await _wipeIncriminatingStateForDuress(
          preserveEmergencyQueue: preserveQueue);
    } catch (_) {
      _debugLog('Duress wipe did not fully complete.');
    }
    // Drop any sensitive in-memory session state behind the decoy, without
    // changing anything visible: the calculator stays exactly as it looks.
    if (mounted) {
      if (_supportsInAppCamouflage) _clearProductSurfacesForDecoy();
      setState(() {
        _isLoggedIn = false;
        _isConnected = false;
        _tunnelDisplayLedger.endSession();
        _isFreeAccessSession = false;
        _accountController.clear();
        _calculatorPinEntry.reset();
        _showDecoyCalculator = _supportsInAppCamouflage;
      });
    }
    // NO dialog is raised from here any more, and NO native app-data wipe is
    // called from here any more. Both were removed for the same reason: each
    // was a thing that happened ONLY on the duress path.
    //
    //  * The dialog is now raised by the keypad caller for every entry that
    //    fails to unlock, mistyped codes included, so it is no longer a tell.
    //    See _onCalculatorButtonPressed and _showEntryFailurePopup.
    //
    //  * clearApplicationUserData() resets the app to factory-fresh, which is
    //    precisely what UNMASKED it: a cold start afterwards showed the
    //    branded consent dialog over the real activation screen. The wipe
    //    below is now the thorough one on every branch and keeps only the
    //    camouflage latch, so the app stays a calculator instead of
    //    announcing itself to whoever is holding the phone.
  }

  /// True only where a covert, no-interaction native send is actually
  /// possible: Android (SmsManager). iOS CANNOT send SMS without showing the
  /// system compose UI and a manual tap, so covert device-native send is
  /// impossible there; reported honestly, never faked. There is deliberately
  /// no relay/hub fallback anywhere (owner decision): iOS duress is a local
  /// wipe only, and no code path may imply otherwise.
  bool get _supportsDeviceNativeSms {
    try {
      return Platform.isAndroid;
    } catch (_) {
      return false;
    }
  }

  /// Whether a failed first attempt is worth queuing for a later retry: only
  /// where a transport could actually drain it later, i.e. Android device-
  /// native SMS to a phone-shaped contact. On iOS this is always false, so an
  /// iOS duress never queues an alert it could never send: the wipe is
  /// thorough and nothing is left implying a pending delivery.
  bool _duressRetryTransportAvailable(String contact) {
    return _supportsDeviceNativeSms && _isPhoneShapedContact(contact);
  }

  /// Delivers one dispatch via the device's own SMS radio (Android only).
  /// Returns true only when the alert has left the device in a form that
  /// survives the subsequent wipe (an SMS handed to the telephony radio has
  /// left the app; even a thorough wipe cannot recall it, and the OS keeps no
  /// app-readable Sent copy). There is no other transport: no relay, no hub.
  Future<bool> _deliverDuressDispatch(DuressDispatch dispatch) async {
    if (_supportsDeviceNativeSms &&
        _isPhoneShapedContact(dispatch.trustedContact)) {
      return _sendDuressViaDeviceSms(dispatch);
    }
    return false;
  }

  /// Hands the alert to the platform's SMS radio with no compose UI and no
  /// user tap (Android `SmsManager`). The native handler returns true only
  /// when every SMS part was accepted by the radio; a no-service/offline
  /// result returns false so the caller queues for a later retry. Because this
  /// app is not the default SMS handler, the send writes nothing to the system
  /// Messages/Sent store, so it leaves no on-device trace.
  Future<bool> _sendDuressViaDeviceSms(DuressDispatch dispatch) async {
    try {
      final ok = await _methodChannel.invokeMethod<bool>('sendDuressSms', {
        'destination': dispatch.trustedContact,
        'text': dispatch.smsText(),
      }).timeout(const Duration(seconds: 25));
      return ok == true;
    } catch (_) {
      _debugLog('Device-native duress SMS did not complete.');
      return false;
    }
  }

  /// Durably queues a dispatch inside vpn_settings.txt for a later retry, and
  /// reports whether the write actually stuck. Mirrors _queuePendingLogout's
  /// write-then-read-back durability check.
  Future<bool> _queueDuressDispatch(DuressDispatch dispatch) async {
    try {
      await _mutateVpnRuntimeSettings((data) {
        data['pending_emergency'] = dispatch.toQueueJson();
      });
      final settings = await _readSensitiveJsonMap('vpn_settings.txt');
      return settings['pending_emergency'] != null;
    } catch (_) {
      _debugLog('Duress queue write did not persist.');
      return false;
    }
  }

  /// Retries a queued dispatch on launch (called beside _retryPendingLogout).
  /// Retries via the same device-native-first path as the live arming, deletes
  /// the record on success, bumps a bounded attempt counter on failure, and
  /// gives up after a cap so an undeliverable alert is not retried forever.
  Future<void> _retryDuressDispatch() async {
    // RETIRED (owner decision 2026-08-18): never dispatch; see the startup
    // call-site note. The queue/retry body was excised so no unreachable code
    // remains; the early return is the feature's single obvious off switch.
    return;
  }

  /// Securely removes every incriminating local record, then sweeps the app's
  /// own storage so nothing readable is left behind it.
  ///
  /// The named secure-state records go first, through the native store that
  /// owns them. `vpn_settings.txt` is either deleted whole or, when an alert
  /// is still queued, rewritten to hold ONLY that queued dispatch.
  ///
  /// The sweep that follows exists because the named list was never the whole
  /// story. Measured on a device on 2026-08-06, the offline branch left
  /// `node_cache.json` behind in PLAINTEXT: node display names, slugs,
  /// `endpoint` host:port, the covert `stealth_endpoint` domain and per-
  /// transport reachability -- a readable directory of circumvention
  /// infrastructure, handed to exactly the inspector the wipe exists to
  /// defeat, in the branch the design calls "the realistic inspection case".
  /// `install_id.txt` survived beside it, and on Android the tunnel service's
  /// own `wins_xray_client.json` and carrier-profile credentials sit in
  /// `files/` where no named delete ever reached them.
  ///
  /// So the rule is inverted: everything in the app's storage goes EXCEPT
  /// what [duressWipeKeepsEntry] names, which is the camouflage latch (so the
  /// disguise outlives the wipe) and, only while an alert is still queued,
  /// the encrypted secure-state directory that carries it.
  Future<void> _wipeIncriminatingStateForDuress({
    required bool preserveEmergencyQueue,
  }) async {
    _doubleVpnIntentWritesSealed = true;
    await _doubleVpnIntentRecordQueue;
    for (final name in const <String>[
      'calc_session.json',
      'calc_state.json',
      'user_pin.txt',
      'vpn_config.txt',
      'client_keypair.json',
      'winn3_keypair.json',
      'wins_vpn_restart_config.conf',
      'pending_logout.json',
    ]) {
      try {
        await _deleteSensitiveText(name);
      } catch (_) {}
    }
    if (Platform.isAndroid) {
      try {
        await _deleteSensitiveText(_doubleVpnIntentRecord);
      } catch (_) {}
    }
    try {
      if (preserveEmergencyQueue) {
        await _mutateVpnRuntimeSettings((data) {
          final record = data['pending_emergency'];
          data.clear();
          if (record != null) data['pending_emergency'] = record;
        });
      } else {
        await _settingsMutationQueue;
        await _deleteSensitiveText('vpn_settings.txt');
      }
    } catch (_) {}
    await _sweepAppStorageForDuress(
        preserveEmergencyQueue: preserveEmergencyQueue);
    // Written LAST, and unconditionally, so the disguise is guaranteed to be
    // standing whatever else failed above. This is the whole answer to the
    // unmask: the decoy no longer depends on a credential the wipe destroys.
    await _latchCamouflage();
  }

  /// Deletes everything in the app's own storage that [duressWipeKeepsEntry]
  /// does not explicitly keep. Best-effort throughout: a single unlinkable
  /// entry must never abort the rest of the wipe or surface to the user.
  Future<void> _sweepAppStorageForDuress({
    required bool preserveEmergencyQueue,
  }) async {
    // The pairing file goes with the sweep below; the in-memory registry must
    // go first, or a paired browser keeps control until the app restarts.
    await _revokeBrowserBridgePairings('duress');
    Future<void> sweep(Directory root) async {
      if (!await root.exists()) return;
      await for (final entity in root.list(followLinks: false)) {
        final name = entity.path.split(Platform.pathSeparator).last;
        if (duressWipeKeepsEntry(name,
            preserveEmergencyQueue: preserveEmergencyQueue)) {
          continue;
        }
        try {
          await entity.delete(recursive: true);
        } catch (_) {}
      }
    }

    try {
      final documents = await _appDocumentsDirectory();
      await sweep(documents);
      // Android keeps a second, separate root: `files/` holds the native
      // secure-state directory AND the tunnel service's own writes (the Xray
      // client config, the restart config, the carrier profile and its
      // credentials). None of those is reachable by a named secure-state
      // delete, so without this they simply survived.
      if (Platform.isAndroid) {
        final parent = documents.parent;
        await sweep(Directory('${parent.path}${Platform.pathSeparator}files'));
      }
    } catch (e) {
      _debugLog('Duress storage sweep did not fully complete: $e');
    }

    // APPLE'S THIRD ROOT, AND THE ONLY ONE THAT SURVIVES APP DELETION.
    //
    // Keychain items outlive uninstalling the app on iOS. Until this existed,
    // duress deleted six named records from ONE Keychain service
    // (`org.winsvpn.app.secure-state`) and left three others standing:
    // `org.winsvpn.client-keypair` -- the WireGuard client's own private key,
    // in a shared access group -- plus the peer preshared key, the Xray UUID and
    // the stable per-install id the backend knows this handset by. A wipe that
    // leaves a key capable of proving which account a seized phone belonged
    // to, and which uninstalling does not remove, has not done its job.
    //
    // FIRST, BEFORE THE CONTAINER. Ordered by durability, not by convenience:
    // the container dies with the app, the Keychain does not. If this wipe is
    // interrupted -- process killed, battery, jetsam -- the item that must
    // already be gone is the one deleting the app would not have taken.
    if (Platform.isIOS || Platform.isMacOS) {
      try {
        final report = await _methodChannel.invokeMapMethod<String, dynamic>(
          'purgeKeychainIdentity',
          {'preserveEmergencyQueue': preserveEmergencyQueue},
        ).timeout(const Duration(seconds: 4));
        // Counts and fixed labels only -- never an account, which for the
        // client key store embeds the account scope token. `complete` is
        // strict: it requires each store to have been OBSERVED to hold
        // something and then observed empty, because a Keychain query that
        // matches nothing proves only that the query matches nothing.
        final residual = keychainPurgeLeftResidual(report);
        _debugLog('Duress Keychain purge: '
            'complete=${report?['keychain_purge_complete']} '
            'purged=${report?['keychain_purge_purged_count']} '
            'absent=${report?['keychain_purge_absent_count']} '
            'blocked=${report?['keychain_purge_blocked_count']} '
            'remaining=${report?['keychain_purge_remaining_items']} '
            'residual=$residual');
      } catch (e) {
        _debugLog('Duress Keychain purge did not complete: $e');
      }
    }

    // APPLE'S SECOND ROOT, AND THE ONE NOTHING COULD SEE.
    //
    // The App Group container is shared between this app and the Packet
    // Tunnel extension, and Dart structurally cannot reach it: no Flutter
    // plugins are registered on either Apple platform, so
    // `_appDocumentsDirectory()` returns the app's OWN
    // `Application Support/wins_vpn` and the sweep above stops at that edge.
    // Everything the appex writes lives on the far side of it.
    //
    // What was surviving there, observed in a real container on 2026-08-07:
    // `Tunnel/latest_tunnel.conf` -- gateway endpoint host:port, gateway
    // public key, THIS DEVICE'S own client public key, address, DNS and the
    // complete AmneziaWG obfuscation parameter set, all plaintext (only
    // `PrivateKey` is a Keychain placeholder) -- plus `latest_tunnel.json`
    // and a 120-field `latest_status.json`. It is the same shape of defect as
    // Android's `node_cache.json`: a readable description of circumvention
    // infrastructure, handed to exactly the inspector the wipe exists to
    // defeat.
    //
    // DELIBERATELY OUTSIDE THE try ABOVE. A failure to resolve or sweep the
    // app's own directory must not be able to skip this; the two roots fail
    // independently or the wipe inherits the weaker of the two.
    if (Platform.isIOS || Platform.isMacOS) {
      try {
        final report = await _methodChannel
            .invokeMapMethod<String, dynamic>('purgeAppGroupContainer')
            .timeout(const Duration(seconds: 4));
        // The purge re-reads the directory and reports what is STILL there,
        // so this log records an observation rather than an intention. A
        // delete that was never observed to delete is the defect class this
        // whole path was audited for.
        final residual = appGroupPurgeLeftResidual(report);
        _debugLog('Duress App Group purge: '
            'complete=${report?['app_group_purge_complete']} '
            'removed=${report?['app_group_purge_removed_count']} '
            'remaining=${report?['app_group_purge_remaining_count']} '
            'residual=$residual');
      } catch (e) {
        _debugLog('Duress App Group purge did not complete: $e');
      }
    }
  }

  // THERE IS DELIBERATELY NO NATIVE APP-DATA WIPE ON THIS PATH ANY MORE.
  //
  // _emergencyNativeWipe() called Android's
  // ActivityManager.clearApplicationUserData(), which is genuinely the
  // strongest self-wipe a non-device-owner app can perform -- and that is
  // exactly why it could not stay. It leaves the app "indistinguishable from
  // a fresh install", and a fresh install of THIS app opens on the branded
  // "Privacy Policy and Legal Consent" dialog, naming the service and its
  // domain, over the real activation screen. Measured on a device: the
  // delivered branch took the disguise off just as completely as the offline
  // one. Nothing app-side can survive that call, so no latch, marker or file
  // could ever have carried the camouflage across it.
  //
  // _sweepAppStorageForDuress replaces it and removes the same material --
  // app_flutter and, on Android, files/: the node cache, the install id, the
  // Xray client config, the carrier profile and its credentials, the
  // secure-state directory -- while keeping exactly the two things the design
  // needs kept: the camouflage latch, and the queued alert when there is one.
  // shared_prefs is left alone because the only thing in it is the sticky
  // camouflage fact, now stored under a calculator's name.
  //
  // The native `emergencyWipeAppData` handler is untouched and still present;
  // nothing on the duress path invokes it.

  /// The plausible cover story, raised after ANY credential-shaped entry that
  /// failed to unlock the app -- a mistyped code, an unknown code, a throttled
  /// attempt, an app with nothing enrolled behind it, or the duress code.
  ///
  /// It used to fire only for duress. Frame-by-frame on a real device that
  /// meant: wrong code -> nothing, ever; duress code -> a modal dialog 1047 ms
  /// later. A captor who had already watched one mistyped entry produce
  /// silence would see the duress entry produce a dialog, which is a direct,
  /// unmistakable tell on the one feature whose entire value is that using it
  /// looks like nothing happened.
  ///
  /// Sharing it across every failing entry is what makes it safe: the two
  /// paths now raise the same widget from the same call site after the same
  /// work, so they are indistinguishable in content AND in timing, and the
  /// cover story for the wipe is kept rather than traded away.
  ///
  /// Copy is deliberately generic, dismissible, and free of any word that
  /// names a VPN, a code, a panic feature, or a message having been sent. It
  /// is owner-tunable and should be localized (Burmese) before release.
  void _showEntryFailurePopup() {
    if (!mounted) return;
    // One at a time. Without this a burst of failed entries would stack
    // dialogs, and "how many dialogs" would become a new observable. The
    // guard applies identically to both paths.
    if (_entryFailurePopupOpen) return;
    _entryFailurePopupOpen = true;
    unawaited(showDialog<void>(
      context: context,
      barrierDismissible: true,
      // The keypad's own popup: the route guard keeps decoy/ routes.
      routeSettings: const RouteSettings(name: '${kDecoyRoutePrefix}entry-failure'),
      builder: (dialogContext) => buildEntryFailureDialog(
        translate: _t,
        onDismiss: () => Navigator.of(dialogContext).pop(),
      ),
    ).whenComplete(() => _entryFailurePopupOpen = false));
  }

  Future<AccountCleanupJournal?> _readAccountCleanupJournal() async {
    try {
      // An unfinished local reset leaves the journal unreadable, even when
      // its record is gone or has become readable again.
      if (await _accountResetMarkerPresent()) return null;
      final encoded = await _readSensitiveText('calc_session.json');
      if (encoded == null) return null;
      final decoded = jsonDecode(encoded);
      if (decoded is! Map) return null;
      return AccountCleanupJournal.fromJson(Map<String, dynamic>.from(decoded));
    } catch (_) {
      _debugLog('Account cleanup journal is unavailable or invalid.');
      return null;
    }
  }

  Future<bool> _accountCleanupJournalExists() async {
    if (_accountResetRequiresRestart) return true;
    try {
      if (await _accountResetMarkerPresent()) return true;
      return await _readSensitiveText('calc_session.json') != null;
    } catch (_) {
      // Storage ambiguity is not proof that an ordinary cleanup journal is
      // absent. Startup and activation must remain fail-closed.
      return true;
    }
  }

  /// The local reset's durable marker on every platform except Android,
  /// whose SecureFileStore keeps its own (`secure_state/repair.dat`) and
  /// fails journal reads while it exists. Present means a reset started and
  /// did not finish, so the barrier holds and the reset is offered again.
  Future<File> _accountResetMarkerFile() async =>
      _accountResetMarker ??= File('${(await _appDocumentsDirectory()).path}'
          '${Platform.pathSeparator}repair.dat');

  Future<bool> _accountResetMarkerPresent() async {
    if (Platform.isAndroid) return false;
    return (await _accountResetMarkerFile()).exists();
  }

  Future<void> _writeAccountCleanupJournal(
      AccountCleanupJournal journal, int expectedEpoch) async {
    if (!_accountEpochIsCurrent(expectedEpoch)) {
      throw StateError('Account cleanup was superseded');
    }
    final encoded = jsonEncode(journal.toJson());
    await _writeSensitiveText('calc_session.json', encoded);
    if (!_accountEpochIsCurrent(expectedEpoch) ||
        await _readSensitiveText('calc_session.json') != encoded) {
      throw StateError('Account cleanup journal failed durable read-back');
    }
  }

  Future<bool> _deleteSensitiveArtifactVerified(String name) async {
    await _deleteSensitiveText(name);
    return await _readSensitiveText(name) == null;
  }

  Future<bool> _deleteVpnConfigVerified() async {
    if (_isApplePlatform) {
      await _deleteVpnConfigOnApple();
      return await _readEncodedVpnConfigOnApple() == null;
    }
    return _deleteSensitiveArtifactVerified('vpn_config.txt');
  }

  Future<bool> _stopAndProveTunnelInactive() async {
    // Every caller ends the account session for good (expiry, revocation,
    // deactivation, deletion and their startup continuation) and the app then
    // refuses to reconnect, so the Android kill-switch block is released with
    // the tunnel, exactly as a user disconnect releases it
    // (_toggleVpnConnection). Without the flag the native teardown keeps a
    // blocking interface while the dashboard reads "Disconnected", and
    // nothing in the app or on the disguised notification can release it.
    await _cancelAndStopNativeTunnel(
        keepVpnLauncher: true, releaseKillSwitchBlock: true);
    final deadline = DateTime.now().add(const Duration(seconds: 30));
    DateTime? inactiveSince;
    var inactiveSamples = 0;
    while (DateTime.now().isBefore(deadline)) {
      final activity = await _nativeTunnelActivityForStopSettlement();
      if (activity == false) {
        inactiveSince ??= DateTime.now();
        inactiveSamples += 1;
        if (inactiveSamples >= 3 &&
            DateTime.now().difference(inactiveSince) >=
                const Duration(milliseconds: 750)) {
          return true;
        }
      } else {
        inactiveSince = null;
        inactiveSamples = 0;
        if (activity == true) {
          await _cancelAndStopNativeTunnel(
              keepVpnLauncher: true, releaseKillSwitchBlock: true);
        }
      }
      await Future.delayed(const Duration(milliseconds: 300));
    }
    return false;
  }

  Future<bool> _deleteCleanupArtifact(String artifact, String scopeToken) {
    switch (artifact) {
      case 'vpn_config':
        return _deleteVpnConfigVerified();
      case 'user_pin':
        return _deleteSensitiveArtifactVerified('user_pin.txt');
      case 'pending_logout':
        return _deletePendingLogoutForScope(scopeToken);
      case 'vpn_settings':
        return () async {
          await _settingsMutationQueue;
          return _deleteSensitiveArtifactVerified('vpn_settings.txt');
        }();
      case 'restart_config':
        return () async {
          if (!await _deleteSensitiveArtifactVerified(
              'wins_vpn_restart_config.conf')) {
            return false;
          }
          // Drain any earlier native write before verifying deletion.
          await _doubleVpnIntentRecordQueue;
          return !Platform.isAndroid ||
              await _deleteSensitiveArtifactVerified(_doubleVpnIntentRecord);
        }();
      case 'activation_marker':
        return _deleteSensitiveArtifactVerified('calc_state.json');
      case 'client_keys':
        // Retires BOTH identities of this scope: the AWG pair and this
        // device's own winn/3 pair. Folded into this one artifact rather than
        // a new journal name, so a journal written by this build stays
        // readable by every build that knows 'client_keys'.
        return _serializeClientKeyOperationForScopeToken(
          scopeToken,
          () async {
            final awgDeleted =
                await _deleteClientKeyPairForScopeTokenUnlocked(scopeToken);
            final winn3Deleted =
                await _deleteWinn3KeyPairForScopeToken(scopeToken);
            return awgDeleted && winn3Deleted;
          },
        );
    }
    return Future<bool>.value(false);
  }

  Future<bool> _clearOrdinaryCamouflageLatchVerified() async {
    if (!_supportsInAppCamouflage) return true;
    // The ordinary cleanup journal is the discriminator that makes this safe.
    // Duress never writes this journal and explicitly deletes any stale one.
    if (await _readAccountCleanupJournal() == null) return false;
    final latch = await _camouflageLatchFile();
    if (await latch.exists()) await latch.delete();
    return !await latch.exists();
  }

  Future<bool> _runAccountCleanup(
    AccountCleanupJournal journal,
    int expectedEpoch,
  ) async {
    var current = journal;
    for (final artifact in _accountCleanupArtifacts) {
      if (!current.pendingArtifacts.contains(artifact)) continue;
      if (!_accountEpochIsCurrent(expectedEpoch)) return false;
      try {
        if (!await _deleteCleanupArtifact(artifact, current.scopeToken)) {
          continue;
        }
        final remaining = Set<String>.from(current.pendingArtifacts)
          ..remove(artifact);
        current = current.copyWith(
          phase: remaining.isEmpty ? 'local_cleanup_verified' : 'purging',
          pendingArtifacts: remaining,
        );
        await _writeAccountCleanupJournal(current, expectedEpoch);
      } catch (_) {
        _debugLog('Account cleanup artifact deletion remains pending.');
      }
    }
    if (!_accountEpochIsCurrent(expectedEpoch) ||
        current.pendingArtifacts.isNotEmpty) {
      return false;
    }
    final durable = await _readAccountCleanupJournal();
    if (durable == null || durable.pendingArtifacts.isNotEmpty) return false;
    if (!await _clearOrdinaryCamouflageLatchVerified()) return false;
    if (!await _deleteSensitiveArtifactVerified('calc_session.json')) {
      return false;
    }
    return true;
  }

  void _resetAccountUiAfterVerifiedCleanup() {
    // Logged out: no browser keeps control of this device's VPN.
    unawaited(_revokeBrowserBridgePairings('logout'));
    if (!mounted) return;
    setState(() {
      _isLoggedIn = false;
      _isConnected = false;
      // The record belongs to the account that was just cleaned up.
      _tunnelDisplayLedger.endSession();
      _showDecoyCalculator = false;
      _launcherUnlocked = false;
      _isDoubleVpnRequested = false;
      _isCensorshipModeActive = false;
      _isStealthTransportOnly = false;
      _isFreeAccessSession = false;
      _accountExpiredTerminal = false;
      _activeProtocolLabel = _defaultProtocolLabel;
      _activeProtocolVersion = '';
      // R2-AUDIT-09: a buyer-typed referral never outlives the account.
      _purchaseReferralCode = '';
      _accountController.clear();
      _pinSetupController.clear();
      _activationSecretController.clear();
      _ipAfterVpn = 'Disconnected';
      _isLoading = false;
    });
  }

  void _forcePendingAccountCleanupUi() {
    unawaited(_revokeBrowserBridgePairings('logout'));
    void apply() {
      _settingsWritesSealed = true;
      _accountCleanupPending = true;
      _isLoggedIn = false;
      _isConnected = false;
      _tunnelDisplayLedger.endSession();
      _isFreeAccessSession = false;
      _showDecoyCalculator = false;
      _launcherUnlocked = false;
      _isLoading = false;
    }

    if (mounted) {
      setState(apply);
    } else {
      apply();
    }
  }

  void _completePendingAccountCleanup() {
    _settingsWritesSealed = false;
    _accountCleanupPending = false;
    _unreadableCleanupJournalPasses = 0;
    _cleanupJournalUnreadable = false;
    _resetAccountUiAfterVerifiedCleanup();
  }

  void _continueStartupAfterCleanupRetry() {
    if (!_accountCleanupStartupBlocked) return;
    _accountCleanupStartupBlocked = false;
    if (mounted) unawaited(_initializePrivacyConsentGate());
  }

  Future<AccountCleanupResumeOutcome> _resumePendingAccountCleanup() =>
      _accountCleanupStartupBarrier.resume();

  Future<void> _attemptPendingAccountCleanup() async {
    if (_accountResetRequiresRestart) {
      throw StateError('Local account reset requires restart');
    }
    if (_accountLifecycleBusy) {
      throw StateError('Another account lifecycle operation is active');
    }
    _accountLifecycleBusy = true;
    try {
      final pending = await _readAccountCleanupJournal();
      if (pending == null) {
        await _noteUnreadableCleanupJournal();
        return;
      }
      _unreadableCleanupJournalPasses = 0;
      final epoch = _beginAccountTeardown();
      if (!await _stopAndProveTunnelInactive() ||
          !_accountEpochIsCurrent(epoch)) {
        return;
      }
      var resumable = pending;
      if (pending.intent == AccountCleanupIntent.deactivate &&
          pending.phase != 'purging' &&
          pending.phase != 'local_cleanup_verified') {
        final settings = await _readVpnRuntimeSettings();
        if (!_accountEpochIsCurrent(epoch)) return;
        final freeAccess = settings['free_access_session'] == true;
        final accountNumber = freeAccess
            ? _freeAccessAccountNumber
            : (settings['account_number'] ?? '').toString().trim();
        final deviceAuthToken = await _readDeviceAuthToken();
        if (accountNumber.isEmpty || !_accountEpochIsCurrent(epoch)) return;
        final logoutOk = await _sendLogoutToHub(
          freeAccess: freeAccess,
          accountNumber: accountNumber,
          deviceId: _appScopedDeviceId,
          deviceAuthToken: deviceAuthToken,
        );
        if (!_accountEpochIsCurrent(epoch)) return;
        if (logoutOk) {
          // Verified cleanup removes only this account's queued logout.
        } else if (!await _queuePendingLogout(
          freeAccess: freeAccess,
          accountNumber: accountNumber,
          deviceId: _appScopedDeviceId,
          deviceAuthToken: deviceAuthToken,
        )) {
          return;
        } else {
          final retained = Set<String>.from(resumable.pendingArtifacts)
            ..remove('pending_logout');
          resumable = resumable.copyWith(pendingArtifacts: retained);
        }
        resumable = resumable.copyWith(phase: 'purging');
        await _writeAccountCleanupJournal(resumable, epoch);
      }
      await _runAccountCleanup(resumable, epoch);
    } finally {
      _accountLifecycleBusy = false;
    }
  }

  /// Counts barrier passes that find a cleanup journal present but not
  /// readable. Only a journal still unreadable on three passes in a row
  /// (about 10 s at the barrier's 5 s retry) offers the local reset, so a
  /// keystore or I/O failure that clears on retry never does.
  Future<void> _noteUnreadableCleanupJournal() async {
    if (!await _accountCleanupJournalExists()) {
      _unreadableCleanupJournalPasses = 0;
      return;
    }
    _unreadableCleanupJournalPasses += 1;
    if (_unreadableCleanupJournalPasses < 3 || _cleanupJournalUnreadable) {
      return;
    }
    if (mounted) {
      setState(() => _cleanupJournalUnreadable = true);
    } else {
      _cleanupJournalUnreadable = true;
    }
  }

  /// Explicit recovery for a cleanup journal that exists but cannot be read
  /// (CORE-7-T15C-claude). The journal is the only record of which account
  /// was leaving, so every account's local data is deleted instead, after
  /// the user confirms it. From quiescence on, this process stays blocked
  /// and every write is refused until a fresh start; Android closes the
  /// app itself after a verified reset.
  Future<void> _requestLocalAccountReset() async {
    if (!mounted ||
        !_cleanupJournalUnreadable ||
        _accountLifecycleBusy ||
        _accountResetSucceeded) {
      return;
    }

    setState(() => _accountLifecycleBusy = true);
    try {
      final confirmed = await showDialog<bool>(
        context: context,
        barrierDismissible: false,
        builder: (dialogContext) => AlertDialog(
          title: const Text('Reset local account data?'),
          content: Text(
            'This deletes every account saved on this device, including the '
            'account being removed, with its keys, settings, PIN and queued '
            'actions. It does not delete your server account. '
            '${Platform.isAndroid ? 'The app closes when the reset is verified. Reopen it and activate again.' : 'When the reset is verified, close and reopen the app and activate again.'}',
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.of(dialogContext).pop(false),
              child: const Text('Cancel'),
            ),
            TextButton(
              onPressed: () => Navigator.of(dialogContext).pop(true),
              child: const Text('Delete local account data'),
            ),
          ],
        ),
      );
      if (confirmed != true || !mounted) return;
      // A journal that has become readable, or is gone, is the ordinary
      // cleanup path's to finish.
      if (await _readAccountCleanupJournal() != null ||
          !await _accountCleanupJournalExists()) {
        _unreadableCleanupJournalPasses = 0;
        _cleanupJournalUnreadable = false;
        return;
      }

      final epoch = _beginAccountTeardown();
      await _settingsMutationQueue.timeout(const Duration(seconds: 4));
      // Native tunnel starts are sealed before the stop, so no supplied or
      // restored configuration starts a tunnel between the stop-proof and the
      // erase. The seal never lifts in this process.
      if (Platform.isAndroid) {
        final sealed = await _methodChannel.invokeMethod<bool>(
          'sealAccountStartsForRecovery',
        ).timeout(const Duration(seconds: 4));
        if (sealed != true || !_accountEpochIsCurrent(epoch)) {
          throw StateError('Local account tunnel starts were not sealed');
        }
      }
      if (!await _stopAndProveTunnelInactive() ||
          !_accountEpochIsCurrent(epoch) ||
          _clientKeyOperationQueue.pendingOperationCount != 0) {
        throw StateError('Local reset could not establish quiescence');
      }

      // Browser pairings are a local grant, not account data, but a reset
      // must leave no grant behind: memory first (control stops at once),
      // then the store, before the account erase runs.
      await _revokeBrowserBridgePairings('reset');
      _accountResetRequiresRestart = true;
      final erased = Platform.isAndroid
          ? await _methodChannel
                  .invokeMethod<bool>('resetAllLocalAccountData')
                  .timeout(const Duration(seconds: 30)) ==
              true
          : await _eraseLocalAccountDataKeepingDevice(epoch);
      if (!erased) {
        throw StateError('Local account reset was not verified');
      }

      _accountResetSucceeded = true;
      _accountResetMessage = 'Local account data was deleted. Close and '
          'reopen the app, then activate again.';
      if (Platform.isAndroid) {
        await _methodChannel.invokeMethod<bool>('closeAfterAccountRecovery');
      }
    } catch (_) {
      if (!_accountResetSucceeded) {
        _accountResetMessage = 'Reset has not confirmed completion. '
            'Activation remains disabled. Retry, or close and reopen the app.';
      }
    } finally {
      _accountLifecycleBusy = false;
      if (mounted) setState(() {});
    }
  }

  /// The reset on every platform except Android, where SecureFileStore runs
  /// it natively. The marker is written first and removed last; every other
  /// record except the journal and the install id is deleted and verified,
  /// then the camouflage latch as ordinary cleanup clears it, then the native
  /// runtime configuration on Windows and Linux, and only then the journal.
  Future<bool> _eraseLocalAccountDataKeepingDevice(int epoch) async {
    final marker = await _accountResetMarkerFile();
    await marker.writeAsString('1', flush: true);

    if (_isApplePlatform) {
      // The App Group container the Packet Tunnel extension shares: the
      // tunnel handoff file, its metadata and the carrier credentials. The
      // marker and the latch live in the app's own Application Support, which
      // this purge does not reach.
      final appGroupReport =
          await _methodChannel.invokeMapMethod<String, dynamic>(
        'purgeAppGroupContainer',
      ).timeout(const Duration(seconds: 30));
      if (appGroupPurgeLeftResidual(appGroupReport)) return false;

      // Every scope's Keychain key pair and tunnel secret, and every
      // secure-state row except the journal and the per-install id.
      final keychainReport =
          await _methodChannel.invokeMapMethod<String, dynamic>(
        'purgeAccountDataKeepingCleanupJournal',
      ).timeout(const Duration(seconds: 4));
      if (keychainReport == null ||
          keychainReport['keychain_purge_blocked_count'] != 0 ||
          keychainReport['keychain_purge_remaining_items'] != 0) {
        return false;
      }
    }

    if (!await _deleteVpnConfigVerified()) return false;
    for (final name in _sensitiveStateFileNames) {
      if (name == 'calc_session.json' || name == 'install_id.txt') continue;
      if (!await _deleteSensitiveArtifactVerified(name)) return false;
    }
    await _doubleVpnIntentRecordQueue;
    if (Platform.isAndroid &&
        !await _deleteSensitiveArtifactVerified(_doubleVpnIntentRecord)) {
      return false;
    }
    if (_supportsInAppCamouflage) {
      final latch = await _camouflageLatchFile();
      if (await latch.exists()) await latch.delete();
      if (await latch.exists()) return false;
    }

    if (Platform.isWindows || Platform.isLinux) {
      // A stop that leaves the tunnel inactive does not prove its unchecked
      // deletions happened, and a crash leaves uniquely named copies the stop
      // never deletes. The native side deletes every runtime configuration
      // copy it owns and returns true only when it observes none left.
      final runtimeErased = await _methodChannel.invokeMethod<bool>(
        'eraseLocalAccountRuntime',
      ).timeout(const Duration(seconds: 4));
      if (runtimeErased != true) return false;
    }

    if (!_accountEpochIsCurrent(epoch)) return false;
    if (!await _deleteSensitiveArtifactVerified('calc_session.json')) {
      return false;
    }
    await marker.delete();
    return !await marker.exists();
  }

  Future<void> _deactivateCurrentDevice() async {
    if (_accountLifecycleBusy) return;
    _accountLifecycleBusy = true;
    final freeAccess = _isFreeAccessSession;
    var accountNumber =
        freeAccess ? _freeAccessAccountNumber : _accountController.text.trim();
    if (!freeAccess && accountNumber.replaceAll('-', '').length != 12) {
      accountNumber = await _currentAccountNumberForRefresh();
    }
    final scopeToken = _clientKeyScopeToken(accountNumber);
    final epoch = _beginAccountTeardown();
    if (mounted) setState(() => _isLoading = true);
    try {
      var journal = AccountCleanupJournal(
        intent: AccountCleanupIntent.deactivate,
        scopeToken: scopeToken,
        phase: 'stop_pending',
        pendingArtifacts: Set<String>.from(_accountCleanupArtifacts),
      );
      await _writeAccountCleanupJournal(journal, epoch);
      if (!await _stopAndProveTunnelInactive() ||
          !_accountEpochIsCurrent(epoch)) {
        _showFeedback(
            'VPN shutdown is not yet proven. No account data was erased; try again.');
        return;
      }
      journal = journal.copyWith(phase: 'logout_pending');
      await _writeAccountCleanupJournal(journal, epoch);
      final deviceAuthToken = await _readDeviceAuthToken();
      if (!_accountEpochIsCurrent(epoch)) return;
      final logoutOk = await _sendLogoutToHub(
        freeAccess: freeAccess,
        accountNumber: accountNumber,
        deviceId: _appScopedDeviceId,
        deviceAuthToken: deviceAuthToken,
      );
      if (!_accountEpochIsCurrent(epoch)) return;
      if (logoutOk) {
        // Verified cleanup removes only this account's queued logout.
      } else if (!await _queuePendingLogout(
        freeAccess: freeAccess,
        accountNumber: accountNumber,
        deviceId: _appScopedDeviceId,
        deviceAuthToken: deviceAuthToken,
      )) {
        _showFeedback(
            'Could not safely queue server cleanup. No credentials were erased.');
        return;
      } else {
        final retained = Set<String>.from(journal.pendingArtifacts)
          ..remove('pending_logout');
        journal = journal.copyWith(pendingArtifacts: retained);
      }
      journal = journal.copyWith(phase: 'purging');
      await _writeAccountCleanupJournal(journal, epoch);
      if (!await _runAccountCleanup(journal, epoch)) {
        _showFeedback(
            'Device cleanup is incomplete and will retry on next launch.');
        return;
      }
      _settingsWritesSealed = false;
      _resetAccountUiAfterVerifiedCleanup();
    } catch (_) {
      _showFeedback(
          'Device cleanup is incomplete. No success was recorded; try again.');
    } finally {
      _accountLifecycleBusy = false;
      if (mounted && _isLoading) setState(() => _isLoading = false);
    }
  }

  // --------------------------------------------------------------------
  // Account deletion (Apple Guideline 5.1.1(v) in-app deletion).
  //
  // Every call is authenticated with THIS device's scoped bearer token, the
  // same credential /logout uses. The hub counts a confirmation only for the
  // device that presented its own token, so nothing here can be replayed on
  // another device's behalf.
  // --------------------------------------------------------------------

  Future<AccountDeletionState?> _postAccountDeletion(
    List<String> Function(GatewayEndpoints) gatewaySelector, {
    Map<String, dynamic> extra = const <String, dynamic>{},
  }) async {
    final token = (await _readDeviceAuthToken())?.trim() ?? '';
    if (token.isEmpty) {
      // Matches the /logout contract: without a scoped token this device was
      // never properly activated, and the hub would reject it anyway.
      _debugLog(
          'Account deletion skipped: device auth token unavailable; device needs re-activation.');
      return null;
    }
    final endpoints = await _resolveDynamicEndpoints();
    final gatewayEndpoints = GatewayEndpoints(gateway: endpoints['gateway']!);
    final body = jsonEncode({
      'account_number': _accountController.text.trim(),
      'device_id': _appScopedDeviceId,
      ...extra,
    });
    final headers = _jsonHeaders();
    headers['Authorization'] = 'Bearer $token';
    // The staggered hub window, as _sendLogoutToHub uses: the serial walk was
    // 29 fronts at 6 s each, up to 174 s of spinner per deletion step on a
    // filtering network. The hub joins a repeated request to the pending one
    // (one pending row per account), so a hedged duplicate is harmless. A
    // timed-out request is aborted, not left open.
    final outcome = await runHubRequestWindow<AccountDeletionState>(
      urls: gatewaySelector(gatewayEndpoints),
      preference: _hubOriginPreference,
      policy: const HubRequestWindowPolicy(
        perRequestTimeout: Duration(seconds: 6),
        totalDeadline: kHubVerifyTotalDeadline,
      ),
      attempt: (url, abort) async {
        try {
          final response = await sendHubRequest(
            _controlPlaneClient,
            'POST',
            Uri.parse(url),
            abort: abort,
            headers: headers,
            body: body,
          );
          if (response.statusCode >= 200 && response.statusCode < 300) {
            final decoded = jsonDecode(response.body);
            if (decoded is Map<String, dynamic>) {
              return HubAttemptResult<AccountDeletionState>.accepted(
                  AccountDeletionState.fromStatusPayload(decoded));
            }
          }
        } catch (_) {}
        return const HubAttemptResult<AccountDeletionState>.rejected();
      },
    );
    return outcome.value;
  }

  Future<AccountDeletionState?> _fetchAccountDeletionStatus() =>
      _postAccountDeletion(accountDeletionStatusGateways);

  Future<AccountDeletionState?> _requestAccountDeletion() =>
      _postAccountDeletion(accountDeletionRequestGateways);

  Future<AccountDeletionState?> _confirmAccountDeletion(String requestId) =>
      _postAccountDeletion(
        accountDeletionConfirmGateways,
        extra: {'request_id': requestId},
      );

  Future<AccountDeletionState?> _cancelAccountDeletion() =>
      _postAccountDeletion(accountDeletionCancelGateways);

  /// The account no longer exists on the hub, so every local credential for it
  /// is now dead weight and must go. Deliberately does NOT call /logout: there
  /// is no account left to log out of.
  Future<bool> _clearLocalStateAfterAccountDeletion() async {
    if (_accountLifecycleBusy) return false;
    _accountLifecycleBusy = true;
    final scopeToken = _clientKeyScopeToken(_accountController.text.trim());
    final epoch = _beginAccountTeardown();
    try {
      var journal = AccountCleanupJournal(
        intent: AccountCleanupIntent.accountDelete,
        scopeToken: scopeToken,
        phase: 'stop_pending',
        pendingArtifacts: Set<String>.from(_accountCleanupArtifacts),
      );
      await _writeAccountCleanupJournal(journal, epoch);
      if (!await _stopAndProveTunnelInactive() ||
          !_accountEpochIsCurrent(epoch)) {
        return false;
      }
      journal = journal.copyWith(phase: 'purging');
      await _writeAccountCleanupJournal(journal, epoch);
      if (!await _runAccountCleanup(journal, epoch)) return false;
      _settingsWritesSealed = false;
      _resetAccountUiAfterVerifiedCleanup();
      return true;
    } catch (_) {
      return false;
    } finally {
      _accountLifecycleBusy = false;
    }
  }

  Future<void> _openAccountDeletionSheet() async {
    setState(() => _isLoading = true);
    final initial = await _fetchAccountDeletionStatus();
    if (!mounted) return;
    setState(() => _isLoading = false);
    if (initial == null) {
      _showFeedback(
          'Could not reach the account service to check deletion status. Check your connection and try again.');
      return;
    }
    if (initial.stage == AccountDeletionStage.completed) {
      final cleanupComplete = await _clearLocalStateAfterAccountDeletion();
      if (mounted && cleanupComplete) {
        _showFeedback('Your account and its data have been deleted.');
      } else if (mounted) {
        _showFeedback(
            'Local account cleanup is incomplete and will retry on next launch.');
      }
      return;
    }
    final deleted = await showModalBottomSheet<bool>(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.white,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(16)),
      ),
      builder: (_) => AccountDeletionSheet(
        initialState: initial,
        onRequest: _requestAccountDeletion,
        onConfirm: _confirmAccountDeletion,
        onCancel: _cancelAccountDeletion,
        onRefresh: _fetchAccountDeletionStatus,
      ),
    );
    if (deleted == true) {
      final cleanupComplete = await _clearLocalStateAfterAccountDeletion();
      if (mounted && cleanupComplete) {
        _showFeedback('Your account and its data have been deleted.');
      } else if (mounted) {
        _showFeedback(
            'Local account cleanup is incomplete and will retry on next launch.');
      }
    }
  }

  Future<String> _loadOrCreateInstallId() async {
    if (Platform.isIOS || Platform.isMacOS) {
      try {
        final nativeInstallId =
            await _methodChannel.invokeMethod<String>('loadOrCreateInstallId');
        final installId = (nativeInstallId ?? '').trim();
        if (installId.length >= 24) return installId;
      } catch (e) {
        _debugLog('Native Apple install ID unavailable: $e');
      }
    }

    // install_id.txt lives in the encrypted native store on every platform
    // (SecureFileStore.kt, windows_tunnel_backend.cpp, WinsSecureStateStore,
    // linux_secure_store.cc; ruling 8b). A plaintext copy an older build left
    // in the documents directory is adopted once, and removed only after the
    // secure copy reads back.
    final stored = (await _readSensitiveText('install_id.txt'))?.trim() ?? '';
    var installId = stored;
    final directory = await _appDocumentsDirectory();
    final legacyFile = File('${directory.path}/install_id.txt');
    if (installId.length < 24 && await legacyFile.exists()) {
      installId = (await legacyFile.readAsString()).trim();
    }
    if (installId.length < 24) {
      final random = Random.secure();
      final bytes = List<int>.generate(24, (_) => random.nextInt(256));
      installId = base64UrlEncode(bytes).replaceAll('=', '');
    }
    if (installId != stored) {
      await _writeSensitiveText('install_id.txt', installId);
      if ((await _readSensitiveText('install_id.txt'))?.trim() != installId) {
        throw StateError('Install id failed durable read-back');
      }
    }
    if (await legacyFile.exists()) {
      // Retried on every launch until it succeeds. A failure here never
      // withholds the identity, which is already durable in the store.
      try {
        await legacyFile.writeAsBytes(
            List<int>.filled(await legacyFile.length(), 0),
            flush: true);
        await legacyFile.delete();
      } catch (e) {
        _debugLog('Install id: plaintext copy not removed yet; retrying '
            'next launch: $e');
      }
    }
    return installId;
  }

  String _displayNodeName(dynamic value, {String fallback = 'Unknown'}) {
    final raw = (value ?? fallback).toString().trim();
    final cleaned = raw
        .replaceFirst(RegExp(r'\s*(?:[-–—]\s*Free|\(Free\))\s*$'), '')
        .trim();
    return cleaned.isEmpty ? fallback : cleaned;
  }

  String _normalizeFlag(dynamic value) {
    final raw = (value ?? '').toString().trim();
    if (raw.isEmpty) return '🌐';
    final countryCode = raw.toUpperCase();
    if (RegExp(r'^[A-Z]{2}$').hasMatch(countryCode)) {
      final first = countryCode.codeUnitAt(0) - 65;
      final second = countryCode.codeUnitAt(1) - 65;
      if (first >= 0 && first < 26 && second >= 0 && second < 26) {
        return String.fromCharCodes([0x1F1E6 + first, 0x1F1E6 + second]);
      }
    }
    return raw;
  }

  /// Per-transport reachability as reported by the hub, e.g.
  /// `{direct_awg_udp: unreachable, stealth_tcp_ws: ok}`. Unknown shapes
  /// collapse to an empty map rather than throwing, because a listing payload
  /// must never be able to break server selection.
  Map<String, String> _transportStates(dynamic raw) {
    if (raw is! Map) return const <String, String>{};
    final out = <String, String>{};
    raw.forEach((key, value) {
      final k = key?.toString().trim() ?? '';
      if (k.isEmpty) return;
      out[k] = value?.toString().trim().toLowerCase() ?? 'unknown';
    });
    return out;
  }

  /// Human-readable reason a server cannot be selected right now.
  String _unreachableReason(Map<String, dynamic> node) {
    final transports = _transportStates(node['transports']);
    final anyUp = transports.values.any((v) => v == 'ok');
    if (anyUp) {
      // Some route works, just not one this platform can use.
      return 'Not reachable from this device right now';
    }
    return 'Server unreachable right now';
  }

  Map<String, dynamic> _normalizeNodeItem(
    Map<String, dynamic> item, {
    ({int mono, int wall})? loadReceipt,
  }) {
    final load = loadReceipt == null ? null : serverLoadPctOf(item);
    return <String, dynamic>{
      'name': _displayNodeName(item['name']),
      'flag': _normalizeFlag(item['flag']),
      'slug': item['slug'] ?? 'unknown',
      'status': item['status'] ?? 'online',
      'endpoint': item['endpoint'] ?? item['server_endpoint'] ?? '',
      'stealth_endpoint':
          item['stealth_endpoint'] ?? item['stealthendpoint'] ?? '',
      'free_access_enabled':
          _boolValue(item['free_access_enabled'] ?? item['freeaccessenabled']),
      'direct_awg_enabled': _boolDefaultTrue(
          item['direct_awg_enabled'] ?? item['directawgenabled']),
      // Optional. Today's GET /nodes SELECT does not emit these; when a hub
      // does, the v3 cover-node picker can skip labelled standalone v3
      // successors without waiting for a vpn_config fetch.
      'protocol_version':
          (item['protocol_version'] ?? item['protocolversion'] ?? '')
              .toString()
              .trim(),
      'carrier': (item['carrier'] ?? '').toString().trim(),
      // Data-plane reachability, proven by the hub from OUTSIDE the node.
      //
      // Defaults to TRUE when absent, deliberately: cached-on-disk entries,
      // bootstrap entries and any older hub all predate this field, and
      // defaulting to false would render every one of them unselectable and
      // leave the user with nothing. A node is only shown as unreachable when
      // the hub affirmatively says so.
      'reachable': _boolDefaultTrue(item['reachable'] ?? item['datareachable']),
      'transports':
          _transportStates(item['transports'] ?? item['reachabletransports']),
      'regional_aliases': _stringListValue(item['regional_aliases'] ??
          item['regionalaliases'] ??
          item['stealth_aliases'] ??
          item['stealthaliases']),
      if (_nodeLatencyMs(item) != null) 'latency_ms': _nodeLatencyMs(item),
      // Hub-reported load, 0..100 in steps of 5. Kept only when it is exactly a
      // contract value AND the caller stamped when it was received (only a live
      // /nodes reply does); anything else (missing, null, string, float, out of
      // range, or a cached/auth copy) is dropped here, which the load bar
      // renders as "unknown". This projection runs inside _parseNodesResponse's
      // single try, so it must never throw: one bad value would otherwise
      // discard the whole list.
      if (load != null && loadReceipt != null) ...<String, dynamic>{
        kServerLoadPctKey: load,
        kServerLoadReceivedMonoKey: loadReceipt.mono,
        kServerLoadReceivedWallKey: loadReceipt.wall,
      },
    };
  }

