  String _localizedAnnouncement(String value) {
    final trimmed = value.trim();
    if (trimmed.isEmpty ||
        trimmed == _defaultAnnouncement ||
        trimmed == 'Welcome to Wins VPN.') {
      return _t(_defaultAnnouncement);
    }
    if (trimmed == 'Secure Connection Established.') return _t(trimmed);
    return value;
  }

  String _nodeSortKey(Map<String, dynamic> node) {
    final name = (node['name'] ?? '').toString().trim().toLowerCase();
    if (name.isNotEmpty) return name;
    return (node['slug'] ?? '').toString().trim().toLowerCase();
  }

  int _compareNodeItems(Map<String, dynamic> a, Map<String, dynamic> b) {
    final nameCompare = _nodeSortKey(a).compareTo(_nodeSortKey(b));
    if (nameCompare != 0) return nameCompare;
    return (a['slug'] ?? '')
        .toString()
        .toLowerCase()
        .compareTo((b['slug'] ?? '').toString().toLowerCase());
  }

  List<Map<String, dynamic>> _sortedNodeItems(
      Iterable<Map<String, dynamic>> nodes) {
    final list = nodes.map((node) => Map<String, dynamic>.from(node)).toList();
    list.sort(_compareNodeItems);
    return list;
  }

  int? _nodeLatencyMs(Map<String, dynamic>? node) {
    if (node == null) return null;
    final raw = node['latency_ms'] ?? node['latencyms'];
    final parsed = raw is int ? raw : int.tryParse((raw ?? '').toString());
    if (parsed == null || parsed <= 0 || parsed > 9999) return null;
    return parsed;
  }

  String _nodeLatencyLabel(Map<String, dynamic>? node) {
    final latency = _nodeLatencyMs(node);
    return latency == null ? '' : '$latency ms';
  }

  int? _medianLatencyMs(Iterable<int> values) {
    final samples = values.where((value) => value > 0 && value < 10000).toList()
      ..sort();
    if (samples.isEmpty) return null;
    return samples[samples.length ~/ 2];
  }

  int? _smoothedNodeLatencyMs(int? currentLatency, int? measuredLatency) {
    if (measuredLatency == null) return currentLatency;
    if (currentLatency == null) return measuredLatency;
    final delta = (measuredLatency - currentLatency).abs();
    if (delta <= max(12, currentLatency ~/ 5)) return measuredLatency;
    return ((currentLatency * 2) + measuredLatency) ~/ 3;
  }

  Future<int?> _probeTcpLatencyMs(String host, int port) async {
    final samples = <int>[];
    // Dial the literal, never the name. Handing a hostname to Socket.connect
    // makes dart:io run an implicit InternetAddress.lookup with no family hint
    // (an A and an AAAA), which is exactly the physical-interface name leak
    // this probe made on every latency-refresh cycle while the server picker
    // was open. This is the same "dial the literal, never the name" discipline
    // the Xray preflight path already follows (see _preflightXrayWebSocketTransport).
    // Resolve A-only once, then dial the literal; if a name produces no public
    // IPv4, refuse the probe instead of falling back to the name.
    var dialHost = host;
    if (requiresAonlyIpv4ProbeResolution(host)) {
      final addresses = await _resolveXrayCarrierIpv4ForPreflight(host);
      dialHost = firstPublicIpv4ProbeDialTarget(
        host: host,
        aonlyAddresses: addresses,
      );
      if (dialHost.isEmpty) return null;
    }
    for (var attempt = 0; attempt < _nodeLatencyProbeSamples; attempt++) {
      Socket? socket;
      final watch = Stopwatch()..start();
      try {
        socket = await Socket.connect(
          dialHost,
          port,
          timeout: _nodeLatencyProbeTimeout,
        );
        watch.stop();
        final ms = max(1, watch.elapsedMilliseconds);
        samples.add(ms);
      } catch (_) {
      } finally {
        socket?.destroy();
      }
      if (attempt < _nodeLatencyProbeSamples - 1) {
        await Future.delayed(const Duration(milliseconds: 35));
      }
    }
    return _medianLatencyMs(samples);
  }

  int? _parsePingLatencyMs(String output) {
    final normalized = output.replaceAll(',', '.');
    final unixAverageMatch = RegExp(
            r'(?:rtt|round-trip)[^=]*=\s*[0-9.]+/([0-9]+(?:\.[0-9]+)?)/',
            caseSensitive: false)
        .firstMatch(normalized);
    if (unixAverageMatch != null) {
      final value = double.tryParse(unixAverageMatch.group(1) ?? '');
      if (value != null && value > 0) return max(1, value.round());
    }
    final averageMatch =
        RegExp(r'Average\s*=\s*([0-9]+)\s*ms', caseSensitive: false)
            .firstMatch(normalized);
    if (averageMatch != null) {
      final value = int.tryParse(averageMatch.group(1) ?? '');
      if (value != null && value > 0) return value;
    }
    final samples =
        RegExp(r'time[=<]\s*([0-9]+(?:\.[0-9]+)?)\s*ms', caseSensitive: false)
            .allMatches(normalized)
            .map((match) => double.tryParse(match.group(1) ?? ''))
            .whereType<double>()
            .map((value) => max(1, value.round()));
    return _medianLatencyMs(samples);
  }

  Future<int?> _probePingLatencyMs(String host) async {
    if (host.trim().isEmpty) return null;
    final executable = Platform.isWindows
        ? 'ping'
        : (Platform.isAndroid ? '/system/bin/ping' : 'ping');
    final fallbackExecutable = Platform.isWindows ? 'ping.exe' : 'ping';
    // A-01 (audits 2026-08-28): a hub-supplied host beginning with `-` used
    // to be "defused" by stripping ONE leading dash -- `--flag` became
    // `-flag`, still a flag. Option-like or malformed hosts are now refused
    // outright: argv-only already prevented shell injection, but the
    // argument POSITION is a ping flag position, so anything that is not an
    // unambiguous host is rejected rather than repaired.
    final trimmedHost = host.trim();
    if (trimmedHost.isEmpty ||
        trimmedHost.startsWith('-') ||
        !RegExp(r'^[A-Za-z0-9.:\[\]-]+$').hasMatch(trimmedHost)) {
      return null;
    }
    final args = Platform.isWindows
        ? <String>['-n', '3', '-w', '1000', trimmedHost]
        : <String>['-c', '3', '-W', '1', trimmedHost];

    // `Process.run(...).timeout(...)` was what crashed a 128 GB MacBook on
    // 2026-08-08: the app reached 152 GiB across 447k VM regions. `timeout`
    // completes the FUTURE, it does not kill the child and it does not stop
    // `Process.run` buffering that child's output -- which it does in memory,
    // with no cap, until the child exits. macOS `ping` does not always exit:
    // when its ICMP socket errors persistently (a route change under a tunnel
    // does it) BSD ping loops `recvmsg` -> `warn()` -> write-to-stderr with no
    // delay, spewing at full CPU speed forever. Because Dart kept draining
    // that pipe, ping never blocked on a full one, so the two ran as a pump
    // straight into the heap -- measured at ~16 MB/s per wedged child, and a
    // fresh pair was started every 45 s by _refreshNodeLatencies. The silent
    // `catch (_)` meant it read as a probe that simply returned no latency.
    //
    // Two structural bounds now, neither of which can be forgotten by a future
    // edit that keeps using this helper:
    //   1. `finally` SIGKILLs the child on every exit path, so no probe can
    //      leave a process alive past its own timeout.
    //   2. at most _pingOutputByteCap bytes are ever retained; bytes past the
    //      cap are dropped on the floor rather than appended.
    Future<int?> runPing(String command) async {
      Process? started;
      StreamSubscription<List<int>>? outSub;
      StreamSubscription<List<int>>? errSub;
      try {
        final process = await Process.start(command, args);
        started = process;

        final buffer = StringBuffer();
        var captured = 0;
        void capture(List<int> chunk) {
          if (captured >= _pingOutputByteCap) return;
          final room = _pingOutputByteCap - captured;
          final slice = chunk.length <= room ? chunk : chunk.sublist(0, room);
          captured += slice.length;
          buffer.write(utf8.decode(slice, allowMalformed: true));
        }

        final outDone = Completer<void>();
        final errDone = Completer<void>();
        void settle(Completer<void> completer) {
          if (!completer.isCompleted) completer.complete();
        }

        outSub = process.stdout.listen(
          capture,
          onDone: () => settle(outDone),
          onError: (_) => settle(outDone),
          cancelOnError: true,
        );
        errSub = process.stderr.listen(
          capture,
          onDone: () => settle(errDone),
          onError: (_) => settle(errDone),
          cancelOnError: true,
        );

        final settled = await Future.wait<Object?>([
          process.exitCode,
          outDone.future,
          errDone.future,
        ]).timeout(_pingProbeTimeout);

        if (settled.first != 0) return null;
        return _parsePingLatencyMs(buffer.toString());
      } catch (_) {
        return null;
      } finally {
        started?.kill(ProcessSignal.sigkill);
        unawaited(outSub?.cancel());
        unawaited(errSub?.cancel());
      }
    }

    final primary = await runPing(executable);
    // Off Windows both names are the literal 'ping', so the fallback re-ran
    // the identical command and doubled every leak -- the crashed machine was
    // left holding orphaned pings in pairs. Only retry a DIFFERENT executable.
    if (primary != null || fallbackExecutable == executable) return primary;
    return runPing(fallbackExecutable);
  }

  Future<int?> _probeNodeLatencyMs(Map<String, dynamic> node) async {
    // The TCP-fallback preference pauses optional probes to a gateway's own
    // address. It does not suppress the required Winn v3 or Winn v1 AWG connect
    // attempt, but it avoids additional pre-connect traffic.
    //
    // Why not just skip the ping and keep the TCP one: `stealth_endpoint` is
    // gated on `stealth.host == direct.host`, i.e. it only ever runs against
    // the node's REAL address, and `_probeTcpLatencyMs` opens a real
    // `Socket.connect` to it. Gating the ICMP probe alone would have swapped an
    // echo request for a SYN to the same address and left the promise just as
    // false, on a protocol the verification capture happened not to be
    // filtering for. There is no CDN-fronted per-node host to fall back to --
    // nodes carry only `endpoint` and `stealth_endpoint` -- and probing the
    // fronted control-plane host instead would measure Cloudflare, not this
    // node, which is a worse answer than no answer.
    //
    // Found 2026-08-07 during rollout consolidation (X3/S5). The connect path
    // was gated in five places; this read path was missed because it is driven
    // from the node-picker UI rather than from Connect.
    if (_isStealthTransportOnly) return null;

    // A-01 (audits 2026-08-28, three reports): no node latency traffic while
    // disconnected. Every endpoint this function can touch is hub-served,
    // and the ICMP/TCP probes left the device from the user's REAL IP --
    // three echo requests per node, steerable by a compromised hub toward
    // arbitrary targets, and the burst itself identified the app. While
    // disconnected (or mid-transition) the picker shows cached/absent
    // latency instead of measuring it. Through an established tunnel the
    // probes ride the tunnel; the number then means "RTT from your exit",
    // which is the only measurement this app may take.
    if (!_isConnected || _isTunnelTransitioning) return null;

    final direct = _hostPortValue(node['endpoint'], defaultPort: 9110);
    if (direct != null) {
      final pingLatency = await _probePingLatencyMs(direct.host);
      if (pingLatency != null) return pingLatency;
      // Deliberately no TCP probe against the direct endpoint. `endpoint` is
      // the AmneziaWG peer address and is UDP by construction, so a TCP connect
      // to it can only burn the timeout -- and it would put a SYN on the
      // gateway's REAL address, on a port the Cloudflare-only nftables chain
      // does not cover, which is the exposure this transport already has too
      // much of. What stood here used the fleet-wide port NUMBER as a proxy for
      // "this is the UDP one"; that proxy stops holding the moment nodes carry
      // per-node listen ports, and it fails open, into a scan. The TCP
      // measurement that is actually meaningful is the stealth one below.
    }

    final stealth = _hostPortValue(
      node['stealth_endpoint'] ?? node['stealthendpoint'],
      defaultPort: 80,
    );
    if (stealth != null && direct != null && stealth.host == direct.host) {
      final tcpLatency = await _probeTcpLatencyMs(stealth.host, stealth.port);
      if (tcpLatency != null) return tcpLatency;
    }
    return null;
  }

  Future<void> _refreshNodeLatencies({bool force = false}) async {
    if (_locations.isEmpty || _nodeLatencyProbeRunning) return;
    bool foreground() {
      final lifecycle = WidgetsBinding.instance.lifecycleState;
      return lifecycle == null || lifecycle == AppLifecycleState.resumed;
    }
    if (!foreground()) return;
    final now = DateTime.now();
    if (!force &&
        now.difference(_lastNodeLatencyRefresh) < _nodeLatencyRefreshInterval) {
      return;
    }
    _lastNodeLatencyRefresh = now;
    _nodeLatencyProbeRunning = true;
    final generation = ++_nodeLatencyProbeGeneration;
    var completed = false;
    final probes = _locations
        .map((node) => Map<String, dynamic>.from(node))
        .where((node) => (node['slug'] ?? '').toString().trim().isNotEmpty)
        .toList();

    try {
      for (var i = 0; i < probes.length; i += _nodeLatencyProbeConcurrency) {
        if (!mounted ||
            !foreground() ||
            generation != _nodeLatencyProbeGeneration) return;
        final end = min(i + _nodeLatencyProbeConcurrency, probes.length);
        final results = await Future.wait(probes.sublist(i, end).map((node) {
          return () async {
            final slug = (node['slug'] ?? '').toString();
            final latency = await _probeNodeLatencyMs(node);
            return (slug: slug, latency: latency);
          }();
        }));
        if (!mounted ||
            !foreground() ||
            generation != _nodeLatencyProbeGeneration) return;
        setState(() {
          for (final result in results) {
            final index = _locations.indexWhere(
                (node) => (node['slug'] ?? '').toString() == result.slug);
            if (index < 0) continue;
            if (result.latency == null) {
              continue;
            } else {
              _locations[index]['latency_ms'] = _smoothedNodeLatencyMs(
                    _nodeLatencyMs(_locations[index]),
                    result.latency,
                  ) ??
                  result.latency;
            }
          }
        });
      }
      completed = true;
    } finally {
      if (completed &&
          mounted &&
          foreground() &&
          generation == _nodeLatencyProbeGeneration) {
        unawaited(_saveCachedNodes());
      }
      if (generation == _nodeLatencyProbeGeneration) {
        _nodeLatencyProbeRunning = false;
      }
    }
  }

  Widget _buildServerTitleLine(
    Map<String, dynamic>? node, {
    String fallback = 'Searching...',
    String? nameOverride,
    bool showLatency = true,
  }) {
    final name = nameOverride ??
        (node != null ? _displayNodeName(node['name']) : fallback);
    final latency = showLatency ? _nodeLatencyLabel(node) : '';
    return Row(
      children: [
        if (latency.isNotEmpty) ...[
          Text(
            latency,
            maxLines: 1,
            overflow: TextOverflow.fade,
            softWrap: false,
            style: const TextStyle(
              color: _surfaceMutedText,
              fontSize: 11,
              fontWeight: FontWeight.w700,
            ),
          ),
          const SizedBox(width: 8),
        ],
        Expanded(
          child: Text(
            name,
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            softWrap: false,
          ),
        ),
      ],
    );
  }

  /// The shared load bar for [node], or null when there is no concrete server:
  /// "Automatic" and an unidentified tunnel node have no single server whose
  /// load could be shown. It sits on the row under the server name (see
  /// [_buildServerStatusRow]), never on the name row, so the name keeps the
  /// full width.
  Widget? _buildServerLoadBar(
    Map<String, dynamic>? node, {
    bool followLiveListing = false,
  }) {
    if (node == null) return null;
    if (followLiveListing) {
      // The picker renders a copy of the list; follow the live row for this
      // slug so a fetch that lands while it is open updates the bar.
      return LiveServerLoadBar(
        listing: _nodeListingRevision,
        resolve: () =>
            tunnelListingRowForSlug(
                _locations, (node['slug'] ?? '').toString()) ??
            node,
      );
    }
    return ServerLoadBar(node: node);
  }

  /// The row under a server name: [text] (the status, the picker note, the
  /// free-server count) with the load bar directly to its right. Null when
  /// there is neither text nor a bar.
  Widget? _buildServerStatusRow(
    Widget? text,
    Map<String, dynamic>? node, {
    bool showLoad = true,
    bool followLiveListing = false,
  }) {
    final bar = showLoad
        ? _buildServerLoadBar(node, followLiveListing: followLiveListing)
        : null;
    if (bar == null) return text;
    return Row(
      children: [
        if (text != null) ...[
          Flexible(child: text),
          const SizedBox(width: 8),
        ],
        bar,
      ],
    );
  }

  bool _isFreeNode(Map<String, dynamic> node) {
    // Free access follows the same server listing and admission gates as paid.
    return (node['slug'] ?? '').toString().trim().isNotEmpty;
  }

  List<Map<String, dynamic>> _freeLocations() =>
      _locations.where(_isFreeNode).toList();

  List<Map<String, dynamic>> _nodesForCurrentSession(
      Iterable<Map<String, dynamic>> nodes) {
    final sorted = _sortedNodeItems(nodes);
    if (!_isFreeAccessSession) return sorted;
    final freeOnly = sorted.where(_isFreeNode).toList();
    return freeOnly;
  }

  /// Row 0 for anything not listed. Not for resolving a user's pick: that
  /// goes through _rebindSelection. The one caller binds a slug it has just
  /// merged into the listing (_applySelectedNodeFromAuth).
  int _indexForNodeSlug(String? slug) {
    final normalized = (slug ?? '').trim();
    if (normalized.isEmpty || normalized == 'auto') return 0;
    final index = _locations.indexWhere(
        (location) => (location['slug'] ?? '').toString() == normalized);
    return index >= 0 ? index : 0;
  }

  /// A manual choice that the listing does not carry, so no row is selected.
  bool get _manualSelectionUnlisted =>
      !_automaticNodeSelection &&
      _selectedLocationIndex == kUnlistedSelectionIndex &&
      _unlistedSelection != null;

  /// Re-binds [intendedSlug] to the current `_locations`. A manual choice the
  /// listing does not carry stays the choice instead of becoming row 0.
  void _rebindSelection(String intendedSlug,
      {Iterable<Map<String, dynamic>> knownRows =
          const <Map<String, dynamic>>[]}) {
    final previous = _unlistedSelection;
    final rebind = rebindSelection(
      locations: _locations,
      intendedSlug: intendedSlug,
      automatic: _automaticNodeSelection,
      knownRows: <Map<String, dynamic>>[
        ...knownRows,
        if (previous != null) previous,
      ],
    );
    _selectedLocationIndex = rebind.index;
    _unlistedSelection = rebind.unlisted;
  }

  /// Whether a fresh live listing omits [slug] (see [freshListingOmits]).
  bool _freshListingOmits(String slug) => freshListingOmits(
        locations: _locations,
        slug: slug,
        liveListingAt: _liveListingReceivedAt,
        now: DateTime.now(),
      );

  /// The unlisted choice as the card names it: `unavailable` only when a
  /// fresh live listing omits it, otherwise `unknown`. Null when the choice
  /// is listed or automatic.
  Map<String, dynamic>? _unlistedSelectionForDisplay() {
    final unlisted = _unlistedSelection;
    if (!_manualSelectionUnlisted || unlisted == null) return null;
    final slug = (unlisted['slug'] ?? '').toString();
    return <String, dynamic>{
      ...unlisted,
      'status': _freshListingOmits(slug) ? 'unavailable' : 'unknown',
    };
  }

  // A settings restart deferred until a live listing arrives, bound to the
  // display session and account epoch of the tunnel it was deferred for.
  // Declared here with the selection helpers because every transaction
  // harness that runs them also runs the restart.
  bool _settingsRestartPending = false;
  int _settingsRestartGeneration = -1;
  int _settingsRestartEpoch = -1;

  /// Feedback from the L91 selection paths, which can complete after the app
  /// went to the background and the decoy calculator came back. Never over
  /// the decoy (the rule of _showAnnouncementWindow): the message is dropped,
  /// and the action it reports has already been decided without it.
  void _showSelectionFeedback(String message) {
    if (_showDecoyCalculator) return;
    _showFeedback(message);
  }

  /// A server switch to [targetSlug] the current listing no longer carries
  /// (a refresh removed it after the tap) is refused before anything is torn
  /// down, never resolved to another row. Returns true when refused.
  bool _refuseUnlistedSwitchTarget(String? targetSlug, String serverName) {
    final slug = (targetSlug ?? '').trim();
    if (slug.isEmpty) return false;
    if (_locations.any((node) => (node['slug'] ?? '').toString() == slug)) {
      return false;
    }
    _showSelectionFeedback('$serverName is no longer in the server list. '
        'Your current VPN was kept.');
    return true;
  }

  void _applySelectedNodeFromAuth(Map<String, dynamic> data,
      {bool freeAccess = false}) {
    final node = _mapValue(data, ['selected_node', 'selectednode']);
    if (node.isEmpty) return;
    final slug = _stringValue(node, ['slug']) ?? 'auto';
    // The auth reply names the node (slug, name, flag, status) and nothing
    // else. Start from this slug's listing row so its endpoints, transports,
    // protocol labels, reachability, latency and free flag survive until the
    // next /nodes refresh instead of being blanked here.
    Map<String, dynamic>? listed;
    for (final location in _locations) {
      if (location['slug'] == slug) {
        listed = location;
        break;
      }
    }
    final item = _normalizeNodeItem(<String, dynamic>{
      ...?listed,
      'name': _stringValue(node, ['name']) ?? 'Auto Selected',
      'flag': _stringValue(node, ['flag']) ?? '🌐',
      'slug': slug,
      'status': _stringValue(node, ['status']) ?? 'online',
      'free_access_enabled':
          freeAccess || listed?['free_access_enabled'] == true,
    });
    if (freeAccess && slug.trim().isNotEmpty && slug != 'auto') {
      _freeNodeSlugs.add(slug);
      _freeNodeSnapshotLive = true;
    }
    if ((_winn3CoverExactTargetSlug ?? '').trim().isNotEmpty) {
      return;
    }
    // The auth reply carries no load; keep the listing's value for this slug
    // rather than blanking the bar until the next /nodes refresh.
    if (listed != null) {
      // Figure AND receipt stamps, so it keeps its original age.
      copyServerLoad(listed, item);
    }
    final merged = _locations
        .where((location) => location['slug'] != slug)
        .toList()
      ..add(item);
    _locations = _sortedNodeItems(merged);
    _selectedLocationIndex = _indexForNodeSlug(slug);
    unawaited(_saveCachedNodes());
  }

  Map<String, dynamic> _normalizeVpnConfig(Map<String, dynamic> raw) {
    final obfs = raw['obfuscation'];
    // Winn Protocol forward-compat seam (no-op for the shipping v1 protocol).
    // Mirrors the hub's served vpn_config: an absent protocol_version means the
    // shipping "winn/1" AmneziaWG path with empty protocol_params, so old
    // configs and old hubs behave exactly as before. Winn Protocol v3 (post-
    // quantum, built separately) sends "winn/3" plus its material (ML-KEM
    // public key, etc.) in protocol_params. Read here, dispatched in
    // _startTunnelCandidate.
    final protoParams = raw['protocol_params'] ?? raw['protocolparams'];
    final xrayRaw = raw['xray'];
    final Map<String, dynamic> xray = xrayRaw is Map
        ? Map<String, dynamic>.from(xrayRaw)
        : <String, dynamic>{};
    final bool stealthActive =
        _boolValue(raw['stealth_active'] ?? raw['stealthactive'] ?? false);
    final List<String> regionalAliases = _stringListValue(
        raw['regional_aliases'] ??
            raw['regionalaliases'] ??
            raw['stealth_aliases'] ??
            raw['stealthaliases']);
    final List<String> xrayFallbackHosts = <String>{
      ..._stringListValue(xray['fallback_hosts'] ??
          xray['fallbackhosts'] ??
          xray['regional_aliases'] ??
          xray['regionalaliases']),
      ...regionalAliases,
    }.toList();
    final List<String> windowsTransportBypassIpv4 =
        validatedXrayCarrierIpv4Pins(
      xrayHost: '',
      advertisedCarrierPins: _stringListValue(
        raw['windows_transport_bypass_ipv4'] ??
            raw['windowstransportbypassipv4'] ??
            xray['windows_transport_bypass_ipv4'] ??
            xray['windowstransportbypassipv4'],
      ),
    ).take(16).toList(growable: false);
    // A3 winn/3 fields (descriptor Map + device static private, plus the
    // rest of the hub overlay) used to be dropped here because this function
    // rebuilds a closed key list. applyWinn3ServedFields copies them onto
    // that list without inventing withheld keys. Empty {} still fail-closes
    // as no-descriptor-served. No other normalize gate is relaxed.
    // copyWinn3SelectedNodeIdentities keeps every selected-node alias so a
    // conflicting location_slug cannot collapse into a self-consistent INI.
    final config = copyWinn3SelectedNodeIdentities(
      dest: applyWinn3ServedFields(
        dest: <String, dynamic>{
          'client_ip': _stringValue(raw, ['client_ip', 'clientip']) ?? '',
          'tunnel_gateway_ipv4':
              _stringValue(raw, ['tunnel_gateway_ipv4', 'tunnelgatewayipv4']) ??
                  '',
          'client_private_key':
              _stringValue(raw, ['client_private_key', 'clientprivatekey']) ??
                  '',
          'client_public_key':
              _stringValue(raw, ['client_public_key', 'clientpublickey']) ?? '',
          'server_public_key':
              _stringValue(raw, ['server_public_key', 'serverpublickey']) ?? '',
          'preshared_key':
              _stringValue(raw, ['preshared_key', 'presharedkey']) ?? '',
          'server_endpoint':
              _stringValue(raw, ['server_endpoint', 'serverendpoint']) ?? '',
          'stealth_gateway_endpoint': _stringValue(raw,
                  ['stealth_gateway_endpoint', 'stealthgatewayendpoint']) ??
              '',
          'regional_aliases': regionalAliases,
          // Windows resolves the Xray carrier before raising its owned tunnel
          // routes. Preserve only bounded public IPv4 pins so a later DNS outage
          // can still start the carrier without promoting the unrelated AWG
          // endpoint or weakening TLS server-name verification.
          'windows_transport_bypass_ipv4': windowsTransportBypassIpv4,
          'stealth_active': stealthActive,
          'double_vpn_active': _boolValue(raw['double_vpn_active'] ??
              raw['doublevpnactive'] ??
              raw['double_vpn'] ??
              raw['doublevpn'] ??
              false),
          'direct_awg_enabled': _boolDefaultTrue(
              raw['direct_awg_enabled'] ?? raw['directawgenabled']),
          'double_vpn_exit_slug': _stringValue(
                  raw, ['double_vpn_exit_slug', 'doublevpnexitslug']) ??
              '',
          'double_vpn_core_id':
              _stringValue(raw, ['double_vpn_core_id', 'doublevpncoreid']) ??
                  '',
          'protocol': _stringValue(raw, ['protocol']) ??
              (stealthActive ? 'xray-vless-ws+amneziawg' : 'amneziawg'),
          'node_slug':
              _stringValue(raw, ['node_slug', 'nodeslug', 'location_slug']) ??
                  '',
          'mtu': raw['mtu'] ?? _directAwgMtu,
          'dns': _stringValue(raw, ['dns']) ?? '10.8.1.1',
          'obfuscation': obfs is Map
              ? Map<String, dynamic>.from(obfs)
              : <String, dynamic>{},
          // Winn Protocol forward-compat seam -- kept alongside obfuscation above.
          'protocol_params': protoParams is Map
              ? Map<String, dynamic>.from(protoParams)
              : <String, dynamic>{},
          // The outer transport ARRANGEMENT, served per node and absent by
          // default. Carried through normalization unchanged so
          // resolveWinnProtocolStart can see it; an absent or unrecognised value
          // leaves every refusal in winn_protocol_dispatch.dart firing exactly as
          // it did.
          kWinnOuterTransportKey: _stringValue(raw, [
                kWinnOuterTransportKey,
                'winnoutertransport',
              ]) ??
              '',
          'xray': <String, dynamic>{
            'enabled': _boolValue(xray['enabled'] ?? stealthActive),
            'uuid': _stringValue(xray, ['uuid']) ?? '',
            'host': _stringValue(xray, ['host']) ?? '',
            'port': int.tryParse((xray['port'] ?? '443').toString()) ?? 443,
            'server_name': _stringValue(xray, ['server_name', 'servername']) ??
                _stringValue(xray, ['host']) ??
                '',
            'path': _stringValue(xray, ['path']) ?? '/wins-stealth-tunnel',
            'security': _stringValue(xray, ['security']) ?? 'tls',
            'local_port': int.tryParse(
                    (xray['local_port'] ?? xray['localport'] ?? '42110')
                        .toString()) ??
                42110,
            'remote_awg_host':
                _stringValue(xray, ['remote_awg_host', 'remoteawghost']) ??
                    '127.0.0.1',
            'remote_awg_port': int.tryParse(
                    (xray['remote_awg_port'] ?? xray['remoteawgport'] ?? '9110')
                        .toString()) ??
                9110,
            'fallback_hosts': xrayFallbackHosts,
            'transports': sanitizeAdvertisedXrayTransports(
              xray['transports'] ??
                  xray['stealth_transports'] ??
                  raw['stealth_transports'] ??
                  raw['stealthtransports'],
            ),
          },
        },
        raw: raw,
      ),
      raw: raw,
    );
    // The fetch stamp survives normalization so a restored or re-projected
    // cache keeps its age. Fresh hub responses are re-stamped after this.
    final fetchedAt = raw[kVpnConfigFetchedAtKey];
    if (fetchedAt is int && fetchedAt > 0) {
      config[kVpnConfigFetchedAtKey] = fetchedAt;
    }
    return normalizeTlsOnlyXrayConfig(
      copyWinnProtocolVersionAliases(dest: config, raw: raw),
      advertisedTransports: originalAdvertisedXrayTransports(xray, raw),
    );
  }

  bool _hasUsableVpnConfig(Map<String, dynamic> config) {
    return VpnConfigValidator.isUsable(config);
  }

  Map<String, dynamic> _configForTransport(
    Map<String, dynamic> source, {
    required bool stealthMode,
    String? xrayHost,
    int? xrayPort,
    String? xraySecurity,
  }) {
    final config = _normalizeVpnConfig(source);
    // Normalization copies served fields only, so it drops the app's own
    // session-key marker; carry it with the key it describes.
    if (servedWinn3StaticPrivate(config).isNotEmpty &&
        source.containsKey(kWinn3StaticPrivateOriginField)) {
      config[kWinn3StaticPrivateOriginField] =
          source[kWinn3StaticPrivateOriginField];
    }
    final xray = config['xray'] is Map
        ? Map<String, dynamic>.from(config['xray'])
        : <String, dynamic>{};
    if (xrayHost != null && xrayHost.trim().isNotEmpty) {
      final host = _hostnameOnly(xrayHost);
      if (host.isNotEmpty) {
        xray['host'] = host;
      }
    }
    if (xrayPort != null) xray['port'] = xrayPort;
    if (xraySecurity != null && xraySecurity.trim().isNotEmpty) {
      xray['security'] = xraySecurity.trim().toLowerCase();
    }
    final tlsOptions = buildXrayTransportOptions(
      hosts: [(xray['host'] ?? '').toString()],
      advertisedPort: xray['port'],
      advertisedSecurity: xray['security'],
      advertisedTransports: xray['transports'],
    );
    final effectiveStealthMode = stealthMode &&
        (xray['security'] ?? '').toString().trim().toLowerCase() == 'tls' &&
        tlsOptions.any(
          (option) => option.port ==
              int.tryParse((xray['port'] ?? '').toString()),
        );
    xray['enabled'] = effectiveStealthMode;
    config['xray'] = xray;
    config['stealth_active'] = effectiveStealthMode;
    config['protocol'] =
        effectiveStealthMode ? 'xray-vless-ws+amneziawg' : 'amneziawg';
    config['mtu'] =
        effectiveStealthMode ? _stealthTransportMtu : _directAwgMtu;
    return config;
  }

  List<String> _xrayHostCandidates(Map<String, dynamic> config) {
    final xray = config['xray'] is Map
        ? Map<String, dynamic>.from(config['xray'])
        : <String, dynamic>{};
    final hosts = <String>[];
    final primary = _hostnameOnly((xray['host'] ?? '').toString());
    if (primary.isNotEmpty) hosts.add(primary);
    hosts.addAll(_stringListValue(xray['fallback_hosts'] ??
        xray['fallbackhosts'] ??
        config['regional_aliases'] ??
        config['regionalaliases']));
    return hosts.where((host) => host.isNotEmpty).toSet().toList();
  }

  String _nativeTunnelDnsServers(Map<String, dynamic> config) {
    final rawDns = (config['dns'] ?? '').toString().trim();
    if (!_isApplePlatform) return rawDns;
    final servers = rawDns
        .split(',')
        .map((server) => server.trim())
        .where((server) => server.isNotEmpty)
        .toList();
    if (servers.isEmpty) return '9.9.9.9,149.112.112.112';
    final hasPublicResolver = servers.any(_isPublicIpv4Literal);
    return hasPublicResolver ? servers.join(',') : '9.9.9.9,149.112.112.112';
  }

  bool _isPublicIpv4Literal(String value) {
    final parsed = _ipv4LiteralToInt(value);
    if (parsed == null) return false;
    final first = (parsed >> 24) & 0xff;
    final second = (parsed >> 16) & 0xff;
    if (first == 10 || first == 127 || first == 0) return false;
    if (first == 100 && second >= 64 && second <= 127) return false;
    if (first == 169 && second == 254) return false;
    if (first == 172 && second >= 16 && second <= 31) return false;
    if (first == 192 && second == 168) return false;
    if (first >= 224) return false;
    return true;
  }

  int? _ipv4LiteralToInt(String value) {
    final parts = value.trim().split('.');
    if (parts.length != 4) return null;
    var result = 0;
    for (final part in parts) {
      if (part.isEmpty || !RegExp(r'^\d{1,3}$').hasMatch(part)) return null;
      final octet = int.tryParse(part);
      if (octet == null || octet < 0 || octet > 255) return null;
      result = (result << 8) | octet;
    }
    return result;
  }

  String _windowsTunnelGatewayIpv4(Map<String, dynamic> config) {
    final explicit =
        (config['tunnel_gateway_ipv4'] ?? config['tunnelgatewayipv4'] ?? '')
            .toString()
            .trim();
    final parsed = _ipv4LiteralToInt(explicit);
    if (parsed == null) {
      throw StateError('Windows per-app routing has no valid tunnel gateway.');
    }
    final first = (parsed >> 24) & 0xff;
    final second = (parsed >> 16) & 0xff;
    final last = parsed & 0xff;
    final isRfc1918 = first == 10 ||
        (first == 172 && second >= 16 && second <= 31) ||
        (first == 192 && second == 168);
    if (!isRfc1918 || last == 0 || last == 255) {
      throw StateError('Windows per-app routing has no valid tunnel gateway.');
    }
    return explicit;
  }

  String _buildRawAmneziaConfig(
    Map<String, dynamic> config, {
    Winn3DescriptorCheck? winn3Descriptor,
  }) {
    // SECOND ANTI-DOWNGRADE GATE, and deliberately not a duplicate of the one
    // in _startTunnelCandidate. This is the only function that turns a served
    // config into the string the native tunnel actually starts from, so a
    // winn/3 config cannot become a plain AmneziaWG start even if the dispatch
    // seam above were removed, reordered, or bypassed by a new call site. The
    // seam decides gracefully; winnSectionForTunnelConfig throws. Its refusal
    // must not be caught or defaulted to '' here -- '' is precisely what
    // VpnTunnelService reads as "start plain AmneziaWG".
    final winnSection = winnSectionForTunnelConfig(
      operatingSystem: Platform.operatingSystem,
      config: config,
      // Passed through from the caller, which verified it against THIS
      // candidate's config. Deliberately not re-derived here: verification is
      // asynchronous and this function is not, and a synchronous "verify"
      // would either have to block or have to skip -- and skipping is how a
      // standalone session ends up trusting an unverified gateway record.
      // Null makes a standalone config throw, which is the fail-closed
      // behaviour this whole gate exists for.
      winn3Descriptor: winn3Descriptor,
    );
    final obfs = config['obfuscation'] is Map
        ? Map<String, dynamic>.from(config['obfuscation'])
        : <String, dynamic>{};
    final xray = config['xray'] is Map
        ? Map<String, dynamic>.from(config['xray'])
        : <String, dynamic>{};
    final bool stealthActive = _boolValue(config['stealth_active']);
    final int mtu = int.tryParse(config['mtu'].toString()) ?? _directAwgMtu;
    final dnsServers = _nativeTunnelDnsServers(config);
    final int xrayLocalPort =
        int.tryParse((xray['local_port'] ?? '42110').toString()) ?? 42110;
    // THE ONE FIELD BOTH RELAYS WANT, and the reason they were called mutually
    // exclusive. v1 stealth points it at the Xray inbound. A winn/3 session
    // points it at the real gateway and lets the native host rewrite it to the
    // Winn seam at start (VpnTunnelService, WinsPacketTunnelEngine,
    // RewriteAwgPeerEndpointToSeam) -- so in the STACKED arrangement it must
    // take the winn/3 form, not the stealth one. The Xray inbound is still
    // reached, one hop later, as the Winn engine's own gateway endpoint.
    // Emitting the stealth form here instead would put AmneziaWG straight onto
    // Xray and leave the Winn engine with nothing to carry: a v1 session
    // wearing a v3 label, which is the downgrade the refusals exist to stop.
    final bool stealthChain = winnConfigUsesStealthChain(config);
    // A bound ciphertext relay (w3r/1) moves the carrier to the Core: keep the
    // peer address equal to the dialled `[winn] endpoint` host so route
    // exclusions stay on the address the session really uses. The binding was
    // enforced by winnSectionForTunnelConfig above, which throws on a refusal.
    final String? relayPeerEndpoint =
        stealthActive ? null : readWinn3ServedRelay(config).relay?.endpoint;
    final String peerEndpoint = stealthActive && !stealthChain
        ? '127.0.0.1:$xrayLocalPort'
        : relayPeerEndpoint ?? config['server_endpoint'].toString();
    final String presharedKey = (config['preshared_key'] ?? '').toString();
    final String presharedKeyLine =
        presharedKey.isNotEmpty ? 'PresharedKey = $presharedKey' : '';
    final String xraySection = stealthActive
        ? """
[Xray]
Enabled = true
Uuid = ${xray['uuid']}
Host = ${xray['host']}
Port = ${xray['port']}
ServerName = ${xray['server_name']}
Path = ${xray['path']}
Security = ${xray['security']}
LocalPort = $xrayLocalPort
RemoteAwgHost = ${xray['remote_awg_host']}
RemoteAwgPort = ${xray['remote_awg_port']}
"""
        : "";
    final String debugSection = """
[WinsDebug]
ClientPublicKey = ${config['client_public_key'] ?? ''}
""";
    final selectedPackages = (Platform.isWindows
            ? const <String>[]
            : _excludedVpnPackages)
        .map((packageName) => packageName.trim())
        .where((packageName) => packageName.isNotEmpty)
        .toSet()
        .toList()
      ..sort();
    final windowsManualRouting =
        Platform.isWindows && windowsRequiresManualTunnelRoutes();
    final peerHost = _hostnameOnly(peerEndpoint);
    final windowsPeerBypassCidrs =
        Platform.isWindows && _isPublicIpv4Literal(peerHost)
            ? <String>['$peerHost/32']
            : const <String>[];
    final windowsCarrierBypassCidrs = Platform.isWindows && stealthActive
        ? _stringListValue(config['windows_transport_bypass_ipv4'])
            .where((address) => _ipv4LiteralToInt(address) != null)
            .map((address) => '$address/32')
            .toList()
        : const <String>[];
    final allowedIpv4Routes = allowedIpv4CidrsExcluding(<String>[
      ..._excludedVpnCidrs,
      ...windowsPeerBypassCidrs,
      ...windowsCarrierBypassCidrs,
    ]);
    if (allowedIpv4Routes.isEmpty) {
      throw StateError('Split tunneling cannot exclude the entire IPv4 space.');
    }
    if (allowedIpv4Routes.length > 256) {
      throw StateError(
          'Split tunneling produced too many routes. Use broader destination ranges.');
    }
    final allowedIpRoutes = windowsManualRouting
        ? windowsPerAppAllowedIpCidrs(allowedIpv4Routes)
        : <String>[...allowedIpv4Routes, '::/0'];
    final tableLine = windowsManualRouting ? 'Table = off' : '';
    final windowsTunnelGatewayLine = windowsManualRouting
        ? 'TunnelGatewayIPv4 = ${_windowsTunnelGatewayIpv4(config)}'
        : '';
    // CONNECT TIME: WireGuard retries a lost handshake after a fixed 5 s
    // (RekeyTimeout), so one lost initiation or response pushes a connect past
    // the 4 s target. Measured in the L30 lab (2026-09-24, pinned
    // amneziawg-go v3.1.20260828 on both ends, 100 cold connects per cell,
    // seeded netem): at 10% loss 22% of default connects exceeded 4 s against
    // 2% with RekeyTimeout = 3 (max 9.4 s); on fades 9% against 3% (max 6.3 s).
    // RekeyTimeout = 2 stopped completing handshakes from 2.2 s RTT, while 3
    // still connects at 3.0 s RTT. Both keys are client-only in AmneziaWG 3,
    // so no gateway parity is involved.
    // MaxHandshakeAttempts = 30 keeps WireGuard's 90 s give-up window
    // (18 x 5 s) at the 3 s interval (30 x 3 s). Android only: the Android
    // UAPI converters (AwgUserspaceConfig.kt, tools/amneziawg_android_official_jni)
    // map both keys, while the Windows and Linux INI allowlists and the Apple
    // parser do not know them and would refuse the whole config.
    final String awgHandshakeTimingLines =
        Platform.isAndroid ? 'RekeyTimeout = 3\nMaxHandshakeAttempts = 30' : '';
    // Android only: the route this config really has, so the service can tell
    // a single-hop config from a Double VPN one when the SYSTEM restarts it
    // later. Only the two known values are ever written. Every other platform
    // writes exactly the section it always did.
    final String doubleVpnRouteLine = Platform.isAndroid &&
            (config['double_vpn_route'] == doubleVpnRouteTwoHop ||
                config['double_vpn_route'] == doubleVpnRouteSingleHop)
        ? '\nDoubleVpnRoute = ${config['double_vpn_route']}'
        : '';
    final String appSection = """
[WinsApp]
ExcludedPackages = ${selectedPackages.join(',')}
ExcludedPathsB64 = ${base64Encode(utf8.encode(selectedPackages.join('\n')))}
$windowsTunnelGatewayLine$doubleVpnRouteLine
""";

    return """
[Interface]
PrivateKey = ${config['client_private_key']}
Address = ${config['client_ip']}/32
$tableLine
MTU = $mtu
DNS = $dnsServers
Jc = ${obfs['Jc'] ?? _defaultAwgJc}
Jmin = ${obfs['Jmin'] ?? _defaultAwgJmin}
Jmax = ${obfs['Jmax'] ?? _defaultAwgJmax}
S1 = ${obfs['S1'] ?? 16}
S2 = ${obfs['S2'] ?? 80}
S3 = ${obfs['S3'] ?? 16}
S4 = ${obfs['S4'] ?? 0}
H1 = ${obfs['H1'] ?? 11}
H2 = ${obfs['H2'] ?? 22}
H3 = ${obfs['H3'] ?? 33}
H4 = ${obfs['H4'] ?? 44}
$awgHandshakeTimingLines

[Peer]
PublicKey = ${config['server_public_key']}
$presharedKeyLine
Endpoint = $peerEndpoint
AllowedIPs = ${allowedIpRoutes.join(', ')}
PersistentKeepalive = 25

$xraySection
$debugSection
$appSection
$winnSection
"""
        .split('\n')
        .map((line) => line.trim())
        .where((line) => line.isNotEmpty)
        .join('\n');
  }

  String _currentSelectedSlug() {
    if (_locations.isNotEmpty &&
        _selectedLocationIndex >= 0 &&
        _selectedLocationIndex < _locations.length) {
      return (_locations[_selectedLocationIndex]['slug'] ?? 'auto').toString();
    }
    // An unlisted manual choice is requested as itself: the hub refuses a
    // closed node instead of the app dialling whichever row sorts first.
    if (_manualSelectionUnlisted) {
      return (_unlistedSelection!['slug'] ?? 'auto').toString();
    }
    return 'auto';
  }

  String _requestedLocationSlug() => nodeLocationForRequest(
        automatic: _automaticNodeSelection,
        displayedNodeSlug: _currentSelectedSlug(),
        exactCoverTargetSlug: _winn3CoverExactTargetSlug,
      );

  int _firstFreeLocationIndex() {
    return _locations.indexWhere(_isFreeNode);
  }

  Map<String, dynamic>? _selectedFreeLocation() {
    if (_locations.isEmpty) return null;
    if (_selectedLocationIndex >= 0 &&
        _selectedLocationIndex < _locations.length &&
        _isFreeNode(_locations[_selectedLocationIndex])) {
      return _locations[_selectedLocationIndex];
    }
    final freeIndex = _firstFreeLocationIndex();
    return freeIndex >= 0 ? _locations[freeIndex] : null;
  }

  bool _selectedSlugIsVisible({bool freeOnly = false}) {
    final selectedSlug = _currentSelectedSlug().trim();
    if (selectedSlug.isEmpty || selectedSlug == 'auto') return true;
    return _locations.any((node) {
      final slug = (node['slug'] ?? '').toString().trim();
      if (slug != selectedSlug) return false;
      return !freeOnly || _isFreeNode(node);
    });
  }

  void _selectFirstUsableNode({bool freeOnly = false}) {
    // Never replace an unlisted manual choice with a row the user did not pick.
    if (_manualSelectionUnlisted) return;
    final nextIndex =
        freeOnly ? _firstFreeLocationIndex() : (_locations.isEmpty ? -1 : 0);
    if (nextIndex >= 0 && nextIndex < _locations.length) {
      _selectedLocationIndex = nextIndex;
    }
  }

  bool _cachedConfigMatchesCurrentSelection(Map<String, dynamic> config) {
    final cachedProtocol = strictWinnProtocolVersion(config);
    if (cachedProtocol != null &&
        cachedProtocol != _userSelectedProtocolVersion) {
      return false;
    }
    final cachedSlug = (config['node_slug'] ?? '').toString().trim();
    if (cachedSlug.isEmpty) return true;
    if (_automaticNodeSelection) return true;
    final selectedSlug = _currentSelectedSlug().trim();
    return selectedSlug.isEmpty ||
        selectedSlug == 'auto' ||
        selectedSlug == cachedSlug;
  }

  Map<String, dynamic>? _cachedDirectConfigForFastConnect() {
    if (_cachedVpnConfig.isEmpty) return null;
    final directConfig =
        _configForTransport(_cachedVpnConfig, stealthMode: false);
    if (!_hasUsableVpnConfig(directConfig)) return null;
    if (!_cachedConfigMatchesCurrentSelection(directConfig)) return null;
    return directConfig;
  }

  Map<String, dynamic>? _protocolListingNodeForConfig(
    Map<String, dynamic>? config,
  ) {
    final cachedSlug = VpnConfigValidator.persistedNodeSlug(config);
    return listingNodeForSlug(
      _locations,
      cachedSlug.isNotEmpty ? cachedSlug : _currentSelectedSlug(),
    );
  }

  String _selectedWallpaperLandmarkKey() {
    final Map<String, dynamic>? location = (_locations.isNotEmpty &&
            _selectedLocationIndex >= 0 &&
            _selectedLocationIndex < _locations.length)
        ? _locations[_selectedLocationIndex]
        : null;
    if (!_isConnected && _preVpnCountryCode.trim().isNotEmpty) {
      return _countryCodeToLandmarkKey(_preVpnCountryCode);
    }
    final label =
        '${location?['slug'] ?? ''} ${location?['name'] ?? ''}'.toLowerCase();
    if (label.contains('france') || label.contains('paris')) return 'france';
    if (label.contains('los-angeles') ||
        label.contains('los angeles') ||
        label.contains('california')) {
      return 'los_angeles';
    }
    if (label.contains('new-york') ||
        label.contains('new york') ||
        label.contains('nyc') ||
        label.contains('manhattan')) {
      return 'new_york';
    }
    if (label.contains('chicago')) return 'chicago';
    if (label.contains('oregon') || label.contains('portland')) return 'oregon';
    if (label.contains('singapore')) return 'singapore';
    if (label.contains('london') ||
        label.contains('united kingdom') ||
        label.contains('united-kingdom') ||
        label.contains(' uk ') ||
        label.contains('uk-')) {
      return 'london';
    }
    if (label.contains('japan') || label.contains('tokyo')) return 'japan';
    if (label.contains('korea') || label.contains('seoul')) return 'korea';
    if (label.contains('germany') || label.contains('berlin')) {
      return 'germany';
    }
    if (label.contains('netherlands') || label.contains('amsterdam')) {
      return 'netherlands';
    }
    if (label.contains('canada') || label.contains('toronto')) return 'canada';
    if (label.contains('australia') || label.contains('sydney')) {
      return 'australia';
    }
    if (label.contains('usa') || label.contains('united-states')) return 'usa';
    return _worldDefaultLandmarkKey(label);
  }

  String _countryCodeToLandmarkKey(String countryCode) {
    switch (countryCode.trim().toUpperCase()) {
      case 'US':
        return 'usa';
      case 'GB':
      case 'UK':
        return 'london';
      case 'FR':
        return 'france';
      case 'SG':
        return 'singapore';
      case 'JP':
        return 'japan';
      case 'KR':
        return 'korea';
      case 'AU':
        return 'australia';
      case 'DE':
        return 'germany';
      case 'CA':
        return 'canada';
      default:
        return 'global';
    }
  }

  bool _labelHasAny(String label, List<String> terms) {
    final normalized = label.replaceAll(RegExp(r'[-_]'), ' ');
    return terms.any((term) => normalized.contains(term));
  }

