  Future<void> _loadCachedVpnConfigFromDisk() async {
    try {
      final String? encoded;
      if (_isApplePlatform) {
        encoded = await _readEncodedVpnConfigOnApple();
      } else {
        encoded = await _readSensitiveText('vpn_config.txt');
      }
      if (encoded != null) {
        final decoded = jsonDecode(encoded);
        if (decoded is Map) {
          _cachedVpnConfig =
              _normalizeVpnConfig(Map<String, dynamic>.from(decoded));
        }
      }
    } catch (e) {
      _debugLog('Config restore failed: $e');
    }
  }

  Future<String> _currentAccountNumberForRefresh() async {
    final typed = _accountController.text.trim();
    if (typed.replaceAll('-', '').length == 12) return typed;

    try {
      final decoded = await _readVpnRuntimeSettings();
      final saved = (decoded['account_number'] ?? '').toString().trim();
      if (saved.replaceAll('-', '').length == 12) {
        _accountController.text = saved;
        return saved;
      }
    } catch (e) {
      _debugLog('Saved account number restore failed: $e');
    }

    return '';
  }

  // The identifier every _loadOrCreateClientKeyPair call site must agree on
  // for "which account is this session acting as right now", so a device
  // handoff between accounts (free access <-> paid, or paid -> a different
  // paid account) can never reuse another account's WireGuard key.
  Future<String> _effectiveAccountScopeForKeyPair() async {
    if (_isFreeAccessSession) return _freeAccessAccountNumber;
    return _currentAccountNumberForRefresh();
  }

  @override
  void initState() {
    super.initState();
    _showDecoyCalculator = calculatorCoversFirstFrame(
      Platform.operatingSystem,
      _globalIsAndroidTv ? DeviceFormFactor.tv : DeviceFormFactor.phone,
    );
    _accountCleanupStartupBarrier = AccountCleanupStartupBarrier(
      journalExists: _accountCleanupJournalExists,
      attemptCleanup: _attemptPendingAccountCleanup,
      onPending: _forcePendingAccountCleanupUi,
      onCompleted: _completePendingAccountCleanup,
      onRetryCompleted: _continueStartupAfterCleanupRetry,
    );
    WidgetsBinding.instance.addObserver(this);
    WatchBridge.instance.attach(_handleWatchCommand);
    _startBrowserBridgeAppIpc();
    unawaited(_refreshFormFactor());
    WidgetsBinding.instance.addPostFrameCallback((_) async {
      if (!mounted) return;
      // LOCAL-STATE RESET, compile-time gated and OFF by default.
      //
      // WHY THIS EXISTS. On Apple platforms the sensitive state lives in the
      // Keychain, and Keychain items deliberately SURVIVE app deletion. The
      // camouflage decoy arms whenever a session exists, and dismissing it
      // requires the 4-digit PIN. So a user who forgets that PIN sees only a
      // calculator, and reinstalling the app does NOT clear it -- verified on a
      // real device 2026-08-05: full uninstall + clean reinstall still came up
      // showing the decoy. Without a reset the install is permanently unusable,
      // and by design the decoy hides that anything is wrong.
      //
      // This wipes only THIS app's own sensitive names, nothing else in the
      // Keychain. It exists only in debug mode and must be asked for:
      //   flutter run --debug --dart-define=WINS_RESET_LOCAL_STATE=true
      //
      // This is a recovery tool, not the product fix. A discoverable,
      // camouflage-preserving reset path is still needed -- see the handoff.
      const resetLocalState = kDebugMode &&
          bool.fromEnvironment('WINS_RESET_LOCAL_STATE', defaultValue: false);
      if (resetLocalState) {
        for (final name in _sensitiveStateFileNames) {
          try {
            await _deleteSensitiveText(name);
            _debugLog('WINS_RESET_LOCAL_STATE: cleared $name');
          } catch (e) {
            _debugLog('WINS_RESET_LOCAL_STATE: could not clear $name: $e');
          }
        }
      }
      if (mounted) {
        unawaited(_initializeLocalSecurityThenPrivacyConsent());
      }
    });
  }

  void _startBrowserBridgeAppIpc() {
    if (!browserBridgeAppIpcSupportedOn(Platform.operatingSystem)) return;

    final pairing = BrowserBridgePairingRegistry(
      prompt: _confirmBrowserBridgePairing,
      available: _browserBridgePairingAvailable,
      persist: _persistBrowserBridgePairings,
    );
    final BrowserBridgeAppIpcServer server;
    try {
      server = BrowserBridgeAppIpcServer(
        snapshot: _browserBridgeSnapshot,
        onCommand: _handleBrowserBridgeAppIpcCommand,
        pairing: pairing,
      );
    } catch (_) {
      _debugLog('browser bridge app ipc discovery unavailable');
      return;
    }

    _browserBridgeIpc = server;
    _browserBridgePairing = pairing;
    unawaited(() async {
      try {
        // Load before listening, so a paired browser is never refused just
        // because the store had not been read yet.
        final file = await _browserBridgePairingStoreFile();
        pairing.replaceRecords(await readBrowserBridgePairingStore(file));
        if (mounted) setState(() {});
      } catch (_) {
        _debugLog('browser bridge pairing store unavailable');
      }
      try {
        await server.start();
      } catch (_) {
        _debugLog('browser bridge app ipc failed to start');
        if (identical(_browserBridgeIpc, server)) {
          _browserBridgeIpc = null;
        }
      }
    }());
  }

  /// Pairings are a local grant to control this device's VPN. Logout, a
  /// local reset and a duress wipe leave none behind. revokeAll() clears
  /// memory before it writes, so a failed write still stops control now.
  Future<void> _revokeBrowserBridgePairings(String why) async {
    try {
      await _browserBridgePairing?.revokeAll();
    } catch (_) {
      _debugLog('browser pairings could not be persisted as revoked ($why)');
    }
  }

  Future<File> _browserBridgePairingStoreFile() async {
    final directory = await _appDocumentsDirectory();
    return File('${directory.path}/$kBrowserBridgePairingStoreFileName');
  }

  Future<void> _persistBrowserBridgePairings(
    List<BrowserBridgePairingRecord> records,
  ) async {
    await writeBrowserBridgePairingStore(
      await _browserBridgePairingStoreFile(),
      records,
    );
    if (mounted) setState(() {});
  }

  /// The app asks only when it is unlocked and showing its own UI: never over
  /// the decoy, never logged out, never during a local reset.
  bool _browserBridgePairingAvailable() {
    return mounted &&
        !_showDecoyCalculator &&
        !_accountResetRequiresRestart &&
        (_isLoggedIn || _isFreeAccessSession);
  }

  Future<bool> _confirmBrowserBridgePairing(
    BrowserBridgePairingRequest request,
  ) async {
    if (!_browserBridgePairingAvailable()) return false;
    final account = _accountSessionEpoch.current;
    final approved = await confirmBrowserBridgePairing(
      context,
      request,
      t: _t,
    );
    // An approval that outlived the session it was given in is not one.
    return approved &&
        _browserBridgePairingAvailable() &&
        account == _accountSessionEpoch.current;
  }

  /// Tunnel state as the native-messaging host is allowed to see it.
  ///
  /// Derived from the same fields the on-screen power button and the watch
  /// read, so the three surfaces cannot disagree. The host overlays its own
  /// proxy port; this snapshot never names one.
  BridgeStatus _browserBridgeSnapshot() {
    final locked =
        _showDecoyCalculator || (!_isLoggedIn && !_isFreeAccessSession);
    final BridgeTunnelStatus status;
    if (_lastAppleTunnelNeedsPermissionApproval || _androidNeedsVpnPermission) {
      status = BridgeTunnelStatus.permissionRequired;
    } else if (_isLoading) {
      status = _isVpnConnectInFlight
          ? BridgeTunnelStatus.connecting
          : BridgeTunnelStatus.disconnecting;
    } else if (_rendersConnected) {
      status = BridgeTunnelStatus.connected;
    } else {
      status = BridgeTunnelStatus.disconnected;
    }
    final BridgeDetailCode detail;
    if (status == BridgeTunnelStatus.permissionRequired) {
      detail = BridgeDetailCode.permissionRequired;
    } else if (locked && status != BridgeTunnelStatus.connected) {
      detail = BridgeDetailCode.refusedByApp;
    } else {
      detail = BridgeDetailCode.none;
    }
    final selected = _currentSelectedSlug().trim();
    return BridgeStatus(
      status: status,
      detail: detail,
      winn: _browserBridgeWinnState(status),
      selectedSlug:
          locked ? '' : (kSlugPattern.hasMatch(selected) ? selected : ''),
      nodes: locked ? const <BridgeNode>[] : _browserBridgeNodes(),
      // The IPC server offers control only to a paired caller
      // (BridgeStatus.copyWithPairing); unpaired callers see false.
      canRequestConnect: !locked,
      proxyPort: 0,
      proxyReady: status.isCarryingTraffic,
    );
  }

  BridgeWinnState _browserBridgeWinnState(BridgeTunnelStatus status) {
    if (!platformSupportsWinnProtocol(Platform.operatingSystem)) {
      return BridgeWinnState.unavailableOnThisPlatform;
    }
    if (status.isCarryingTraffic && _activeProtocolVersion.trim() == 'winn/3') {
      return BridgeWinnState.inUse;
    }
    return BridgeWinnState.availableNotInUse;
  }

  List<BridgeNode> _browserBridgeNodes() {
    final nodes = <BridgeNode>[];
    for (final location in _locations) {
      if (nodes.length >= kBrowserBridgeAppIpcMaxNodes) break;
      try {
        nodes.add(
          BridgeNode(
            slug: (location['slug'] ?? '').toString().trim(),
            name: (location['name'] ?? '').toString().trim(),
            flag: (location['flag'] ?? '').toString().trim(),
          ),
        );
      } catch (_) {}
    }
    return nodes;
  }

  /// Same path the watch uses: existing tunnel controls, never a second client.
  ///
  /// Reached only for a paired browser (the IPC server refuses the rest).
  /// The app says so on screen, so a browser-initiated change is never silent.
  Future<void> _handleBrowserBridgeAppIpcCommand(
    BrowserBridgeAppIpcCommand command,
  ) async {
    switch (command) {
      case BrowserBridgeAppIpcCommand.requestConnect:
        _noteBrowserBridgeControl(_t('A paired browser asked to connect.'));
        await _handleWatchCommand(WatchCommand.connect, '');
      case BrowserBridgeAppIpcCommand.requestDisconnect:
        _noteBrowserBridgeControl(
          _t('A paired browser disconnected the VPN and turned off the kill switch.'),
        );
        await _handleWatchCommand(WatchCommand.disconnect, '');
      case BrowserBridgeAppIpcCommand.getStatus:
      case BrowserBridgeAppIpcCommand.pairBegin:
      case BrowserBridgeAppIpcCommand.pairPoll:
      case BrowserBridgeAppIpcCommand.pairRevoke:
        break;
    }
  }

  void _noteBrowserBridgeControl(String message) {
    // _showFeedback itself never shows anything over the decoy.
    if (!mounted) return;
    _showFeedback(message);
  }

  /// Companion-watch commands.
  ///
  /// Every branch routes into the same methods the on-screen controls use, so
  /// the watch can never take a shortcut past a gate the phone UI enforces
  /// (force-update, maintenance, legal acceptance, VPN consent). The watch is a
  /// second finger on the existing buttons, not a second client.
  Future<void> _handleWatchCommand(WatchCommand command, String slug) async {
    if (!mounted) return;

    // Stopping a tunnel is always allowed, deliberately: a user who needs the
    // VPN off in a hurry must be able to do it from the wrist even while the
    // phone is locked behind the decoy. Nothing is revealed by stopping.
    if (command == WatchCommand.disconnect) {
      if (!_isConnected && !_isLoading) return;
      await _toggleVpnConnection();
      return;
    }

    // Starting a tunnel or switching server is not allowed to route around the
    // local PIN gate. While the decoy is showing, the user has not
    // authenticated on the phone, and a watch tap must not stand in for that.
    if (_showDecoyCalculator) return;
    if (!_isLoggedIn && !_isFreeAccessSession) return;

    switch (command) {
      case WatchCommand.connect:
        if (_isConnected || _isLoading) return;
        await _toggleVpnConnection();
      case WatchCommand.disconnect:
        break;
      case WatchCommand.selectCountry:
        await _selectWatchCountry(slug);
    }
  }

  /// The phone's own country-picker tap handler, for a listed row.
  Future<void> _selectWatchCountry(String slug) async {
    final normalized = slug.trim();
    if (normalized.isEmpty) return;
    final index = _locations.indexWhere(
        (location) => (location['slug'] ?? '').toString() == normalized);
    if (index < 0) return;
    if (_isLoading) return;
    await _onServerRowTapped(Map<String, dynamic>.from(_locations[index]));
  }

  /// State as the watch should see it, derived from the same fields the
  /// on-screen power button reads so the two can never disagree.
  void _publishWatchState() {
    final WatchTunnelStatus status;
    if (_lastAppleTunnelNeedsPermissionApproval || _androidNeedsVpnPermission) {
      status = WatchTunnelStatus.permissionRequired;
    } else if (_isLoading) {
      status = _isVpnConnectInFlight
          ? WatchTunnelStatus.connecting
          : WatchTunnelStatus.disconnecting;
    } else if (_rendersConnected) {
      status = WatchTunnelStatus.connected;
    } else {
      status = WatchTunnelStatus.disconnected;
    }

    // While the decoy is engaged the phone is, to the user, a calculator. Do
    // not hand a paired watch a server list and a live "Connected to Japan"
    // readout that the phone itself is deliberately hiding. The empty list
    // makes the watch render "Open Win's VPN on phone" and disables connect and
    // country switching, while leaving disconnect available.
    final locked =
        _showDecoyCalculator || (!_isLoggedIn && !_isFreeAccessSession);

    WatchBridge.instance.publish(
      status: status,
      selectedSlug: locked ? '' : _watchSelectedSlug(),
      locations: locked ? const <Map<String, dynamic>>[] : _locations,
      canConnect: !locked,
    );
  }

  Future<void> _loadInstalledAppsForSplitTunnel() async {
    if (!_supportsPerAppSplitTunneling) return;
    if (_appsLoading) return;
    if (mounted) setState(() => _appsLoading = true);
    final timeoutCompleter = Completer<dynamic>();
    final timeoutTimer = Timer(const Duration(seconds: 5), () {
      timeoutCompleter.completeError(
        TimeoutException('Installed-app enumeration timed out.'),
      );
    });
    _installedAppsLoadTimeoutTimer?.cancel();
    _installedAppsLoadTimeoutTimer = timeoutTimer;
    try {
      final response = await Future.any<dynamic>([
        _methodChannel.invokeMethod<dynamic>('getInstalledApps'),
        timeoutCompleter.future,
      ]);
      if (response is! List) return;
      final apps = response
          .whereType<Map>()
          .map((item) => Map<String, dynamic>.from(item))
          .where((item) =>
              (item['package_name'] ?? '').toString().trim().isNotEmpty)
          .take(512)
          .toList()
        ..sort((a, b) => (a['name'] ?? a['package_name'] ?? '')
            .toString()
            .toLowerCase()
            .compareTo((b['name'] ?? b['package_name'] ?? '')
                .toString()
                .toLowerCase()));
      if (mounted) setState(() => _installedApps = apps);
    } catch (e) {
      _debugLog('Split tunnel app list load failed: $e');
    } finally {
      timeoutTimer.cancel();
      if (identical(_installedAppsLoadTimeoutTimer, timeoutTimer)) {
        _installedAppsLoadTimeoutTimer = null;
      }
      if (mounted) setState(() => _appsLoading = false);
    }
  }

  Future<bool> _ensureAndroidPackageVisibilityConsent() {
    if (!Platform.isAndroid ||
        _androidPackageVisibilityConsentVersion ==
            _androidPackageVisibilityDisclosureVersion) {
      return Future<bool>.value(true);
    }
    final pending = _androidPackageVisibilityConsentRequest;
    if (pending != null) return pending;

    final request = _promptForAndroidPackageVisibilityConsent();
    _androidPackageVisibilityConsentRequest = request;
    return request.whenComplete(() {
      if (identical(_androidPackageVisibilityConsentRequest, request)) {
        _androidPackageVisibilityConsentRequest = null;
      }
    });
  }

  Future<bool> _promptForAndroidPackageVisibilityConsent() async {
    // Only a tap on the split-tunnel row asks. Never over the decoy, and no
    // consent is assumed: the answer is false and nothing is stored.
    if (!mounted || _showDecoyCalculator) return false;
    final accepted = await showDialog<bool>(
      context: context,
      barrierDismissible: false,
      builder: (dialogContext) => AlertDialog(
        backgroundColor: _surfacePanel,
        // Same fix as _showPrivacyPolicyDialog: showDialog renders above the
        // dashboard's local _lightSurfaceTheme wrap, so without explicit
        // colors here this text falls back to the app-wide dark theme's
        // light default color on top of this light _surfacePanel -- unreadable.
        titleTextStyle: const TextStyle(
          color: _surfaceText,
          fontSize: 20,
          fontWeight: FontWeight.w700,
        ),
        contentTextStyle: const TextStyle(color: _surfaceText),
        title: const Text('Installed app access'),
        content: const Text(
          "To show Exclude Apps From VPN, Win's VPN needs to access the list of installed apps on this device. The list is used only on your device to build the split-tunneling picker. The full list is not uploaded, shared, sold, or used for ads or analytics. Only package names you select for exclusion are stored locally and passed to Android VpnService. You can choose Not now and continue using the VPN without per-app exclusions.",
        ),
        actions: [
          TextButton(
            onPressed: () => _endOwnDialog<bool>(dialogContext, false),
            child: const Text('Not now'),
          ),
          ElevatedButton(
            onPressed: () => _endOwnDialog<bool>(dialogContext, true),
            child: const Text('Continue'),
          ),
        ],
      ),
    );
    if (accepted != true) return false;

    _androidPackageVisibilityConsentVersion =
        _androidPackageVisibilityDisclosureVersion;
    await _saveVpnRuntimeSettings(
      androidPackageVisibilityConsentVersion:
          _androidPackageVisibilityDisclosureVersion,
    );
    return true;
  }

  Future<void> _toggleSplitTunnelPanel() async {
    if (_splitTunnelExpanded) {
      if (mounted) setState(() => _splitTunnelExpanded = false);
      return;
    }
    if (!await _ensureAndroidPackageVisibilityConsent() || !mounted) return;

    setState(() => _splitTunnelExpanded = true);
    if (_visibleSplitTunnelApps().isEmpty && !_appsLoading) {
      unawaited(_loadInstalledAppsForSplitTunnel());
    }
    _bringSplitTunnelPanelIntoView();
  }

  bool get _supportsPerAppSplitTunneling =>
      Platform.isAndroid || Platform.isLinux;

  /// Whether this device holds a provisioned Winn SPA knock key.
  ///
  /// ALWAYS FALSE TODAY, and deliberately so rather than optimistically true.
  /// Nothing in this app, on any platform, writes the knock key file
  /// (`kWinnSpaKeyCredentialFileName`) that a carrier profile's `spa_key_path`
  /// names. The key is a deployment-scoped shared secret the owner distributes
  /// out of band, and no delivery path for it exists yet -- see
  /// `docs/handoff/WINN_SPA_CLIENT_EMITTERS_AND_MIGRATION_20260805.md`.
  ///
  /// THIS IS THE ONE PLACE THAT CHANGES when provisioning lands. It must become
  /// a real check that the key is present on THIS device -- a method-channel
  /// call into each native host, which is the only layer that can see its own
  /// credential directory -- and it must never become a build flag or a version
  /// comparison. Reporting a capability the device cannot actually perform is
  /// how this feature would come to "report success while carrying nothing":
  /// the control plane would serve `spa_*`, the profile would name a key file
  /// that is not there, and every connection would fail.
  bool get _winnSpaKeyProvisioned => false;

  /// The `supports_*` flags this device may honestly advertise for Winn
  /// Protocol v3. Derived from device state, never from a build flag.
  Map<String, bool> get _winnCapabilityFlags {
    final flags = Map<String, bool>.from(winnClientCapabilities(
      operatingSystem: Platform.operatingSystem,
      spaKeyProvisioned: _winnSpaKeyProvisioned,
    ));
    if (_userSelectedProtocolVersion == kWinnProtocolV1) {
      flags['supports_winn3'] = false;
    }
    // The relay Double capability joins only for a build whose relay define
    // names this platform; for every other build the map is unchanged. It
    // follows supports_winn3, so a user pinned to winn/1 never advertises it.
    flags.addAll(winnClientRelayCapabilityFlags(
      operatingSystem: Platform.operatingSystem,
      supportsWinn3: flags['supports_winn3'] == true,
      supportsWinn3Descriptor: flags['supports_winn3_descriptor'] == true,
      suppressed: winn3RelaySuppressed(
        until: _winn3RelaySuppressedUntil,
        now: DateTime.now(),
      ),
    ));
    return flags;
  }

  String get _perAppSplitTunnelPlatformName {
    if (Platform.isWindows) return 'Windows apps';
    if (Platform.isLinux) return 'Linux apps';
    return 'Android apps';
  }

  String get _unsupportedPerAppSplitTunnelMessage {
    if (_isApplePlatform) {
      return 'Destination-based split tunneling is available. Apple permits per-app VPN only for MDM-managed apps and profiles, so it is not presented as a consumer feature.';
    }
    return 'Destination-based split tunneling is available on this operating system.';
  }

  Future<void> _launchLinuxSplitTunnelApp(String desktopFile) async {
    if (!Platform.isLinux) return;
    if (!_excludedVpnPackages.contains(desktopFile)) {
      _showFeedback('Select this app for bypass before launching it.');
      return;
    }
    if (!_isConnected) {
      _showFeedback(
          "Connect Win's VPN first, then launch the selected Linux app outside the VPN.");
      return;
    }
    try {
      await _methodChannel.invokeMethod<dynamic>(
        'launchSplitTunnelApp',
        <String, dynamic>{'package_name': desktopFile},
      );
      _showFeedback('Linux app launched outside the VPN.');
    } on PlatformException catch (e) {
      _showFeedback(e.message ?? 'The Linux app could not be launched.');
    } catch (_) {
      _showFeedback('The Linux app could not be launched.');
    }
  }

  Future<void> _setExcludedVpnPackage(String packageName, bool excluded) async {
    final normalized = packageName.trim();
    if (normalized.isEmpty) return;
    if (_isConnected) {
      final action =
          excluded ? 'excluding apps from the VPN' : 'changing excluded apps';
      _showFeedback(
          'Please disconnect the VPN first before $action. Split Tunneling was not changed.');
      return;
    }
    setState(() {
      if (excluded) {
        _excludedVpnPackages.add(normalized);
      } else {
        _excludedVpnPackages.remove(normalized);
      }
    });
    await _saveVpnRuntimeSettings();
  }

  Future<void> _setAllSplitTunnelAppsExcluded(bool excluded) async {
    if (_isConnected) {
      _showFeedback(
          'Please disconnect the VPN first before changing excluded apps. Split Tunneling was not changed.');
      return;
    }
    final packageNames = _installedApps
        .map((app) => (app['package_name'] ?? '').toString().trim())
        .where((packageName) => packageName.isNotEmpty)
        .toSet();
    if (packageNames.isEmpty) return;
    setState(() {
      if (excluded) {
        _excludedVpnPackages.addAll(packageNames);
      } else {
        _excludedVpnPackages.removeAll(packageNames);
      }
    });
    await _saveVpnRuntimeSettings();
  }

  Future<void> _applySplitTunnelRoutes() async {
    if (_isConnected) {
      _showFeedback(
          'Please disconnect the VPN first before changing bypass destinations. Split Tunneling was not changed.');
      return;
    }
    try {
      final requested = _splitTunnelRoutesController.text
          .split(RegExp(r'[\s,;]+'))
          .map((value) => value.trim())
          .where((value) => value.isNotEmpty);
      final normalized = normalizeExcludedIpv4Cidrs(requested);
      if (normalized.length > 64) {
        throw const FormatException(
            'Use no more than 64 destination networks.');
      }
      final allowed = allowedIpv4CidrsExcluding(normalized);
      if (allowed.isEmpty) {
        throw const FormatException(
            '0.0.0.0/0 cannot be excluded because it would block the VPN.');
      }
      if (allowed.length > 256) {
        throw const FormatException(
            'Those exclusions produce too many routes; combine nearby networks.');
      }
      setState(() {
        _excludedVpnCidrs
          ..clear()
          ..addAll(normalized);
        _splitTunnelRoutesController.text = normalized.join(', ');
      });
      await _saveVpnRuntimeSettings();
      _showFeedback(normalized.isEmpty
          ? 'All IPv4 destinations will use the VPN.'
          : '${normalized.length} destination network${normalized.length == 1 ? '' : 's'} will bypass the VPN.');
    } on FormatException catch (e) {
      _showFeedback(e.message.toString());
    }
  }

  bool get _allInstalledAppsExcluded {
    final packageNames = _installedApps
        .map((app) => (app['package_name'] ?? '').toString().trim())
        .where((packageName) => packageName.isNotEmpty)
        .toList();
    return packageNames.isNotEmpty &&
        packageNames.every(_excludedVpnPackages.contains);
  }

  bool get _someInstalledAppsExcluded {
    return _installedApps.any((app) {
      final packageName = (app['package_name'] ?? '').toString().trim();
      return packageName.isNotEmpty &&
          _excludedVpnPackages.contains(packageName);
    });
  }

  List<Map<String, dynamic>> _visibleSplitTunnelApps() {
    final query = _splitTunnelSearchQuery.trim().toLowerCase();
    final apps = _installedApps
        .where((app) {
          if (query.isEmpty) return true;
          final packageName =
              (app['package_name'] ?? '').toString().toLowerCase();
          final label = (app['name'] ?? packageName).toString().toLowerCase();
          return packageName.contains(query) || label.contains(query);
        })
        .map((app) => Map<String, dynamic>.from(app))
        .toList();

    apps.sort((a, b) {
      final aPackage = (a['package_name'] ?? '').toString();
      final bPackage = (b['package_name'] ?? '').toString();
      final aExcluded = _excludedVpnPackages.contains(aPackage);
      final bExcluded = _excludedVpnPackages.contains(bPackage);
      if (aExcluded != bExcluded) return aExcluded ? -1 : 1;
      final aLabel = (a['name'] ?? aPackage).toString().toLowerCase();
      final bLabel = (b['name'] ?? bPackage).toString().toLowerCase();
      return aLabel.compareTo(bLabel);
    });

    return apps;
  }

  String _splitTunnelSummaryText() {
    final appCount =
        _supportsPerAppSplitTunneling ? _excludedVpnPackages.length : 0;
    final routeCount = _excludedVpnCidrs.length;
    if (appCount == 0 && routeCount == 0) {
      return 'All traffic currently uses the VPN.';
    }
    final parts = <String>[];
    if (appCount > 0) {
      parts.add('$appCount app${appCount == 1 ? '' : 's'}');
    }
    if (routeCount > 0) {
      parts.add('$routeCount destination network${routeCount == 1 ? '' : 's'}');
    }
    return '${parts.join(' and ')} bypass the VPN.';
  }

  void _clearInputHighlights() {
    _inputHighlightTimer?.cancel();
    if (!mounted) return;
    if (_highlightAccountField ||
        _highlightPinField ||
        _highlightActivationSecretField ||
        _inputGuidanceMessage.isNotEmpty) {
      setState(() {
        _highlightAccountField = false;
        _highlightPinField = false;
        _highlightActivationSecretField = false;
        _inputGuidanceMessage = "";
      });
    }
  }

  void _clearInputGuidanceOnTyping() {
    if (!mounted || _inputGuidanceMessage.isEmpty) return;
    setState(() => _inputGuidanceMessage = "");
  }

  String? _accountGuidanceText() {
    if (!_highlightAccountField || _inputGuidanceMessage.isEmpty) return null;
    if (_highlightPinField) return 'Type the 12-digit Account Number here.';
    return _inputGuidanceMessage;
  }

  String? _pinGuidanceText() {
    if (!_highlightPinField || _inputGuidanceMessage.isEmpty) return null;
    if (_highlightAccountField) {
      return 'Set your $kCamouflagePinLength-digit PIN here.';
    }
    return _inputGuidanceMessage;
  }

  String? _activationSecretGuidanceText() {
    if (!_highlightActivationSecretField || _inputGuidanceMessage.isEmpty) {
      return null;
    }
    return _inputGuidanceMessage;
  }

  void _highlightInputField({
    bool account = false,
    bool pin = false,
    bool activationSecret = false,
  }) {
    _inputHighlightTimer?.cancel();
    if (!mounted) return;
    setState(() {
      _highlightAccountField = account;
      _highlightPinField = pin;
      _highlightActivationSecretField = activationSecret;
    });
    if (account) {
      _accountFocusNode.requestFocus();
    } else if (pin) {
      _pinFocusNode.requestFocus();
    } else if (activationSecret) {
      _activationSecretFocusNode.requestFocus();
    }
    _inputHighlightTimer = Timer(const Duration(seconds: 8), () {
      if (!mounted) return;
      setState(() {
        _highlightAccountField = false;
        _highlightPinField = false;
        _highlightActivationSecretField = false;
      });
    });
