  void _promptForActivationSecret() {
    const message =
        'New or reinstalled device: enter the setup key from your welcome email, then click "Activate Device" again.';
    if (mounted) setState(() => _inputGuidanceMessage = message);
    _highlightInputField(activationSecret: true);
    _showFeedback(message);
  }

  /// Refuses a code that is the right length but trivially guessable. Uses
  /// the same highlight/guidance channel as every other activation-input
  /// problem, so nothing about this refusal looks special, and the message
  /// itself (see [weakPinRejectionMessage]) never mentions what the app is.
  void _rejectWeakPinAtSetup(String message) {
    if (mounted) setState(() => _inputGuidanceMessage = message);
    _highlightInputField(pin: true);
    _showFeedback(message);
  }

  void _promptForPinBeforeFreeServer() {
    const message =
        'Please set the PIN by typing it here and click the "Try Free Server" button again.';
    if (mounted) setState(() => _inputGuidanceMessage = message);
    _highlightInputField(pin: true);
    _showFeedback(message);
  }

  void _promptForActivationInput({
    required bool missingAccount,
    required bool missingPin,
  }) {
    _highlightInputField(account: missingAccount, pin: missingPin);
    if (missingAccount && missingPin) {
      const message =
          'Please type your 12-digit Account Number and set a $kCamouflagePinLength-digit PIN before clicking "Activate Device".';
      if (mounted) setState(() => _inputGuidanceMessage = message);
      _showFeedback(message);
    } else if (missingAccount) {
      const message =
          'Please type your 12-digit Account Number before clicking "Activate Device".';
      if (mounted) setState(() => _inputGuidanceMessage = message);
      _showFeedback(message);
    } else {
      const message =
          'Please set a $kCamouflagePinLength-digit PIN by typing it in the PIN box before activating.';
      if (mounted) setState(() => _inputGuidanceMessage = message);
      _showFeedback(message);
    }
  }

  /// The Android service's own copy of the user's CURRENT Double VPN choice,
  /// in a record of its own so that a system restart of a saved tunnel (which
  /// brings back a config started under whatever the choice was then) can be
  /// judged against what the user wants now. No other platform has a service
  /// that restarts a saved config, so nothing is written there. A failed write
  /// that would leave a stale "0" behind for a wanted Double VPN removes the
  /// record instead: absent reads as unknown there, which is treated as wanted.
  Future<bool> _writeDoubleVpnIntentRecord(bool requested) {
    if (!Platform.isAndroid) return Future<bool>.value(true);
    final scheduledEpoch = _accountSessionEpoch.current;
    final operation = _doubleVpnIntentRecordQueue.then((_) async {
      if (_doubleVpnIntentWritesSealed ||
          !_accountEpochIsCurrent(scheduledEpoch)) return false;
      try {
        await _writeSensitiveText(_doubleVpnIntentRecord, requested ? '1' : '0');
        if (_doubleVpnIntentWritesSealed ||
            !_accountEpochIsCurrent(scheduledEpoch)) return false;
        return true;
      } catch (e) {
        _debugLog('Double VPN intent record write failed: $e');
        if (requested && !_doubleVpnIntentWritesSealed &&
            _accountEpochIsCurrent(scheduledEpoch)) {
          try {
            await _deleteSensitiveText(_doubleVpnIntentRecord);
          } catch (_) {}
        }
        return false;
      }
    });
    _doubleVpnIntentRecordQueue = operation.then<void>(
      (_) {},
      onError: (_, __) {},
    );
    return operation;
  }

  Future<bool> _persistDoubleVpnRequested(bool requested) async {
    // Turning it on records the service's copy FIRST, so a failure leaves
    // nothing half done on the side that would stay silent. Turning it off
    // records it after: a failed write then leaves "1" behind, which only ever
    // adds a marker, and the next start writes it again.
    if (requested && !await _writeDoubleVpnIntentRecord(true)) return false;
    try {
      await _mutateVpnRuntimeSettings((data) {
        data['double_vpn_requested'] = requested;
      });
    } catch (e) {
      _debugLog('Double VPN preference save failed: $e');
      if (requested) await _writeDoubleVpnIntentRecord(false);
      return false;
    }
    if (!requested) await _writeDoubleVpnIntentRecord(false);
    return true;
  }

  // True from the first await of a change to the Double VPN choice until the
  // choice is both saved and visible. A connect reads the choice, and the
  // service's copy of it, when it starts, so neither may move under it.
  bool _doubleVpnPreferenceChanging = false;

  /// A connect refuses to start while a change to the Double VPN choice is
  /// still being saved (and the change refuses while a connect is starting,
  /// see [_setDoubleVpnRequested]), so the route marker built for a start can
  /// never describe a different choice than the one in force at its commit.
  bool _refuseConnectWhileDoubleVpnSaving() {
    if (!_doubleVpnPreferenceChanging) return false;
    _showFeedback(
        'Double VPN is still being saved. Connect again when it finishes.');
    return true;
  }

  Future<void> _setDoubleVpnRequested(bool requested) async {
    if (_isConnected) {
      _showFeedback(
          'Please disconnect the VPN first. Double VPN cannot be changed while the VPN is connected, so nothing was changed.');
      return;
    }
    if (_doubleVpnPreferenceChanging ||
        _isVpnConnectInFlight ||
        _isTunnelTransitioning ||
        _isLoading ||
        _accountCleanupPending) {
      _showFeedback(
          'Wait for the current connection or account operation to finish before changing Double VPN. Nothing was changed.');
      return;
    }
    _doubleVpnPreferenceChanging = true;
    _doubleVpnPreferenceRevision++;
    try {
      if (!requested) {
        if (!await _persistDoubleVpnRequested(false)) {
          _showFeedback(
              'Double VPN could not be saved because the app could not write its settings. Nothing was changed.');
          return;
        }
        if (!mounted) return;
        setState(() {
          _isDoubleVpnRequested = false;
        });
        return;
      }
      if (_isFreeAccessSession && !_doubleVpnFreeAccessEnabled) {
        await _persistDoubleVpnRequested(false);
        if (mounted) {
          setState(() {
            _isDoubleVpnRequested = false;
          });
        }
        _showFeedback('This feature is for paid users only.');
        return;
      }
      if (requested && !_doubleVpnAvailable) {
        await _persistDoubleVpnRequested(false);
        if (mounted) {
          setState(() {
            _isDoubleVpnRequested = false;
          });
        }
        _showFeedback('Our core server is currently offline for maintenance.');
        return;
      }
      if (!await _persistDoubleVpnRequested(true)) {
        _showFeedback(
            'Double VPN could not be saved because the app could not write its settings. Nothing was changed.');
        return;
      }
      if (!mounted) return;
      setState(() {
        _isDoubleVpnRequested = true;
      });
    } finally {
      _doubleVpnPreferenceChanging = false;
    }
  }

  // STEALTH-TRANSPORT-ONLY LANE (2026-08-06). Own key, own writer. Deliberately
  // NOT folded into the broad _persistVpnRuntimeSnapshot write for the same
  // reason Double VPN is not: an older queued snapshot must not be able to
  // overwrite a newer, already-durable switch selection.
  Future<bool> _persistStealthTransportOnly(bool enabled) async {
    try {
      await _mutateVpnRuntimeSettings((data) {
        data['stealth_transport_only'] = enabled;
      });
      return true;
    } catch (e) {
      _debugLog('TCP-only preference save failed: $e');
      return false;
    }
  }

  Future<void> _setStealthTransportOnly(bool enabled) async {
    // Same guard as Double VPN: this changes which transport a connect is
    // allowed to use, which is only meaningful for the NEXT connect. Changing
    // it under a live tunnel would either lie about the running session or
    // force a reconnect the user did not ask for.
    if (_isConnected) {
      _showFeedback(
          'Please disconnect the VPN first. The TCP fallback preference cannot be changed while the VPN is connected, so nothing was changed.');
      return;
    }
    if (!await _persistStealthTransportOnly(enabled)) {
      _showFeedback(
          'That setting could not be saved because the app could not write its settings. Nothing was changed.');
      return;
    }
    if (!mounted) return;
    setState(() {
      _isStealthTransportOnly = enabled;
    });
  }

  // BUILD-SETTINGS LANE (2026-08-10). Transport-mode helpers.
  //
  // The protocol selector and the legacy TCP-fallback switch stay
  // in lock-step. 'tcp' means exactly what the legacy flag means, and the
  // legacy flag is the single value the connect path reads, so whichever
  // control wrote it, the live connect behaves the same. The 'udp' mode is the
  // only genuinely new leg-suppression and it is expressed separately below.
  static String transportModeForStealthFlag(bool stealthOnly) =>
      stealthOnly ? 'tcp' : 'auto';

  static bool stealthFlagForTransportMode(String mode) => mode == 'tcp';

  Future<bool> _persistTransportMode(String mode) async {
    try {
      await _mutateVpnRuntimeSettings((data) {
        if (mode == 'auto') {
          // 'auto' is the default; leave no record rather than an explicit
          // 'auto', so an older queued snapshot cannot resurrect a stale pick.
          data.remove('transport_mode');
        } else {
          data['transport_mode'] = mode;
        }
      });
      return true;
    } catch (e) {
      _debugLog('Transport-mode save failed: $e');
      return false;
    }
  }

  Future<void> _setTransportMode(String mode) async {
    if (mode != 'auto' && mode != 'udp' && mode != 'tcp') return;
    // Same rule as the Double VPN / TCP-only switches: it changes which
    // transport a connect may use, which is only meaningful for the NEXT
    // connect. Changing it under a live tunnel would lie about the session.
    if (_isConnected) {
      _showFeedback(
          'Please disconnect the VPN first. The protocol setting cannot be '
          'changed while the VPN is connected, so nothing was changed.');
      return;
    }
    if (!await _persistTransportMode(mode)) {
      _showFeedback(
          'That setting could not be saved because the app could not write its '
          'settings. Nothing was changed.');
      return;
    }
    if (!mounted) return;
    setState(() {
      _transportMode = mode;
      // Keep the legacy flag aligned so both controls agree.
      _isStealthTransportOnly = stealthFlagForTransportMode(mode);
    });
  }

  // BUILD-SETTINGS LANE (2026-08-10). Always-on preference.
  Future<bool> _persistAlwaysOnEnabled(bool enabled) async {
    try {
      await _mutateVpnRuntimeSettings((data) {
        if (enabled) {
          data['always_on_enabled'] = true;
        } else {
          data.remove('always_on_enabled');
        }
      });
      return true;
    } catch (e) {
      _debugLog('Always-on save failed: $e');
      return false;
    }
  }

  /// Applies the always-on choice to the platform. Only Android has a real
  /// always-on facility; the result strings are surfaced verbatim so the UI
  /// never claims a state the platform did not confirm.
  Future<String> _applyAlwaysOnToNative(bool enabled) async {
    if (!Platform.isAndroid) return 'unsupported';
    try {
      return (await _methodChannel
                  .invokeMethod<String>('setAlwaysOnVpn', {'enabled': enabled}))
              ?.toString() ??
          'unavailable';
    } catch (e) {
      _debugLog('Always-on native apply failed: $e');
      return 'unavailable';
    }
  }

  Future<void> _setAlwaysOnEnabled(bool enabled) async {
    if (!await _persistAlwaysOnEnabled(enabled)) {
      _showFeedback(
          'That setting could not be saved because the app could not write its '
          'settings. Nothing was changed.');
      return;
    }

    final nativeResult = await _applyAlwaysOnToNative(enabled);
    if (!mounted) return;

    setState(() {
      // Only Android has an always-on facility (see _applyAlwaysOnToNative).
      // Elsewhere the switch must not read as ON next to a promise to block
      // traffic that nothing enforces.
      _alwaysOnEnabled = enabled && Platform.isAndroid;
    });

    if (!Platform.isAndroid) {
      _showFeedback(
          'The preference was saved. Android system VPN settings are '
          'unavailable on this device.');
    } else if (nativeResult != 'saved_settings_opened' &&
        nativeResult != 'saved_settings_unavailable') {
      _showFeedback(
          'The preference was saved, but the native traffic-blocking setting '
          'could not be confirmed. Traffic blocking may still be active. '
          'Check system VPN settings.');
    } else if (enabled) {
      _showFeedback(
          'Traffic blocking after a tunnel failure is requested while the '
          'service remains running. For protection across process death, '
          'enable Always-on VPN and Block connections without VPN in system '
          'VPN settings.');
    } else {
      _showFeedback(
          'The app traffic-blocking preference is off. An existing blocking '
          'interface may remain until you disconnect. The system VPN '
          'configuration was not changed or verified. Check system VPN '
          'settings.');
    }
  }

  Future<bool> _setDiagnosticsEnabled(bool enabled) async {
    try {
      await _mutateVpnRuntimeSettings((data) {
        data['diagnostics_enabled'] = enabled;
      });
      if (!enabled) {
        // Turning diagnostics off also clears anything already collected.
        await _clearTunnelFailureDiagnostic();
      }
      if (mounted) {
        setState(() {
          _diagnosticsEnabled = enabled;
        });
      }
      return true;
    } catch (e) {
      _debugLog('Diagnostics preference save failed: $e');
      return false;
    }
  }

  /// Whether failure diagnostics are currently allowed to be collected.
  /// An absent key leaves collection disabled until the user opts in.
  Future<bool> _readDiagnosticsCollectionEnabled() async {
    final settings = await _readVpnRuntimeSettings();
    return settings['diagnostics_enabled'] == true;
  }

  Future<void> _setSelectedProtocolVersion(String version) async {
    if (version != kWinnProtocolV3 && version != kWinnProtocolV1) return;
    if (_userSelectedProtocolVersion == version) return;
    try {
      await _mutateVpnRuntimeSettings((data) {
        data['selected_protocol_version'] = version;
      });
    } catch (e) {
      _debugLog('Protocol preference save failed: $e');
    }
    if (!mounted) return;
    setState(() {
      _userSelectedProtocolVersion = version;
      _cachedVpnConfig = const <String, dynamic>{};
    });
    if (_isConnected) {
      _scheduleTunnelSettingsReconnect(
          _t("Restarting VPN to apply protocol change..."));
    }
  }

