  void _scheduleTunnelSettingsReconnect(String message) {
    if (!_isConnected || _isLoading) return;
    _settingsReconnectTimer?.cancel();
    _showFeedback(message);
    _settingsReconnectTimer = Timer(const Duration(milliseconds: 900), () {
      if (mounted && _isConnected && !_isLoading) {
        unawaited(_restartTunnelForSettingsChange());
      }
    });
  }

  Future<void> _restartTunnelForSettingsChange() async {
    if (!_isConnected || _isLoading) return;
    // Behind the decoy nothing is torn down or reconnected, and nothing is
    // said: no PIN has been entered (the watch rule in _handleWatchCommand).
    // The restart waits, bound to this tunnel, and runs after the unlock.
    if (_showDecoyCalculator) {
      _settingsRestartPending = true;
      _settingsRestartGeneration = _tunnelDisplayLedger.generation;
      _settingsRestartEpoch = _accountSessionEpoch.current;
      return;
    }
    // Never tear down a working tunnel to reconnect to a saved choice the
    // listing does not carry: the replacement would be refused and the user
    // left with no connection. Without a fresh live listing that is not yet
    // known, so the restart waits for the next listing
    // (_runPendingSettingsRestart). With a fresh omission the carrying tunnel
    // stays up, and says so.
    if (_manualSelectionUnlisted) {
      if (!_freshListingOmits(_currentSelectedSlug())) {
        _settingsRestartPending = true;
        _settingsRestartGeneration = _tunnelDisplayLedger.generation;
        _settingsRestartEpoch = _accountSessionEpoch.current;
        _showSelectionFeedback(
            'The new settings apply as soon as the server list has loaded.');
        return;
      }
      _settingsRestartPending = false;
      final unlistedName = _displayNodeName(_unlistedSelection!['name']);
      _showSelectionFeedback('$unlistedName is not in the server list right now, so '
          'your current connection was kept. The new settings apply when you '
          'choose another server or Automatic.');
      return;
    }
    if (mounted) {
      setState(() {
        _isLoading = true;
        _ipAfterVpn = 'Applying VPN route settings...';
      });
    }
    try {
      final displayGeneration = _tunnelDisplayLedger.generation;
      final accountEpoch = _accountSessionEpoch.current;
      final stopped = await _stopNativeTunnel(keepVpnLauncher: true);
      // The stop result describes the session this restart began with. If a
      // commit, cutover, death or account change replaced it meanwhile, the
      // restart has nothing left to restart: drop it (finally clears loading).
      if (!_nativeReadingIsCurrent(displayGeneration, accountEpoch)) return;
      if (!stopped) {
        _showFeedback('Still disconnecting. Try again in a moment.');
        // Same rule as the power-button teardown: a failed stop is not proof
        // the tunnel is up. Read the live backend so the greens never outlive
        // the tunnel that earned them.
        final readingLifecycleGeneration = _resumeProofGeneration;
        final stillActive = await _readNativeTunnelActive();
        // _isLoading does not exclude every connect (the Apple live-tunnel
        // smoke path connects without it). A reading that straddled another
        // commit, cutover, death or account change is dropped before any
        // write, as in reconciliation.
        if (_appInBackground ||
            readingLifecycleGeneration != _resumeProofGeneration ||
            !_nativeReadingIsCurrent(displayGeneration, accountEpoch)) {
          return;
        }
        if (mounted) {
          setState(() {
            final wasConnected = _isConnected;
            _isConnected = stillActive;
            _settleTunnelDisplaySession(wasConnected,
                observedGeneration: displayGeneration);
            if (!stillActive) _ipAfterVpn = _t('Disconnected');
          });
        }
        return;
      }
      if (mounted) {
        setState(() {
          final wasConnected = _isConnected;
          _isConnected = false;
          _settleTunnelDisplaySession(wasConnected,
              observedGeneration: displayGeneration);
        });
      }
      await _connectWithSmartProtocol();
    } finally {
      if (mounted) setState(() => _isLoading = false);
    }
  }

  void _bringSplitTunnelPanelIntoView() {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      final context = _splitTunnelPanelKey.currentContext;
      if (context == null || !_splitTunnelExpanded) return;
      Scrollable.ensureVisible(
        context,
        duration: const Duration(milliseconds: 260),
        curve: Curves.easeOutCubic,
        alignment: 0.28,
      );
    });
  }

  Future<void> _fetchPreVpnCountryCode() async {
    if (!_privacyConsentGranted) return;
    if (_isConnected) return;
    if (_supportsNativeTunnelReadiness) {
      final lifecycleGeneration = _resumeProofGeneration;
      final displayGeneration = _tunnelDisplayLedger.generation;
      final accountEpoch = _accountSessionEpoch.current;
      final active = await _readNativeTunnelActive();
      if (_appInBackground ||
          lifecycleGeneration != _resumeProofGeneration ||
          !_nativeReadingIsCurrent(displayGeneration, accountEpoch) ||
          active) {
        return;
      }
    }
    // A-01 (audits 2026-08-28): user-triggered only. This fetch leaves the
    // device from the user's real IP to branded hosts, so it runs when the
    // user asked for the approximate-location map and at no other time.
    if (!_preVpnGeoUserRequested) return;
    if (_preVpnGeoFetchInFlight) return;
    _preVpnGeoFetchInFlight = true;
    try {
      await _fetchPreVpnCountryCodeNow();
    } finally {
      _preVpnGeoFetchInFlight = false;
    }
  }

  Future<void> _fetchPreVpnCountryCodeNow() async {
    final sources = buildPreVpnGeoSceneSources(primaryStealthGateways);
    PreVpnGeoScene? countryOnlyFallback;
    for (final source in sources) {
      try {
        final headers = preVpnGeoRequestHeaders(source);
        // B-APP-006: a source is either fetched through the SPKI-pinned
        // client, or it must belong to the compiled closed geo host allowlist
        // before a stock client may carry a pre-tunnel request from the
        // user's real IP to it. Release builds enforce the allowlist on every
        // stock fetch; debug/profile builds keep the wider surface for
        // testing (the WINS_GEO_EDGE_BASES warning covers that case).
        final pinned = controlPlaneRequestTargetAllowed(source);
        final stockAllowed = !kReleaseMode ||
            permittedPreVpnGeoHosts.contains(source.host.toLowerCase());
        if (!pinned && !stockAllowed) {
          _debugLog(
            'Refused pre-VPN geo source outside the compiled host allowlist: '
            '${source.host}',
          );
          continue;
        }
        // The stock fetch trusts the device store, so its body is capped
        // while it streams; the pinned client carries its own cap.
        final response = await (pinned
                ? _controlPlaneClient.get(source, headers: headers)
                : fetchWithoutRedirectsCapped(
                    source,
                    maxBytes: kMaxPreVpnGeoSceneBytes,
                    deadline: const Duration(seconds: 3),
                    headers: headers,
                  ))
            .timeout(const Duration(seconds: 3));
        if (response.statusCode != 200 || response.body.contains('<!DOCTYPE')) {
          continue;
        }
        final scene = parsePreVpnGeoScene(jsonDecode(response.body));
        if (scene == null) continue;
        if (!scene.hasSpecificLocation) {
          countryOnlyFallback ??= scene;
          continue;
        }
        _applyPreVpnGeoScene(scene);
        return;
      } catch (e) {
        _debugLog('Pre-VPN country lookup failed through $source: $e');
      }
    }
    if (countryOnlyFallback != null) {
      _applyPreVpnGeoScene(countryOnlyFallback);
    }
  }

  void _applyPreVpnGeoScene(PreVpnGeoScene scene) {
    final rejectedTileHost = scene.rejectedMapTileHost;
    if (rejectedTileHost != null) {
      // Fail loudly rather than silently: an unexpected host here means the
      // hub tried to steer a pre-tunnel, real-IP fetch somewhere this build
      // does not trust. Logged by host alone -- never the template, which can
      // carry credentials in its userInfo. Degradation is benign: the map
      // keeps rendering from the compiled WINS_MAP_TILE_URL endpoint.
      _debugLog(
        'Rejected hub map_tile_url_template: host "$rejectedTileHost" is not '
        'in this build\'s trusted map-tile hosts. Keeping the compiled tile '
        'endpoint.',
      );
    }
    final regionCenter =
        preVpnRegionCenter(scene.countryCode, scene.regionCode);
    final latitude = scene.latitude ?? regionCenter?.latitude;
    final longitude = scene.longitude ?? regionCenter?.longitude;
    void apply() {
      _preVpnCountryCode = scene.countryCode;
      _preVpnRegionCode = scene.regionCode;
      _preVpnLatitude = latitude;
      _preVpnLongitude = longitude;
      // Cache the coarse position so a duress entry made offline, or after a
      // restart, still carries a last-known location. Best-effort and never
      // awaited: the map scene must render regardless.
      unawaited(_persistLastKnownCoarseLocation(latitude, longitude));
      if (scene.mapTileUrlTemplate != null) {
        _preVpnMapTileUrlTemplate = scene.mapTileUrlTemplate!;
      }
      if (scene.mapAttributionText != null) {
        _preVpnMapAttributionText = scene.mapAttributionText!;
      }
      if (scene.mapAttributionUrl != null) {
        _preVpnMapAttributionUrl = scene.mapAttributionUrl!;
      }
    }

    if (mounted) {
      setState(apply);
    } else {
      apply();
    }
  }

  Future<bool> _openExternalUrl(String url) async {
    try {
      if (Platform.isAndroid || Platform.isIOS || Platform.isMacOS) {
        final launched = await _methodChannel
                .invokeMethod<bool>('launchExternalUrl', {'url': url}) ??
            false;
        if (launched) return true;
        return false;
      } else if (Platform.isWindows) {
        await Process.start(
          windowsSystemExecutable('rundll32.exe'),
          ['url.dll,FileProtocolHandler', url],
          mode: ProcessStartMode.detached,
        );
        return true;
      } else if (Platform.isLinux) {
        await Process.start('xdg-open', [url], mode: ProcessStartMode.detached);
        return true;
      }
    } catch (_) {
      return false;
    }
    return false;
  }

  // Attribution/web-fallback call sites that fire-and-forget rather than
  // going through _launchURL's dismiss/feedback flow (see L-12).
  Future<bool> _openValidatedHttpsUrl(String url) async {
    try {
      return await _openExternalUrl(validatedHttpsUrl(url).toString());
    } catch (e) {
      _debugLog('Rejected external URL before launch: $e');
      return false;
    }
  }

  Future<void> _launchURL(
    String url, {
    bool dismissCurrentView = true,
    String failureMessage = "Could not open payment link.",
  }) async {
    Uri validated;
    try {
      validated = validatedHttpsUrl(url);
    } catch (e) {
      _debugLog('Rejected external URL before launch: $e');
      _showFeedback(failureMessage);
      return;
    }
    if (dismissCurrentView && Navigator.canPop(context)) {
      Navigator.pop(context);
    }
    final launched = await _openExternalUrl(validated.toString());
    if (!launched) _showFeedback(failureMessage);
  }

  Future<void> _launchPaymentURL(String url) async {
    Uri validated;
    try {
      validated = validatedPaymentUrl(url);
    } catch (e) {
      _debugLog('Rejected payment URL before launch: $e');
      _showFeedback('Could not open payment link.');
      return;
    }
    if (Navigator.canPop(context)) Navigator.pop(context);
    final launched = await _openExternalUrl(validated.toString());
    if (!launched) _showFeedback('Could not open payment link.');
  }

  Future<void> _promptAppUpdateRequired() async {
    // Force-update: block the action and send the user to the update channel.
    // Prefer the hub-advertised URL, but ONLY if it passes the first-party
    // update-host allowlist (M-9); otherwise fall back to the public website's
    // download page (the universal, censorship-resistant direct-distribution
    // channel). A malformed/untrusted hub URL therefore never suppresses the
    // fallback. The website fallback rides the SAME validator (B-APP-002), so
    // a re-pointed WINS_PUBLIC_WEBSITE_URL can never smuggle a nonstandard
    // port or a fragment into the update flow either; a rejected fallback
    // leaves the prompt without a link rather than launching an untrusted one.
    var target = '';
    final hubUrl = _appUpdateUrl.trim();
    if (hubUrl.isNotEmpty) {
      try {
        target = validatedAppUpdateUrl(hubUrl).toString();
      } catch (e) {
        _debugLog('Rejected hub app update URL before launch: $e');
        target = '';
      }
    }
    if (target.isEmpty) {
      final website = _publicWebsiteUrl.trim();
      if (website.isNotEmpty) {
        try {
          target = validatedAppUpdateUrl('$website/download').toString();
        } catch (e) {
          _debugLog('Rejected website update fallback URL before launch: $e');
        }
      }
    }
    _showFeedback(_t(
        'A required update is available. Please update to the latest version to continue.'));
    if (target.isNotEmpty) {
      await _launchURL(
        target,
        dismissCurrentView: false,
        failureMessage:
            'Could not open the update page. Visit our website to update.',
      );
    }
  }

  /// M-8: single choke point for the force-update gate at the native-start
  /// boundary. Returns true (after prompting) when an update is required, so
  /// the caller must abort the start. Deliberately does NOT tear down an
  /// already-active tunnel -- it only blocks NEW starts, so it is leak-safe to
  /// call from any connect path. Callers that had an active tunnel (settings
  /// restart, server switch) have already stopped it before reaching a start,
  /// so blocking here simply leaves the user safely disconnected rather than
  /// downgraded onto a known-outdated build.
  Future<bool> _blockIfUpdateRequired() async {
    if (!_appUpdateRequired) return false;
    await _promptAppUpdateRequired();
    return true;
  }

  // appUrl is an app-specific deep-link scheme (e.g. fb://, twitter://) by
  // design and is intentionally not routed through validatedHttpsUrl (see
  // L-12) - only the HTTPS web-fallback is. It is only ever launched with
  // hardcoded, compiled-in call sites, never with server/user-controlled
  // input.
  Future<void> _launchSocialUrl(String appUrl, String webUrl) async {
    if (Platform.isAndroid && appUrl.trim().isNotEmpty) {
      final launchedApp = await _openExternalUrl(appUrl);
      if (launchedApp) return;
    }
    Uri validatedWebUrl;
    try {
      validatedWebUrl = validatedHttpsUrl(webUrl);
    } catch (e) {
      _debugLog('Rejected social web-fallback URL before launch: $e');
      _showFeedback("Could not open social link.");
      return;
    }
    final launchedWeb = await _openExternalUrl(validatedWebUrl.toString());
    if (!launchedWeb) _showFeedback("Could not open social link.");
  }

  String _paymentSourceTag() {
    if (Platform.isAndroid) return 'app_android';
    if (Platform.isWindows) return 'app_windows';
    if (Platform.isIOS) return 'app_ios';
    if (Platform.isLinux) return 'app_linux';
    if (Platform.isMacOS) return 'app_macos';
    return 'app';
  }

  String get _publicPremiumAccessUrl {
    final base = _publicWebsiteUrl.trim().isEmpty
        ? 'https://winsvpn.org'
        : _publicWebsiteUrl.trim();
    return '${base.split('#').first.replaceFirst(RegExp(r'/+$'), '')}/#get';
  }

  String _trackedPaymentUrl(String optionKey) {
    final candidate = defaultGatewayBase.trim().isNotEmpty
        ? gatewayBase(defaultGatewayBase)
        : _publicWebsiteUrl;
    for (final base in <String>[candidate, kReviewedPaymentBase]) {
      try {
        return validatedPaymentUrl(
          '$base/pay/$optionKey?src=${_paymentSourceTag()}${_purchaseReferralQuery(optionKey)}',
        ).toString();
      } catch (e) {
        _debugLog('Rejected candidate payment origin before launch: $e');
      }
    }
    return '';
  }

  // R2: the hub's GET /pay/{option_key} reads the referral from ?ref=.
  String _purchaseReferralQuery(String optionKey) {
    final code = _purchaseReferralCode.trim().replaceAll(RegExp(r'[^\w-]'), '');
    if (code.isEmpty || optionKey == 'donation') return '';
    return '&ref=${Uri.encodeQueryComponent(code)}';
  }

  // R2: in-app prepaid redemption only on direct-distribution builds. Apple
  // App Review 3.1.1 forbids an own license-key unlock in App Store builds
  // (iOS links to the website instead, and only when external links are
  // enabled for the build), and Google Play builds never offer it.
  bool get _canRedeemPrepaidInApp =>
      _externalPaymentLinksEnabled && !_googlePlayBuild && !Platform.isIOS;

  Future<void> _showPrepaidRedemption() async {
    if (!_canRedeemPrepaidInApp) return;
    final epoch = _accountSessionEpoch.current;
    final signedIn = _isLoggedIn && !_isFreeAccessSession;
    final account =
        signedIn ? formatAccountNumberForRedemption(_accountController.text) : '';
    final token = signedIn ? (await _readDeviceAuthToken() ?? '') : '';
    if (!mounted || !_accountSessionEpoch.isCurrent(epoch)) return;
    // One pinned origin and no failover fan-out: a prepaid code is a one-time
    // bearer value (the activationAttemptGateways rule).
    final origin = Uri.parse(kReviewedPaymentBase);
    await showDialog<void>(
      context: context,
      barrierDismissible: false,
      builder: (_) => PrepaidRedemptionDialog(
        // The dialog's strings and the hub messages it shows use _t too.
        translate: _t,
        account: account,
        deviceId: signedIn ? _appScopedDeviceId : '',
        deviceToken: token,
        // R2-AUDIT-09: show the extended expiry through the normal status path.
        onAccountExtended: signedIn
            ? (_) {
                if (!mounted || !_accountSessionEpoch.isCurrent(epoch)) return;
                unawaited(_refreshAccountStatusOnce(force: true, expectedEpoch: epoch));
              }
            : null,
        onNewCredentials: signedIn
            ? null
            : (number, setupKey) {
                if (!mounted) return;
                _accountController.text = number;
                _activationSecretController.text = setupKey;
              },
        post: (path, request) async {
          if (!_accountSessionEpoch.isCurrent(epoch)) {
            throw StateError('Session changed');
          }
          final abort = Completer<void>();
          final timer = Timer(const Duration(seconds: 20), () {
            if (!abort.isCompleted) abort.complete();
          });
          try {
            return await sendHubRequest(
              _controlPlaneClient,
              'POST',
              origin.replace(path: path),
              abort: abort.future,
              headers: request.headers,
              body: request.body,
            );
          } finally {
            timer.cancel();
          }
        },
      ),
    );
  }

  String _extractReferralCodeFromLink(String link) {
    try {
      final uri = Uri.parse(link.trim());
      final segments = uri.pathSegments
          .where((segment) => segment.trim().isNotEmpty)
          .toList();
      for (var i = 0; i < segments.length - 1; i++) {
        final marker = segments[i].toLowerCase();
        if (marker == 'ref' || marker == 'referral') {
          return Uri.decodeComponent(segments[i + 1]).trim();
        }
      }
      if (segments.isNotEmpty) return Uri.decodeComponent(segments.last).trim();
    } catch (_) {}
    return '';
  }

  String _officialReferralUrlFromCode(String code, {String? base}) {
    final clean = code.trim();
    if (clean.isEmpty) return '';
    final selectedBase = (base ?? _publicReferralBase).trim();
    return '${selectedBase.replaceFirst(RegExp(r'/+$'), '')}/${Uri.encodeComponent(clean)}';
  }

  String _brandedReferralLink({bool backup = false}) {
    final base = backup ? _publicReferralBackupBase : _publicReferralBase;
    final directCode = _referralCode.trim();
    if (directCode.isNotEmpty) {
      return _officialReferralUrlFromCode(directCode, base: base);
    }

    final stored = (backup ? _referralBackupLink : _referralLink).trim();
    final extractedCode = _extractReferralCodeFromLink(stored);
    if (extractedCode.isNotEmpty) {
      return _officialReferralUrlFromCode(extractedCode, base: base);
    }
    return stored;
  }

  // Owner ruling 2026-10-24: one label in every build. The button opens the
  // website's home page, so "Buy Premium Access" would misdescribe it.
  String get _premiumAccessActionLabel => kPremiumAccessActionLabel;

  /// Owner ruling 2026-10-24 ("Home page everywhere"): the premium access
  /// button, and the expired account's "Renew access", open the website's
  /// home page in the external browser in every build. The same validated
  /// launch as every other external link (HTTPS only, native scheme
  /// allowlist, a message when no browser opens, as on some TV devices).
  /// Nothing is opened behind the calculator decoy.
  Future<void> _openPremiumAccessHomePage() async {
    if (_showDecoyCalculator) return;
    await _launchURL(
      kPremiumAccessHomePageUrl,
      dismissCurrentView: false,
      failureMessage: kPremiumAccessOpenFailedMessage,
    );
  }

  // R2 entry point of its own (owner ruling 2026-10-24). The premium button
  // no longer opens the payment sheet, which was the only way into in-app
  // prepaid redemption, so direct-distribution builds that offer redemption
  // show this entry instead. A constant condition returns first in Google
  // Play builds, so the compiler drops the R2 text (release gate S14A lists
  // this method among the R2 sources); App Store and store-safe builds never
  // offer redemption (_canRedeemPrepaidInApp).
  List<Widget> _prepaidRedemptionEntries({required double tvOrder}) {
    if (_googlePlayBuild) return const <Widget>[];
    if (!_canRedeemPrepaidInApp) return const <Widget>[];
    return <Widget>[
      TvFocusDecoration(
        order: tvOrder,
        child: TextButton.icon(
          key: const Key('prepaid_redemption_entry'),
          onPressed: () {
            if (_showDecoyCalculator) return;
            unawaited(_showPrepaidRedemption());
          },
          icon: const Icon(Icons.card_giftcard, color: Colors.teal, size: 16),
          label: Text(_t("Redeem a Prepaid Card")),
        ),
      ),
    ];
  }

  // Unreachable since owner ruling 2026-10-24: every premium button opens the
  // website home page (_openPremiumAccessHomePage) and prepaid redemption has
  // its own entry (_prepaidRedemptionEntries). Kept, not deleted, pending an
  // owner decision on retiring the in-app plan sheet: its billing disclosure,
  // R2 strings and store notices are pinned by the D1 legal, S14A Play gate,
  // R2 Burmese and Apple submission checks, which would all need updating.
  void _showPaymentOptions(BuildContext context) {
    // Play builds are Android only. A constant condition lets the compiler
    // drop the rest of this sheet (external payment and R2 redemption text)
    // from Play builds entirely; release gate S14A checks the AABs for it.
