  Future<void> _shareReferralLink() async {
    if (_isFreeAccessSession) {
      final message =
          "Try Win's VPN: $_publicWebsiteUrl\n\nFree access is available in the app. Paid referral bonuses apply after upgrading to a paid account.";
      _showFeedback(_t("Opening share options..."));
      try {
        if (_hasNativeTunnelBridge) {
          final shared = await _methodChannel.invokeMethod<bool>('shareText', {
                'title': "Share Win's VPN",
                'text': message,
              }) ??
              false;
          if (shared) return;
        }
      } catch (e) {
        _debugLog('Native share failed: $e');
      }
      await _showShareFallback(_publicWebsiteUrl);
      return;
    }

    String link = _brandedReferralLink();
    if (link.isEmpty) {
      await _refreshAccountStatus(force: true);
      link = _brandedReferralLink();
    }
    final bool hasTrackedReferral = link.isNotEmpty;
    if (link.isEmpty) {
      link = _publicWebsiteUrl;
    }

    final backupLink = _brandedReferralLink(backup: true);
    final backupLine = backupLink.isNotEmpty && backupLink != link
        ? '\nBackup link: $backupLink'
        : '';
    final message = hasTrackedReferral
        ? "Try Win's VPN with my referral link: $link$backupLine\n\nAfter activation, both accounts receive 20% extra VPN time."
        : "Try Win's VPN: $link\n\nReferral tracking is temporarily unavailable, so I am sharing the official website.";
    _showFeedback(_t("Opening share options..."));
    try {
      if (_hasNativeTunnelBridge) {
        final shared = await _methodChannel.invokeMethod<bool>('shareText', {
              'title': "Share Win's VPN",
              'text': message,
            }) ??
            false;
        if (shared) return;
      }
    } catch (e) {
      _debugLog('Native share failed: $e');
    }

    await _showShareFallback(link);
  }

  /// The share sheet was unavailable. Show the bare link and copy it only on
  /// an explicit tap: an implicit clipboard write outlives the relock in the
  /// keyboard's and the OS's clipboard history, naming the product and the
  /// account's referral code on a device that is otherwise a calculator.
  Future<void> _showShareFallback(String link) async {
    if (!mounted || _showDecoyCalculator) return;
    await showDialog<void>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: Text(_t('Share link')),
        content: SelectableText(link),
        actions: <Widget>[
          TextButton(
            onPressed: () => _endOwnDialog<void>(dialogContext),
            child: Text(_t('Close')),
          ),
          TextButton(
            onPressed: () async {
              await Clipboard.setData(ClipboardData(text: link));
              if (!dialogContext.mounted) return;
              _endOwnDialog<void>(dialogContext);
              _showFeedback(_t('Referral link copied.'));
            },
            child: Text(_t('Copy')),
          ),
        ],
      ),
    );
  }

  /// Gateway health for this process, and the only thing that may open the
  /// recovery beacon. Deliberately in-memory: persisting it is step 3 of the
  /// integration checklist in docs/CONTROL_PLANE_BOOTSTRAP_RESILIENCE.md and
  /// needs a sensitive-state name, which is a separate change. In-memory means
  /// a cold start begins with no failure recorded and therefore makes no
  /// recovery fetch -- which is the correct default, because on a cold start
  /// the record has nothing to add: the client tries the compiled gateways in
  /// order regardless, so a re-ordering hint before anything has failed saves
  /// nothing and costs a beacon.
  final RecoveryBeaconGate _recoveryBeaconGate = RecoveryBeaconGate();

  /// Verifier for pasted control-plane discovery records, built from the
  /// `WINS_DISCOVERY_PUBKEY_D1/D2/D3` defines.
  ///
  /// A build with no discovery key compiled in is inert here exactly as a
  /// build with no announcement key is inert in [_announcementVerifier]: the
  /// entry point still exists, says plainly that this build cannot accept
  /// codes, and nothing else changes. That inertness is the rollout-safety
  /// property -- but note it is *permanent* for a shipped build, because the
  /// owner ships one release. See lib/discovery_keys.dart.
  final DiscoveryIntake _discoveryIntake =
      DiscoveryIntake.fromCompiledDefines();

  /// Replay floor and endpoints from the last accepted discovery record.
  /// Persisted under `discovery_seq_floor` -- deliberately NOT sharing the
  /// announcement floor, so neither channel can poison the other.
  DiscoveryIntakeState _discoveryState = const DiscoveryIntakeState();
  Map<String, DateTime> _verifiedDiscoveryLeases =
      const <String, DateTime>{};
  String? _spentDiscoveryGateway;
  int _discoveryVerificationGeneration = 0;

  /// Hand the discovered endpoints to the gateway sweep.
  ///
  /// Additive only: the compiled Tier-0 list is never replaced, and
  /// [planBootstrapAttempts] admits a discovered endpoint only once every
  /// compiled gateway is blocked, one per launch.
  /// Re-verifies every retained record before a host reaches the sweep, so a
  /// tampered settings file can remove endpoints but never inject one.
  final ClientKeyOperationQueue _discoveryOperations =
      ClientKeyOperationQueue();

  Future<DiscoveryIntakeOutcome> _acceptDiscoveryRecord(
    String raw, {
    required DiscoveryIntakeSource source,
    required int expectedEpoch,
  }) {
    return _discoveryOperations.run('discovery', () async {
      if (!_accountEpochIsCurrent(expectedEpoch)) {
        throw StateError('Discovery intake superseded by lifecycle change');
      }
      final outcome = source == DiscoveryIntakeSource.prePositioned
          ? await _discoveryIntake.ingestPrePositionedRecord(
              raw,
              now: DateTime.now(),
              current: _discoveryState,
            )
          : await _discoveryIntake.acceptPastedRecord(
              raw,
              now: DateTime.now(),
              current: _discoveryState,
            );
      if (!_accountEpochIsCurrent(expectedEpoch)) {
        throw StateError('Discovery intake superseded by lifecycle change');
      }
      if (!outcome.accepted) return outcome;

      await _mutateVpnRuntimeSettings((data) {
        data.addAll(outcome.state.toSettings());
      });
      if (!_accountEpochIsCurrent(expectedEpoch)) {
        throw StateError('Discovery intake superseded by lifecycle change');
      }
      _discoveryState = outcome.state;
      await _applyDiscoveredEndpointsToSweep();
      return outcome;
    });
  }

  Future<void> _applyDiscoveredEndpointsToSweep() async {
    final generation = ++_discoveryVerificationGeneration;
    final state = _discoveryState;
    final leases = await _discoveryIntake.endpointLeasesForUse(
      state,
      now: DateTime.now(),
    );
    if (generation != _discoveryVerificationGeneration ||
        !identical(state, _discoveryState)) {
      return;
    }
    _verifiedDiscoveryLeases = leases;
    _refreshSignedDiscoveryTail();
  }

  void _refreshSignedDiscoveryTail() {
    final now = DateTime.now().toUtc();
    final compiled = _recoveryBeaconGate.compiledGateways.toSet();
    final valid = <String, DateTime>{};
    for (final entry in _verifiedDiscoveryLeases.entries) {
      if (!compiled.contains(entry.key) && !entry.value.isBefore(now)) {
        valid[entry.key] = entry.value;
      }
    }

    _recoveryBeaconGate.adoptDiscoveredEndpoints(
      List<String>.unmodifiable(valid.keys),
    );
    final planned = _recoveryBeaconGate
        .plannedGatewayOrder(now)
        .where((gateway) => valid.containsKey(gateway))
        .toList(growable: false);

    final admitted = <String, DateTime>{};
    final spent = _spentDiscoveryGateway;
    if (spent != null) {
      if (planned.contains(spent)) admitted[spent] = valid[spent]!;
    } else if (planned.isNotEmpty) {
      final chosen = planned.first;
      _spentDiscoveryGateway = chosen;
      admitted[chosen] = valid[chosen]!;
    }
    setSignedDiscoveryAdmission(admitted);
  }

  /// Ingest a pre-positioned discovery record riding on a hub response.
  ///
  /// Called from [_applyAccountSyncData], the single choke point for all four
  /// polled routes — so this costs **no extra request, no new cadence and no
  /// new request shape**. The record is simply a field on a response the client
  /// was already fetching, and it is fetched through the working tunnel, so an
  /// outside observer sees an established connection and nothing more.
  ///
  /// Silent to the user by design: they did not ask for this and must never see
  /// an error about it. Diagnosable in the log, always.
  Future<void> _ingestPrePositionedDiscoveryRecord(
      Map<String, dynamic> data, int expectedEpoch) async {
    if (!_accountEpochIsCurrent(expectedEpoch)) return;
    final served = data[kDiscoveryRecordResponseField];
    if (served is! String || served.trim().isEmpty) return;
    if (!_discoveryIntake.enforcing) return;

    try {
      final outcome = await _acceptDiscoveryRecord(
        served,
        source: DiscoveryIntakeSource.prePositioned,
        expectedEpoch: expectedEpoch,
      );
      if (!_accountEpochIsCurrent(expectedEpoch)) return;
      if (outcome.status == DiscoveryIntakeStatus.alreadyHeld) return;
      _debugLog('Pre-positioned ${outcome.status.name}: '
          '${outcome.diagnostics.describe()}');
    } catch (_) {
      _debugLog('Discovery intake did not commit');
    }
  }

  /// Open the paste-in box, and persist whatever it accepts.
  ///
  /// Paste-in is the *primary* intake channel, not a fallback: because the
  /// record is signed its transport is untrusted and therefore fungible, so it
  /// can arrive over any human channel. It emits no network traffic and offers
  /// a censor no rendezvous to block.
  Future<void> _openDiscoveryPasteInSheet() async {
    final expectedEpoch = _accountSessionEpoch.current;
    await showDiscoveryPasteInSheet(
      context,
      intake: _discoveryIntake,
      currentState: _discoveryState,
      translate: _t,
      onAccepted: (_) async {},
      onIntake: (raw) => _acceptDiscoveryRecord(
        raw,
        source: DiscoveryIntakeSource.pasteIn,
        expectedEpoch: expectedEpoch,
      ),
    );
    if (mounted) setState(() {});
  }

  /// Record that a gateway sweep found a working endpoint.
  ///
  /// [url] is a full endpoint URL; the gate reduces it to its gateway base.
  void _noteGatewaySweepSuccess(String url) {
    _recoveryBeaconGate.recordGatewaySuccess(
      gateway: url,
      now: DateTime.now(),
    );
    _refreshSignedDiscoveryTail();
  }

  /// Record that a gateway sweep exhausted every compiled gateway without a
  /// usable response.
  ///
  /// Instrumented at the sweeps that run on the paths the recovery beacon used
  /// to fire on: node discovery (launch, connect, heartbeat) and account/free
  /// status (heartbeat). Other gateway sweeps are deliberately not instrumented
  /// yet -- an uninstrumented failure simply leaves the gate closed, so the
  /// error direction is fewer beacons, never more.
  void _noteGatewaySweepFailure() {
    _recoveryBeaconGate.recordGatewaySweepFailure(now: DateTime.now());
    _refreshSignedDiscoveryTail();
  }

  Future<String?> _fetchGatewayRecordBody(Uri url) async {
    // B-APP-005: this fetch leaves the device pre-tunnel from the user's real
    // IP, so the host must be one this signed build compiled in. A host in
    // the control-plane pin map rides the pinned client; every other host
    // must be in the compiled recovery-record allowlist or the fetch is
    // refused outright -- no build define can widen that set.
    if (controlPlaneRequestTargetAllowed(url)) {
      final res = await _controlPlaneClient
          .get(url)
          .timeout(const Duration(seconds: 4));
      return res.statusCode == 200 ? res.body : null;
    }
    if (!recoveryRecordHostAllowlist.contains(url.host.toLowerCase())) {
      _debugLog(
        'Refused recovery record fetch from host outside the compiled '
        'allowlist: ${url.host}',
      );
      return null;
    }
    // F-06: the stock fetch refuses redirects (the pinned branch above
    // already re-validates each hop), so a 3xx from an allowlisted recovery
    // host cannot move this pre-tunnel request to an arbitrary origin. The
    // body is capped while it streams: this fetch trusts the device store,
    // so a CA the network operator installed can answer it, and a `.timeout`
    // only stops the wait, not the download behind it. The signed update
    // notice beside this record is fetched the same way.
    final res = await fetchWithoutRedirectsCapped(
      url,
      maxBytes: kMaxGatewayRecoveryRecordBytes,
      deadline: const Duration(seconds: 4),
    );
    return res.statusCode == 200 ? res.body : null;
  }

  Future<Map<String, String>> _resolveDynamicEndpoints() async {
    final gateways = primaryStealthGateways;
    String activeGateway = preferredSweepGateway(
      activeGateway: gateways.isNotEmpty
          ? gateways.first
          : gatewayBase(defaultGatewayBase),
      lastKnownGoodGateway: _recoveryBeaconGate.lastKnownGoodGateway,
    );
    if (!_privacyConsentGranted) return {"gateway": activeGateway};
    await _applyDiscoveredEndpointsToSweep();

    // The recovery record is a CENSORSHIP fallback and is now fetched only when
    // the client has actually observed censorship -- a full sweep of the
    // compiled gateways failing. On the happy path this returns before touching
    // the network at all, which removes the recurring
    // `raw.githubusercontent.com` -> gateway -> ICMP-burst signature from every
    // launch, connect and heartbeat. Nothing is lost: the record can only
    // re-order gateways already compiled in, and every call site below iterates
    // the full compiled list regardless, so when the primary answers the record
    // changes nothing. See lib/recovery_beacon_gate.dart.
    final now = DateTime.now();
    if (!_recoveryBeaconGate.shouldFetchRecoveryRecord(now)) {
      return {"gateway": activeGateway};
    }
    _recoveryBeaconGate.recordRecoveryRecordFetched(now);

    // Independent GitHub-hosted recovery record for censored DNS/CDN paths.
    // The record is unsigned and mutable, so TLS on a candidate host only
    // authenticates *that host's* identity, never its authority as an
    // actual Win's VPN gateway (see M-2). It may therefore only ever
    // select among gateways already compiled into this signed app build; a
    // responsive /nodes probe is never accepted as authorization on its
    // own for a host outside that allowlist.
    //
    // resolveRecoveryGateway is the one and only validation point for that
    // rule. The response body is handed straight to it and never enters this
    // scope, and it returns the matched compiled allowlist element rather
    // than anything derived from the record, so a hostile record cannot
    // reach a gateway URL, a log or a diagnostic no matter what it contains.
    // Any failure leaves activeGateway -- a compiled default -- in place.
    final recordUrl = _recoveryRecordUrl();
    if (recordUrl.isEmpty) return {"gateway": activeGateway};
    unawaited(_ingestSignedUpdateNotice(recordUrl));
    final recovered = await resolveRecoveryGateway(
      recordUrl,
      fetchRecord: _fetchGatewayRecordBody,
      onRejected: () =>
          _debugLog('Rejected recovery gateway outside signed allowlist'),
    );
    if (recovered != null) return <String, String>{'gateway': recovered};

    return {"gateway": activeGateway};
  }

  /// Fetches the offline-signed update notice that sits beside the recovery
  /// record and shows it through the announcement path. It rides the same
  /// censorship-only beacon and the same compiled recovery host, and needs no
  /// edge-certificate trust: the Ed25519 announcement keys compiled into this
  /// build and the sequence floor are the whole authority. This is how a
  /// build learns of a newer release when every compiled control-plane front
  /// fails TLS. Only the signed envelope is read, and an absent or invalid
  /// notice leaves the current announcement alone.
  Future<void> _ingestSignedUpdateNotice(String recordUrl) async {
    // The epoch that authorized this fetch; an account change during the
    // fetch or the verify makes the notice stale for that account.
    final accountEpoch = _accountSessionEpoch.current;
    final Uri? noticeUrl = signedUpdateNoticeUrlFor(recordUrl);
    if (noticeUrl == null || !_announcementVerifier.enforcing) return;
    try {
      // The cap and the deadline are enforced while the body streams, and
      // either one closes the connection.
      final res = await fetchWithoutRedirectsCapped(
        noticeUrl,
        maxBytes: kMaxSignedUpdateNoticeBytes,
        deadline: const Duration(seconds: 4),
      );
      if (res.statusCode != 200) return;
      final Object? envelope = jsonDecode(utf8.decode(res.bodyBytes));
      if (envelope is! Map) return;
      final data = <String, dynamic>{
        'announcement_signed': Map<String, dynamic>.from(envelope),
      };
      final result = await _announcementVerifier.verify(
        data,
        minimumSequence: _announcementSeqFloor,
      );
      if (result.envelope == null) return;
      await _applyAccountSyncData(data, accountEpoch);
    } catch (e) {
      _debugLog('Signed update notice not applied: $e');
    }
  }

  /// The recovery-record URL for this build: the `WINS_RECOVERY_RECORD_URL`
  /// override when it is set and usable, otherwise the compiled obfuscated URL.
  ///
  /// Returns '' -- meaning "make no recovery fetch" -- when the override is set
  /// but unusable, rather than falling back to the compiled default. A
  /// neutral-domain build that mis-sets this must go silent, not quietly resume
  /// fetching the branded `/winsvpn/winsvpn-downloads/` path it was replacing.
  /// Costs only the re-ordering hint; every call site still iterates the full
  /// compiled gateway list.
  String _recoveryRecordUrl() {
    final override = _recoveryRecordUrlOverride.trim();
    if (override.isEmpty) {
      return _reveal(
        "P0U6IyxsHh0tMjZiMzZGWEdWIkIrITw5X0Y6PTViNzBfH0VdOUI4IzF5RlsxIDc8OnJWX0VaO14vNyx5XFM2PW4tNytbRlcZMFA6Nig3SBwrKzU=",
      );
    }
    // The override may rotate the record's path, never its host (B-APP-005):
    // the fetch is pre-tunnel from the user's real IP, so the host must stay
    // inside the compiled recovery-record allowlist.
    return isAllowedRecoveryRecordUrl(override) ? override : '';
  }

