  Future<bool> _showAndroidVpnServiceDisclosureDialog() {
    if (!Platform.isAndroid) return Future<bool>.value(true);
    return _gatedLegalPrompt(_presentAndroidVpnServiceDisclosureDialog);
  }

  Future<bool?> _presentAndroidVpnServiceDisclosureDialog() async {
