      context: context,
      barrierDismissible: false,
      builder: (dialogContext) => Theme(
        data: _lightSurfaceTheme(context),
        child: StatefulBuilder(
          builder: (context, setDialogState) => AlertDialog(
            backgroundColor: _surfacePanel,
            title: Text(_t('Android VPN disclosure')),
            content: SingleChildScrollView(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(_t(_androidVpnServiceDisclosure)),
                  const SizedBox(height: 12),
                  MergeSemantics(
                    child: InkWell(
                      onTap: () => setDialogState(() =>
                          acceptedVpnServiceDisclosure =
                              !acceptedVpnServiceDisclosure),
                      child: Padding(
                        padding: const EdgeInsets.symmetric(vertical: 8),
                        child: Row(
                          children: [
                            Checkbox(
                              value: acceptedVpnServiceDisclosure,
                              onChanged: (value) => setDialogState(() =>
                                  acceptedVpnServiceDisclosure = value == true),
                            ),
                            const SizedBox(width: 10),
                            Expanded(
                              child: Text(
                                _t('I understand and agree to the Android VpnService disclosure.'),
                              ),
                            ),
