    // Decided by the bounded Double attempt below.
    var singleHopFirst = false;
    var requestDoubleRoute = _isDoubleVpnRequested;
    var upgradeInitialDelay = Duration.zero;
    if (upgradeAttempt == null) _cancelDoubleVpnUpgrade();
    if ((Platform.isWindows || Platform.isLinux) &&
        beforeTunnelStart == null &&
        !_winn3CoverFallbackInProgress &&
