    }

    final trackedSlug = (_winn3CoverExactTargetSlug ?? '').trim().isNotEmpty
        ? _winn3CoverExactTargetSlug!.trim()
        : _currentSelectedSlug();
    _winn3CoverFallbackTriedSlugs.add(trackedSlug);
    if (await _blockIfUpdateRequired()) return;
    if (transitionCancelled()) return;

    if (Platform.isAndroid && !_hasCurrentAndroidVpnServiceDisclosureConsent) {
      final legalFields = await _ensureLegalAcceptanceForActivation(
        await _currentAccountNumberForRefresh(),
      );
      if (legalFields == null || transitionCancelled()) return;
    }

    _lastAppleTunnelFailureStatus = '';
    _lastAppleTunnelNeedsPermissionApproval = false;
    _androidNeedsVpnPermission = false;
    _lastAppleInternetProbeFailure = null;
    _lastAppleConnectedReadinessSnapshot = null;
    if (mounted && previousTunnelReleased) {
      setState(() {
        _activeProtocolLabel = _defaultProtocolLabel;
        _activeProtocolVersion = '';
        _ipAfterVpn = _t('Starting Winn Protocol...');
      });
    }

    final cachedDirectConfig = _cachedDirectConfigForFastConnect();
    // Every new initiation refreshes authoritative protocol selection before
    // using a persisted v1 config. Explicit-node fast-connect used to reuse a
    // structurally valid cached v1 document and skip the hub; if that node is
    // now registered Winn v3, that path would start AWG/Xray as primary v1 and
    // bypass matching-generation fallback authorization. Automatic mode still
    // reaches the hub first so the Smart Router sees `location: auto`. Cached
    // v1 may lead AWG/Xray only with current listing evidence that the node is
    // still v1/legacy.
    final coverExact = (_winn3CoverExactTargetSlug ?? '').trim();
    var directConfigFromFreshHub = false;
    Map<String, dynamic>? protocolListingNode;
    var directConfig = !fastConnectEligible && beforeTunnelStart == null &&
            maySkipControlPlaneRefreshWithCachedConfig(
              cachedConfig: cachedDirectConfig,
              automaticMode: _automaticNodeSelection,
              coverExactTarget: coverExact.isNotEmpty,
            )
        ? cachedDirectConfig
        : null;
    if (directConfig != null &&
        _boolValue(directConfig['double_vpn_active']) != requestDoubleRoute) {
      directConfig = null;
    }
    // The same explicit v3 cache, ignoring its age: a stale one refreshes
    // first but still leads if the hub cannot be reached.
    final cachedExplicitV3Candidate = beforeTunnelStart == null &&
        cachedDirectConfig != null &&
        _boolValue(cachedDirectConfig['double_vpn_active']) ==
            requestDoubleRoute &&
        cachedConfigIsExplicitWinn3FastPathCandidate(
          cachedConfig: cachedDirectConfig,
          automaticMode: _automaticNodeSelection,
          coverExactTarget: coverExact.isNotEmpty,
        );
    final directConfigFromFastPath = directConfig != null;
    if (directConfig == null) {
      var directRefreshed = false;
      if (fastConnectEligible && _winn3CoverFallbackInProgress) {
        // A cover successor dials another node than the Double assignment
        // would exit through: one hop, marked unavailable, and no upgrade.
        singleHopFirst = true;
        requestDoubleRoute = false;
        _doubleVpnUpgradePhase = DoubleVpnUpgradePhase.unavailable;
