        directRefreshed = await _refreshVpnConfigForCurrentSelection(
          stealthMode: false,
          shouldCancel: transitionCancelled,
          onPrepared: beforeTunnelStart == null ? null : capturePrepared,
          doubleVpnRoute: requestDoubleRoute,
        );
      }
