      if (!directRefreshed) {
        _debugLog(
            'Config refresh failed: direct_config_unavailable_or_rejected');
        protocolListingNode = _lastConfigRefreshHadLiveNodeListing
            ? _protocolListingNodeForConfig(cachedDirectConfig)
            : null;
        if (beforeTunnelStart == null &&
            cachedDirectConfig != null &&
            _boolValue(cachedDirectConfig['double_vpn_active']) ==
                requestDoubleRoute &&
            mayLeadWithCachedConfigAfterRefreshFailure(
              cachedConfig: cachedDirectConfig,
              listingNode: protocolListingNode,
              automaticMode: _automaticNodeSelection,
              coverExactTarget: coverExact.isNotEmpty,
              explicitFastPathCandidate: cachedExplicitV3Candidate,
            )) {
          directConfig = cachedDirectConfig;
        } else {
          failConnect(_capacityAwareConnectFailureMessage(
              'Could not refresh VPN config. Check hub connection and try again.'));
          return;
        }
      } else {
        directConfig = _configForTransport(preparedConfig ?? _cachedVpnConfig,
            stealthMode: false);
        directConfigFromFreshHub = true;
      }
    }

