      final clientKeys = await _loadExistingClientKeyPair(
        await _effectiveAccountScopeForKeyPair(),
      );
      if (transitionCancelled()) return;
      final localWinn3 = await _loadExistingWinn3KeyPair(
        await _effectiveAccountScopeForKeyPair(),
      );
      if (transitionCancelled()) return;
      // A hub-served winn/3 key is usable only by the session that fetched
      // it; a cached one (or one an older build persisted) is refreshed.
      if (clientKeys == null ||
          !_configMatchesLocalClientKeys(directConfig, clientKeys) ||
          !winn3ConfigKeyUsable(directConfig, localWinn3,
              freshFromHub: directConfigFromFreshHub)) {
        _debugLog('Cached VPN config client key mismatch; refreshing.');
        final directRefreshed = await _refreshVpnConfigForCurrentSelection(
          stealthMode: false,
          shouldCancel: transitionCancelled,
          onPrepared: beforeTunnelStart == null ? null : capturePrepared,
          doubleVpnRoute: requestDoubleRoute,
        );
        if (transitionCancelled()) return;
        if (directRefreshed) {
          directConfig = _configForTransport(preparedConfig ?? _cachedVpnConfig,
              stealthMode: false);
          directConfigFromFreshHub = true;
        } else {
          directConfig = null;
        }
      }
