      directConfig = null;
    }

    if (directConfig == null || !_hasUsableVpnConfig(directConfig)) {
      failConnect(_capacityAwareConnectFailureMessage(
          'VPN config missing. Deactivate and activate again.'));
      return;
    }
    protocolListingNode ??= _protocolListingNodeForConfig(directConfig);
    if (preparedResponse != null) {
      await _applyAccountSyncData(preparedResponse!, accountEpoch);
      if (transitionCancelled()) return;
