    if (isDirectV1 && !_winn3OrdinaryConnectivityAuthorized) {
      if (!armWinn1PrimaryHubDispatchAuthorization(
        config: directConfig,
        selectionGeneration: _winn3SelectionGeneration,
      )) {
        _debugLog('Config rejected: primary_v1_dispatch_generation_or_target');
        failConnect(
            'The selected server configuration could not be authorized. Please retry.');
        return;
      }
    }
