    // or diagnostic plan) it hands nothing over and stays one hop.
    if (upgradeAttempt != null && !attemptLeadCandidate) return;
    if (attemptLeadCandidate) {
      final directStarted = await attemptDirectAwgCandidate();
      if (transitionCancelled()) return;
      if (!previousTunnelReleased) {
        _debugLog(
            'Server switch stopped during preparation; previous route retained.');
        if (!nativePreparationFinished &&
            !_lastTunnelCandidateWasSecurityRefusal &&
            !_lastAppleTunnelNeedsPermissionApproval &&
            !_androidNeedsVpnPermission) {
