        if (upgradeAttempt != null) {
          upgradeAttempt.result = DoubleVpnCutoverResult.upgraded;
        } else if (singleHopFirst) {
          _armDoubleVpnUpgrade(directCandidateConfig,
              initialDelay: upgradeInitialDelay);
        }
        unawaited(_fetchLiveNetworkIp());
        _refreshAnnouncementsAfterConnectInBackground();
        return;
      }
      // CIPHERTEXT RELAY DOUBLE VPN (w3r/1). A config the hub served with a
      // Core relay route led this attempt and the path failed (the
      // native verdict is ordinary connectivity, or the silence of an
      // unconfirmed terminal start; a typed security refusal never gets here
      // as a path failure). The relay is a path, not an identity, so this is
      // not evidence against the exit: stop asking for the relay for a while
      // (in memory only) and, for a fresh connect, run ONE full connect again.
      // The capability is not sent during the window, so the hub serves
      // today's AmneziaWG Double, and the fast connect budget, the marked
      // single hop and the background upgrade apply to it unchanged. An
      // upgrade attempt only opens the window: its own handling below restores
      // the single-hop session and the upgrade loop asks again without the
      // relay. The Double preference itself is never changed.
      final relayFailure = winn3RelayFailureAction(
        config: directCandidateConfig,
        isUpgradeAttempt: upgradeAttempt != null,
        retryAlreadyUsed: _winn3RelayRetryInProgress,
        verdict: _lastWinn3NativeVerdict,
        shape: _lastWinn3FailureShape,
      );
      if (relayFailure != Winn3RelayFailureAction.none) {
        _winn3RelaySuppressedUntil = winn3RelaySuppressionUntil(DateTime.now());
      }
      if (relayFailure == Winn3RelayFailureAction.suppressAndRetry) {
        _debugLog('Winn v3 relay path failure; retrying once without the '
            'relay capability.');
        if (!await _stopNativeTunnelForFailover()) {
          await _persistTunnelFailureDiagnostic(_defaultProtocolLabel,
              'failover_stop_settlement_failed_before_relay_retry');
          failConnect(
              'The previous VPN route could not be removed safely. Restart the app before retrying.');
          return;
        }
        if (transitionCancelled()) return;
        _winn3RelayRetryInProgress = true;
        try {
          await _connectWithSmartProtocol();
        } finally {
          _winn3RelayRetryInProgress = false;
        }
        return;
      }
      if (upgradeAttempt != null) {
        // The Double start was handed over and did not commit. Its interface
        // still holds the device's traffic: start the single-hop session
        // again the same way, in place, never through a stop and never
        // through the TCP or cover legs below.
        await _restoreSingleHopAfterDoubleVpnHandover(
          upgradeAttempt,
          transitionGeneration: transitionGeneration,
          shouldCancel: transitionCancelled,
          failConnect: failConnect,
        );
        return;
      }
      if (_lastTunnelCandidateWasSecurityRefusal) {
        // A config that led from the cache may carry an operator plan the hub
        // has since changed (a node's path MTU, a rotated descriptor). The
        // engine's ErrPathMTUMismatch and descriptor refusals reach Dart only
        // as these typed terminal verdicts, so the evidence of staleness is
        // the hub's answer itself: ONE fresh refresh, and a retry only if the
        // served plan differs. An unchanged plan fails exactly as before.
        final failedShape = _lastWinn3FailureShape;
        if (winn3TerminalFailureMayRetryWithFreshConfig(
          configFromFastPath:
              directConfigFromFastPath && !directConfigFromFreshHub,
          retryAlreadyUsed: _winn3FreshConfigRetryInProgress,
        )) {
          final freshRefreshed = await _refreshVpnConfigForCurrentSelection(
            stealthMode: false,
            shouldCancel: transitionCancelled,
          );
          if (transitionCancelled()) return;
          if (freshRefreshed &&
              winn3ServedPlanChanged(
                previous: directCandidateConfig,
                current:
                    _configForTransport(_cachedVpnConfig, stealthMode: false),
              )) {
            _debugLog('Winn v3 terminal failure on a cached config; the hub '
                'now serves a different plan. Retrying once with it.');
            if (!await _stopNativeTunnelForFailover()) {
              await _persistTunnelFailureDiagnostic(_defaultProtocolLabel,
                  'failover_stop_settlement_failed_before_fresh_config_retry');
              failConnect(
                  'The previous VPN route could not be removed safely. Restart the app before retrying.');
              return;
            }
            if (transitionCancelled()) return;
            _winn3FreshConfigRetryInProgress = true;
            try {
              await _connectWithSmartProtocol();
            } finally {
              _winn3FreshConfigRetryInProgress = false;
            }
            return;
          }
        }
        await _markCachedVpnConfigStale();
        if (transitionCancelled()) return;
        // Still terminal either way, and a typed security refusal keeps its
