      setState(() => _ipAfterVpn =
          'Diagnostic Xray override is on. Selecting a legacy TCP route...');
    } else if (!directAwgEnabled && mounted) {
      setState(() => _ipAfterVpn = 'Trying TCP fallback...');
    } else if (mounted) {
      setState(() => _ipAfterVpn = 'Testing TCP fallback...');
