      policy: leadPolicy,
      primaryAttempted: directUdpAttemptedThisConnect,
      primaryVerdict: _lastWinn3NativeVerdict,
      securityRefused: _lastTunnelCandidateWasSecurityRefusal,
      servedConfigNeedsLegacyNode:
          servedConfigNeedsCoverNodeFallback(directCandidateConfig),
