        locations: _locations,
        failedSlug: _currentSelectedSlug(),
        alreadyTriedSlugs: _winn3CoverFallbackTriedSlugs,
      );
      if (nextIndex != null &&
          winn3CoverFallbackBudgetRemains(_winn3CoverFallbackTriedSlugs)) {
        const routeReason = 'winn3_connectivity_fallback_to_winn1';
        await _persistTunnelFailureDiagnostic(
          _defaultProtocolLabel,
          routeReason,
        );
        if (!await _stopNativeTunnelForFailover()) {
          await _persistTunnelFailureDiagnostic(_defaultProtocolLabel,
              'failover_stop_settlement_failed_before_cover_node');
          failConnect(
              'The previous VPN route could not be removed safely. Restart the app before retrying.');
          return;
        }
        if (transitionCancelled()) return;
        final nextSlug =
            (_locations[nextIndex]['slug'] ?? '').toString().trim();
        if (nextSlug.isEmpty || nextSlug.toLowerCase() == 'auto') {
          failConnect('Winn Protocol could not start any VPN path.');
          return;
        }
        if (_winn3CoverAuthorizationToken == null ||
            _winn3CoverAuthorizationToken! <= 0) {
          failConnect('Winn Protocol could not start any VPN path.');
          return;
        }
        final nextName = _displayNodeName(
            _locations[nextIndex]['name'] ?? _locations[nextIndex]['slug']);
        _winn3CoverFailedNode = _currentSelectedSlug();
        _winn3CoverExactTargetSlug = nextSlug;
        _winn3CoverStartGeneration = transitionGeneration;
        if (mounted) {
          setState(() {
            _cachedVpnConfig = <String, dynamic>{};
            _ipAfterVpn = _t('This server is not answering. Trying a legacy '
                'cover-bearing server ($nextName)...');
          });
        } else {
          _cachedVpnConfig = <String, dynamic>{};
        }
        _winn3OrdinaryConnectivityAuthorized = true;
        _winn3CoverFallbackInProgress = true;
        try {
          await _connectWithSmartProtocol();
        } finally {
          _winn3CoverFallbackInProgress = false;
          _winn3CoverExactTargetSlug = null;
          _winn3CoverFailedNode = '';
          _winn3CoverAuthorizationToken = null;
          _winn3CoverStartGeneration = 0;
          _winn3SelectionGeneration = '';
          _winn3OrdinaryConnectivityAuthorized = false;
        }
        return;
      }
      failConnect('Winn Protocol could not start any VPN path.');
      return;
    }

    // BUILD-SETTINGS LANE (2026-08-10). Transport selector: in 'udp' mode the
    // direct leg is the only leg. Reaching here means it just failed, so there
    // is no TCP fallback to try -- finish honestly instead of silently trying a
    // transport the user excluded. The 'tcp' preference never suppresses the
    // required direct lead.
    if (_transportMode == 'udp') {
      failConnect(_capacityAwareConnectFailureMessage(
          'Could not connect over direct UDP on this network, and "Direct (UDP) '
          'only" is on, so the TCP route was not tried. Turn that setting off in '
          'Settings to let the app try it.'));
      return;
    }

    if (!await _stopNativeTunnelForFailover()) {
      await _persistTunnelFailureDiagnostic(
          _defaultProtocolLabel, 'failover_stop_settlement_failed_before_tcp');
      failConnect(
          'The previous VPN route could not be removed safely. Restart the app before retrying.');
      return;
    }
    if (transitionCancelled()) return;
    if (mounted) {
      setState(() => _ipAfterVpn = directAwgEnabled
          ? 'Direct route unavailable. Trying TCP...'
          : 'Using TCP fallback...');
    }

    final stealthRefreshed = await _refreshVpnConfigForCurrentSelection(
      stealthMode: true,
      shouldCancel: transitionCancelled,
      requestedLocation: winn3SelectedNodeIdentity(directCandidateConfig),
      doubleVpnRoute: requestDoubleRoute,
    );
    if (transitionCancelled()) return;
    final stealthBase = _configForTransport(
        stealthRefreshed ? _cachedVpnConfig : directConfig,
        stealthMode: true);
    if (!_hasUsableVpnConfig(stealthBase)) {
      // STEALTH-TRANSPORT-ONLY LANE (2026-08-06). This is the likeliest way the
      // preference strands someone: a server with no TCP registration, where
      // the direct leg would ordinarily have connected before this point. The
      // generic text would blame the server alone and hide the setting that
      // withheld the alternative, so name both, and both remedies. Capacity
      // still outranks it -- that is a genuinely different cause.
      //
      // Kept as its own branch with its own early return, rather than a ternary
      // inside the call below, so the generic message stays passed directly to
      // _finishTunnelConnectFailure -- connect_transition_cancellation_test
      // pins that adjacency, and it is a good rule: a terminal failure message
      // should be readable at the helper that resets the dashboard.
      failConnect(_capacityAwareConnectFailureMessage(
          'TCP fallback is not registered for this server yet.'));
      return;
    }
    if (!cachedConfigMayAuthorizeAwgOrXray(
      config: stealthBase,
      hasFreshHubConfig: stealthRefreshed || directConfigFromFreshHub,
      listingNode: protocolListingNode,
    )) {
      _debugLog('Config rejected: xray_dispatch_authorization');
      failConnect(_capacityAwareConnectFailureMessage(
          'Could not refresh VPN config. Check hub connection and try again.'));
      return;
    }
    if (requestDoubleRoute &&
        !_boolValue(stealthBase['double_vpn_active'])) {
      // Same single-hop fallback as the direct-AWG path above: stealthBase
      // already passed _hasUsableVpnConfig, so it is a working config.
      if (mounted) {
        setState(() => _ipAfterVpn = _t(
            'Double VPN core is offline for maintenance. Connecting with standard VPN instead...'));
      }
    }

    var candidates = await _reachableTcpFallbackOptions(
      stealthBase,
      _xrayHostCandidates(stealthBase),
    );
    if (transitionCancelled()) return;
    if (candidates.isEmpty) {
      await _persistTunnelFailureDiagnostic(
          _defaultProtocolLabel, 'tcp_fallback_candidate_preflight_failed');
      final blindCandidates = _windowsBlindTcpFallbackOptions(stealthBase);
      if (blindCandidates.isNotEmpty) {
        candidates = blindCandidates;
        await _persistTunnelFailureDiagnostic(
          _defaultProtocolLabel,
          'tcp_fallback_preflight_dns_blinded_windows_pinned_start',
        );
      }
    }
    final boundedCandidates = boundedXrayTransportOptions(
      candidates,
      maximumCandidates: _maximumTcpFallbackCandidates,
    );
    // M-8: the stealth-mode config refresh above also re-hits /nodes and can
    // raise the force-update flag. Recheck once more immediately before the
    // TCP-fallback native start so the settings-restart / server-switch /
    // first-connect paths can't slip a start past a just-discovered minimum.
    if (await _blockIfUpdateRequired()) return;
    for (final candidate in boundedCandidates) {
      if (transitionCancelled()) return;
      final candidateConfig = _configForTransport(
        stealthBase,
        stealthMode: true,
        xrayHost: candidate.host,
        xrayPort: candidate.port,
        xraySecurity: candidate.security,
      );
      if (await _startTunnelCandidate(
        candidateConfig,
        _defaultProtocolLabel,
        transitionGeneration: transitionGeneration,
        shouldCancel: transitionCancelled,
      )) {
        if (singleHopFirst) {
          _armDoubleVpnUpgrade(candidateConfig,
              initialDelay: upgradeInitialDelay);
        }
        unawaited(_fetchLiveNetworkIp());
        _refreshAnnouncementsAfterConnectInBackground();
        return;
      }
      if (_lastTunnelCandidateWasSecurityRefusal) {
        failConnect(
            'Winn Protocol® refused an invalid or unsupported server configuration. No fallback was attempted.');
        return;
      }
      if (transitionCancelled()) return;
      if (!await _stopNativeTunnelForFailover()) {
        await _persistTunnelFailureDiagnostic(
            _defaultProtocolLabel, 'failed_tcp_stop_settlement_failed');
        failConnect(
            'The failed VPN route could not be removed safely. Restart the app before retrying.');
        return;
      }
    }

    if (!transitionCancelled()) {
      // Name the setting rather than reporting a generic failure: the direct
      // leg that would have been tried here was withheld on the user's own
      // instruction, and they cannot act on "could not start any VPN path".
      failConnect('Winn Protocol could not start any VPN path.');
    }
  }

  Future<void> _toggleVpnConnection() async {
    // Round A3: a held Winn v3 session's own Disconnect enters here with this
    // latch set (see _disconnectHeldWinn3Session). It may only disconnect,
    // and it skips the required-update and maintenance gates below, which
    // exist to stop CONNECTING: releasing a held capture stays available.
    final heldDisconnect = _winn3HeldDisconnectPending;
    _winn3HeldDisconnectPending = false;
    if (heldDisconnect && !_isConnected) return;
    _debugLog('toggleVpnConnection entered: isLoading=$_isLoading, '
        'isConnectInFlight=$_isVpnConnectInFlight, isConnected=$_isConnected');
    if (_isLoading) {
      if (!_isVpnConnectInFlight) return;
      final operationEpoch = ++_vpnUiOperationEpoch;
      final displayGeneration = _tunnelDisplayLedger.generation;
      if (mounted) {
        setState(() {
          _isVpnConnectInFlight = false;
          _ipAfterVpn = _t('Disconnecting...');
        });
      }
      final accountEpoch = _accountSessionEpoch.current;
      final stopped = await _cancelAndStopNativeTunnel(
          keepVpnLauncher: true, releaseKillSwitchBlock: true);
      if (mounted && operationEpoch == _vpnUiOperationEpoch) {
        // The UI operation epoch owns this cancel's flags; display ownership
        // decides whether its stop result may still write connection state.
        final stopResultCurrent =
            _nativeReadingIsCurrent(displayGeneration, accountEpoch);
        setState(() {
          if (stopResultCurrent) {
            final wasConnected = _isConnected;
            _isConnected = false;
            _settleTunnelDisplaySession(wasConnected,
                observedGeneration: displayGeneration);
            _activeProtocolLabel = _defaultProtocolLabel;
            _activeProtocolVersion = '';
            _ipAfterVpn = stopped
                ? _t('Disconnected')
                : _t('Still disconnecting. Try again in a moment.');
          }
          _isLoading = false;
          _isVpnConnectInFlight = false;
          _isTunnelTransitioning = false;
        });
      }
      return;
    }
    if (_appUpdateRequired && !_isConnected) {
      if (!heldDisconnect) {
        await _promptAppUpdateRequired();
        return;
      }
    }
    if (_isUnderMaintenance && !_isConnected) {
      if (!heldDisconnect) {
        _showFeedback('Maintenance in progress. Please wait.');
        return;
      }
    }
    if (_accountExpiredTerminal && !_isConnected) {
      _showFeedback('Subscription expired. Renew access before reconnecting.');
      return;
    }
    // Fail closed and say so: the saved server is not in the listing. No
    // other server is dialled in its place; see the method.
    if (!_isConnected && _manualSelectionUnlisted) {
      // The refresh awaits: a tunnel or operation that appeared meanwhile
      // owns the state now, and this tap must not toggle it.
      if (!await _confirmUnlistedChoiceBeforeConnect() ||
          _isConnected ||
          _isLoading) {
        return;
      }
    }
    // Before any flag is raised: a connect that is refused here has nothing
    // to settle afterwards.
    if (!_isConnected && _refuseConnectWhileDoubleVpnSaving()) return;
    final operationEpoch = ++_vpnUiOperationEpoch;
    setState(() {
      _isLoading = true;
      _isVpnConnectInFlight = !_isConnected;
    });
    if (!_isConnected) {
      await _connectWithSmartProtocol();
    } else {
      final showCamouflageAfterDisconnect =
          _supportsInAppCamouflage && (_isLoggedIn || _isFreeAccessSession);
      final displayGeneration = _tunnelDisplayLedger.generation;
      final accountEpoch = _accountSessionEpoch.current;
      final tunnelStopped = await _cancelAndStopNativeTunnel(
        keepVpnLauncher: true,
        releaseKillSwitchBlock: true,
      );
      if (!tunnelStopped) {
        _showFeedback('Still disconnecting. Try again in a moment.');
        // A failed teardown is not proof the tunnel is still up: the native
        // stop may have failed because the engine already died. Reflect the
        // live backend reading instead of re-forcing the previous green.
        final readingLifecycleGeneration = _resumeProofGeneration;
        final stillActive = await _readNativeTunnelActive();
        if (mounted && operationEpoch == _vpnUiOperationEpoch) {
          // The operation epoch owns this toggle's flags. A direct commit can
          // replace the display session without advancing that epoch, so the
          // reading itself must still belong to the display session.
          final readingCurrent =
              !_appInBackground &&
              readingLifecycleGeneration == _resumeProofGeneration &&
              _nativeReadingIsCurrent(displayGeneration, accountEpoch);
          setState(() {
            if (readingCurrent) {
              final wasConnected = _isConnected;
              _isConnected = stillActive;
              _settleTunnelDisplaySession(wasConnected,
                  observedGeneration: displayGeneration);
              if (!stillActive) _ipAfterVpn = _t('Disconnected');
            }
            _isLoading = false;
            _isVpnConnectInFlight = false;
          });
        }
        return;
      }
      final stopResultCurrent =
          _nativeReadingIsCurrent(displayGeneration, accountEpoch);
      if (mounted) {
        if (showCamouflageAfterDisconnect) _clearProductSurfacesForDecoy();
        setState(() {
          if (stopResultCurrent) {
            final wasConnected = _isConnected;
            _isConnected = false;
            _settleTunnelDisplaySession(wasConnected,
                observedGeneration: displayGeneration);
            _activeProtocolLabel = _defaultProtocolLabel;
            _activeProtocolVersion = '';
            _preVpnCountryCode = '';
            _preVpnRegionCode = '';
            _preVpnLatitude = null;
            _preVpnLongitude = null;
          }
          // The user's own disconnect decides the camouflage surface.
          _showDecoyCalculator = showCamouflageAfterDisconnect;
        });
      }
      unawaited(_setLauncherCamouflage(enabled: showCamouflageAfterDisconnect));
      unawaited(_fetchLiveNetworkIp());
      if (stopResultCurrent && _preVpnGeoUserRequested) {
        unawaited(_fetchPreVpnCountryCode());
      }
    }
    if (mounted && operationEpoch == _vpnUiOperationEpoch) {
      setState(() {
        _isLoading = false;
        _isVpnConnectInFlight = false;
      });
    }
  }

  /// Round A3: Disconnect for a held Winn v3 session (recovering or blocked,
  /// capture kept). The same disconnect branch as the power control, entered
  /// with the held-disconnect latch so the required-update and maintenance
  /// gates cannot stand between the user and releasing the capture.
  Future<void> _disconnectHeldWinn3Session() async {
    if (!_isConnected) return;
    _winn3HeldDisconnectPending = true;
    await _toggleVpnConnection();
  }

  void _showFeedback(String message) {
    // Never over the decoy, whichever continuation, timer or callback asks.
    if (_showDecoyCalculator) return;
    final messenger = ScaffoldMessenger.of(context);
    messenger.hideCurrentSnackBar();
    messenger.showSnackBar(
      SnackBar(
        content: Text(message),
        backgroundColor: const Color(0xFF1B5BC4),
        behavior: SnackBarBehavior.floating,
      ),
    );
  }

  /// Before a user connect to a manual choice the listing does not carry:
  /// wait for one live /nodes walk (the one already in flight, if any), for
  /// at most kUnlistedChoiceRefreshBound, then refuse only when a fresh live
  /// listing omits the choice. When no fresh listing exists (discovery
  /// blocked or slow), the exact choice is attempted and the hub decides; no
  /// other node is ever dialled. The wait is a connect in flight: the watch
  /// and the bridge say connecting, and a second tap abandons it. Returns
  /// true to go on connecting.
  Future<bool> _confirmUnlistedChoiceBeforeConnect() async {
    if (!_manualSelectionUnlisted) return true;
    if (!mounted) return false;
    final accountEpoch = _accountSessionEpoch.current;
    final operationEpoch = ++_vpnUiOperationEpoch;
    final previousStatus = _ipAfterVpn;
    final checkingStatus = _t('Checking the server list...');
    setState(() {
      _isLoading = true;
      _isVpnConnectInFlight = true;
      _ipAfterVpn = checkingStatus;
    });
    try {
      await _sharedNodeDiscovery()
          .timeout(kUnlistedChoiceRefreshBound, onTimeout: () => false);
    } catch (_) {
      // No listing: decided below on what is known.
    }
    // A second tap (the in-flight cancel) owns the flags now.
    if (!mounted || operationEpoch != _vpnUiOperationEpoch) return false;
    setState(() {
      _isLoading = false;
      _isVpnConnectInFlight = false;
      // Only this method's own line is replaced, and from the current state:
      // reconciliation that adopted a tunnel during the wait leaves this line
      // in place (it rewrites only an empty or "disconnected" line), so a
      // connected tunnel gets the secured line, not the pre-tap one.
      if (_ipAfterVpn == checkingStatus) {
        _ipAfterVpn =
            _isConnected ? _t("Traffic Secured & Obfuscated") : previousStatus;
      }
    });
    if (!_accountEpochIsCurrent(accountEpoch)) return false;
    // Re-bound to a listed row, or no longer manual: connect as usual.
    if (!_manualSelectionUnlisted) return true;
    final slug = _currentSelectedSlug();
    if (!_freshListingOmits(slug)) return true;
    final unlistedName = _displayNodeName(_unlistedSelection?['name'] ?? slug);
    _showSelectionFeedback('$unlistedName is not in the server list right now. '
        'Choose another server or Automatic.');
    return false;
  }

  // The discovery walk _sharedNodeDiscovery hands to concurrent callers.
  Future<bool>? _sharedNodeDiscoveryWalk;

  /// One node discovery walk for concurrent callers (startup, the picker, a
  /// connect to an unlisted choice), so a connect waits on the walk already
  /// running instead of starting a second one.
  Future<bool> _sharedNodeDiscovery() {
    final inFlight = _sharedNodeDiscoveryWalk;
    if (inFlight != null) return inFlight;
    late final Future<bool> walk;
    walk = _fetchAvailableNodes().whenComplete(() {
      if (identical(_sharedNodeDiscoveryWalk, walk)) {
        _sharedNodeDiscoveryWalk = null;
      }
    });
    _sharedNodeDiscoveryWalk = walk;
    return walk;
  }

  // Retries a deferred settings restart that found another operation running.
  Timer? _settingsRestartRetry;

  /// A settings restart deferred because the listing had not loaded (see
  /// _restartTunnelForSettingsChange), run once a live listing has arrived.
  /// It belongs to the tunnel it was deferred for: a disconnect, a reconnect,
  /// a committed switch or an account change ends that display session, and
  /// the replacement was built with the current settings, so the restart is
  /// dropped. While another operation holds _isLoading (the picker's own
  /// discovery, for example) it is retried until that clears.
  void _runPendingSettingsRestart() {
    _settingsRestartRetry?.cancel();
    _settingsRestartRetry = null;
    if (!_settingsRestartPending) return;
    if (!_isConnected ||
        !_nativeReadingIsCurrent(
            _settingsRestartGeneration, _settingsRestartEpoch)) {
      _settingsRestartPending = false;
      return;
    }
    // Behind the decoy it stays pending, with no timer: the unlock runs it.
    if (_showDecoyCalculator) return;
    if (_isLoading) {
      _settingsRestartRetry = Timer(
          kSettingsRestartRetryInterval, _runPendingSettingsRestart);
      return;
    }
    _settingsRestartPending = false;
    unawaited(_restartTunnelForSettingsChange());
  }

