  ThemeData _lightSurfaceTheme(BuildContext context) {
    final base = ThemeData.light();
    return base.copyWith(
      primaryColor: Colors.blueAccent,
      colorScheme: base.colorScheme.copyWith(
        primary: Colors.blueAccent,
        secondary: _emuGreen,
        surface: _surfacePanel,
        onSurface: _surfaceText,
      ),
      scaffoldBackgroundColor: Colors.transparent,
      textTheme: base.textTheme
          .apply(bodyColor: _surfaceText, displayColor: _surfaceText),
      iconTheme: const IconThemeData(color: _surfaceText),
      listTileTheme: const ListTileThemeData(
        textColor: _surfaceText,
        iconColor: _surfaceText,
      ),
      inputDecorationTheme: InputDecorationTheme(
        filled: true,
        fillColor: Colors.white.withOpacity(0.56),
        hintStyle: const TextStyle(color: _surfaceMutedText),
        labelStyle: const TextStyle(color: _surfaceText),
        prefixIconColor: _surfaceMutedText,
        suffixIconColor: _surfaceMutedText,
      ),
      dividerColor: _surfaceBorder,
      checkboxTheme: CheckboxThemeData(
        fillColor: WidgetStateProperty.resolveWith((states) {
          if (states.contains(WidgetState.selected)) return Colors.blueAccent;
          return Colors.white.withOpacity(0.80);
        }),
        checkColor: WidgetStateProperty.all(Colors.white),
      ),
    );
  }

