  @override
  Widget build(BuildContext context) {
    // Cheap: WatchBridge drops identical state before doing any work, so this
    // costs one string comparison per rebuild in the steady state. Placed here
    // rather than at the ~40 sites that mutate connection state, so the watch
    // can never miss a transition one of them forgot to announce.
    _publishWatchState();
    _paintedProofClaims = _proofClaims;

    // TV must never be disguised: even if _showDecoyCalculator was latched
    // true before the async TV probe completed, the decoy is unreachable on
    // a D-pad remote (Material+InkWell+onTap, no focus handling) and would
    // permanently lock the user out.
    if (_showDecoyCalculator && _deviceFormFactor != DeviceFormFactor.tv) {
      return _buildFunctionalCalculatorView();
    }
    if (_showDecoyCalculator && _deviceFormFactor == DeviceFormFactor.tv) {
      // Self-heal the latched flag so subsequent builds do not re-enter.
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted && _showDecoyCalculator) {
          setState(() => _showDecoyCalculator = false);
          unawaited(_setLauncherCamouflage(enabled: false));
          _runPendingSettingsRestart();
        }
      });
    }

    String displayDate = _expirationDate;
    if (_expirationDate.length > 10 && _expirationDate.contains('T')) {
      displayDate = _expirationDate.split('T')[0];
    }
    final mapExpanded = _showExpandedMap && !_isConnected;

    return Scaffold(
      body: TvDpadWrapper(
        onBack: () {
          if (mapExpanded) {
            setState(() => _showExpandedMap = false);
          } else if (Navigator.of(context).canPop()) {
            Navigator.of(context).pop();
          } else {
            SystemNavigator.pop();
          }
        },
        child: Stack(
          children: [
            Positioned.fill(child: _buildWallpaperBackdrop()),
            if (!mapExpanded)
              Positioned.fill(
                child: IgnorePointer(
                  child: DecoratedBox(
                    decoration: BoxDecoration(
                      gradient: LinearGradient(
                        begin: Alignment.topCenter,
                        end: Alignment.bottomCenter,
                        colors: [
                          Colors.white.withOpacity(0.06),
                          Colors.white.withOpacity(0.24),
                        ],
                      ),
                    ),
                  ),
                ),
              ),
            if (!mapExpanded)
              SafeArea(
                child: LayoutBuilder(
                  builder: (context, constraints) {
                    final displayFeatures =
                        MediaQuery.displayFeaturesOf(context);
                    DisplayFeature? verticalHinge;
                    for (final feature in displayFeatures) {
                      if ((feature.type == DisplayFeatureType.hinge ||
                              feature.type == DisplayFeatureType.fold) &&
                          feature.bounds.height >= feature.bounds.width) {
                        verticalHinge = feature;
                        break;
                      }
                    }
                    final bool hasVerticalHinge = verticalHinge != null;
                    final bool isLandscapeCompact = constraints.maxWidth >= 560 &&
                        constraints.maxHeight < 520;
                    final bool isWideScreen = _isLoggedIn &&
                        (constraints.maxWidth >= 680 ||
                            hasVerticalHinge ||
                            isLandscapeCompact);
                    final double hingeGap = hasVerticalHinge
                        ? max(16.0, verticalHinge.bounds.width)
                        : 18.0;
                    final double panelMaxWidth = isWideScreen
                        ? min(constraints.maxWidth - 24, 940.0)
                        : min(constraints.maxWidth - 24, 460.0);
                    final bool isSmallScreen = constraints.maxWidth < 380;
                    final EdgeInsets scrollPadding = EdgeInsets.symmetric(
                      horizontal: isSmallScreen ? 10 : (isWideScreen ? 16 : 20),
                      vertical: isSmallScreen ? 10 : (isWideScreen ? 12 : 18),
                    );
                    final EdgeInsets panelPadding = EdgeInsets.fromLTRB(
                      isSmallScreen ? 12 : (isWideScreen ? 20 : 18),
                      // No padding above the header: the logo artwork sits
                      // almost on the card's top edge (owner, 2026-09-29).
                      0,
                      isSmallScreen ? 12 : (isWideScreen ? 20 : 18),
                      isSmallScreen ? 14 : (isWideScreen ? 18 : 20),
                    );

                    return SingleChildScrollView(
                      padding: scrollPadding,
                      child: ConstrainedBox(
                        constraints: BoxConstraints(
                          minHeight: max(0.0, constraints.maxHeight - scrollPadding.vertical),
                        ),
                        child: Center(
                          child: ConstrainedBox(
                            constraints: BoxConstraints(maxWidth: panelMaxWidth),
                            child: Container(
                              width: double.infinity,
                              padding: panelPadding,
                              decoration: BoxDecoration(
                                color: _surfacePanel,
                                borderRadius: BorderRadius.circular(14),
                                border: Border.all(color: _surfaceBorder),
                                boxShadow: [
                                  BoxShadow(
                                    color: Colors.black.withOpacity(0.28),
                                    blurRadius: 24,
                                    offset: const Offset(0, 12),
                                  ),
                                ],
                              ),
                              child: Theme(
                                data: _lightSurfaceTheme(context),
                                child: DefaultTextStyle.merge(
                                  style: const TextStyle(color: _surfaceText),
                                  child: IconTheme(
                                    data: const IconThemeData(
                                        color: _surfaceText),
                                    child: Column(
                                      mainAxisSize: MainAxisSize.min,
                                      children: [
                                        _buildHomeBrandHeader(
                                          areaWidth: constraints.maxWidth,
                                          scrollPadding: scrollPadding,
                                          panelPadding: panelPadding,
                                          panelMaxWidth: panelMaxWidth,
                                        ),
                                        const SizedBox(height: 6),
                                        if (_isUnderMaintenance)
                                          Container(
                                              width: double.infinity,
                                              padding: const EdgeInsets.all(12),
                                              decoration: BoxDecoration(
                                                  color:
                                                      _flagRed.withOpacity(0.1),
                                                  border: Border.all(
                                                      color: _flagRed),
                                                  borderRadius:
                                                      BorderRadius.circular(8)),
                                              child: Text(
                                                  "Maintenance underway: Some servers may be offline.",
                                                  style: TextStyle(
                                                      color: _flagRed,
                                                      fontSize: 11,
                                                      fontWeight:
                                                          FontWeight.bold),
                                                  textAlign: TextAlign.center)),
                                        if (_isUnderMaintenance)
                                          const SizedBox(height: 10),
                                        if (_isLoggedIn &&
                                            _accountExpiredTerminal)
                                          Container(
                                            key: const Key(
                                                'expired_renewal_banner'),
                                            width: double.infinity,
                                            padding: const EdgeInsets.all(12),
                                            decoration: BoxDecoration(
                                              color: _flagRed.withOpacity(0.1),
                                              border:
                                                  Border.all(color: _flagRed),
                                              borderRadius:
                                                  BorderRadius.circular(8),
                                            ),
                                            child: Column(
                                              children: [
                                                const Text(
                                                  'Subscription expired. Reconnect is disabled.',
                                                  textAlign: TextAlign.center,
                                                  style: TextStyle(
                                                    color: _flagRed,
                                                    fontWeight: FontWeight.bold,
                                                  ),
                                                ),
                                                TextButton(
                                                  onPressed: () => unawaited(
                                                      _openPremiumAccessHomePage()),
                                                  child: const Text(
                                                      'Renew access'),
                                                ),
                                              ],
                                            ),
                                          ),
                                        if (_isLoggedIn &&
                                            _accountExpiredTerminal)
                                          const SizedBox(height: 10),
                                        _accountCleanupPending
                                            ? _buildAccountCleanupPendingView()
                                            : _isLoading
                                                ? _isVpnConnectInFlight &&
                                                        _isLoggedIn
                                                    ? VpnConnectTransitionView(
                                                        status: _ipAfterVpn,
                                                        connectedColor:
                                                            _emuGreen,
                                                        disconnectedColor:
                                                            _flagRed,
                                                        onCancel:
                                                            _toggleVpnConnection,
                                                      )
                                                    : const Padding(
                                                        padding: EdgeInsets
                                                            .symmetric(
                                                                vertical: 40),
                                                        child:
                                                            CircularProgressIndicator(),
                                                      )
                                                : !_isLoggedIn
                                                    ? _buildLoginInterface()
                                                    : _buildVpnDashboard(
                                                        displayDate,
                                                        isWide: isWideScreen,
                                                        hingeGap: hingeGap,
                                                      ),
                                        const SizedBox(height: 4),
                                        Padding(
                                          padding: const EdgeInsets.symmetric(
                                              horizontal: 4),
                                          child: Row(
                                            mainAxisAlignment:
                                                MainAxisAlignment.spaceBetween,
                                            children: [
                                              Expanded(
                                                child: Align(
                                                  alignment:
                                                      Alignment.centerLeft,
                                                  child: TvFocusDecoration(
                                                    order: 27,
                                                    child:
                                                        _buildPrivacyPolicyAction(),
