  }

  /// The home header, kept clear of the floating map and share buttons. The
  /// header now starts higher than the old 124 dp logo box did, so on a narrow
  /// window (under about 350 dp) its box would run under them. Where it would,
  /// it is moved sideways or down just far enough; on a wider window this is
  /// the bare header. Positions come from the same numbers the panel is laid
  /// out with (top-aligned, the worst case; the buttons are in the same
  /// SafeArea as the panel).
  Widget _buildHomeBrandHeader({
    required double areaWidth,
    required EdgeInsets scrollPadding,
    required EdgeInsets panelPadding,
    required double panelMaxWidth,
  }) {
    const header = WinsHomeBrandHeader();
    final panelWidth = min(areaWidth - scrollPadding.horizontal, panelMaxWidth);
    final panelLeft =
        scrollPadding.left + (areaWidth - scrollPadding.horizontal - panelWidth) / 2;
    // 1 dp panel border on each side.
    final innerWidth = panelWidth - 2 - panelPadding.horizontal;
    final headerWidth = min(WinsHomeBrandHeader.logoWidth, innerWidth);
    final scale = headerWidth / WinsHomeBrandHeader.logoWidth;
    final headerBox = Rect.fromLTWH(
      panelLeft + 1 + panelPadding.left + (innerWidth - headerWidth) / 2,
      scrollPadding.top + 1 + panelPadding.top,
      headerWidth,
      WinsHomeBrandHeader.bandHeight * scale,
    );
    final obstacles = <Rect>[
      if (!_isConnected)
        // TvFocusDecoration draws a 1 dp border (transparent unless focused)
        // around the 48 dp IconButton, so the box is 50 dp.
        Rect.fromLTWH(
          WinsHomeBrandHeader.mapButtonLeft,
          WinsHomeBrandHeader.mapButtonTop,
          WinsHomeBrandHeader.mapButtonSize + 2 * WinsHomeBrandHeader.mapButtonBorder,
          WinsHomeBrandHeader.mapButtonSize + 2 * WinsHomeBrandHeader.mapButtonBorder,
        ),
      if (_isLoggedIn && !_isLoading)
        Rect.fromLTWH(
          areaWidth -
              WinsHomeBrandHeader.shareButtonRight -
              WinsHomeBrandHeader.shareButtonSize,
          WinsHomeBrandHeader.shareButtonTop,
          WinsHomeBrandHeader.shareButtonSize,
          WinsHomeBrandHeader.shareButtonSize,
        ),
    ];
    final move = WinsHomeBrandHeader.clearance(
      header: headerBox,
      obstacles: obstacles,
      spareRight: (innerWidth - headerWidth) / 2,
    );
    if (move.dx == 0 && move.dy == 0) return header;
    // A Column centers its child, so a left padding of 2 x dx moves it dx.
    return Padding(
      padding: EdgeInsets.only(top: move.dy, left: 2 * move.dx),
      child: header,
    );
  }

