  Widget _buildWallpaperBackdrop() {
    // TV: map is gesture-only with no D-pad equivalent. Recommend static
    // backdrop on TV rather than trying to make pinch/zoom work on a remote.
    // This keeps the remote navigable and avoids trapping focus on a
    // non-focusable InteractiveViewer/flutter_map surface.
    if (_isAndroidTv) {
      if (!_isConnected) {
        return Image.asset(
          'assets/wallpaper/default.webp',
          fit: BoxFit.cover,
          alignment: Alignment.center,
          filterQuality: FilterQuality.high,
        );
      }
      final assetPath = _selectedWallpaperAsset();
      return Image.asset(
        assetPath,
        fit: BoxFit.cover,
        alignment: Alignment.center,
        filterQuality: FilterQuality.high,
      );
    }
    if (!_isConnected) {
      // A-01: until the user asks, the disconnected backdrop is the offline
      // world map -- no geo lookup, no tile fetch, no branded SNI, ever.
      // The affordance below is the ONLY thing that arms the lookup.
      return Stack(
        alignment: Alignment.bottomCenter,
        children: [
          PublicIpMapBackdrop(
            countryCode: _preVpnCountryCode,
            regionCode: _preVpnRegionCode,
            latitude: _preVpnLatitude,
            longitude: _preVpnLongitude,
            tileUrlTemplate: _preVpnMapTileUrlTemplate,
            attributionText: _preVpnMapAttributionText,
            onAttributionTap: () => unawaited(
              _openValidatedHttpsUrl(_preVpnMapAttributionUrl),
            ),
            onOfflineAttributionTap: () => unawaited(
              _openValidatedHttpsUrl(
                'https://www.naturalearthdata.com/about/terms-of-use/',
              ),
            ),
          ),
          if (_preVpnCountryCode.trim().isEmpty &&
              !_preVpnGeoFetchInFlight &&
              !_preVpnGeoUserRequested &&
              _showExpandedMap)
            Padding(
              padding: const EdgeInsets.only(bottom: 18),
              child: OutlinedButton.icon(
                key: const Key('pre-vpn-show-location'),
                onPressed: () {
                  setState(() => _preVpnGeoUserRequested = true);
                  unawaited(_fetchPreVpnCountryCode());
                },
                style: OutlinedButton.styleFrom(
                  backgroundColor: const Color(0xF5203038),
                  foregroundColor: Colors.white,
                  side: const BorderSide(color: Color(0x66FFFFFF)),
                ),
                icon: const Icon(Icons.travel_explore, size: 18),
                label: Text(_t('Show my approximate location')),
              ),
            ),
        ],
      );
    }
    final assetPath = _selectedWallpaperAsset();
    return Image.asset(
      assetPath,
      fit: BoxFit.cover,
      alignment: Alignment.center,
      filterQuality: FilterQuality.high,
    );
  }

