  Widget _buildFunctionalCalculatorView() {
    // H-11 (handoff §11): a single design used to clone iOS's calculator on
    // every platform, so it didn't resemble Samsung's real One UI Calculator
    // on Android at all. Branch on the real target so each platform matches
    // its own device's stock app instead of a wrong-platform lookalike.
    final bool isAndroidCalc = Platform.isAndroid;
    // Real Samsung One UI Calculator has a "()" key here, not "±".
    // Real iOS Calculator keeps the "±"-style sign-toggle key.
    final List<String> gridButtons = isAndroidCalc
        ? const [
            "AC",
            "⌫",
            "%",
            "÷",
            "7",
            "8",
            "9",
            "×",
            "4",
            "5",
            "6",
            "-",
            "1",
            "2",
            "3",
            "+",
            "()",
            "0",
            ".",
            "="
          ]
        : const [
            "AC",
            "⌫",
            "%",
            "÷",
            "7",
            "8",
            "9",
            "×",
            "4",
            "5",
            "6",
            "-",
            "1",
            "2",
            "3",
            "+",
            "±",
            "0",
            ".",
            "="
          ];
    final Color scaffoldBg =
        isAndroidCalc ? const Color(0xFFF5F5F7) : const Color(0xFF1C1C1E);
    final Color displayColor =
        isAndroidCalc ? const Color(0xFF1A1A1A) : Colors.white;
    return Scaffold(
      backgroundColor: scaffoldBg,
      body: SafeArea(
        child: LayoutBuilder(
          builder: (context, constraints) {
            final displayHeight =
                (constraints.maxHeight * 0.20).clamp(74.0, 180.0);
            return Column(
              children: [
                if (isAndroidCalc)
                  Padding(
                    padding: const EdgeInsets.fromLTRB(18, 10, 18, 0),
                    child: Row(
                      mainAxisAlignment: MainAxisAlignment.spaceBetween,
                      children: const [
                        Icon(Icons.history, color: Color(0xFF3C4043), size: 22),
                        Row(
                          children: [
                            Icon(Icons.straighten,
                                color: Color(0xFF3C4043), size: 22),
                            SizedBox(width: 18),
                            Icon(Icons.functions,
                                color: Color(0xFF3C4043), size: 22),
                          ],
                        ),
                      ],
                    ),
                  ),
                SizedBox(
                  height: displayHeight,
                  child: Container(
                    alignment: Alignment.bottomRight,
                    padding: const EdgeInsets.fromLTRB(22, 12, 22, 12),
                    child: FittedBox(
                      fit: BoxFit.scaleDown,
                      alignment: Alignment.bottomRight,
                      child: Text(
                        _calcDisplayString,
                        maxLines: 1,
                        style: TextStyle(
                          fontSize: 58,
                          color: displayColor,
                          fontWeight: FontWeight.w300,
                        ),
                      ),
                    ),
                  ),
                ),
                Expanded(
                  child: Padding(
                    padding: const EdgeInsets.fromLTRB(14, 0, 14, 18),
                    child: LayoutBuilder(
                      builder: (context, gridConstraints) {
                        const columns = 4;
                        const rows = 5;
                        const spacing = 10.0;
                        final cellWidth = (gridConstraints.maxWidth -
                                spacing * (columns - 1)) /
                            columns;
                        final cellHeight =
                            (gridConstraints.maxHeight - spacing * (rows - 1)) /
                                rows;
                        final aspectRatio = cellHeight > 0
                            ? (cellWidth / cellHeight).clamp(0.55, 4.5)
                            : 1.0;
                        return GridView.count(
                          physics: const NeverScrollableScrollPhysics(),
                          crossAxisCount: columns,
                          mainAxisSpacing: spacing,
                          crossAxisSpacing: spacing,
                          childAspectRatio: aspectRatio,
                          children: gridButtons
                              .map((t) => _buildCalculatorKey(t))
                              .toList(growable: false),
                        );
                      },
                    ),
                  ),
                ),
              ],
            );
          },
        ),
      ),
    );
  }

  Widget _buildCalculatorKey(String text) {
    final bool isAndroidCalc = Platform.isAndroid;
    final bool primary = text == "=";
    final bool operatorKey = ["÷", "×", "-", "+"].contains(text);
    // Samsung: only AC/⌫ get the red-orange treatment; % is styled like a
    // plain digit key (black-on-white), unlike iOS where AC/±/% share one
    // light-gray utility style.
    final bool destructive = text == "AC" || text == "⌫";
    final bool utility = ["AC", "⌫", "%", "±"].contains(text);

    final Color bg;
    final Color fg;
    if (isAndroidCalc) {
      if (primary) {
        bg = const Color(0xFF1FAF64);
        fg = Colors.white;
      } else if (operatorKey) {
        bg = const Color(0xFFE3E3E6);
        fg = const Color(0xFF1A1A1A);
      } else {
        bg = Colors.white;
        fg = destructive ? const Color(0xFFFF5722) : const Color(0xFF1A1A1A);
      }
    } else {
      if (primary || operatorKey) {
        bg = const Color(0xFFFF9F0A);
        fg = Colors.white;
      } else if (utility) {
        bg = const Color(0xFFA5A5A5);
        fg = Colors.black;
      } else {
        bg = const Color(0xFF333333);
        fg = Colors.white;
      }
    }
    return Semantics(
      label: 'Calculator $text',
      button: true,
      excludeSemantics: true,
      child: Material(
        color: bg,
        borderRadius: BorderRadius.circular(28),
        child: InkWell(
          borderRadius: BorderRadius.circular(28),
          onTap: () => unawaited(_onCalculatorButtonPressed(text)),
          child: Center(
            child: Text(
              text,
              style: TextStyle(
                fontSize: text.length > 1 ? 20 : 28,
                color: fg,
                fontWeight: FontWeight.w500,
              ),
            ),
          ),
        ),
      ),
    );
  }

  /// Honest threat-model framing shown on the activation/onboarding screen.
  /// Every claim is defensible against the shipping path (AWG + Xray), not
  /// against Winn Protocol v3, which is not yet in a shipping artifact. It
  /// deliberately avoids promising anonymity, invisibility, or universal
  /// reachability that the app does not provide.
