  Widget _buildSplitTunnelPanel() {
    final visibleApps = _visibleSplitTunnelApps();
    return Container(
      key: _splitTunnelPanelKey,
      decoration: BoxDecoration(
        color: _surfacePanelSoft,
        borderRadius: BorderRadius.circular(10),
        border: Border.all(color: _surfaceBorder),
      ),
      child: Column(
        children: [
          ListTile(
            dense: true,
            visualDensity: VisualDensity.compact,
            contentPadding:
                const EdgeInsets.symmetric(horizontal: 16, vertical: 0),
            title: const Text(
              "Split Tunneling (to exclude apps & IPs such as Android Auto without having to disconnect the VPN)",
              maxLines: 2,
              overflow: TextOverflow.ellipsis,
              style: TextStyle(fontSize: 12, fontWeight: FontWeight.w600),
            ),
            subtitle: Text(
              _splitTunnelSummaryText(),
              style: const TextStyle(color: _surfaceMutedText, fontSize: 11),
            ),
            trailing: Icon(
              _splitTunnelExpanded
                  ? Icons.keyboard_arrow_up
                  : Icons.keyboard_arrow_down,
            ),
            onTap: () => unawaited(_toggleSplitTunnelPanel()),
          ),
          AnimatedCrossFade(
            duration: const Duration(milliseconds: 180),
            crossFadeState: _splitTunnelExpanded
                ? CrossFadeState.showSecond
                : CrossFadeState.showFirst,
            firstChild: const SizedBox.shrink(),
            secondChild: SizedBox(
              height: Platform.isLinux
                  ? 500
                  : (_supportsPerAppSplitTunneling ? 452 : 230),
              child: _appsLoading
                  ? const Center(child: CircularProgressIndicator())
                  : Column(
                      children: [
                        Padding(
                          padding: const EdgeInsets.fromLTRB(12, 0, 12, 10),
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              const Text(
                                'Destinations outside VPN (all operating systems)',
                                style: TextStyle(
                                    fontSize: 11, fontWeight: FontWeight.w700),
                              ),
                              const SizedBox(height: 4),
                              Row(
                                children: [
                                  Expanded(
                                    child: TextField(
                                      controller: _splitTunnelRoutesController,
                                      enabled: !_isConnected,
                                      minLines: 1,
                                      maxLines: 2,
                                      style: const TextStyle(fontSize: 11),
                                      decoration: InputDecoration(
                                        isDense: true,
                                        hintText:
                                            'Example: 192.168.0.0/16, 203.0.113.9',
                                        contentPadding:
                                            const EdgeInsets.symmetric(
                                                horizontal: 9, vertical: 8),
                                        border: OutlineInputBorder(
                                          borderRadius:
                                              BorderRadius.circular(8),
                                        ),
                                      ),
                                    ),
                                  ),
                                  const SizedBox(width: 6),
                                  IconButton.filledTonal(
                                    tooltip: 'Apply bypass destinations',
                                    onPressed: _isConnected
                                        ? null
                                        : () => unawaited(
                                            _applySplitTunnelRoutes()),
                                    icon: const Icon(Icons.check, size: 18),
                                  ),
                                ],
                              ),
                              const SizedBox(height: 3),
                              const Text(
                                'Enter IPv4 addresses or CIDR networks. These destinations use your normal connection; everything else stays in the VPN.',
                                style: TextStyle(
                                    color: _surfaceMutedText, fontSize: 9),
                              ),
                            ],
                          ),
                        ),
                        if (_supportsPerAppSplitTunneling) ...[
                          const Divider(height: 1),
                          Padding(
                            padding: const EdgeInsets.fromLTRB(12, 8, 12, 8),
                            child: TextField(
                              controller: _splitTunnelSearchController,
                              onChanged: (value) => setState(
                                  () => _splitTunnelSearchQuery = value),
                              style: const TextStyle(fontSize: 12),
                              decoration: InputDecoration(
                                isDense: true,
                                prefixIcon: const Icon(Icons.search, size: 18),
                                suffixIcon: _splitTunnelSearchQuery.isEmpty
                                    ? null
                                    : IconButton(
                                        tooltip: 'Clear search',
                                        icon: const Icon(Icons.close, size: 16),
                                        onPressed: () {
                                          _splitTunnelSearchController.clear();
                                          setState(() =>
                                              _splitTunnelSearchQuery = '');
                                        },
                                      ),
                                hintText:
                                    'Search $_perAppSplitTunnelPlatformName to exclude',
                                contentPadding: const EdgeInsets.symmetric(
                                    horizontal: 10, vertical: 9),
                                border: OutlineInputBorder(
                                  borderRadius: BorderRadius.circular(8),
                                ),
                              ),
                            ),
                          ),
                          if (Platform.isLinux)
                            const Padding(
                              padding: EdgeInsets.fromLTRB(12, 0, 12, 7),
                              child: Text(
                                "Linux bypass is launcher-scoped: connect, select an app, then use its launch button here. Apps opened normally remain protected by the VPN.",
                                style: TextStyle(
                                    color: _surfaceMutedText, fontSize: 9),
                              ),
                            ),
                          SizedBox(
                            height: 46,
                            child: CheckboxListTile(
                              dense: true,
                              tristate: true,
                              contentPadding:
                                  const EdgeInsets.only(left: 12, right: 8),
                              visualDensity: const VisualDensity(
                                  horizontal: -4, vertical: -4),
                              value: _installedApps.isEmpty
                                  ? false
                                  : (_allInstalledAppsExcluded
                                      ? true
                                      : (_someInstalledAppsExcluded
                                          ? null
                                          : false)),
                              onChanged: _installedApps.isEmpty
                                  ? null
                                  : (value) => unawaited(
                                        _setAllSplitTunnelAppsExcluded(
                                            !_allInstalledAppsExcluded),
                                      ),
                              title: Text(
                                'Exclude all $_perAppSplitTunnelPlatformName',
                                maxLines: 1,
                                overflow: TextOverflow.ellipsis,
                                style: TextStyle(
                                    fontSize: 12, fontWeight: FontWeight.w700),
                              ),
                              controlAffinity: ListTileControlAffinity.trailing,
                            ),
                          ),
                          const Divider(height: 1),
                          Expanded(
                            child: visibleApps.isEmpty
                                ? Center(
                                    child: Text(
                                      _installedApps.isEmpty
                                          ? "App list is not ready yet."
                                          : "No apps match your search.",
                                      style: const TextStyle(
                                          color: _surfaceMutedText,
                                          fontSize: 12),
                                      textAlign: TextAlign.center,
                                    ),
                                  )
                                : Scrollbar(
                                    child: ListView.builder(
                                      padding: EdgeInsets.zero,
                                      itemCount: visibleApps.length,
                                      itemBuilder: (context, index) {
                                        final app = visibleApps[index];
                                        final packageName =
                                            (app['package_name'] ?? '')
                                                .toString();
                                        final label =
                                            (app['name'] ?? packageName)
                                                .toString()
                                                .trim();
                                        final isSystem =
                                            app['is_system'] == true;
                                        final excluded = _excludedVpnPackages
                                            .contains(packageName);
                                        return SizedBox(
                                          height: 48,
                                          child: Stack(
                                            fit: StackFit.expand,
                                            children: [
                                              CheckboxListTile(
                                                dense: true,
                                                contentPadding: EdgeInsets.only(
                                                    left: Platform.isLinux
                                                        ? 52
                                                        : 12,
                                                    right: 8),
                                                visualDensity:
                                                    const VisualDensity(
                                                        horizontal: -4,
                                                        vertical: -4),
                                                value: excluded,
                                                onChanged: (value) => unawaited(
                                                  _setExcludedVpnPackage(
                                                      packageName,
                                                      value == true),
                                                ),
                                                title: Text(
                                                  isSystem
                                                      ? "${label.isEmpty ? packageName : label} (system app)"
                                                      : (label.isEmpty
                                                          ? packageName
                                                          : label),
                                                  maxLines: 1,
                                                  overflow:
                                                      TextOverflow.ellipsis,
                                                  style: const TextStyle(
                                                      fontSize: 12),
                                                ),
                                                subtitle: Text(
                                                  Platform.isLinux
                                                      ? (excluded
                                                          ? "Use the launch button to open outside the VPN"
                                                          : "Select to enable launcher-scoped bypass")
                                                      : packageName,
                                                  maxLines: 1,
                                                  overflow:
                                                      TextOverflow.ellipsis,
                                                  style: TextStyle(
                                                    color: _surfaceMutedText
                                                        .withOpacity(0.86),
                                                    fontSize: 9,
                                                  ),
                                                ),
                                                controlAffinity:
                                                    ListTileControlAffinity
                                                        .trailing,
                                              ),
                                              if (Platform.isLinux)
                                                Align(
                                                  alignment:
                                                      Alignment.centerLeft,
                                                  child: Semantics(
                                                    label: excluded
                                                        ? (_isConnected
                                                            ? 'Launch outside VPN'
                                                            : 'Connect VPN to launch outside')
                                                        : 'Select app for bypass first',
                                                    button: true,
                                                    enabled: excluded &&
                                                        _isConnected,
                                                    container: true,
                                                    excludeSemantics: true,
                                                    child: IconButton(
                                                      tooltip: excluded
                                                          ? (_isConnected
                                                              ? 'Launch outside VPN'
                                                              : 'Connect VPN to launch outside')
                                                          : 'Select app for bypass first',
                                                      onPressed: excluded &&
                                                              _isConnected
                                                          ? () => unawaited(
                                                                _launchLinuxSplitTunnelApp(
                                                                    packageName),
                                                              )
                                                          : null,
                                                      icon: const Icon(
                                                          Icons.open_in_new,
                                                          size: 17),
                                                    ),
                                                  ),
                                                ),
                                            ],
                                          ),
                                        );
                                      },
                                    ),
                                  ),
                          ),
                        ] else
                          Expanded(
                            child: Center(
                              child: Padding(
                                padding:
                                    const EdgeInsets.symmetric(horizontal: 18),
                                child: Text(
                                  _unsupportedPerAppSplitTunnelMessage,
                                  style: const TextStyle(
                                      color: _surfaceMutedText, fontSize: 12),
                                  textAlign: TextAlign.center,
                                ),
                              ),
                            ),
                          ),
                      ],
                    ),
            ),
          ),
        ],
      ),
    );
  }

