  /// Shows a freshly minted recovery code exactly once.
  ///
  /// Wording carries no product name, no "VPN", and no hint about what the
  /// code opens: this is the screen most likely to be read over a shoulder.
  /// Reached only from inside the unlocked app, never from the decoy.
  /// Shows [code]; true only when the user confirmed it ("I have saved
  /// it"). A dialog a relock removed answers null, which is not a
  /// confirmation.
  Future<bool> _showRecoveryCodeOnce(String code) async {
    if (!mounted) return false;
    final confirmed = await showDialog<bool>(
      context: context,
      barrierDismissible: false,
      builder: (dialogContext) => AlertDialog(
        backgroundColor: _surfacePanel,
        title: Text(
          _t("Save this recovery code"),
          style: const TextStyle(fontSize: 16),
        ),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(
              _t("Write it down, or put it in a password manager. Keep it "
                  "somewhere separate from this device."),
              style: const TextStyle(fontSize: 13, color: _surfaceText),
            ),
            const SizedBox(height: 14),
            SelectableText(
              PinCredentialCodec.formatRecoveryCodeForDisplay(code),
              style: const TextStyle(
                fontSize: 20,
                fontWeight: FontWeight.w600,
                letterSpacing: 1.5,
                fontFamily: 'monospace',
              ),
            ),
            const SizedBox(height: 14),
            Text(
              _t("If you forget your unlock code, this is the only way back "
                  "in. It will not be shown again."),
              style: const TextStyle(fontSize: 12, color: _surfaceText),
            ),
          ],
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(dialogContext).pop(true),
            child: Text(_t("I have saved it")),
          ),
        ],
      ),
    );
    return confirmed == true;
  }

  /// Mints and shows a recovery code, reporting failure without detail.
  /// Best effort by design: a storage failure here must never block or undo
  /// an activation that has otherwise succeeded.
  Future<void> _issueAndShowRecoveryCode() async {
    final decoyGeneration = _decoyGeneration;
    String code;
    try {
      // Set before minting, cleared only when the user confirms the code: a
      // code minted and then lost unseen (the process died behind a relock)
      // is replaced by a new one at the next unlock. The code itself is
      // never written anywhere but the recovery credential.
      await _setRecoveryCodeUnconfirmed(true);
      code = await _issueRecoveryCode();
    } catch (e) {
      _debugLog('Recovery code issue failed: $e');
      if (mounted) {
        setState(() => _recoveryCodeMissing = true);
        _showFeedback(_t(
            "The recovery code could not be stored on this device. You can try "
            "again from the home screen."));
      }
      return;
    }
    if (mounted) setState(() => _recoveryCodeMissing = false);
    await _showRecoveryCodeUntilSeen(code, decoyGeneration);
  }

  /// Shows [code] once, unless a relock came before the dialog or removed it:
  /// then it stays pending, in memory only, for the next unlock. Confirmed
  /// by the user, it is done, and the persisted flag is cleared.
  Future<void> _showRecoveryCodeUntilSeen(
      String code, int decoyGeneration) async {
    if (!_decoyStillAway(decoyGeneration)) {
      _pendingRecoveryCode = code;
      return;
    }
    final confirmed = await _showRecoveryCodeOnce(code);
    if (!confirmed) {
      _pendingRecoveryCode = code;
      return;
    }
    _pendingRecoveryCode = null;
    await _setRecoveryCodeUnconfirmed(false);
  }

  /// After an unlock: the recovery code a relock interrupted, from memory;
  /// or, after a process restart lost it, a NEW code (minting it invalidates
  /// the unseen one), shown once.
  Future<void> _showPendingRecoveryCode() async {
    if (!mounted || _showDecoyCalculator) return;
    final code = _pendingRecoveryCode;
    if (code != null) {
      _pendingRecoveryCode = null;
      await _showRecoveryCodeUntilSeen(code, _decoyGeneration);
      return;
    }
    if (!await _recoveryCodeUnconfirmed()) return;
    if (!mounted || _showDecoyCalculator) return;
    await _issueAndShowRecoveryCode();
  }

  /// Whether a recovery code was issued and never confirmed seen. Only this
  /// flag is persisted (vpn_settings.txt, wiped by duress); never the code.
  Future<bool> _recoveryCodeUnconfirmed() async =>
      (await _readVpnRuntimeSettings())['recovery_code_unconfirmed'] == true;

  Future<void> _setRecoveryCodeUnconfirmed(bool value) =>
      _mutateVpnRuntimeSettings((data) {
        if (value) {
          data['recovery_code_unconfirmed'] = true;
        } else {
          data.remove('recovery_code_unconfirmed');
        }
      });

  /// After a recovery-code unlock the user has proved possession, not
  /// knowledge of the PIN, so a new PIN is required before they carry on.
  /// Not dismissible - but the previous PIN keeps working until the new one
  /// is durably stored, so killing the app here strands nobody.
  Future<void> _promptForMandatoryPinReset() async {
    // Never over the decoy. If the app re-locked between the recovery
    // unlock and this call, the flag stays set and the prompt returns on
    // the next successful unlock instead.
    if (!mounted || _showDecoyCalculator) return;
    if (_pinResetDialogOpen) return; // one reset dialog at a time
    // A write from an earlier prompt still running (a relock and a PIN unlock
    // inside one write): wait for it, and ask nothing if it paid the debt. A
    // second dialog would store a second credential and mint a second recovery
    // code that invalidates the first.
    final running = _pinResetInFlight;
    if (_pinResetWriting && running != null) {
      if (_pinResetPromptWaiting) return;
      _pinResetPromptWaiting = true;
      try {
        await running;
      } finally {
        _pinResetPromptWaiting = false;
      }
      if (!mounted ||
          _showDecoyCalculator ||
          _pinResetDialogOpen ||
          !_pinResetRequired) {
        return;
      }
    }
    _pinUpgradeController.clear();
    _pinResetCommitted = false;
    _pinResetInFlight = null;
    String? inlineError;
    bool saving = false;
    _pinResetDialogOpen = true;
    bool? done;
    try {
      done = await showDialog<bool>(
      context: context,
      barrierDismissible: false,
      builder: (dialogContext) {
        return PopScope(
          canPop: false,
          child: StatefulBuilder(
            builder: (dialogContext, setDialogState) {
              return FocusTraversalGroup(
                policy: OrderedTraversalPolicy(),
                child: Shortcuts(
                  shortcuts: <LogicalKeySet, Intent>{
                    LogicalKeySet(LogicalKeyboardKey.arrowUp):
                        const DirectionalFocusIntent(TraversalDirection.up),
                    LogicalKeySet(LogicalKeyboardKey.arrowDown):
                        const DirectionalFocusIntent(TraversalDirection.down),
                    LogicalKeySet(LogicalKeyboardKey.arrowLeft):
                        const DirectionalFocusIntent(TraversalDirection.left),
                    LogicalKeySet(LogicalKeyboardKey.arrowRight):
                        const DirectionalFocusIntent(TraversalDirection.right),
                    LogicalKeySet(LogicalKeyboardKey.select):
                        const ActivateIntent(),
                    LogicalKeySet(LogicalKeyboardKey.enter):
                        const ActivateIntent(),
                    LogicalKeySet(LogicalKeyboardKey.escape):
                        const DismissIntent(),
                    LogicalKeySet(LogicalKeyboardKey.goBack):
                        const DismissIntent(),
                  },
                  child: Actions(
                    actions: <Type, Action<Intent>>{
                      DirectionalFocusIntent: DirectionalFocusAction(),
                      ActivateIntent: CallbackAction<ActivateIntent>(
                          onInvoke: (intent) => null),
                      DismissIntent: CallbackAction<DismissIntent>(
                        onInvoke: (intent) => null,
                      ),
                    },
                    child: OwnedKeyboardListener(
                      onKeyEvent: (event) {},
                      child: AlertDialog(
                        backgroundColor: _surfacePanel,
                        title: Text(
                          _t("Choose a new unlock code"),
                          style: const TextStyle(fontSize: 16),
                        ),
                        content: Column(
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            Text(
                              _t("You opened the app with your recovery code, so "
                                  "please set a new $kCamouflagePinLength-digit "
                                  "unlock code now."),
                              style: const TextStyle(
                                  fontSize: 13, color: _surfaceText),
                            ),
                            const SizedBox(height: 12),
                            TvFocusDecoration(
                              order: 1,
                              child: TextField(
                                controller: _pinUpgradeController,
                                autofocus: true,
                                textAlign: TextAlign.center,
                                autofillHints: null,
                                enableSuggestions: false,
                                autocorrect: false,
                                keyboardType: TextInputType.number,
                                maxLength: kCamouflagePinLength,
                                inputFormatters: [
                                  FilteringTextInputFormatter.digitsOnly
                                ],
                                decoration: InputDecoration(
                                  counterText: '',
                                  hintText: "$kCamouflagePinLength digits",
                                  errorText: inlineError,
                                  errorMaxLines: 4,
                                ),
                              ),
                            ),
                          ],
                        ),
                        actions: [
                          TvFocusDecoration(
                            order: 2,
                            child: TextButton(
                              // Off while the write runs: a second tap would
                              // start a second write on the same credential.
                              onPressed: saving
                                  ? null
                                  : () async {
                                      setDialogState(() => saving = true);
                                      final error = await _commitPinReset(
                                          _pinUpgradeController.text.trim());
                                      // A relock while the write ran removed
                                      // this dialog: nothing to update,
                                      // nothing to pop.
                                      if (!dialogContext.mounted) return;
                                      if (error != null) {
                                        setDialogState(() {
                                          saving = false;
                                          inlineError = error;
                                        });
                                        return;
                                      }
                                      // This dialog only, never a newer one
                                      // on top (_endOwnDialog).
                                      _endOwnDialog<bool>(dialogContext, true);
                                    },
                              child: Text(_t("Save")),
                            ),
                          ),
                        ],
                      ),
                    ),
                  ),
                ),
              );
            },
          ),
        );
      },
      );
    } finally {
      _pinResetDialogOpen = false;
    }
    _pinUpgradeController.clear();
    // The write is what counts, not how the dialog ended: a relock that
    // removed the dialog while it ran answers null, and the credential is
    // stored all the same. That answer arrives BEFORE the write finishes, so
    // wait for a write still in flight before reading its outcome.
    final inFlight = _pinResetInFlight;
    if (inFlight != null) await inFlight;
    final committed = _pinResetCommitted;
    _pinResetCommitted = false;
    if ((done != true && !committed) || !mounted) return;
    // The old recovery code was just spent, and it was exposed for as long
    // as it took to type. Retire it and issue a replacement only now that a
    // working PIN is durably stored. Behind the decoy the new code is kept
    // pending for the unlock (_showRecoveryCodeUntilSeen).
    await _issueAndShowRecoveryCode();
  }

  /// The Save action of the mandatory PIN reset. Returns the message to show
  /// under the field, or null once the new code is stored.
  ///
  /// The keypad's expected length and the reset debt follow the stored
  /// credential the moment the write commits (see _commitPinUpgrade): a
  /// relock that removes the dialog while the write runs leaves a six-digit
  /// credential behind a four-digit keypad, and the spent recovery code live.
  ///
  /// One write at a time: a second Save while one runs gets the running
  /// write's answer, never a second write (the dialog also disables the
  /// button, this is the guard behind it).
  Future<String?> _commitPinReset(String candidate) {
    final running = _pinResetInFlight;
    if (_pinResetWriting && running != null) return running;
    _pinResetWriting = true;
    return _pinResetInFlight = _runPinResetCommit(candidate)
        .whenComplete(() => _pinResetWriting = false);
  }

  Future<String?> _runPinResetCommit(String candidate) async {
    final rejection = pinPolicyRejectionReason(candidate);
    if (rejection != null) return rejection;
    try {
      await _replaceUserPin(candidate);
    } catch (e) {
      _debugLog('Mandatory unlock code reset failed: $e');
      return _t(
          "The new code could not be stored on this device. Nothing was changed.");
    }
    _pinResetCommitted = true;
    if (mounted) {
      setState(() {
        _pinResetRequired = false;
        _pinUpgradeAvailable = false;
        _calculatorPinEntry.pinLength = kCamouflagePinLength;
      });
    }
    return null;
  }

